   \centering
   \includegraphics[width=\textwidth]{globular_clusters_metallicity2.pdf}
      \caption{The [Fe/H] differences between predictions from various ML methods and \citet{Harris1996} reference values for globular clusters. Each panel represents a cluster, with histograms of [Fe/H] differences for the four ML methods explored in Sect.~\ref{sec:val}: this paper, \citet{andrae23}, \citet{Zhang2023}, and \citet{gu25}. The mean and standard deviation of the differences are annotated only for our method.}
   \label{fig:glob_cluster_all}
   \end{figure*}

   \begin{figure*}[t]
   \centering
   \includegraphics[width=\textwidth]{open_clusters_metallicity.pdf}
      \caption{The same as in Fig.\ref{fig:glob_cluster_all}, but for open clusters.}
   \label{fig:open_cluster_all}
   \end{figure*}

