\subsection{Systemic Risk Measures}\label{sec:background-systemic}

Consider a financial system with $N\in\N$ institutions. In this multivariate setting, we will consider systemic risk measures that are defined as set-valued functionals on the space $L^\infty(\R^N)$. Here, each $X\in L^\infty(\R^N)$ is called a \emph{random shock} or a \emph{stress scenario}, e.g., for each $i\in [N]$, the random variable $X_i$ represents the future worth of the assets of institution $i$, which affects its ability to meet its contractual obligations. %In this setting, we will generically refer to a multivariate extended real-valued function as an \emph{aggregation function}.

%\notiz{Give a precise definition of aggregation function here: increasing in $m$ with $\dom\Lambda\neq\emptyset$.}

We start by introducing the notion of aggregation function in our setting. For a function $\Lambda\colon\R^N\times\R^N\to\R\cup\{-\infty\}$ and $\bar{x},\bar{m}\in\R^N$, we denote by $\Lambda|_{m=\bar{m}}$ the section $x\mapsto \Lambda(x,\bar{m})$ and by $\Lambda|_{x=\bar{x}}$ the section $m\mapsto \Lambda(\bar{x},m)$. Recall that we consider the effective domain $\dom\Lambda = \{(x,m) \in \R^N \times \R^N \; | \; \Lambda(x,m) \in\R\}$; in particular, $\Lambda(x,m) = -\infty$ for $(x,m) \not\in \dom\Lambda$.

\begin{definition}\label{defn:agg}
A function $\Lambda\colon\R^N\times\R^N\to\R\cup\{-\infty\}$ is called an \textbf{aggregation function} if it satisfies the following properties:%there exists a closed convex pointed cone $K\subseteq\R^N$ with $\R^N_+\subseteq K$, called the \textbf{ordering cone of $\Lambda$,} such that the following properties are satisfied:
\begin{enumerate}
\item \textbf{Monotone:} $\Lambda$ is increasing with $\dom\Lambda\neq\emptyset$.
\item \textbf{Upper semicontinuous:} $\Lambda$ is upper semicontinuous.
%\item \textbf{Closed domain:} $\dom\Lambda$ is a nonempty closed set. %\notiz{May need later: $\Lambda$ is usc, which implies $\dom\Lambda$ is closed.}
\item \textbf{Rectangular domain:} (i) For each $\bar{m}\in\R^N$, it holds $\dom\Lambda|_{m=\bar{m}}\in \mathcal{R}(\R^N;\R^N_+)$.\\
(ii) For each $\bar{x}\in\R^N$, it holds $\dom\Lambda|_{x=\bar{x}}\in\mathcal{R}(\R^N;\R^N_+)$.
%\item \textbf{Local ideal point:} (i) For each $m\in\R^N$, every nonempty compact subset $E$ of $\dom\Lambda|_m := \{x\in\R^N\; | \; \Lambda(x,m)>-\infty\}$ has an ideal point, i.e., there exists $\bar{x}\in \dom\Lambda|_m$ such that $\bar{x}\leq x$ for every $x\in E$.\\
%(ii) For each $x\in\R^N$, every nonempty compact subset $E$ of $\dom\Lambda|_x :=\{m\in\R^N\; | \; \Lambda(x,m)>-\infty\}$ has an ideal point, i.e., there exists $\bar{m}\in \dom\Lambda|_x$ such that $\bar{m}\leq m$ for every $m\in E$.
\end{enumerate}
%$\Lambda$ is $K\times K$-increasing,  s section $m\mapsto \Lambda(x,m)$ is increasing for every $x\in\R^N$ and $\dom\Lambda\neq \emptyset$ is a closed set.
%\notiz{Do we want $(x,m) \mapsto \Lambda(x,m)$ increasing since we will later want $x \mapsto \Lambda_i(x,m)$ increasing?}
A function $\bar\Lambda\colon\R^N\to\R\cup\{-\infty\}$ is called a \textbf{single-element aggregation function} if $(x,m)\mapsto \bar{\Lambda}(x)$ is an aggregation function.%it is increasing and $\dom\bar\Lambda\neq\emptyset$ is a closed set.
\end{definition}

\begin{remark}\label{rem:single}
In view of Definition~\ref{defn:agg}, a function $\bar{\Lambda}\colon\R^N\to\R\cup\{-\infty\}$ is a single-element aggregation function if and only if it is increasing, upper semicontinuous, and $\dom\bar\Lambda$ is a nonempty rectangular upper set. In particular, part (ii) of the rectangular domain property becomes redundant in this case.%with the local ideal point property, i.e., for every nonempty compact set $E\subseteq\dom\bar\Lambda$, there exists $\bar{x}\in \dom\bar\Lambda$ such that $\bar{x}\leq x$ for every $x\in E$. In particular, part (ii) of the local ideal point property of Definition~\ref{defn:agg} becomes redundant in this case.}
\end{remark}

\begin{remark}
For an aggregation function $\Lambda$, the quantity $\Lambda(x,m)$ can be seen as the impact of a shock of magnitude $x\in \R^N$ to society under capital level $m\in\R^N$. More generally, we can easily extend Definition~\ref{defn:agg} to functions $\Lambda\colon \R^N \times \R^M \to \R \cup \{-\infty\}$, where $M\in\N$. In this way, the shocks need not be of the same dimension as the capital requirements. This applies if, e.g., we consider factor models to generate the shocks (see \cite{banerjee2022pricing}) or groupings of the institutions for capital requirements (see \cite{feinstein2017measures,meimanjan2023}).
\end{remark}

%\notiz{It might be convenient to assume $D(X) \neq \emptyset$ for every $X \in L^\infty(\R^N)$ so that $L^\infty_{\Lambda}(\R^N) = L^\infty(\R^N)$. The relates to having the self-feasible property for decomposable}
We will discuss single-element aggregation functions later starting at Example~\ref{ex:syst}. For our general framework, let $\A \subseteq L^\infty(\R)$ be the acceptance set of a risk measure $\rho$ and $\Lambda\colon\R^N \times \R^N \to \R \cup \{-\infty\}$ be an aggregation function. For each $X\in L^\infty(\R^N)$, we define the set
\[
D(X)\coloneqq \{m\in\R^N\; | \; \mathbb{P}\{(X,m)\in \dom\Lambda\}=1\},
\]
i.e., $\Lambda(X,m)$ is a real-valued random variable for each $m\in D(X)$. In the sequel, it will be convenient to introduce the set
\[
L^\infty_\Lambda(\R^N)\coloneqq \cb{X\in L^\infty(\R^N)\; | \; D(X)\neq\emptyset}.
\]
Since $\dom\Lambda\neq\emptyset$, it is easy to verify that $L^\infty_\Lambda(\R^N)\neq\emptyset$ as well.

%Moreover, throughout the paper, we work under the following assumption on $\Lambda$.

\begin{lemma}\label{asmp:domain}
(i) For each $X\in L^\infty(\R^N)$, we have $D(X)=D(\essinf X) = \dom\Lambda|_{x=\essinf X}$.\\
(ii) For each $X\in L_\Lambda^\infty(\R^N)$ and $m\in D(X)$, it holds $\Lambda(X,m)\in L^\infty(\R)$. %\notiz{The assumption is now a lemma.}%\notiz{If we impose joint monotonicity, $-\infty < \Lambda(X,m) \leq \Lambda(\|X\|_\infty,m)$}
\end{lemma}

\begin{proof}
(i) Let $X\in L^\infty(\R^N)$. Since $\essinf X\leq X$ a.s., we have $D(\essinf X)\subseteq D(X)$. The converse is trivial if $D(X)=\emptyset$. Otherwise, let $\bar{m}\in D(X)$. Then, $\Pr\{X\in \dom\Lambda|_{m=\bar{m}}\}=1$. In particular, $\dom\Lambda|_{m=\bar{m}}$ is a nonempty set. Since $\dom\Lambda|_{m=\bar{m}}\in \mathcal{R}(\R^N_+;\R^N_+)$, there exists $\underline{x}\in\dom\Lambda|_{m=\bar{m}}$ such that $\underline{x}\leq X$ a.s. Then, $\underline{x}\leq \essinf X$ so that $-\infty<\Lambda(\underline{x},\bar{m})\leq \Lambda(\essinf X, \bar{m})$ by the monotonicity of $\Lambda$. Hence, $\bar{m}\in D(\essinf X)$ and we get $D(X)\subseteq D(\essinf X)$. \\
(ii) Let $X\in L_\Lambda^\infty(\R^N)$ and $m\in D(X)$. By (i), we have $m\in D(\essinf X)$ so that $-\infty<\Lambda(\essinf X,m)\leq \Lambda(X,m)\leq \Lambda(\esssup X,m)$ a.s. by monotonicity. 
%We define
%\[
%E(m):=[\essinf X,\esssup X]\cap \dom\Lambda\vert_m.
%\]
%Since $\dom\Lambda$ is a closed set, its section $\dom\Lambda|_m$ is also closed. Hence, $E(m)\subseteq\dom\Lambda|_m$ is a compact set such that $X(\o)\in E(m)$ for $\Pr$-a.e. $\o\in\O$. Then, by the local ideal point property of $\Lambda$, there exists $\bar{x}\in \dom\Lambda|_m$ such that $\bar{x}\leq X(\o)$ for $\Pr$-a.e. $\o\in\O$. With this, monotonicity implies that $-\infty<\Lambda(\bar{x},m)\leq \Lambda(X(\o),m)$ for $\Pr$-a.e. $\o\in\O$. On the other hand, since $X\in L^\infty(\R^N)$, we can find $\bar{\bar{x}} \in\R^N$ such that $X(\o)\leq \bar{\bar{x}}$ for $\Pr$-a.e. $\o\in\O$. %\notiz{Will be shown more carefully, or by a reference.} 
%Then, by monotonicity, we have $\Lambda(X(\o),m)\leq \Lambda(\bar{\bar{x}},m)$ for $\Pr$-a.e. $\o\in\O$. 
Hence, we obtain $\Lambda(X,m)\in L^\infty(\R)$.
\end{proof}


\begin{definition}\label{defn:systrisk}
%\footnote{Throughout we take the convention that $\Lambda(x,m) = -\infty$ for any $(x,m) \not\in \dom\Lambda$.}
The set-valued functional $R\colon L^\infty_\Lambda(\R^N)\rightrightarrows \R^N$ defined by
\[
R(X) \coloneqq \{m \in D(X) \; | \; \Lambda(X,m) \in \A\},
\]
for each $X\in L_\Lambda^\infty(\R^N)$, is called the \textbf{$(\A,\Lambda)$-systemic risk measure}.
\end{definition}

In the above definition, if a stress scenario $X \in L_\Lambda^\infty(\R^N)$ is given, then $R(X)$ provides the set of all acceptable \emph{systemic} capital allocations, i.e., accounting for interactions between institutions as modeled by the aggregation function $\Lambda$.

\begin{remark}\label{rem:upperset}
Since $m\mapsto \Lambda(x,m)$ is increasing with a rectangular domain for each $x\in\R^N$, the set-valued function $D$ and the $(\A,\Lambda)$-systemic risk measure $R$ map into the collection of rectangular upper and upper sets, respectively, i.e., $D(X) \in \mathcal{R}(\R^N;\R^N_+)$ and $R(X)\in \P(\R^N;\R^N_+)$ for each $X\in L_\Lambda^\infty(\R^N)$; see \eqref{eq:upperset} and \eqref{eq:rectset}. Moreover, since $x\mapsto \Lambda(x,m)$ is increasing for each $m\in\R^N$ as well, $D$ and $R$ have the following monotonicity property: $D(X^1)\subseteq D(X^2)$ and $R(X^1)\subseteq R(X^2)$ for every $X^1,X^2\in L^\infty_\Lambda(\R^N)$ with $X^1\leq X^2$.
\end{remark}

We proceed with examples of systemic risk measures that have been studied in the recent literature.

\begin{example}\label{ex:syst}
Within the literature, systemic risk measures tend to follow one of three forms discussed below. All of these constructions are derived from a single-element aggregation function $\bar\Lambda\colon \R^N \to \R \cup \{-\infty\}$.
%Throughout this work, we will focus on two broad categories of systemic risk measures found in the literature. \rev{Both of these are derived from a single-element aggregation function $\bar\Lambda\colon \R^N \to \R \cup \{-\infty\}$.} %Let us also fix an acceptance set that corresponds to a risk measure $\rho$.
\begin{itemize}
\item \textbf{Insensitive systemic risk measures:} Let us take $\Lambda=\Lambda^I$, where
\begin{equation}\label{eq:lambda-ins}
\Lambda^I(x,m) := \bar\Lambda(x) + \sum_{i \in [N]} m_i
\end{equation}
for each $x,m\in\R^N$. Clearly, $\Lambda^I$ is an aggregation function and $\dom\Lambda^I=\dom\bar\Lambda\times\R^N$. Let
\[
L^\infty(\dom \bar\Lambda)\coloneqq \{X\in L^\infty(\R^N)\; | \; \mathbb{P}\{X\in\dom\bar\Lambda\}=1\}.
\]
Then, we have $D^I(X):=D(X)=\emptyset$ if $X\notin L^\infty(\dom \bar\Lambda)$ and $D^I(X):=D(X)=\R^N$ if $X\in L^\infty(\dom \bar\Lambda)$. In particular, $L^\infty_{\Lambda^I}(\R^N)=L^\infty(\dom\bar\Lambda)$. For every $X\in L^\infty(\dom\bar\Lambda)$, by Lemma~\ref{asmp:domain}, we have $\bar\Lambda(X)\in L^\infty(\R)$ and
\[
R^I(X)\coloneqq R(X)\negthinspace=\negthinspace\cb{m\in\R^N\; | \; \bar\Lambda(X)+\sum_{i\in[N]} m_i \in \A}\negthinspace=\negthinspace \cb{m\in\R^N\; | \; \rho(\bar\Lambda(X))\leq \sum_{i\in[N]} m_i};
\]
in particular, $R^I(X)$ is a halfspace. Hence, the set-valued functional $R^I$ essentially reduces to the real-valued functional $X\mapsto \rho(\bar\Lambda(X))$ on $L^\infty(\dom \bar\Lambda)$ as studied in \cite{chen2013axiomatic,kromer2016systemic}.
\item \textbf{Sensitive systemic risk measures:} Let us take $\Lambda=\Lambda^S$, where
\begin{equation}\label{eq:lambda-sen}
\Lambda^S(x,m) \coloneqq \bar\Lambda(x+m)
\end{equation}
for each $x,m\in\R^N$. Clearly, $\Lambda^S$ is an aggregation function with
\begin{equation}\label{eq:domsen}
\dom\Lambda^S=\{(x,m)\in\R^N\times\R^N\; | \; x+m\in\dom\bar\Lambda\}.
\end{equation}
Then, for each $X\in L^\infty(\R^N)$, we have
\begin{equation}\label{eq:Dsen}
D^S(X):=D(X)=\{m\in\R^N\; | \; \mathbb{P}\{X+m\in \dom \bar\Lambda\}=1\}.
\end{equation}
Since $\dom\bar\Lambda\neq\emptyset$ and $\bar\Lambda$ is increasing, it follows that $D^S(X)\neq \emptyset$ for every $X\in L^\infty(\R^N)$. In particular, $L^\infty_{\Lambda^S}(\R^N)=L^\infty(\R^N)$. By Lemma~\ref{asmp:domain}, we have $\bar\Lambda(X+m)\in L^\infty(\R)$ for every $X\in L^\infty(\R^N)$ and $m\in D^S(X)$. Then,
\begin{align*}
R^S(X)\coloneqq R(X)&=\{m\in D^S(X)\; | \; \bar\Lambda(X+m)\in \A\}\\
&=\{m\in \R^N\; | \; \rho(\bar\Lambda(X+m))\leq 0,\ \essinf X+m\in \dom\bar\Lambda\}
\end{align*}
for every $X\in L^\infty(\R^N)$, which yields the systemic risk measures studied in \cite{feinstein2017measures,ararat2020dual}. Compared to the previous case, these systemic risk measures consider the direct impact of capital allocations on the stress scenario before aggregation, hence they are more sensitive to capital levels.
