\section{Nash Allocation Rules}\label{sec:nash}

In this section, we wish to construct a financially meaningful capital allocation rule that accounts for the contribution that each firm makes towards the risk of the full system. We are specifically motivated by the aggregation functions that are sums of univariate utilities (see Example~\ref{ex:se-aggregation}\eqref{util}), i.e.,
$\bar\Lambda(x) = \sum_{i \in [N]} u_i(x_i)$, $x\in\R^N$, for univariate utility functions $u_1,\ldots,u_N\colon \R \to \R \cup \{-\infty\}$ so that each bank's contribution to the system's utility is clear. We aim to generalize this concept for broader classes of aggregation functions. Notably, in contrast to the \emph{set-valued} systemic risk measures introduced in Section~\ref{sec:background-systemic}, which provide the collection of all acceptable capital requirements, we focus on finding specific, i.e., \emph{vector-valued}, acceptable capital allocations instead.

Throughout this section, let $\A$ be the acceptance set of a risk measure $\rho$ and $\Lambda\colon \R^N\times\R^N\to\R\cup\{-\infty\}$ be an aggregation function. We consider the corresponding $(\A,\Lambda)$-systemic risk measure $R$ given by Definition~\ref{defn:systrisk}. We will work under the following assumption:

\begin{assumption}\label{asmp:coherent}
The risk measure $\rho$ is a coherent risk measure that is continuous from above; equivalently, the acceptance set $\A$ is a convex cone that is closed with respect to the weak* topology on $L^\infty(\R)$.% and the aggregation function $\Lambda$ satisfies Assumption~\ref{asmp:domain}.
%For the remainder of this work, following the results of Proposition~\ref{prop:acceptable}, we assume that the acceptance set $\A$ is coherent.
\end{assumption}

As a generalization of aggregation functions that are in the form of a sum of univariate utility functions, we introduce the notion of decomposition of an aggregation function next.

\begin{definition}\label{defn:decomposition}
Let $\Lambda_1,\ldots,\Lambda_N\colon\R^N\times\R^N\to\R\cup\{-\infty\}$ be aggregation functions. The collection $(\Lambda_i)_{i \in [N]}$ is called a \textbf{decomposition} of $\Lambda$ if the following properties hold:
\begin{enumerate}
\item \textbf{Consistent domain:} For each $i\in[N]$, it holds $\dom\Lambda_i=\dom\Lambda$.
%\item \textbf{Upper semicontinuous:} For each $i\in[N]$, the function $\Lambda_i$ is upper semicontinuous.
%\item \rev{\textbf{Continuity:} For each $i\in[N]$, $\Lambda_i$ is continuous on $\dom\Lambda$.}
%For each $i\in[N]$, the function $\Lambda_i$ is upper semicontinuous.}
%the restriction of $\Lambda_i$ on $\dom\Lambda$ is continuous.} \notiz{I think we only need upper semicontinuity}
%\item \textbf{Monotonicity in shock:} For each $i\in[N]$, the section $x\mapsto \Lambda_i(x,m)$ is increasing for every $m\in\R^N$.
%\item \textbf{Monotonicity in marginal capital:} For each $i\in[N]$, the section $m_i\mapsto \Lambda_i(x,m)$ is increasing for every $x\in\R^N$ and $m_j\in\R$, $j\in[N]\setminus\{i\}$.\footnote{Often the decomposition will satisfy the stronger $(x,m) \mapsto \Lambda_i(x,m)$ increasing property.} %\notiz{Also want $x \mapsto \Lambda_i(x,m)$ increasing.}
\item \textbf{Dominated by $\Lambda$:} It holds $\sum_{i \in [N]}\Lambda_i(x,m) \leq \Lambda(x,m)$ for every $x,m\in\R^N$.
%\item \textbf{Bounded 0-superlevel set:} For every $x\in\R^N$ and $i\in [N]$, there exists some $\underline{r}_i \in \R$ such that $\{m \in \R^N\; | \; \Lambda_i(x,m) \geq 0\} \subseteq \{m\in\R^N\; | \; m_i\geq \underline r_i\}$.
%\footnote{If $\dom\bar\Lambda = \R^N_+$ then $\underline{r}^i = 0 \in \R^N$ can always be selected.}}
\item \textbf{Self-feasible:} For every $\bar{x}\in \R^N$ with $D(\bar{x}) = \dom\Lambda|_{x = \bar{x}} \neq \emptyset$, there exists $\bar{r} \in D(\bar{x})$ such that $\Lambda_i(\bar{x},(\bar{r}_i,m_{-i})) \geq 0$ for every $m \in D(\bar{x})$ and $i \in [N]$.
\item \textbf{Self-infeasible:} For every $\underline{x}\in \R^N$ with $D(\underline{x}) = \dom\Lambda|_{x = \underline{x}} \neq \emptyset$, there exists $\underline{r}\in D(\underline{x})$ such that $-\infty\leq \Lambda_i(\underline{x},(\underline{r}_i-\varepsilon,m_{-i}))<0$ for every $m\in D(\underline{x})$, $i\in[N]$, and $\varepsilon>0$.%\footnote{\notiz{Recall that $\Lambda_i(\underline{x},m) = -\infty$ if $m \notin D(\underline{x})$.}}
%\item \textbf{Strongly self-feasible:} For every $x \in \R^N$ with $D(x)\neq\emptyset$, there exists some $\bar{r} \in D(x)$ such that $\Lambda_i(x,(\bar{r}_i,m_{-i})) \geq 0$ for every $m \in D(x)$ and each $i \in [N]$.%\notiz{Implicitly, $(\bar{r}_i,m_{-i}) \in D(x)$ so long as $m \in D(x)$}
\end{enumerate}
%A decomposition is, additionally, called \textbf{self-monotonic} if the mapping $\bar x_i \mapsto \bar\Lambda_i((\bar x_i,x_{-i}))$ is strictly increasing for any $x \in \dom\bar\Lambda$.
The decomposition $(\Lambda_i)_{i\in[N]}$ is called \textbf{self-preferential} if there exists some constant $L \in [0,1)$ such that, for every $i,j\in[N]$ with $i\neq j$, $(x,m)\in\dom\Lambda$, and $\delta\geq 0$, it holds 
\[
\Lambda_i(x,m+L\delta e_i) \geq \Lambda_i(x,m+\delta e_j).
\]
%\rev{Similarly, given single-element aggregation functions $\bar\Lambda,\bar\Lambda_1,\ldots,\bar\Lambda_N\colon\R^N\to\R\cup\{-\infty\}$, the collection $(\bar\Lambda_i)_{i\in[N]}$ is called a (self-preferential) decomposition of $\bar\Lambda$ if the collection $((x,m)\mapsto \bar\Lambda_i(x))_{i\in[N]}$ is a (self-preferential) decomposition of $(x,m)\mapsto\bar\Lambda(x)$.}
%\rev{A \textbf{(self-preferential) decomposition} for a single-element aggregation function $\bar\Lambda\colon\R^N\to\R\cup\{-\infty\}$ is defined analogously.}
\end{definition}

\begin{remark}
The self-preferential property of a decomposition means that increasing the capital to the bank associated with the aggregation function is more efficient (by a fixed factor) than adding it to another bank. In particular, from the perspective of a Nash game, no bank has an incentive to bail out any other bank; instead, banks will retain any capital they are allocated. This idea will be formally introduced in Definition~\ref{defn:nash-allocation} below.
\end{remark}

Next, we illustrate Definition~\ref{defn:decomposition} through the motivating example of sum of univariate utilities aggregation. Decompositions for single-element aggregation functions will be defined and studied systematically in Section~\ref{sec:single-element}.

\begin{example}\label{ex:sen-ut}
Recall the single-element aggregation function $\bar\Lambda^U$ in Example~\ref{ex:se-aggregation}\eqref{util} that is in the form of sum of univariate utility functions $u_1,\ldots,u_N$. For this example, consider the corresponding sensitive aggregation function $\Lambda^{S}$ defined by
\[
\Lambda^{S}(x,m)\coloneqq \bar\Lambda^U(x+m)=\sum_{i\in[N]}u_i(x_i+m_i)
\]
for each $x,m\in\R^N$. For each $i \in [N]$, let us define
\[
\Lambda^{S}_i(x,m)\coloneqq u_i(x_i+m_i)
\]
if $x,m\in\R^N$ satisfy $x+m\in \dom\bar\Lambda^U$ and $\Lambda^{S}_i(x,m)\coloneqq -\infty$ otherwise. Clearly, $\Lambda^{S}_1,\ldots,\Lambda^{S}_N$ are aggregation functions, $(\Lambda^{S}_i)_{i\in[N]}$ satisfies the consistent domain property, and $\sum_{i\in[N]}\Lambda^{S}_i = \Lambda^{S}$. Let us further assume that $\{x_i \in \dom u_i \; | \; u_i(x_i) \geq 0\} \not\in \{\emptyset,\R\}$ for each $i\in[N]$, which guarantees self-feasibility and self-infeasibility for $(\Lambda^{S}_i)_{i\in[N]}$. Hence, $(\Lambda^{S}_i)_{i\in[N]}$ is a decomposition of $\Lambda^{S}$. Moreover, this decomposition is self-preferential with $L=0$ due to the independence of the utility functions.
\end{example}


Using a decomposition of $\Lambda$, we are ready to define a Nash allocation rule, the central object of the paper. 

\begin{definition}\label{defn:nash-allocation}
Let $(\Lambda_i)_{i\in[N]}$ be a decomposition of $\Lambda$. A vector-valued functional $r\colon L_\Lambda^\infty(\R^N)\to \R^{N}$ is called a $(\A,(\Lambda_i)_{i\in[N]})$\textbf{-Nash allocation rule} if, for every $X\in L_\Lambda^\infty(\R^N)$, it holds
\[
r_i(X) = \inf\{m_i \in \R \; | \; \Lambda_i(X,(m_i,r_{-i}(X))) \in \A\}
\]
for each $i\in[N]$.\footnote{In the infimum, we implicitly consider $m_i\in\R$ such that $(m_i,r_{-i}(X))\in D(X)$, which ensures that $\Lambda_i(X,(m_i,r_{-i}(X)))\in L^\infty(\R)$ by Lemma~\ref{asmp:domain}.} In this case, $r$ is called \textbf{acceptable} if $r(X)\in R(X)$ for every $X\in L_\Lambda^\infty(\R^N)$.
\end{definition}

In Appendix~\ref{sec:rescue}, we propose a generalization of a Nash allocation rule that permits banks to use their capital to directly bail out or rescue other institutions. However, for all examples considered herein, all Nash allocations with rescue funds satisfy the above definition (see Corollary~\ref{prop:self-preferential}); hence, we focus on this simpler setting in this paper. We leave a more formal study of this generalization for future work.

%\notiz{Discuss the optimization problem for Nash generally}\\
%\notiz{Introduce proposition for self-preferential means $r_i(X) = \bar r_i(X) e_i$ where $\bar r(X) \in \R^N$ means everyone only gives to themselves}

%\begin{remark}
%\rev{The problem of finding the Nash allocations is solving for the Nash equilibria of a game with strategic substitutes.} \notiz{Give citation about these types of games.} \rev{\cite[Theorem 1]{dubey2006strategic} proves aggregative game \notiz{(if only depends on other players through $\sum_{j \neq i} r_j$)} of weak strategic substitutes is pseudo-potential game (requires continuity of the best response function); }
%\end{remark}

Within this section, we first consider general conditions for the acceptability of a Nash allocation rule (Section~\ref{sec:nash-acceptable}). With conditions so that acceptability is guaranteed, we provide a general theorem for the existence and uniqueness of Nash allocation rules (Section~\ref{sec:nash-exist}). With these results for general systemic risk measures, we provide further insights for those systemic risk measures generated from a single-element aggregation function, i.e., insensitive (Section~\ref{sec:nash-insensitive}), sensitive (Section~\ref{sec:nash-sensitive}), and scenario-dependent (Section~\ref{sec:nash-cooperative}) systemic risk measures.


\subsection{Acceptable Allocation Rules}\label{sec:nash-acceptable}

Before focusing on Nash allocation rules specifically, we want to consider the acceptability of a given capital allocation vector. Specifically, when we decompose an aggregation function into attributed pieces for each institution, it is not guaranteed that the acceptability of all banks will lead to systemic acceptability; we refer the interested reader to Example~\ref{ex:non-acceptable} for a simple example \emph{without} systemic acceptability. Proposition~\ref{prop:acceptable} provides a simple sufficient condition for acceptability. Recall that Assumption~\ref{asmp:coherent} is imposed herein and for the remainder of this work.

\begin{proposition}\label{prop:acceptable}
%Consider a $(\A,\Lambda)$-systemic risk measure with coherent acceptance set $\A$ and aggregation function $\Lambda$. 
Let $(\Lambda_i)_{i\in[N]}$ be a decomposition of $\Lambda$. Consider a random shock $X \in L_\Lambda^\infty(\R^N)$ and a capital vector $m\in D(X)$. If $\Lambda_i(X,m) \in \A$ for every bank $i\in[N]$, then $\Lambda(X,m) \in \A$. 
\end{proposition}

\begin{proof}
Since $m\in D(X)$, we have $\Lambda(X,m)\in L^\infty(\R)$ by Lemma~\ref{asmp:domain}. Suppose that $\Lambda_i(X,m) \in \A$ for every $i\in[N]$. Since the acceptance set $\A$ is a convex cone, we have $\sum_{i=1}^N \Lambda_i(X,m)\in\A$. Finally, since the underlying risk measure $\rho$ is monotone and $\sum_{i=1}^N\Lambda_i(X,m)\leq \Lambda(X,m)$, we obtain $\Lambda(X,m)\in\A$.
\end{proof}

\begin{example}\label{ex:non-acceptable}
Proposition~\ref{prop:acceptable} guarantees systemic acceptability by imposing a coherence assumption on the acceptance set $\A$. In this example, we consider a convex but \emph{not} coherent risk measure to demonstrate a case where $\Lambda_i(X,m) \in \A$ for each bank $i\in [N]$ but $\Lambda(X,m) \not\in \A$.
Specifically, we take the entropic risk measure with unit risk-aversion and the summation aggregation function over $N = 2$ banks, i.e., $\A = \{Y \in L^\infty(\R) \; | \; \E[1 - e^{-Y}] \geq 0\}$ and $\Lambda(x,m) = \sum_{i \in [N]} (x_i + m_i)$ for each $(x,m) \in \R^N \times \R^N$.
Herein, we consider the natural decomposition of the aggregation function given by $\Lambda_i(x,m) = x_i + m_i$ for each $i\in[N]$ and $(x,m) \in \R^N \times \R^N$.
Finally, we set $X = (X_1,X_2)^\T \in L^\infty(\R^N)$ with $X_1 = X_2$ a.s. and $\mathbb{P}\{X_1 = -\frac12\} = \mathbb{P}\{X_1=2\}=\frac12$. Taking $\bar{m} = (0,0)^\T$, it is clear that $\E[1 - e^{-\Lambda_1(X,\bar{m})}] = \E[1 - e^{-\Lambda_2(X,\bar{m})}] \approx 0.108 \geq 0$ whereas $\E[1 - e^{-\Lambda(X,\bar{m})}] \approx -0.368 < 0$.
\end{example}


\begin{corollary}\label{cor:acceptable}
Let $(\Lambda_i)_{i\in[N]}$ be a decomposition of $\Lambda$. %In addition to Assumption~\ref{asmp:coherent}, suppose that the risk measure $\rho$ corresponding to $\A$ is continuous from above.\footnote{\rev{$\rho$ is continuous from above if and only if $\A$ is closed in the weak* topology.}}}
Then, every $(\A,(\Lambda_i)_{i\in[N]})$-Nash allocation rule is acceptable.
\end{corollary}

\begin{proof}
Let $r$ be an $(\A,(\Lambda_i)_{i\in[N]})$-Nash allocation rule. Let $X\in L^\infty_\Lambda(\R^N)$ and $i\in[N]$. Then, there exists a decreasing sequence $(m_i^n)_{n\in\N}$ in $\R$ that converges to $r_i(X)$ such that
\[
\rho(\Lambda_i(X,(m^n_i,r_{-i}(X)))) \leq 0
\]
for each $n\in\N$. 
By the monotonicity and upper semicontinuity of $\Lambda_i$, we have
\[
\lim_{n\rightarrow\infty} \Lambda_i(X,(m^n,r_{-i}(X)))=\limsup_{n\rightarrow\infty} \Lambda_i(X,(m^n,r_{-i}(X)))\leq \Lambda_i(X,r(X))\ \text{a.s.}
\]
Then, since $\Lambda_i(X,(m^n,r_{-i}(X)))\downarrow \lim_{n\rightarrow\infty} \Lambda_i(X,(m^n,r_{-i}(X)))$, we have
\[
\rho(\Lambda_i(X,r(X)))\leq \rho\of{\lim_{n\rightarrow\infty} \Lambda_i(X,(m^n,r_{-i}(X)))}=\lim_{n\rightarrow\infty}\rho( \Lambda_i(X,(m^n,r_{-i}(X))))\leq 0,
\]
where we use the fact that $\rho$ is continuous from above (see Assumption~\ref{asmp:coherent}) and monotone. Therefore, $\Lambda_i(X,r(X))\in\A$. Following Proposition~\ref{prop:acceptable}, we obtain $\Lambda(X,r(X)) \in \A$ so that $r$ is acceptable.
\end{proof}


We wish to augment Proposition~\ref{prop:acceptable} to consider allocations when the joint distribution of the stress scenario $X$ may be unknown. Notably, in practice, estimating marginal distributions is a much simpler task than the full joint distribution, especially as the number of banks $N$ grows. While distribution estimation is not the focus of this work, the practicality of computing meaningful acceptable systemic allocations would require such considerations. The following result provides a method to find an acceptable allocation using only the marginal distributions when $\A$ is the acceptance set of a coherent optimized certainty equivalent risk measure; this result is adapted from \citet[Lemma D.12]{banerjee2022pricing}.

\begin{corollary}\label{cor:comonotonic}
Suppose that $\A$ is the acceptance set of an optimized certainty equivalent risk measure $\rho$, i.e., %\citep[Definition~2.2]{ben2007old}, i.e.,
\[
\rho(Y) := \inf_{m \in \R} (m - \E[u(Y+m)])
\]
for $Y \in L^\infty(\R)$, where $u\colon \R \to \R$ is defined by
\[
u(t) = \begin{cases} \gamma_2 t &\text{if } t \leq 0, \\ \gamma_1 t &\text{if } t > 0,\end{cases}
\]
and $\gamma_2 \geq 1 \geq \gamma_1 \geq 0$. 
%\notiz{Can we take $\gamma_2 = 1 = \gamma_1$? This is the expectation risk measure and we use it in case studies}
Moreover, suppose that, for every $m\in \R^N$, the function $x \mapsto \Lambda(x,m)$ is submodular on $\R^N$, i.e.,
\[
\Lambda(x\vee y,m)+\Lambda(x\wedge y,m)\leq \Lambda(x,m)+\Lambda(y,m)
\]
for every $x,y\in\R^N$. Let $(\Lambda_i)_{i\in[N]}$ be a decomposition of $\Lambda$. Let $X \in L^\infty(\R^N)$ be a random shock and denote by $Z$ a comonotonic copula of $X$, i.e.,
\[
Z \coloneqq \of{q_{X_1}(U),\ldots,q_{X_N}(U)}^{\T}
\]
for some $U$ that is uniformly distributed on $[0,1]$, where $q_{X_1},\ldots,q_{X_N}$ are the right-continuous quantile functions of $X_1,\ldots,X_N$, respectively. Let $m\in D(Z)$.
If $\Lambda_i(Z,m) \in \A$ for every bank $i\in[N]$, then $\Lambda(X,m) \in \A$.
\end{corollary}

\begin{proof}
The function $u$ is a utility function in the sense of \citet[Definition~2.1]{ben2007old} since it is concave, continuous, increasing, finitely valued with $u(0)=0$, and $1$ is a subgradient of $u$ at zero. Hence, $\rho$ is a convex risk measure by \citet[Theorem~2.1]{ben2007old}. Moreover, the positive homogeneity of $u$ implies that $\rho$ is also coherent. Suppose that $\Lambda_i(Z,m)\in\A$ for every $i\in[N]$. First, we utilize Proposition~\ref{prop:acceptable} to conclude that $\Lambda(Z,m) \in \A$. We claim that $\Lambda(X,m)\in\A$ as well. By \citet[Theorem 9.A.21]{shaked2007stochastic}, we have $\E[\phi(X)] \geq \E[\phi(Z)]$ for every submodular function $\phi\colon\R^N \to \R$. 
In fact $x \mapsto u(\Lambda(x,m)+y)$ is submodular as it is the composition of a concave and increasing function ($u(\cdot+y)$) and a submodular and increasing function ($\Lambda(\cdot,m)$) for every $m \in D(X)$ and $y \in \R$. 
Therefore, for every $y \in \R$, we have $y - \E[u(\Lambda(X,m)+y)] \leq y - \E[u(\Lambda(Z,m)+y)]$. 
In particular, by construction of the optimized certainty equivalent, it immediately follows that $\rho(\Lambda(X,m)) \leq \rho(\Lambda(Z,m)) \leq 0$, i.e., $\Lambda(X,m) \in \A$.
%Therefore, utilizing the dual representation of $\rho$ (Proposition~\ref{prop:riskmsr-dual}) and submodularity of $x \mapsto \Lambda(x,m)$, we find $\rho(\Lambda(X,m)) \leq \rho(\Lambda(Z,m)) \leq 0$, i.e., $\Lambda(X,m) \in \A$.}
\end{proof}


\subsection{Existence and Uniqueness}\label{sec:nash-exist}

In the above section, we take the existence of a Nash allocation rule for granted to prove that, for coherent risk measures that are continuous from above, any Nash allocation leads to an acceptable capital requirement. Within this section, we consider the existence and uniqueness of Nash allocation rules based on the self-preferential property of the decomposition of the aggregation function.

\begin{theorem}\label{thm:exist-unique}
Let $(\Lambda_i)_{i \in [N]}$ be a self-preferential decomposition of $\Lambda$ with constant $L \in [0,1)$. 
\begin{enumerate}
\item\label{thm:exist-unique:1} There exists a $(\A,(\Lambda_i)_{i \in [N]})$-Nash allocation rule $r\colon L_\Lambda^\infty(\R^N) \to \R^N$.
\item\label{thm:exist-unique:2} If $L < \frac{1}{N-1}$, then there exists a unique $(\A,(\Lambda_i)_{i \in [N]})$-Nash allocation rule. %\notiz{We might need an extra condition on $\dom\Lambda$ here. $\phi^X$ can take finite values outside $D(X)$ depending on the geometry of $\dom\Lambda$.}
\end{enumerate}
\end{theorem}

\begin{proof}
Let $X \in L_{\Lambda}^\infty(\R^N)$ be a random shock. Recall $D(X)=D(\essinf X)\neq\emptyset$ by Lemma~\ref{asmp:domain}(i). By self-feasibility, we can find $\bar{r}\in D(\essinf X)$ such that
\begin{equation}\label{eq:feas}
\Lambda_i(\essinf X,(\bar{r}_i,m_{-i}))\geq 0
\end{equation}
for every $m\in D(\essinf X)$ and $i\in[N]$. 
On the other hand, since $\bar{r}\in D(\essinf X)\subseteq D(\esssup X)$, we also have $D(\esssup X)\neq\emptyset$. Then, by self-infeasibility, we can find $\underline{r}\in D(\esssup X)$ such that
\begin{equation}\label{eq:infeas}
\Lambda_i(\esssup X,(\underline{r}_i-\varepsilon,m_{-i}))<0
\end{equation}
for every $m\in D(\esssup X)$, $i\in[N]$, and $\varepsilon>0$.

For each $m\in\R^N$ and $i\in[N]$, we define
\[
\phi^X_i(m) \coloneqq \inf\{r_i \in \R \; | \; \Lambda_i(X,(r_i,m_{-i})) \in \A\}.
\]
Let us fix $m\in D(X)=D(\essinf X)$ and $i\in[N]$. Then, by monotonicity and \eqref{eq:feas},
\begin{align*}
\phi^X_i(m)&\leq \inf\{r_i\in\R\; | \; \Lambda_i(X,(r_i,m_{-i}))\geq 0\}\\
&\leq \inf\{r_i\in\R\; | \; \Lambda_i(\essinf X,(r_i,m_{-i}))\geq 0\}\leq \bar{r}_i.
\end{align*}
Let $\varepsilon>0$. By monotonicity and \eqref{eq:infeas},
\[
\Lambda_i(X,(\underline{r}_i-\varepsilon,m_{-i}))\leq \Lambda_i(\esssup X,(\underline{r}_i-\varepsilon,m_{-i}))<0 \text{ a.s.}.
\]
Then, by the properties of $\rho$ as a coherent risk measure, we have
\[
\rho(\Lambda_i(X,(\underline{r}_{i}-\varepsilon,m_{-i})))\geq \rho(\Lambda_i(\esssup X,(\underline{r}_{i}-\varepsilon,m_{-i})))=-\Lambda_i(\esssup X,(\underline{r}_{i}-\varepsilon,m_{-i}))>0,
\]
Hence, $\Lambda_i(X,(\underline{r}_i-\varepsilon,m_{-i}))\notin \A$ and, by monotonicity, we have $\phi^X_i(m)\geq \underline{r}_i-\varepsilon$. Since $\varepsilon>0$ is arbitrary, we conclude that $\phi^X_i(m)\geq \underline{r}_i$. Therefore, $\phi^X(m)\in [\underline{r},\bar{r}]$ for every $m\in D(X)$. In particular, since $\bar{r}\in D(\essinf X)=D(X)$, we have $\phi^X(\bar{r})\in [\underline{r},\bar{r}]$. On the other hand, since $\phi^X$ is decreasing by construction, we have $m\leq \bar{r}$ implies $\phi^X(\bar{r})\leq \phi^X(m)$. 

We claim that $\phi^X(\bar{r})\in D(X)$ so that $[\phi^X(\bar{r}),\bar{r}]\subseteq D(X)$. The rectangular structure of $D(X)=D(\essinf X)$ ensures that $D(X)=\bigtimes_{i=1}^N A_i$, where, for each $i\in[N]$, we have $A_i=\R$ or $A_i=[\bar{m}_i,+\infty)$ for some $\bar{m}_i\in\R$. Let us fix $i\in [N]$. We may write
\[
\phi^X_i(\bar{r})=\inf\{r_i\in A_i\mid \Lambda_i(X,(r_i,\bar{r}_{-i}))\in\A\}.
\]
Since $\phi^X_i(\bar{r})\geq \underline{r}_i>-\infty$ and $\rho$ is continuous from above, the above infimum is indeed a minimum so that $\phi^X_i(\bar{r})\in A_i$ as well. Hence, $\phi^X(\bar{r})\in D(\essinf X)=D(X)$. This finishes the proof of the claim.
Therefore, $\phi^X$ maps the compact subset $[\phi^X(\bar{r}),\bar{r}]$ of $D(X)$ into itself.


