\begin{remark}\label{rem:N=2}
Following Theorem~\ref{thm:exist-unique}\eqref{thm:exist-unique:2}, in the setting of $N = 2$ banks, there always exists a unique $(\A,(\Lambda_1,\Lambda_2))$-Nash allocation rule for a self-preferential decomposition $(\Lambda_1,\Lambda_2)$ of $\Lambda$.
However, as the number of banks $N$ in the system grow, the uniqueness condition of Theorem~\ref{thm:exist-unique}\eqref{thm:exist-unique:2} becomes more restrictive.
\end{remark}


\subsection{Application to Single-Element Aggregation Functions}\label{sec:single-element}

In this section, we consider applications of Theorem~\ref{thm:exist-unique} to the specific systemic risk measure structures of Example~\ref{ex:syst}. In so doing, we propose decomposition structures that can be used for different systemic risk measure structures based on single-element aggregation functions, e.g., the ones provided in Example~\ref{ex:se-aggregation}.
%We give special consideration to the single-element aggregation functions of Example~\ref{ex:se-aggregation}.

Throughout this section, we fix a single-element aggregation function $\bar\Lambda\colon \R^N\to \R\cup\{-\infty\}$. We first introduce a refinement of decompositions in Definition~\ref{defn:decomposition} that is applicable to $\bar\Lambda$.

\begin{definition}\label{defn:decsingle}
Let $\bar\Lambda_1,\dots,\bar\Lambda_N: \R^N \to \R\cup\{-\infty\}$ be single-element aggregation functions. The collection $(\bar\Lambda_i)_{i \in [N]}$ is called a \textbf{single-element decomposition} of $\bar\Lambda$ if the following properties hold:
\begin{enumerate}
\item \textbf{Consistent domain:} For each $i \in [N]$, it holds $\dom\bar\Lambda_i = \dom\bar\Lambda$.
%\item \textbf{Upper semicontinuous:} For each $i \in [N]$, the function $\bar\Lambda_i$ is upper semicontinuous.
\item \textbf{Dominated by $\bar\Lambda$:} It holds $\sum_{i \in [N]} \bar\Lambda_i(x) \leq \bar\Lambda(x)$ for every $x \in \R^N$.
%\item \notiz{\textbf{Self-monotone:} For each $i \in [N]$, it holds $x_i \mapsto \bar\Lambda_i(x_i,x_{-i})$ is increasing.}
\end{enumerate}
\end{definition}

\begin{example}\label{ex:decomposition}
Let us revisit the single-element aggregation functions in Example~\ref{ex:se-aggregation} and propose single-element decompositions for them. %the derived sensitive aggregation function (see Example~\ref{ex:syst}), i.e., such that $\Lambda_i(x,m) \coloneqq \bar\Lambda_i(x+m)$ for every $i \in [N]$.
\begin{enumerate}
\item\label{util2} \textbf{Sum of univariate utilities:} For the single-element aggregation function $\bar\Lambda^U$ in Example~\ref{ex:se-aggregation}\eqref{util} and Example~\ref{ex:sen-ut}, for each $i \in [N]$ and $x\in\R^N$, let $\bar\Lambda_i^U(x)\coloneqq u_i(x_i)$ if $x\in \dom\bar\Lambda^U$ and $\bar\Lambda_i^U(x)\coloneqq -\infty$ otherwise. Clearly, $\bar\Lambda_1^U,\ldots,\bar\Lambda_N^U$ are upper semicontinuous since $u_1,\ldots,u_N$ are upper semicontinuous functions. Moreover, we have $\sum_{i\in [N]}\bar\Lambda^U_i(x)=\bar\Lambda^U(x)$ for every $x\in\R^N$. Hence, $(\bar\Lambda^U_i)_{i\in[N]}$ is a single-element decomposition of $\bar\Lambda^U$. %The constructed decomposition is self-preferential as an immediate consequence of the monotonicity of $u_1,\ldots,u_N$.}
%Consider the sum of univariate utilities aggregation $\bar\Lambda^u(x) = \sum_{i \in [N]} u_i(x_i)$ for univariate utility functions $u_i: \R \to \R \cup \{-\infty\}$.
%From this construction, we can construct a \emph{natural decomposition} $\bar\Lambda^u_i(x) := u_i(x_i) + \ind_{\{x \in \dom\bar\Lambda\}}$ for every bank $i$ and any $x \in \R^N$.
%Trivially, if $0 \in \operatorname{range}u_i$ for every bank $i$, $(\bar\Lambda_i)_{i \in [N]}$ is a sensitive decomposition of $\Lambda$.
%
\item\label{fof2} \textbf{Fund of funds:} For the single-element aggregation function $\bar\Lambda^{FoF}$ in Example~\ref{ex:se-aggregation}\eqref{fof}, for each $i \in [N]$ and $x \in \R^N$, let $\bar\Lambda^{FoF}_i(x) \coloneqq x_i - \gamma_i x_i^+ - \gamma(x_i - \gamma_i x_i^+)^+$. Then, $(\bar\Lambda^{FoF}_i)_{i\in[N]}$ is a single-element decomposition of $\bar\Lambda^{FoF}$.
%As with the sum of univariate utilities, the derived decomposition is self-preferential because the aggregation for each bank is independent of all other institutions. 
We note that, in contrast to all other decompositions within this work, the fund of funds decomposition is typically strictly dominated by $\Lambda^{FoF}$ rather than guaranteeing an exact match between $\sum_{i\in[N]}\bar\Lambda^{FoF}_i$ and $\bar\Lambda^{FoF}$.
%
\item\label{mf2} \textbf{Mean-field utility:} Consider now the single-element aggregation function $\bar\Lambda^{MF}$ in Example~\ref{ex:se-aggregation}\eqref{mf}. %Consider now the generalization of the sum of univariate utilities so that each bank depends on the rest of the system based on the aggregate behavior, i.e., 
For each $i\in [N]$ and $x\in\R^N$, let $\bar\Lambda^{MF}_i(x) \coloneqq u_i(x_i , \frac{1}{N} \sum_{j \in [N]} x_j)$ if $x \in \dom\bar\Lambda^{MF}$ and $\bar\Lambda^{MF}_i(x) \coloneqq -\infty$ otherwise. Then, $(\bar\Lambda^{MF}_i)_{i\in[N]}$ is a single-element decomposition of $\bar\Lambda^{MF}$ satisfying $\sum_{i\in[N]}\bar\Lambda^{MF}_i(x)=\bar\Lambda^{MF}(x)$ for each $x\in\R^N$.
%The derived decomposition $(\Lambda_i^{MF})_{i \in [N]}$ is a self-preferential decomposition if $\inf_{(x^1,x^2) \in \R^2} \{\frac{\partial}{\partial x^1} u_i(x^1,x^2) \; | \; \frac{\partial}{\partial x^2} u_i(x^1,x^2) \geq 0\} > 0$ for every bank $i \in [N]$.}
\end{enumerate}
\end{example}

\subsubsection{Insensitive Systemic Risk Measures}\label{sec:nash-insensitive}
Throughout this section, we consider the insensitive systemic risk measures discussed in Example~\ref{ex:syst}. To that end, corresponding to the single-element aggregation function $\bar\Lambda\colon\R^N\to\R\cup\{-\infty\}$, we define the insensitive aggregation function $\Lambda^I\colon\R^N\times\R^N\to\R\cup\{-\infty\}$ by \eqref{eq:lambda-ins}:
\[
\Lambda^I(x,m)\coloneqq \bar\Lambda(x)+\sum_{i\in [N]}m_i
\]
for each $x,m\in\R^N$. Recall that we have $L^\infty_{\Lambda^I}(\R^N)=L^\infty(\dom\bar\Lambda)$ in this setting. 
The following corollary characterizes the \emph{unique} Nash allocation rule that exists for any insensitive systemic risk measure.

\begin{corollary}\label{cor:insensitive}
% (
% \rev{Let $(\bar\Lambda_i)_{i\in[N]}$ be a collection of upper semicontinuous functions with domain $\dom\bar\Lambda_i = \dom\bar\Lambda$ for every bank $i \in [N]$.
% Further, assume that this collection of functions is dominated by $\bar\Lambda$ (i.e., $\sum_{i \in [N]} \bar\Lambda_i(x) \leq \bar\Lambda(x)$ for every $x \in \dom\bar\Lambda$).}
Let $(\bar\Lambda_i)_{i\in[N]}$ be a single-element decomposition of $\bar\Lambda$.
For each $i\in[N]$, define a function $\Lambda^I_i\colon \R^N\times\R^N\to\R\cup\{-\infty\}$ by
\[
\Lambda^I_i(x,m)\coloneqq \bar\Lambda_i(x)+m_i
\]
for every $x,m\in \R^N$.
%Let $(\bar\Lambda_i)_{i \in [N]}$ be a collection of single-element aggregation functions dominated by $\bar\Lambda$ \rev{such that $\dom\bar\Lambda_i = \dom\bar\Lambda$ for every $i$} \notiz{$\bigcap_i\dom\bar\Lambda_i = \dom\bar\Lambda$?}.
%Consider a stress scenario $X \in L^\infty(\dom\bar\Lambda)$. 
Then, $(\Lambda_i^I)_{i\in[N]}$ is a self-preferential decomposition of $\Lambda^I$ with $L = 0$.
Moreover, the unique $(\A,(\Lambda_i^I)_{i\in [N]})$-Nash allocation rule $r^I\colon L^\infty(\dom\bar\Lambda)\to\R^N$ is given by
\[
r^I(X):=\of{\rho(\bar\Lambda_1(X)),\ldots,\rho(\bar\Lambda_N(X))}^\T
\]
for every $X\in L^\infty(\dom\bar\Lambda)$.
\end{corollary}
\begin{proof}
It is easy to verify that $(\Lambda_i^I)_{i\in[N]}$ is a self-preferential decomposition of $\Lambda^I$ with $L = 0$. Then, by Theorem~\ref{thm:exist-unique}\eqref{thm:exist-unique:2}, there exists a unique Nash allocation rule $r^I\colon L^\infty(\dom\bar\Lambda) \to \R^N$.
It remains to show that $r^I$ has the form provided in the statement of the corollary.
Let $X\in L^\infty(\dom\bar\Lambda)$. Then, a $(\A,(\Lambda_i^I)_{i\in [N]})$-Nash allocation rule $r^I\colon L^\infty(\dom\bar\Lambda)\to\R^N$ must satisfy
\begin{align*}
r^I_i(X)&=\inf\cb{m_i\in\R\; | \; \Lambda^I_i(X,(m_i,r^I_{-i}(X)))\in\A}\\
&=\inf\cb{m_i\in\R\; | \; \bar\Lambda_i(X)+m_i\in\A}=\rho(\bar\Lambda_i(X)),
\end{align*}
which follows trivially from the primal representation of the risk measure $\rho$ (Proposition~\ref{prop:riskmsr-primal}) and the definition of $\Lambda_i^I$.
\end{proof}

%When considering the insensitive systemic risk measures, we will often call the decomposition $(\Lambda_i^I)_{i \in N}$ constructed in Corollary~\ref{cor:insensitive} the \emph{natural decomposition} of $\Lambda^I$.


\subsubsection{Sensitive Systemic Risk Measures}\label{sec:nash-sensitive}

We now turn our attention to the more complex interconnections within the sensitive systemic risk measures, that is, we consider the sensitive aggregation function $\Lambda^S\colon\R^N\times\R^N\to\R\cup\{-\infty\}$ defined by \eqref{eq:lambda-sen}:
\[
\Lambda^S(x,m)\coloneqq \bar\Lambda(x+m)
\]
for each $x,m\in \R^N$. Recall that we have $L^\infty_{\Lambda^S}(\R^N)=L^\infty(\R^N)$ in this setting.

\begin{corollary}\label{cor:sensitive}
Let $(\bar\Lambda_i)_{i \in [N]}$ be a single-element decomposition of $\bar\Lambda$ that satisfies the following properties:
\begin{enumerate}
\item \textbf{Self-feasible:} There exists $\bar{x} \in \dom\bar\Lambda$ such that $\bar\Lambda_i(\bar{x}_i,x_{-i}) \geq 0$ for every $x \in \dom\bar\Lambda$ and $i \in [N]$.
\item \textbf{Self-infeasible:} There exists $\underline{x} \in \dom\bar\Lambda$ such that $-\infty \leq \bar\Lambda_i(\underline{x}_i-\varepsilon,x_{-i}) < 0$ for every $x \in \dom\bar\Lambda$, $i \in [N]$, and $\varepsilon > 0$.
\item \textbf{Self-preferential:} There exists a constant $L\in [0,1)$ such that, for every $i,j\in[N]$ with $i \neq j$, $x\in\dom\bar\Lambda$, and $\delta\geq 0$, it holds $\bar\Lambda_i(x+L\delta e_i) \geq \bar\Lambda_i(x+\delta e_j)$.
\end{enumerate}
For each $i\in [N]$, define a function $\Lambda^S_i\colon \R^N\times\R^N\to \R\cup\{-\infty\}$ by
\begin{equation}\label{eq:sen-dec}
\Lambda^S_i(x,m)\coloneqq \bar\Lambda_i(x+m)
\end{equation}
for every $x,m\in\R^N$. Then, $(\Lambda^S_i)_{i\in [N]}$ is a self-preferential decomposition of $\Lambda^S$. Moreover, there exists a Nash allocation rule $r^S\colon L^\infty(\R^N)\to\R^N$.
\end{corollary}
\begin{proof}
Immediately, we observe that $\Lambda^S_1,\ldots,\Lambda^S_N$ are aggregation functions and $(\Lambda^S_i)_{i\in[N]}$ satisfies the consistent domain property, it is dominated by $\Lambda^S$, and it is self-preferential. It remains to show that self-feasibility and self-infeasibility hold.
\begin{itemize}
\item \textbf{Self-feasible:} Let $x \in \R^N$ with $D(x) \neq \emptyset$ and define $\bar{r} := \bar{x} - x$. We have $\bar{r}\in D(x)$ since, by construction, $x + \bar{r}= \bar{x} \in \dom\bar\Lambda$. Let $m \in D(x)$, i.e., $x + m \in \dom\bar\Lambda$. Then, for every $i\in[N]$, we have
\[
\Lambda_i^S(x,(\bar r_i , m_{-i})) = \bar\Lambda_i(x+(\bar r_i,m_{-i})) = \bar\Lambda_i(\bar x_i , x_{-i} + m_{-i}) \geq 0.
\]
%
\item \textbf{Self-infeasible:} Let $x \in \R^N$ with $D(x) \neq \emptyset$ and define $\underline{r}:= \underline{r} - x$. We have $\underline{r} \in D(x)$ since, by construction, $x + \underline{r} = \underline{x} \in \dom\bar\Lambda$. Let $m \in D(x)$, i.e., $x + m \in \dom\bar\Lambda$. Then, for every $i\in[N]$ and $\varepsilon > 0$, we have
\[
\Lambda_i^S(x,(\underline r_i-\varepsilon,m_{-i})) = \bar\Lambda_i(x+(\underline r_i-\varepsilon,m_{-i})) = \bar\Lambda_i(\underline x_i-\varepsilon , x_{-i} + m_{-i}) < 0.
\]
\end{itemize}
Then, by Theorem~\ref{thm:exist-unique}\eqref{thm:exist-unique:1}, the existence of a Nash allocation rule follows.
\end{proof}

%\notiz{Add in corollary for existence? Besides being a single-element decomposition, need (4) bounded 0-superlevel set ($\forall x \in \R^N, \forall i \in [N], \exists \underline{r}_i \in \R:~\{m \in \R^N \; | \; \bar\Lambda_i(x+m) \geq 0\} \subseteq \{m \in \R^N \; | \; m_i \geq \underline{r}_i\}$) and (5) strongly self-feasible ($\forall x \in \R^N, \exists \overline{r} \in D(x):~\bar\Lambda_i(x+(\overline{r}_i,m_{-i})) \geq 0 \forall m \in D(x) \forall i \in [N]$) to satisfy Theorem~\ref{thm:exist-unique}\eqref{thm:exist-unique:1}}

As opposed to the insensitive systemic risk measures (Section~\ref{sec:nash-insensitive}), the Nash allocations for sensitive systemic risk measures strongly depend on the aggregation function and its chosen decomposition. To demonstrate how the Nash allocations fit within the scheme of sensitive systemic risk measures, we will revisit the single-element aggregation functions and decompositions from Example~\ref{ex:decomposition}.

\begin{example}\label{ex:nash}
We consider the single-element aggregation functions and their associated decompositions in Example~\ref{ex:decomposition}. 
\begin{enumerate}
\item\label{ex:nash-utility} \textbf{Sum of univariate utilities:} Let us take $\bar\Lambda=\bar\Lambda^U$ and $\bar\Lambda_i=\bar\Lambda^U_i$ for each $i\in[N]$ as defined in Example~\ref{ex:decomposition}\eqref{util2}. Under the assumption that $\{x_i \in \dom u_i \; | \; u_i(x_i) \geq 0\} \not\in \{\emptyset,\R\}$ for each $i \in [N]$, 
%\rev{Under the assumption that $0\in \interior \dom u_i$ for each $i\in[N]$, 
it is easy to verify the properties in Corollary~\ref{cor:sensitive}.
Hence, the corresponding collection $(\Lambda^{S}_i)_{i\in[N]}$ defined by \eqref{eq:sen-dec} is a self-preferential decomposition of the sensitive aggregation function $\Lambda^S$, as was also argued directly in Example~\ref{ex:sen-ut}. 
As with the insensitive systemic risk measures (Section~\ref{sec:nash-insensitive}), there are no interactions between the capital requirements of the banks under this decomposition. Therefore, similar to the proof of Corollary~\ref{cor:insensitive}, it follows that there exists a \emph{unique} $(\A,(\Lambda_i^S)_{i \in [N]})$-Nash allocation rule $r^S\colon L^\infty(\R^N)\to\R^N$ given by %with $X_i \in \dom u_i$ a.s. In fact, this Nash allocation can be fully characterized via the optimization problems:}
\[
r_i^S(X) = \inf\{m_i \in \R \; | \; u_i(X_i+m_i) \in \A\}
\]
for each $X\in L^\infty(\R^N)$ and $i\in[N]$.
\item \textbf{Fund of funds:} Let us take $\bar\Lambda=\bar\Lambda^{FoF}$ and $\bar\Lambda_i=\bar\Lambda^{FoF}_i$ for each $i\in [N]$ as in Example~\ref{ex:decomposition}\eqref{fof2}. %Recall the fund of funds decomposition $\bar\Lambda^{FoF}_i(m) \coloneqq m_i - \gamma_i m_i^+ - \gamma(m_i - \gamma_i m_i^+)^+$ from Example~\ref{ex:decomposition}. 
For this decomposition, it is easy to verify the properties of Corollary~\ref{cor:sensitive}.
Similar to the sum of univariate utilities, the decomposition is such that all banks model their risk independently of each other. As such, there exists a \emph{unique} $(\A,(\Lambda_i^{S})_{i \in [N]})$-Nash allocation rule $r^S\colon L^\infty(\R^N) \to \R^N$ given by
\[
r_i^S(X) = \inf\{m_i \in \R \; | \; X_i+m_i - \gamma_i(X_i+m_i)^+ - \gamma(X_i+m_i-\gamma_i(X_i+m_i)^+)^+ \in \A\}
\]
for each $X\in L^\infty(\R^N)$ and $i\in [N]$.
%
\item \textbf{Mean-field utility:} Let us take $\bar\Lambda=\bar\Lambda^{MF}$ and $\bar\Lambda_i=\bar\Lambda^{MF}_i$ for each $i\in [N]$ as in Example~\ref{ex:decomposition}\eqref{mf2}. 
For simplicity, suppose that $\dom\bar\Lambda=\underline{x}+\R^N_+$ for some $\underline{x}\in\R^N$ and that $u_i$ is concave and continuously differentiable on its domain with gradient function $(\partial_1u_i,\partial_2u_i)$ for each $i\in[N]$. In this case, it is easy to verify that Corollary~\ref{cor:sensitive} applies if there exists some $\bar x \geq \underline{x}$ such that $u_i(\bar x_i , \frac{1}{N} \bar x_i + \frac{1}{N} \sum_{j \neq i} \underline{x}_j) \geq 0$ for every $i\in[N]$ (for self-feasibility)
%\notiz{(self-feasible), 
%$u_i(\underline{x}_i-\varepsilon,a) = -\infty <0$ for every $\varepsilon>0$ and $i\in[N]$ (self-infeasible),} 
and
\[
%\sup_{x \geq \underline x}\left(\frac{\frac{\partial}{\partial \notiz{x^2}} u_i(x_i,\frac{1}{N}\sum_{j \in [N]} x_j)}{N \frac{\partial}{\partial \notiz{x^1}} u_i(x_i,\frac{1}{N}\sum_{j \in [N]} x_j) + \frac{\partial}{\partial \notiz{x^2}} u_i(x_i,\frac{1}{N}\sum_{j \in [N]} x_j)}\right) < 1
\inf_{\substack{x \geq \underline{x} \\ \delta \geq 0}} \frac{\partial_1 u_i\of{x_i+\delta,\frac{1}{N}\sum_{j\in[N]}x_j + \frac{1}{N}\delta}}{\partial_2 u_i\of{x_i,\frac{1}{N}\sum_{j\in[N]}x_j + \frac{1}{N}\delta}}> 0
\]
for every $i \in [N]$ (for being self-preferential).\footnote{Self-infeasibility follows directly from the construction of the domain $\dom\bar\Lambda = \underline{x} + \R^N_+$.}
%\notiz{\begin{itemize}
%\item Self-feasible: Assume $A_i = \R_+$ for every $i$, i.e., $\dom\bar\Lambda^{MF} = \R^N_+$. Assume there exists $\bar x_i \geq 0$ such that $u_i(\bar x_i , \frac{1}{N} \bar x_i) \geq 0$ for every $i \in [N]$.
%\item Self-infeasible: Assume $A_i = \R_+$ for every $i$, i.e., $\dom\bar\Lambda^{MF} = \R^N_+$, then $\underline{x} = 0$. 
%\item Self-preferential: $\sup_{x \in \dom u_i}\left(\frac{\frac{\partial}{\partial x^2} u_i(x_i,\frac{1}{N}\sum_{j \in [N]} x_j)}{N \frac{\partial}{\partial x^1} u_i(x_i,\frac{1}{N}\sum_{j \in [N]} x_j) + \frac{\partial}{\partial x^2} u_i(x_i,\frac{1}{N}\sum_{j \in [N]} x_j)}\right) < 1$ for every $i \in [N]$
%\end{itemize}}
Because of the possible interactions between the firms in this case, it is no longer guaranteed that there exists a unique Nash allocation rule. However, despite the lack of a general theoretical guarantee, we find a unique Nash allocation for the following practical setting with $N=2$. Let us take $u_1=u_2\coloneqq\bar{u}$, where $\bar{u}(x,\bar x) \coloneqq \log(\varepsilon+x) + \lambda \log(\varepsilon+\bar x)$ for each $x,\bar x \geq 0$ and $\bar{u}(x,\bar x)=-\infty$ otherwise, for some fixed $\varepsilon \in (0,1),\lambda > 0$. Then, every $(\A,(\Lambda_i^{S})_{i \in [N]})$-Nash allocation rule $r^S$ is uniquely evaluated at $X = 0$ a.s.\ as $r_1^S(0)=r_2^S(0) = 1-\varepsilon$.
\end{enumerate}
\end{example}

% Theorem~\ref{thm:exist-unique} immediately implies the uniqueness of the Nash allocation for any self-preferential decomposition in the $N = 2$ bank setting. 
% As the number of banks $N$ in the system grow, the uniqueness condition of Theorem~\ref{thm:exist-unique} becomes more restrictive. 

Despite most prior examples admitting unique Nash allocation rules, it is possible to construct self-preferential decompositions with multiple Nash allocation rules. In the following example we find a continuum of Nash allocations, which highlights the importance of choosing the decomposition appropriately.

\begin{example}\label{ex:nonunique}
Consider a system with $N = 3$ banks and a weighted summation aggregation function $\bar\Lambda\colon \R^N \to \R \cup \{-\infty\}$ defined by $\bar\Lambda(x) \coloneqq 1.5 x_1 + 1.5 x_2 + 2.25 x_3 - 3$ if $x \in \R^N_+$ and $\bar\Lambda(x)\coloneqq -\infty$ otherwise. This can be considered as a special case of sum of univariate utilities decomposed as $\bar\Lambda^U_1(x)=u_1(x_1)=1.5x_1-1$, $\bar\Lambda^U_2(x)=u_2(x_2)=1.5x_2-1$, $\bar\Lambda^U_3(x)=u_3(x_3)=2.25x_3-1$ for $x\in \R^N_+$ and $\bar\Lambda^U_1(x)=\bar\Lambda^U_2(x)=\bar\Lambda^U_3(x)=-\infty$ otherwise. %The natural decomposition, as with the aggregate utility, is such that every bank only depends on itself (e.g., $\bar\Lambda_1(x) = 1.5 x_1 - 1$);
This decomposition is associated with a unique associated Nash allocation rule as presented in Example~\ref{ex:nash}\eqref{ex:nash-utility}. Let us consider instead the alternative decomposition $\bar\Lambda_i(x) = a_i^\T x - 1$ for every $i\in[N]$ with $a_1 \coloneqq (1 , 0 , 0.75)^\T$, $a_2\coloneqq (0 , 1 , 0.75)^\T$, $a_3 \coloneqq (0.5 , 0.5 , 0.75)^\T$. In this case, for each $t\in [0,1]$, there exists a $(\A,(\Lambda_i^{S})_{i \in [N]})$-Nash allocation rule $r^S$ such that $r^S(0)=(1-t,1-t,4t/3)^\T$. 
%Fix $X = 0$ a.s.\ and any coherent acceptance set $\A$. The associated set of $(\A,(\bar\Lambda_i(X+\cdot))_{i \in [N]})$-Nash allocations is given by the set:
%\[\left\{(1-t,1-t,4t/3)^\T \; | \; t \in [0,1]\right\}.\]
Notably, in comparison to Example~\ref{ex:nash}\eqref{ex:nash-utility} above, there are infinitely many Nash allocation rules with this decomposition. % number of Nash allocations associated with this alternative decomposition.
As a consequence, it is clear that the choice of the decomposition can greatly influence the set of Nash allocation rules in practice. %and should be chosen carefully.
\end{example}


\subsubsection{Scenario-Dependent Systemic Risk Measures}\label{sec:nash-cooperative}
Finally, we consider the scenario-dependent systemic risk measures, that is, we consider the aggregation function $\Lambda^{SD}: \R^N \times \R^N \to \R \cup \{-\infty\}$ defined by \eqref{eq:lambda-coop} for some single-element aggregation function $\bar\Lambda: \R^N \to \R \cup \{-\infty\}$.

\begin{proposition}\label{prop:coop-decomp}
Fix a single-element aggregation function $\bar\Lambda: \R^N \to \R \cup \{-\infty\}$. If $(\Lambda_i)_{i \in [N]}$ is a (self-preferential) decomposition of $\Lambda^S$, then it is also for $\Lambda^{SD}$.
\end{proposition}
\begin{proof}
The decomposition depends on the original aggregation function only through the domination property. Since $\Lambda^S(x,m) \leq \Lambda^{SD}(x,m)$ for every $x,m \in \R^N$ by construction, the result holds trivially.
\end{proof}
As the decomposition constructed in Proposition~\ref{prop:coop-decomp} does not take advantage of scenario-dependency, we will often call $\Lambda_i^{SD}(x,m) \coloneqq \bar\Lambda_i(x+m)$, $x,m\in\R^N$, $i\in[N]$, the \emph{naive decomposition} of $\Lambda^{SD}$.
While the above observation shows that the scenario-dependent decomposition can be reduced to those found with the sensitive aggregation function, we find that constructing a scenario-dependent decomposition is non-trivial. 
