%where, for each $i\in\{1,\ldots,N\}$, the function $u_i^\ast$ is the concave conjugate of $u^\ast_i$ defined by $u_i(\lambda):=\sup_{y_i\in\R}(u_i(y_i)-\lambda y_i)$ for each $\lambda\in\R_+$.

\begin{remark}
We leave further considerations for the decomposition of the scenario-dependent aggregation function $\Lambda^{SD}$ for future work. For the purposes of this work, we will apply the naive decomposition so that the Nash allocation rules determined under this setting coincide exactly with those found under the sensitive systemic risk measure. For this reason, we refer the reader to Examples~\ref{ex:nash} and~\ref{ex:nonunique} for examples of Nash allocation rules in this systemic risk setting.
\end{remark}


\section{Case Study: Eisenberg-Noe Aggregation}\label{sec:EN}

For the remainder of the paper, we will consider an aggregation function derived from the \cite{eisenberg2001systemic} clearing payments. In contrast to the aggregate utility functions which motivated our proposed structure, the Eisenberg-Noe aggregation function has complex dependencies between the banks within its natural decomposition.
As far as the authors are aware, the Eisenberg-Noe aggregation function was first proposed in~\cite{feinstein2017measures}, though it is a special case of the optimization aggregation function in \citet[Example~4]{chen2013axiomatic} and is closely related to the contagion aggregation function in \citet[Example~7]{chen2013axiomatic}.

\subsection{Eisenberg-Noe Aggregation and Decomposition}\label{sec:EN-background}

Consider a system of $N$ banks that are interconnected via payment obligations. For each $i,j\in[N]$, we let $\bar p_{ij} \geq 0$ denote the obligations that bank $i$ owes to bank $j$; we set $\bar p_{ii} = 0$ to avoid self-dealing. In addition, each bank $i$ also has an obligation $\bar p_{i0} > 0$ external to the financial system; we often refer to these obligations as those due to ``society''. The ~\cite{eisenberg2001systemic} clearing system assumes that these obligations are repaid proportionally. Therefore, from this construction, we set $\pi_{ij} = \bar p_{ij} / \sum_{k = 0}^N \bar p_{ik}$ to be the relative liability of bank $i\in [N]$ to entity (bank or society) $j \in [N]\cup\{0\}$. Assuming that the $N$ banks hold external assets worth $x\in \R^N_+$ and following the priority of debt over equity and limited liabilities, a \emph{clearing payment vector} $p(x)\in\R^N$ is defined a solution of the fixed point equation
\begin{equation}\label{eq:EN}
p_i(x) = \min\left\{\sum_{j = 0}^N \bar p_{ij} \; , \; x_i + \sum_{j = 1}^N \pi_{ji} p_j(x)\right\}, \quad i \in[N].
\end{equation}
Immediately, by applying Tarski fixed point theorem, there exists greatest and least clearing payment vectors for $x \in \R^N_+$. Moreover, as provided by \citet[Theorem 2]{eisenberg2001systemic}, we recover a unique clearing payment vector $p(x)$ for every $x \in \R^N_+$ due to the strictly positive obligations to society. In the following proposition, we provide properties of the clearing payment vector.

\begin{proposition}\label{prop:EN}
Consider a financial network of $N$ banks with obligations $\bar p \in \R^{N \times (N+1)}_+$ satisfying $\bar p_{i0} > 0$ for each $i\in [N]$. For every asset level $x \in \R^N_+$, there exists a unique clearing payment vector $p(x) \in \R^N_+$ satisfying \eqref{eq:EN}. Furthermore, the function $p\colon \R^N_+ \to \R^N_+$ is non-expansive\footnote{That is, $\sum_{i\in[N]}|p_i(x)-p_i(x^\prime)|\leq \sum_{i\in[N]}|x_i-x^\prime_i|$ for every $x,x^\prime\in\R^N_+$.}, concave, increasing, submodular, and it holds $p_j(x + \delta e_i) \leq p_j(x + \delta \pi_{i\cdot})$ for every $i,j\in[N]$ with $i \neq j$, $x \in \R^N_+$, and $\delta \geq 0$.
\end{proposition}

\begin{proof}
Due to the strictly positive obligations to society, the provided system is a regular network as per \citet[Definition 5]{eisenberg2001systemic}. Therefore, by \citet[Theorem 2]{eisenberg2001systemic}, the uniqueness of the clearing payment vector $p(x)$ follows for every $x \in \R^N_+$. Furthermore, by \citet[Lemma 5]{eisenberg2001systemic}, the clearing payment function $p\colon \R^N_+\to\R^N_+$ is concave, increasing, and non-expansive; its submodularity follows from \citet[Proposition A.7]{banerjee2022pricing}.

Finally, let us fix $i\in[N]$, $x \in \R^N_+$, and $\delta \geq 0$. Note that $p_i(x + \delta \pi_{i\cdot}) + \delta \geq p_i(x) + \delta \geq p_i(x + \delta e_i)$ by a simple application of the monotonicity and non-expansiveness of the clearing payment function. Let $J \coloneqq \{j \in [N]\setminus\{i\} \; | \; p_j(x + \delta \pi_{i\cdot}) < \sum_{k = 0}^N \bar p_{jk}\}$ be the collection of banks (not $i$) that fail to make their payments in full under asset level $x+\delta\pi_{i\cdot}\in\R^N_+$. For every $j \in J^c:=([N]\setminus\{i\})\setminus J$, we have $p_j(x + \delta \pi_{i\cdot}) = \sum_{k = 0}^N \bar p_{jk} \geq p_j(x + \delta e_i)$ by construction. Assume that $J \neq \emptyset$ as otherwise the proof is completed. By the construction of clearing payments, with an abuse of notation for sub-vectors and sub-matrices, we have
\begin{align*}
p_J(x + \delta \pi_{i\cdot}) &= x_J + \pi_{iJ}^\T [p_i(x + \delta \pi_{i\cdot}) + \delta] + \pi_{J^c J}^\T \sum_{k = 0}^N \bar p_{J^c k} + \pi_{JJ}^\T p_J(x + \delta \pi_{i\cdot}) \\
&= (I_{|J|} - \pi_{JJ}^\T)^{-1} \left(x_J + \pi_{iJ}^\T [p_i(x + \delta \pi_{i\cdot}) + \delta] + \pi_{J^c J}^\T \sum_{k = 0}^N \bar p_{J^c k}\right) \\
&\geq (I_{|J|} - \pi_{JJ}^\T)^{-1} \left(x_J + \pi_{iJ}^\T p_i(x + \delta e_i) + \pi_{J^c J}^\T p_{J^c}(x + \delta e_i)\right) \geq p_J(x).
\end{align*}
In this calculation, the second line follows from rearranging terms and noting, due to the obligations to society, that $I_{|J|} - \pi_{JJ}^\T$ is invertible. The first inequality takes advantage of the positivity of the Leontief inverse as well as bounds on $p_k(x + \delta \pi_{i\cdot})$ for $k \in J^c \cup \{i\}$. The final inequality follows directly from the construction of the clearing payments.
\end{proof}

As detailed in, e.g.,~\cite{feinstein2017measures}, the payments to society form a meaningful aggregation function for measuring systemic risk. The idea is that, \textit{a priori}, a regulator does not care if a bank fails; instead, the risks are whether these failures spread to society, i.e., the real economy. Assuming that the regulator requires at least $\gamma \in (0,1)$ fraction of all obligations to society to be repaid, the corresponding \emph{Eisenberg-Noe aggregation function} $\bar\Lambda^{EN}: \R^N \to \R$ is defined by
\begin{equation*}%\label{eq:EN-agg}
\bar\Lambda^{EN}(x) := \sum_{i \in [N]} \left(\pi_{i0} p_i(x) - \gamma \bar p_{i0}\right)
\end{equation*}
for every $x \in \R^N_+$, and by $\bar\Lambda^{EN}(x):=-\infty$ otherwise.  

Immediately upon the introduction of the single-element aggregation function $\bar\Lambda^{EN}$, there is a natural decomposition. Specifically, rather than aggregating all payments to society together, the regulator can impose the condition that each bank $i\in[N]$ needs to cover $\gamma$ fraction of its own obligations to society, i.e., we may define
\[
\bar\Lambda^{EN}_i(x) := \pi_{i0} p_i(x) - \gamma \bar p_{i0}
\]
whenever $x \in \R^N_+$, and $\bar\Lambda^{EN}_i(x):=-\infty$ otherwise. It can trivially be verified that $(\bar\Lambda^{EN}_i)_{i\in[N]}$ is a single-element decomposition of $\bar\Lambda^{EN}$ in the sense of Definition~\ref{defn:decsingle}.

\begin{proposition}\label{prop:EN-decomp}
Consider a financial network of $N$ banks with obligations $\bar p \in \R^{N \times (N+1)}_+$ satisfying $\bar p_{i0} > 0$ for each $i\in [N]$. The collection $(\bar\Lambda_i^{EN})_{i \in [N]}$ is a single-element decomposition of the Eisenberg-Noe aggregation function $\bar\Lambda^{EN}$ satisfying all properties in Corollary~\ref{cor:sensitive} with a self-preferential constant $L$ that satisfies
\[
L \leq \max_{\lambda\in \{0,1\}^N}\max_{\substack{i,j\in [N]\colon\\ i\neq j}} \frac{[(I_N - \diag(\lambda)\pi)^{-1}]_{ij}}{[(I_N - \diag(\lambda)\pi)^{-1}]_{jj}}\leq \max_{i\in [N]}(1-\pi_{i0})<1.
\]
%where $0/0 = 0$ by convention.
\end{proposition}

\begin{proof}
First, we note that $\dom\bar\Lambda_i^{EN} = \dom\bar\Lambda^{EN} = \R^N_+$ for all banks $i\in[N]$, hence the consistent domain property holds. Additionally, we have $\sum_{i\in[N]}\bar\Lambda^{EN}_i=\bar\Lambda^{EN}$ so that $(\bar\Lambda^{EN}_i)_{i\in[N]}$ is dominated by $\bar\Lambda^{EN}$. It remains to show that the additional properties in Corollary~\ref{cor:sensitive} hold. Self-feasibility and self-infeasibility follow with $\bar x_i := \sum_{j = 0}^N \bar p_{ij}$ and $\underline x_i := 0$ for every bank $i \in [N]$ as we have, trivially, $p_i(\bar x_i , x_{-i}) = \sum_{j = 0}^N \bar p_{ij}$ and $(\underline x_i-\varepsilon , x_{-i}) \not\in \R^N_+$ for every $x \in \R^{N}_+$ and $\varepsilon > 0$.
Finally, the exact formulation of the self-preferential constant $L$ comes from the worst case using the derivatives of the clearing payments as found in, e.g., \cite{liu2010sensitivity}, i.e., \[\frac{\partial}{\partial x_j} p_i(x) = [(I_N - \diag(\ind_{\{p(x) < \sum_{k = 0}^N \bar p_{\cdot k}\}})\pi^\T)^{-1}]_{ij}\ind_{\{p_j(x) < \sum_{k = 0}^N \bar p_{jk}\}}.\]
Therefore, locally in the default region $\lambda = \ind_{\{p(x) < \sum_{k = 0}^N \bar p_{\cdot k}\}}$, 
\[L(x) = \max_{\substack{i \neq j \\ \lambda_i = 1}} \frac{[(I_N - \diag(\lambda)\pi^\T)^{-1}]_{ij}\lambda_j}{[(I_N - \diag(\lambda)\pi^\T)^{-1}]_{ii}} = \max_{\substack{i \neq j \\ \lambda_j = 1}} \frac{[(I_N - \diag(\lambda)\pi)^{-1}]_{ji}\lambda_i}{[(I_N - \diag(\lambda)\pi)^{-1}]_{jj}}\]
where the equality follows from the use of the Leontief inverses $(I_N - \diag(\lambda)\pi^\T)^{-1}$ and $(I_N - \diag(\lambda)\pi)^{-1}$.
Immediately, the first inequality becomes clear:
\[L \leq \max_{\lambda\in \{0,1\}^N}\max_{\substack{i,j\in [N]\colon\\ i\neq j}} \frac{[(I_N - \diag(\lambda)\pi)^{-1}]_{ij}}{[(I_N - \diag(\lambda)\pi)^{-1}]_{jj}}.\]  
Next, we bound this constant by $\max_{i \in [N]} (1-\pi_{i0})$.

%Let us first consider the case $\lambda_i=1$ for every $i\in\{1,\ldots,N\}$. Note that
%\[
%(I-\pi)^{-1}=\sum_{n=0}^\infty \pi^n
%\]
%Let $E=\{0,1,\ldots,N\}$. We define $\tilde{\pi}=(\pi_{ij})_{i,j\in E}\in\R^{(N+1)\times (N+1)}_+$ to be the relative liabilities matrix of the extended network in which node $0$ represents society and nodes $1,\ldots,N$ represent the banks. Since society does not have any obligations to the banks, we take $\pi_{00}:=1$ and $\pi_{0j}:=0$ for each $j\in\{1,\ldots,N\}$. Hence, $\tilde{\pi}$ is a right stochastic matrix and we may view it as the one-step transition probability matrix of a time-homogeneous Markov chain with state space $E$. Clearly, state $0$ is the only recurrent state and all other states are transient. Moreover, since state $0$ is absorbing, given $i,j\in E\setminus\{0\}$, there is no path from $i$ to $j$ that goes through state $0$; in particular, the $n$-step transition probability can be calculated only by using the original matrix $\pi$ via
