Let us fix a binary vector $\lambda \in \{0,1\}^N$ and define $E(\lambda):=\{i\in [N]\; | \; \lambda_i=0\}$ and $E(\lambda)^c:=[N]\setminus E(\lambda)$. Note that $\diag(\lambda)\pi$ is the matrix obtained by replacing the $i^{\text{th}}$ row of $\pi$ with a row of zeroes for each $i\in E(\lambda)$. Let $\tilde{\pi}(\lambda)=(\pi_{ij}(\lambda))_{i,j\in[N]\cup\{0\}}\in\R^{(N+1)\times (N+1)}_+$ be the relative liabilities matrix of the extended network in which node $0$ represents society and nodes $1,\ldots,N$ represent the banks. Since society does not have any obligations to the banks, we take $\pi_{00}(\lambda):=1$ and $\pi_{0j}(\lambda):=0$ for each $j\in [N]$. Moreover, in this network, we assume that all banks in $E(\lambda)$ have their full obligations to society, i.e.,
\[
\pi_{ij}(\lambda)=\begin{cases}1 & \text{if } i\in E(\lambda)\cup\{0\},\ j=0,\\ 0 &\text{if }i\in E(\lambda)\cup\{0\},\ j\in [N],\\
\pi_{ij}& \text{if }i\in E(\lambda)^c,\ j\in [N]\cup\{0\}.\end{cases}
\]
Note that $\tilde{\pi}(\lambda)$ is a right stochastic matrix and we may view it as the one-step transition probability matrix of a time-homogeneous Markov chain with state space $[N]$. Clearly, state $0$ is the only recurrent state and all other states are transient. Moreover, since state $0$ is absorbing, given $i,j\in [N]$, there is no path from $i$ to $j$ that goes through state $0$; in particular, the corresponding multi-step transition probabilities can be calculated by only using the original matrix $\diag(\lambda)\pi$ via
\[
[(\diag(\lambda)\pi)^{n}]_{ij}=[(\tilde{\pi}(\lambda))^{n}]_{ij},\quad n\in\mathbb{Z}_+.
\]
Moreover, we have
\[
(I_N-\diag(\lambda)\pi)^{-1}=\sum_{n=0}^\infty (\diag(\lambda)\pi)^n,\quad (I_{N+1}-\tilde{\pi}(\lambda))^{-1}=\sum_{n=0}^\infty (\tilde{\pi}(\lambda))^n.
\]
Hence, for every $i,j\in [N]$, we also have
\[
[(I_N-\diag(\lambda)\pi)^{-1}]_{ij}=[(I_{N+1}-(\tilde{\pi}(\lambda))^{-1}]_{ij}.
\]

The matrix $a(\lambda)=(a_{ij}(\lambda))_{i,j\in [N]\cup\{0\}}:=(I_{N+1}-\tilde{\pi}(\lambda))^{-1}$ has a well-known interpretation in the theory of Markov chains. For each $j\in [N]\cup\{0\}$, let $N_j(\lambda)$ be the total number of visits of the chain to state $j$. Then, for each $i\in [N]\cup\{0\}$, we have $a_{ij}(\lambda)=\E_i [N_j(\lambda)]$, where $\E_i$ denotes the conditional expectation given that the chain starts at state $i$ at time zero. Since state $0$ is the unique absorbing state, we have $a_{0j}(\lambda)=0$ for every $j\in [N]$ and $a_{i0}(\lambda)=+\infty$ for every $i\in [N]\cup\{0\}$. %Moreover, for each $j\in E(\lambda)$, since $\pi_{j0}(\lambda)=1$, we have $r_{jj}(\lambda)=1$.

For every $i,j\in [N]$ with $i\neq j$, by \citet[Corollary~5.2.13]{cinlar1975}, we have
\[
a_{ij}(\lambda)=\mathbb{P}_i\{T_j(\lambda)<+\infty\}a_{jj}(\lambda),
\]
where $T_j(\lambda)$ is the first time that the chain visits state $j$ after time zero and $\mathbb{P}_i$ denotes the conditional probability given that the chain starts at state $i$ at time zero. Note that
\[
\mathbb{P}_i\{T_j(\lambda)=+\infty\}\geq \pi_{i0}(\lambda)=\begin{cases}1& \text{if } i\in E(\lambda),\\ \pi_{i0} & \text{if } i\in E(\lambda)^c.\end{cases}
\]
since state $0$ is absorbing. Hence, $\mathbb{P}_i\{T_j(\lambda)<+\infty\}=0$ if $i\in E(\lambda)$ and $\mathbb{P}_i\{T_j(\lambda)<+\infty\}\leq 1-\pi_{i0}$ if $i\in E(\lambda)^c$. Then, we get
\begin{align*}
\max_{\substack{i,j\in [N]\colon\\ i\neq j}}\frac{[(I_N-\diag(\lambda)\pi)^{-1}]_{ij}}{[(I_N-\diag(\lambda)\pi)^{-1}]_{jj}}&=\max_{\substack{i,j\in [N]\colon\\ i\neq j}}\frac{[(I_{N+1}-\tilde{\pi}(\lambda))^{-1}]_{ij}}{[(I_{N+1}-\tilde{\pi}(\lambda))^{-1}]_{jj}}=\max_{\substack{i,j\in [N]\colon\\ i\neq j}}\frac{a_{ij}(\lambda)}{a_{jj}(\lambda)}\\
&\leq \max_{\substack{i,j\in [N]\colon\\ i\neq j}}\mathbb{P}_i\{T_j(\lambda)<+\infty\}\leq \max_{i\in E(\lambda)^c}(1-\pi_{i0}).
\end{align*}
Therefore,
\[
L\leq\max_{\lambda\in \{0,1\}^N}\max_{\substack{i,j\in [N]\colon\\ i\neq j}}\frac{[(I_N-\diag(\lambda)\pi)^{-1}]_{ij}}{[(I_N-\diag(\lambda)\pi)^{-1}]_{jj}}
\leq \max_{\lambda \in \{0,1\}^N} \max_{i\in E(\lambda)^c}(1-\pi_{i0})=\max_{i\in E\setminus\{0\}} (1-\pi_{i0})<1
\]
since we assume that $\pi_{i0}>0$ for every $i\in [N]$.
\end{proof}

