\section{Analytical approximation for the on-shell modes}\label{app:analytic_modes}

To gain some analytical insight into the impact of $\lambda_{\rm ph}$ on the collective hybridized nematic-phonon modes, it is convenient to use the eigenvalues of Eq.~\eqref{eq:prop_matrix} (in the absence of the $-\omega^2 \mathds{1}$ part which will be reinstated later) to determine the poles. These modes are
\begin{equation}
    E_{\pm} = \frac{1}{2}\left( \widetilde{\chi}^{-1}_{\rm dres}(\mbf{q},\omega) + \widetilde{\mathcal{D}}_{\rm dres}^{-1}(\mbf{q},\omega)  \pm \left|\widetilde{\chi}^{-1}_{\rm dres}(\mbf{q},\omega) - \widetilde{\mathcal{D}}_{\rm dres}^{-1}(\mbf{q},\omega)\right|\sqrt{ 1 - \frac{4\Pi_{\rm ph-nem}(\mbf{q},\omega)^2}{\left[ \widetilde{\chi}^{-1}_{\rm dres}(\mbf{q},\omega) - \widetilde{\mathcal{D}}_{\rm dres}^{-1}(\mbf{q},\omega) \right]^2}} \right)\,,\label{eq:eigenvalues}
\end{equation}
where, for convenience, $\widetilde{\chi}^{-1}_{\rm dres}(\mbf{q},\omega)$ and $\widetilde{\mathcal{D}}^{-1}_{\rm dres}(\mbf{q},\omega)$ refer to the dressed propagators without the $-\omega^2$-term:
\begin{align}
    \widetilde{\chi}^{-1}_{\rm dres}(\mbf{q},\omega) &= r+v_n^2 q^2 + \Pi_{\rm nem}(\mbf{q},\omega)\\
    \widetilde{\mathcal{D}}^{-1}_{\rm dres}(\mbf{q},\omega) &= v_s^2 q^2 + \Pi_{\rm ph}(\mbf{q},\omega)
\end{align}
Expanding Eq.~\eqref{eq:eigenvalues} in powers of $\lambda_{\rm ph}^2\lambda_{\rm nem}^2$ to lowest order, we obtain
\begin{align}
    E_{\rm nem} &\approx \widetilde{\chi}_{\rm dres}^{-1}(\mbf{q},\omega) - \frac{\Pi_{\rm ph-nem}(\mbf{q},\omega)^2}{\widetilde{\chi}^{-1}_{\rm dres}(\mbf{q},\omega)-\widetilde{\mathcal{D}}^{-1}_{\rm dres}(\mbf{q},\omega)}\,, \label{eq:E_nem_approx} \\
    E_{\rm ph} &\approx \widetilde{\mathcal{D}}_{\rm dres}^{-1}(\mbf{q},\omega) + \frac{\Pi_{\rm ph-nem}(\mbf{q},\omega)^2}{\widetilde{\chi}^{-1}_{\rm dres}(\mbf{q},\omega)-\widetilde{\mathcal{D}}_{\rm dres}^{-1}(\mbf{q},\omega)}\,, \label{eq:E_ph_approx}
\end{align}
where, without loss of generality, we changed from $E_{\pm}$ to $E_{\rm nem}$ and $E_{\rm ph}$ to emphasize their relation to the unperturbed propagators. Here, $E_{\rm nem}$ originates from $E_+$ if $\widetilde{\chi}_{\rm dres}^{-1}(\mbf{q},\omega) > \widetilde{\mathcal{D}}_{\rm dres}^{-1}(\mbf{q},\omega)$ and from $E_{-}$ if $\widetilde{\chi}_{\rm dres}^{-1}(\mbf{q},\omega) < \widetilde{\mathcal{D}}_{\rm dres}^{-1}(\mbf{q},\omega)$ and vice versa for $E_{\rm ph}$. Focusing on the direction $\theta_{\mbf{q}}=\tfrac{\pi}{4}$, we let $r \rightarrow x + \lambda_{\rm nem}^2 \left(1 + \frac{\lambda_{\rm ph}^2}{v_s^2 - \lambda_{\rm ph}^2} \right)$  and expand Eqs.~\eqref{eq:E_nem_approx} and \eqref{eq:E_ph_approx} to third order in $\tfrac{\omega}{v_F q}$ and reinstate the diagonal $-\omega^2$-term resulting in two equations for the dispersion of the nematic and phononic mode, respectively,
\begin{align}
    x + \frac{\lambda_{\rm ph}^2 \lambda_{\rm nem}^2}{v_s^2 - \lambda_{\rm ph}^2} + [v_n^2 + \alpha(q)]q^2 - \left(1 + \frac{4\lambda_{\rm nem}^2 [1+\lambda_{\rm ph}^2 \kappa(q) q^2]}{v_F^2 q^2} \right)\omega^2 - i\frac{8\lambda_{\rm nem}^2[1+\lambda_{\rm ph}^2 \kappa(q) q^2]}{v_F^3 q^3}\omega^3 = 0 \label{eq:nematic_dispersion_equation} \\
    [v_s^2 -\lambda_{\rm ph}^2 -\alpha(q)]q^2 - \left(1 - \frac{4\lambda_{\rm ph}^2[\kappa(q) \lambda_{\rm nem}^2 - 1]}{v_F^2} \right)\omega^2 + i\frac{8\lambda_{\rm ph}^2[\lambda_{\rm nem}^2 \kappa(q) -1]}{v_F^3 q}\omega^3 = 0\,. \label{eq:phonon_dispersion_equation}
\end{align}
Here, we have defined
\begin{align}
    \beta(q) &= \frac{1}{x + v_n^2 q^2 - (v_s^2 - \lambda_{\rm ph}^2)q^2+ \frac{\lambda_{\rm ph}^2 \lambda_{\rm nem}^2}{v_s^2 -\lambda_{\rm ph}^2}} \\
    \alpha(q) &= \lambda_{\rm ph}^2 \lambda_{\rm nem}^2 \beta(q)\,, \\
    \kappa(q) &= (\lambda_{\rm ph}^2 q^2 - \lambda_{\rm nem}^2)\beta(q)^2 - 2 \beta(q)\,.
\end{align}
Crucially, the $\omega$-independent terms can be treated as perturbations in the long-wavelength limit. In Eq.~\eqref{eq:nematic_dispersion_equation}, the $\omega$-independent terms tend to a constant as $q \rightarrow 0$, while the coefficients of $\omega^2$ and $\omega^3$ both diverge as $q \rightarrow 0$. In Eq.~\eqref{eq:phonon_dispersion_equation}, the $\omega$-independent coefficient goes to zero as $q \rightarrow 0$, while the coefficient of $\omega^2$ tends to a constant and the coefficient of $\omega^3$ diverges.

The solutions, to first order in the $\omega$-independent terms, that have a positive real and a negative imaginary part are
\begin{align}
    \omega_{\rm nem} (q) & \approx \sqrt{\frac{x + \frac{\lambda_{\rm ph}^2 \lambda_{\rm nem}^2}{v_s^2 -\lambda_{\rm ph}^2} + [v_n^2 + \alpha(q)]q^2}{4\lambda_{\rm nem}^2 +[v_F^2 + 4 \lambda_{\rm ph}^2 \lambda_{\rm nem}^2 \kappa(q)]q^2}}v_F q - i \frac{4 \lambda_{\rm nem}^2 [1 + \lambda_{\rm ph}^2 \kappa(q) q^2]\left\{ x + \frac{\lambda_{\rm ph}^2 \lambda_{\rm nem}^2}{v_s^2 -\lambda_{\rm ph}^2} + [v_n^2 + \alpha(q)]q^2\right\}}{[4\lambda_{\rm nem}^2 +[v_F^2 + 4 \lambda_{\rm ph}^2 \lambda_{\rm nem}^2 \kappa(q)]q^2]^2}v_F q \label{eq:omega_nem_w_lambda_ph} \\
    \omega_{\rm ph}(q) & \approx \sqrt{\frac{v_s^2 - \lambda_{\rm ph}^2 - \alpha(q)}{v_F^2 - 4\lambda_{\rm ph}^2[\lambda_{\rm nem}^2 \kappa(q) -1]}} v_F q - i \frac{4\lambda_{\rm ph}^2[v_s^2 - \lambda_{\rm ph}^2 - \alpha(q)][1- \lambda_{\rm nem}^2 \kappa(q)]}{\left\{v_F^2 - 4 \lambda_{\rm ph}^2[\lambda_{\rm nem}^2 \kappa(q) -1] \right\}^2}v_F  q\,. \label{eq:omega_ph_w_lambda_ph}
\end{align}
In the limit where $\lambda_{\rm ph}\rightarrow 0$, the expression in Eq.~\eqref{eq:omega_nem_w_lambda_ph} for the nematic mode reduces to the one of Eq.~\eqref{eq:omega_sol_3}. The simple $q$-dependence in Eqs.~\eqref{eq:omega_nem_w_lambda_ph} and \eqref{eq:omega_ph_w_lambda_ph} is spoiled by the fact that $\alpha$ and $\kappa$ depend on $q$. Away from the QCP we find, to linear order in $q$:
\begin{align}
    \omega_{\rm nem}(q) &\approx \left[ \frac{1}{2\lambda_{\rm nem}}\sqrt{x + \frac{\lambda_{\rm ph}^2 \lambda_{\rm nem}^2}{v_s^2 - \lambda_{\rm ph}^2}} - i \frac{1}{4\lambda_{\rm nem}^2}\left( x+ \frac{\lambda_{\rm ph}^2 \lambda_{\rm nem}^2}{v_s^2 - \lambda_{\rm ph}^2} \right) \right]v_F q \\  
    \omega_{\rm ph}(q) &\approx \sqrt{\frac{x(v_s^2 - \lambda_{\rm ph}^2)\left(x + \frac{\lambda_{\rm ph}^2 \lambda_{\rm nem}^2}{v_s^2 - \lambda_{\rm ph}^2} \right)}{v_F^2  \left(x + \frac{\lambda_{\rm ph}^2 \lambda_{\rm nem}^2}{v_s^2 -\lambda_{\rm ph}^2}\right)^2 + 4\lambda_{\rm ph}^2\left(x + \frac{\lambda_{\rm nem}^2 v_s^2}{v_s^2 - \lambda_{\rm ph}^2} \right)^2}}v_F q \nonumber \\
    & - i \frac{\lambda_{\rm ph}^2 x \left(x + \frac{\lambda_{\rm ph}^2 \lambda_{\rm nem}^2}{v_s^2 - \lambda_{\rm ph}^2} \right) \left(x + \frac{\lambda_{\rm nem}^2 v_s^2}{v_s^2 -\lambda_{\rm ph}^2} \right)^2}{\left( v_F^2 \left(x + \frac{\lambda_{\rm ph}^2\lambda_{\rm nem}^2}{v_s^2 - \lambda_{\rm ph}^2} \right)^2+ 4 \lambda_{\rm ph}^2 \left(x + \frac{\lambda_{\rm nem}^2 v_s^2}{v_s^2 -\lambda_{\rm ph}^2} \right)^2 \right)^2} (v_s^2 - \lambda_{\rm ph}^2)v_F q\,,\label{eq:omega_ph_w_lambda_ph_linear_q}
\end{align}
implying that the nematic mode clearly reduces to Eq.~\eqref{eq:omega_nem_linear_q_no_ph} for $\lambda_{\rm ph}=0$. At the QCP, the linear terms in the phonon dispersion vanish, as expected for a transverse mode at a structural transition. Instead, the leading order term in the real part is quadratic in $q$ while the leading order in the imaginary part is cubic in $q$:
\begin{equation}
    \omega_{\rm ph}(q)|_{x=0} \approx \frac{v_F(v_s^2 -\lambda_{\rm ph}^2)}{\lambda_{\rm nem}}\sqrt{\frac{v_n^2 - (v_s^2 -\lambda_{\rm ph}^2)}{4v_s^4 + \lambda_{\rm ph}^2v_F^2 }}q^2 - i \frac{4 v_F v_s^4 (v_s^2 - \lambda_{\rm ph}^2)^2(v_n^2 - (v_s^2 -\lambda_{\rm ph}^2))}{\lambda_{\rm nem}^2(4 v_s^4 + \lambda_{\rm ph}^2 v_F^2)^2}q^3\,.
\end{equation}
Note that, for $\lambda_{\rm ph}=0$, the phonon mode is unaffected by the QCP, as it is due to critical nematic fluctuations. In this case, the phonon dispersion is purely real and given by $v_s q$ [see Eq.~\eqref{eq:omega_ph_w_lambda_ph_linear_q}], as it should be.


