\end{center}
\end{example}

We remark that Propositions \ref{prop:CrossingOverlap} and \ref{prop:SkeinType2} can also be determined by reinterpreting the work in \cite{canakci2013snake} in terms of fence posets.
We will need one more type of relation which does not appear when considering posets from a pair of intersecting arcs on a surface.  This will involve a \emph{self-overlap},  i.e. an overlap where both subposets are contained in the same poset.

\begin{definition}\label{def:ReverseOverlap}
Let $\calP$ be a labeled, weighted poset such that there exist values $1 \leq r \leq s \leq t \leq h:= \vert \calP \vert$ such that $R:=\calP[r,s]$ and  $R':=\overline{\calP[s+1,t]}$ are overlaps. We say this overlap is a \emph{reverse, kissing self-overlap} if 
\begin{enumerate}\setlength{\leftskip}{-15pt}
\item $R$ is on top of $\calP$ and $R'$ is on bottom of $\calP$;
\item we do not have both $r = 1$ and $t = h$; 
\item $R$ and $R'$ are isomorphic as labeled posets; and 
\item the isomorphism between $R$ and $R'$ is weight-preserving when restricted to $\calP[r,s-1]$ and $\calP[s+2,t]$.
\end{enumerate}
\end{definition} 

\begin{definition}\label{def:ResolutionReverseSelfOverlap}
Let $\calP$ be a labeled, weighted poset on $h$ elements with a reverse, kissing self-overlap $\calP[r,s] \cong \overline{\calP[s+1,t]}$.  We define the \emph{resolution} of $\calP$ with respect to this overlap to be $\{\calP_{34}\}$ and $\{\calP_{56}\}$ where the posets are defined as follows.

\begin{itemize}\setlength{\leftskip}{-15pt}
    \item Let $\calP_{34} = \calP[1,r-1] \nearrow \overline{\calP[t,r]} \nearrow \calP[t+1,h]$.
    \item We have three subcases for $\calP_{56}$.
    \begin{itemize}\setlength{\leftskip}{-15pt}
        \item If $r > 1$ and $t < h$, define $\calP_{56}$ to be  $\calP[1,s-1] \searrow \calP[t+1,h]$.
        \item If $r = 1$, implying $t < d$, let $v>t+1$ be the smallest integer such that $\calP(v) \nless \calP(t+1)$, if it exists, and otherwise let $v = h+1$. Let $\calP_{56} = \calP[v,h]$. 
        \item If $t = h$, implying $r > 1$, let $u < s-1$ be the largest integer such that $\calP(u) \ngtr \calP(s-1)$, if it exists, and otherwise let $u = 0$. Let $\calP_{56} = \calP[1,u]$.
    \end{itemize}
\end{itemize}
\end{definition}

To prove our relation on posets with reverse, kissing overlaps, we will  use the idea of a \emph{switching-position},  which was introduced in \cite{canakci2013snake} in terms of perfect matchings and was translated to the poset setting in \cite{banaian2024skein}.  We recall the definition and existence of switching positions here.

\begin{definition}
Let $\calP_1,\calP_2$ be two weighted posets with overlaps $\calP_1[s,t] \cong \calP_2[s',t']$,  and let $I_1 \in J(\calP_1)$ and $I_2 \in J(\calP_2)$. Suppose there exists a value $0 \leq i \leq t-s$ such that $\calP_1(s+i) \in I_1$ if and only if $\calP_2(s'+i) \in I_2$.  Then,  we say the \emph{switching position} of $I_1$ and $I_2$ is the smallest such $i$.  If no such value $i$ exists, then we say there is no switching position between $I_1$ and $I_2$ with respect to this overlap.
\end{definition}

\begin{lemma}[{\cite[Lemma 3]{banaian2024skein}}]\label{lem:SwitchingPosition}
Let $\calP_1,\calP_2$ be two labeled, weighted posets with overlaps $R_1:=\calP_1[s,t] \cong \calP_2[s',t']=:R_2$,  and let $I_1 \in J(\calP_1)$ and $I_2 \in J(\calP_2)$. Then,  a switching position between $I_1$ and $I_2$ exists unless $R_1 \cap I_1 = \emptyset $ and $R_2 \subseteq I_2$ or $R_1 \subseteq I_1$ and $R_2 \cap I_2 = \emptyset$.
\end{lemma}

We turn to providing a new skein relation on posets.

\begin{proposition}\label{prop:KissingReverseOverlap}
Given a poset $\calP$ with a reverse, kissing self-overlap in $\calP[r,s] \cong \overline{\calP[s+1,t]}$, define $Z^\star_R$ and $Z^\star_t$ by \[
Z^\star_R = \prod_{i = s+1}^t wt^\star(\calP(x)) 
\quad 
Z^\star_t= \begin{cases} \prod_{i=t+1}^{v-1} wt^\star(\calP(i)) & r = 1\\
1 & r>1\end{cases}.
\]
We can rewrite $\mathcal{W}(\calP)$ in the following way using the resolution of $\calP$,\[
\mathcal{W}^\star(\calP) = \mathcal{W}^\star(\calP_{34}) + Z^\star_RZ^\star_t \mathcal{W}^\star(\calP_{56}).
\]
\end{proposition}

\begin{proof}
 For shorthand, let $R$ denote the subposet $\calP[r,s]$ and let $R'$ denote the subposet $\calP[s+1,t]$.  We will follow the proof method which was described in \cite[Section 3.4]{banaian2024skein}. 

 We first assume $r > 1$ and $t < d$.  Let $A$ denote the subset of $J(\calP)$ consisting of all order ideals $I$ such that if $R' \subseteq I$ and $R \cap I = \emptyset$, then $\calP(r-1) \in I$ and $\calP(t+1) \notin I$.  Let $B$ denote the complement of $A$ in $J(\calP)$; equivalently, $B$ is the set of $I \in J(\calP)$ such that $R' \subseteq I$, $R \cap I = \emptyset$, and $\calP(r-1) \in I$ only if $\calP(t+1) \in I$. 

 We begin with a weight-preserving bijection $\Omega$ between $A$ and $J(\calP_{34})$. Let $A = A_1 \sqcup A_2$ where $A_1$ consists of $I \in J(\calP)$ such that we do not have  $R' \subseteq I$ and $R \cap I = \emptyset$ and $A_2$ is the complement, namely, the set of $I \in J(\calP)$ such that $R' \subseteq I$, $R \cap I = \emptyset$,  $\calP(r-1) \in I$ and $\calP(t+1) \notin I$. 

 Suppose we have $I \in A_1$. From Lemma \ref{lem:SwitchingPosition}, we know there exists a switching position,  $0 \leq i \leq s-r$, between $I$ and itself with respect to the reverse, kissing self-overlap. We define $\Omega(I)$ to be the order ideal of $\calP_{34}$ which is determined by the following conditions.
 \begin{enumerate}\setlength{\leftskip}{-15pt}
 \item The subset of $\Omega(I)$ supported on  $\calP_{34}[1,r+i-1] \cup \calP_{34}[t-i+1,h]$ is equivalent to the subset of $I$ supported on $\calP[1,r+i-1] \cup \calP[t-i+1,h]$.
 \item The subset of $\Omega(I)$ supported on $\calP_{34}[r+i,s]$ is equivalent to the subset of $I$ supported on $\calP[s+1,t-i]$.
\item The subset of $\Omega(I)$ supported on $\calP_{34}[s+1,t-i]$ is equivalent to the subset of $I$ supported on $\calP[r+i,s]$.
 \end{enumerate}

From part 3 of Definition \ref{def:ResolutionReverseSelfOverlap} and the fact that  $\calP(s) \in I$, is sent to $\calP_{34}(s+1) \in \Omega(I)$ and vice versa,  we conclude  that if $I \in A_1$, then $wt^\star(I) = wt^\star(\Omega(I))$.  

 Now, suppose we have $I \in A_2$. We define $\Omega(I)$ to be the element of $J(\calP_{34})$ which contains $\calP_{34}[r,s]$ and whose restriction to $\calP[1,r-1] \cup \calP[t+1,h]$ is the same as that of $I$.  Part 3 of Definition \ref{def:ResolutionReverseSelfOverlap} again confirms that if $I \in A_2$,  then $wt^\star(I) = wt^\star(\Omega(I))$.  

Notice that the image $\Omega(A_1)$ consists of all $I \in J(\calP_{34})$ such that we do not have $\calP_{34}[r,s] \subseteq I$ and $\calP_{34}[s+1,t] \cap I = \emptyset$ while $\Omega(A_2)$ exactly contains the complement.  Each map is reversible,  yielding a bijection between $A$ and $J(\calP_{34})$.  

 Given $I \in B$, we can naturally construct an order ideal of $\calP_{56}$ from $I \backslash \calP[s,t]$, and this yields a bijection between $B$ and $J(\calP_{56})$.  Since we delete the elements in $\calP[r,s]$,  we see that $wt^\star(I) = Z^\star_R wt^\star(\Omega(I))$ for all $I \in B$.  Since $J(\calP) = A \sqcup B$,  our formula follows in this case.  

 Next,  suppose $r = 1$,  which implies $t < h$.  If we define $A = A_1 \sqcup A_2$ where $A_1$ is identical to the previous case and $A_2$ consists of all $I \in J(\calP)$ such that $R' \subseteq I$, $R \cap I = \emptyset$ and $\calP(t+1) \notin I$,  then we can use a similar weight-preserving bijection $\Omega: A \to J(\calP_{34})$.  Let $B$ again be the complement of $A$; that is,  $B$ consists of all $I \in J(\calP)$ such that $R' \cup \langle \calP(t+1) \rangle \subseteq I$ and $R \cap I = \emptyset$.  Given $I \in B$,  $I \backslash (R' \cup \langle \calP(t+1) \rangle)$ is an element of $J(\calP_{56})$,  and this defines a bijection between the two sets.  Since for all $I \in B$,  $wt^\star(I) = Z^\star_R Z^\star_t wt^\star(\Omega(I))$,  our claim again follows.

 Finally,  suppose $t = h$,  implying $r > 1$.  If we define $A = A_1 \sqcup A_2$ where $A_1$ is identical to the previous case and $A_2$ consists of all $I \in J(\calP)$ such that $R' \subseteq I$, $R \cap I = \emptyset$ and $\calP(r-1) \in I$,  then we can use a similar weight-preserving bijection $\Omega: A \to J(\calP_{34})$. Let $B$ again be the complement of $A$; that is,  $B$ consists of all $I \in J(\calP)$ such that $R'  \subseteq I$ and $(R \cup \{\calP(r-1)\}) \cap I = \emptyset$.  Given $I \in B$,  $I \backslash R'$ is an element of $J(\calP_{56})$,  and this defines a bijection between the two sets.  Since for all $I \in B$,  $wt^\star(I) = Z^\star_R  wt^\star(\Omega(I))$,  our claim again follows.
\end{proof}

