The goal of this section is to prove the following.

\begin{theorem}\label{thm:Combinatorial_Cohn_Matrix_and_Triple}
For each $\fpq \in \mathbb{Q} \cap [0,\infty)$ or for $\fpq = \frac10$,  $C_\fpq$ is a $(k_1,k_2,k_3)$-CGC matrix, and for each Farey triple $(\frac{p}{q}, \frac{p+r}{q+s},\frs)$ in $\mathrm{F}\mathbb T$,  the triple $(C_{\frac{p}{q}}, C_{\frac{p+r}{q+s}},C_{\frs})$ is a $(k_1,k_2,k_3)$-CGC triple.
\end{theorem}

To this end, we refer to the family of matrices $C_\fpq$ as \emph{combinatorial cluster generalized Cohn matrices} and triples $(C_{\frac{p}{q}}, C_{\frac{p+r}{q+s}},C_{\frs})$ associated to a Farey triple as \emph{combinatorial cluster generalized Cohn triples}.
We divide the verification that combinatorial cluster generalized Cohn matrices and triples satisfy  Definitions \ref{def:gen-Cohn-matrix} and \ref{def:gen-Cohn-triple} into a series of intermediate results.

\begin{proposition}\label{prop:Combinatorial_Cohn_determinant_1}
For each $\fpq\in \mathbb{Q} \cap [0,\infty)$,  $\det(C_\fpq) = 1$.
\end{proposition}

\begin{proof}
Notice the determinant of $C_\fpq$ is given by \[
\xx^{2\gg^\circ_\fpq}\big(\mathcal{W}(\Ptilde_{\frac{p}{q}}; R)\mathcal{W}(\Ptilde_{\frac{p}{q}}; \neg L, \neg R) - \mathcal{W}(\Ptilde_{\frac{p}{q}}; \neg R)\mathcal{W}(\Ptilde_{\frac{p}{q}}; R, \neg L)\big)
\]
so it suffices to show that $\mathcal{W}(\Ptilde_{\frac{p}{q}}; R)\mathcal{W}(\Ptilde_{\frac{p}{q}}; \neg L, \neg R) - \mathcal{W}(\Ptilde_{\frac{p}{q}}; \neg R)\mathcal{W}(\Ptilde_{\frac{p}{q}}; R, \neg L)$ is equal to $\xx^{-2\gg^\circ_\fpq}$.

Let $u>1$ be the smallest number such that $\Ptilde_\fpq(u) \nless \Ptilde_\fpq(1)$. By checking small cases directly, we can assume such a $u$ exists. Since $\Ptilde_\fpq(\widetilde{h}_\fpq) < \Ptilde_\fpq(\widetilde{h}_\fpq - 1)$,  we can rewrite our polynomial as \[
\widehat{x_2}\mathcal{W}(\Ptilde_{\frac{p}{q}}[1,\widetilde{h}_\fpq - 1])\mathcal{W}(\Ptilde_{\frac{p}{q}}[u,h_\fpq]) -\widehat{x_2}\mathcal{W}(\Ptilde_{\frac{p}{q}}[1,h_\fpq])\mathcal{W}(\Ptilde_{\frac{p}{q}}[u,\widetilde{h}_\fpq-1]).
\]
The posets $\Ptilde_{\frac{p}{q}}[u,h_\fpq]$ and $\Ptilde_{\frac{p}{q}}[1,\widetilde{h}_\fpq - 1]$ have a crossing overlap in $\Ptilde_{\frac{p}{q}}[2,h_\fpq]$. This is because this subposet is trivially on top in $\Ptilde_{\frac{p}{q}}[u,h_\fpq]$ and since $\widetilde{P_\fpq}(h_\fpq) < \widetilde{P_\fpq}(h_\fpq+1)$,  it is on bottom in $\Ptilde_{\frac{p}{q}}[1,\widetilde{h}_\fpq - 1]$.  Using Proposition \ref{prop:CrossingOverlap}, we have \[
\widehat{x_2}\mathcal{W}(\Ptilde_{\frac{p}{q}}[1,\widetilde{h}_\fpq - 1])\mathcal{W}(\Ptilde_{\frac{p}{q}}[u,h_\fpq]) - \widehat{x_2} \mathcal{W}(\Ptilde_{\frac{p}{q}}[1,h_\fpq])\mathcal{W}(\Ptilde_{\frac{p}{q}}[u,\widetilde{h}_\fpq-1]) = \widehat{x_2} \prod_{i=2}^{\widetilde{h}_\fpq} wt(\Ptilde_\fpq)(i),
\]
and by Lemma \ref{lem:ProductOfAllWeights} and the fact that $\widehat{x}_1\widehat{x}_2\widehat{x}_3 = 1$, the righthand side is $\xx^{-2\gg^\circ_\fpq}$,  as desired.

\end{proof}
In several proofs,  we will find it convenient to express $\mathscr M $ in terms of a weight-generating function of a weighted poset.  We record this fact for reference.

\begin{lemma}\label{lem:RewriteMinv}
The expression $\mathscr M $ is equal to both $\frac{x_1}{x_2x_3} \mathcal{W}(H; \neg L)$ and $\frac{x_1}{x_2x_3} \mathcal{W}(H; R)$. Explicitly, $\mathscr M $  can be rewritten as \begin{align*}
\mathscr M  &= \frac{x_1}{x_2x_3}(1 + k_2 \widehat{x_2} + \widehat{x_2}^2 + k_1\widehat{x_1}\widehat{x_2}^2 + \widehat{x_1}^2\widehat{x_2}^2 + k_3 \widehat{x_1}^2\widehat{x_2}^2\widehat{x_3})\\
&=  \frac{x_1}{x_2x_3}(k_2 \widehat{x_2} + \widehat{x_2}^2 + k_1\widehat{x_1}\widehat{x_2}^2 + \widehat{x_1}^2\widehat{x_2}^2 + k_3 \widehat{x_1}^2\widehat{x_2}^2\widehat{x_3} + \widehat{x_1}^2\widehat{x_2}^2\widehat{x_3}^2 )
\end{align*}
\end{lemma}

\begin{proof}
Verifying each of these is a straightforward computation. In particular, the last equality is immediate from the fact that $\widehat{x_1}\widehat{x_2}\widehat{x_3} = 1$. 
\end{proof}

\begin{definition}\label{def:alphaShorthand}
For shorthand in the ensuing proofs, let $\alpha:= \mathcal{W}(H;R, \neg L)$. Explicitly, $\alpha = k_2 \widehat{x_2} + \widehat{x_2}^2 + k_1\widehat{x_1}\widehat{x_2}^2 + \widehat{x_1}^2\widehat{x_2}^2 + k_3 \widehat{x_1}^2\widehat{x_2}^2\widehat{x_3}$.
\end{definition}

We highlight some ways in which $\alpha$ will simplify expressions.

\begin{lemma}\label{lem:alphaSimplifying}
Given $\alpha$ as in Definition \ref{def:alphaShorthand}, we have \[
\mathscr M  = \frac{x_1}{x_2x_3}(1 + \alpha ),
\]
\[
\mathcal{W}(\Ptilde_{\fpq}) = (1+\alpha)\mathcal{W}(\calP_{\fpq}) + \mathcal{W}(\calP_{\fpq};R), 
\]
and
\[
\mathcal{W}(\Ptilde_{\fpq};R) = \alpha\mathcal{W}(\calP_{\fpq}) + \mathcal{W}(\calP_{\fpq}).
\]
\end{lemma}

\begin{proposition}\label{prop:Combinatorial_Cohn_Trace_Formula}
For each $\fpq\in \mathbb{Q} \cap [0,\infty)$,  let $p_{12}$ denote the $(1,2)$-entry of $C_\fpq$. We have $\text{tr}(C_\fpq) = \mathscr M  p_{12} - k_\fpq$.
\end{proposition}

\begin{proof}
We first consider the $(1,1)$ entry of $C_\fpq$.  To simplify notation, we assume $k_2 > 0$.  This entry can be written as \[
\xx^{\gg^\circ_\fpq} \mathcal{W}(\Ptilde_\fpq;R_{\Ptilde_\fpq}) = k_2\widehat{x_2}\xx^{\gg^\circ_\fpq} \mathcal{W}(\Ptilde_\fpq[1,\widetilde{h}_\fpq-1]).
\]
We partition the order ideals of $\Ptilde_\fpq[1,\widetilde{h}_\fpq-1]$ into two sets, based on whether they contain $\Ptilde_\fpq(h_\fpq+1)$.  Note that this element is maximal.  The contribution from order ideals which do not contain $\calP_\fpq(h_\fpq+1)$ is \[
k_2\widehat{x_2}\xx^{\gg^\circ_\fpq}\sum_{\substack{I \in J(\calP_\fpq[1,\widetilde{h}_\fpq-1])\\ \calP_\fpq(h_\fpq+1) \notin I}} wt(I)= \xx^{\gg^\circ_\fpq} \alpha \mathcal{W}(\calP_\fpq)
\]
and the contribution from order ideals which contain $\calP_\fpq(h_\fpq+1)$ is \[
k_2\widehat{x_2}\xx^{\gg^\circ_\fpq}\sum_{\substack{I \in J(\calP_\fpq[1,\widetilde{h}_\fpq-1])\\ \calP_\fpq(h_\fpq+1) \in I}} wt(I)= \xx^{\gg^\circ_\fpq}  \widehat{x_1}^2\widehat{x_2}^2\widehat{x_3}^2 \mathcal{W}(\calP_\fpq;R_{\calP_\fpq})=  \xx^{\gg^\circ_\fpq}  \mathcal{W}(\calP_\fpq;R_{\calP_\fpq})
\]
where we use the fact that  $ \widehat{x_1}\widehat{x_2}\widehat{x_3} = 1$ to simplify the right hand side. We remark that $R_{\calP_\fpq} = \calP_\fpq(h_\fpq)$.

Next, we consider the (2,2) entry, which is $ \xx^{\gg^\circ_\fpq}\mathcal{W}(\Ptilde_{\frac{p}{q}}; \neg R_{\Ptilde_{\frac{p}{q}}}, \neg L_{\Ptilde_{\frac{p}{q}}}) $. By the definition of $\Ptilde_\fpq$, this Laurent polynomial is equal to $ \xx^{\gg^\circ_\fpq}\mathcal{W}(\calP_{\frac{p}{q}}; \neg L_{\calP_{\frac{p}{q}}}) $,  and from Lemma \ref{lem:Asymmetry} this is equal to $ \xx^{\gg^\circ_\fpq}(\mathcal{W}(\calP_{\frac{p}{q}}; \neg R_{\calP_{\frac{p}{q}}}) )- k_\fpq $.  

Now,  we have \begin{align*}
\text{tr}(C_\fpq) &= \xx^{\gg^\circ_\fpq}\big(  \mathcal{W}(\Ptilde_\fpq;R_{\Ptilde_\fpq}) + \mathcal{W}(\Ptilde_{\frac{p}{q}}; \neg R_{\Ptilde_\fpq}, \neg L_{\Ptilde_\fpq})\big)\\
&=  \xx^{\gg^\circ_\fpq}\big(\alpha \mathcal{W}(\calP_\fpq)+  \mathcal{W}(\calP_\fpq;R_{\calP_\fpq}) + \mathcal{W}(\calP_\fpq;\neg R_{\calP_\fpq})\big) - k_\fpq\\
&=\frac{x_1}{x_2x_3} \xx^{\gg_\fpq}(1+ \alpha)\mathcal{W}(\calP_\fpq) - k_\fpq\\
&= \mathscr M  \xx^{\gg_\fpq} \mathcal{W}(\calP_\fpq) - k_\fpq
\end{align*}

where in the second-to-last equality,  we use  Lemma \ref{lem:CompareGVecAndGCirc} and in the last equality we use Lemma \ref{lem:RewriteMinv}.  If $k_2 = 0$,  then we follow a similar proof but use the fact that the weight of the element $R$ is not $\widehat{x_2}^2$. 
\end{proof}

As a corollary of Proposition \ref{prop:Combinatorial_Cohn_Trace_Formula},  we show how the cluster variable $X_\fpq$ relates to the corresponding the variable $X^\circ_\fpq$. These latter Laurent polynomials are related to \emph{band graphs} as in \cite{musiker2013bases}, which associates Laurent polynomials to closed curves in a surface. In the ordinary case ($k_1=k_2=k_3=0$),  with the initial cluster variables set to 1, this recovers the well-known fact that the length of the closed curve of slope $\fpq$ on the once-punctured torus is three times the length of the associated arc (for example, see \cite[Theorem 4.9]{canakci2020snake}).  The case $k_1=k_2=k_3=1$ with the initial cluster set to 1 was given in \cite[Theorem 8]{banaian2024generalization} using a combinatorial proof involving snake graphs.

\begin{corollary}\label{cor:Band_Graph_Formula_Conserved}
For each $\fpq \in \mathbb{Q} \cap [0,\infty)$,  we have
\[
X_\fpq^\circ = \mathscr M  x_\fpq - k_\fpq.
\]
\end{corollary}

\begin{proof}
Recall we form $\calP^\circ_\fpq$ by adding the relation $L_{\Ptilde_\fpq} > R_{\Ptilde_\fpq}$ to $\Ptilde_\fpq$.  Therefore,  order ideals of $\calP^\circ_\fpq$ correspond to the subset of order ideals of $\Ptilde_\fpq$ which contain $L_{\Ptilde_\fpq}$ only if they contain $R_{\Ptilde_\fpq}$.  This shows that the trace of $C_\fpq$ is equal to  $\xx^{\gg^\circ_\fpq} \mathcal{W}(\calP^\circ_\fpq)$.  Then,  the equality follows from Proposition \ref{prop:Combinatorial_Cohn_Trace_Formula}.
\end{proof}

The previous results concerned individual positive rational numbers, i.e. $\fpq \in \mathbb{Q} \cap [0,\infty)$. The following concerns Farey triples, and thus we will also consider $\fpq = \frac10$.

\begin{proposition}\label{prop:Mutation_Of_Combinatorial_Cohn}
Let $(\frac{p}{q},\frac{p+r}{q+s},\frs)$ be a Farey triple in $\mathrm{F}\mathbb T$ with $\frac{p}{q} < \frac{p+r}{q+s} < \frs$.  The combinatorial cluster generalized Cohn matrices satisfy \[
C_{ \frac{p+r}{q+s}} = C_{\frac{p}{q}}C_\frs - S_{ \frac{p+r}{q+s} }
\]
where \[
S_{ \frac{p+r}{q+s}}:= S_{C_{ \frac{p+r}{q+s}} } = \begin{bmatrix} k_{\frac{p+r}{q+s}} & 0 \\ k_{\frac{p+r}{q+s}} \mathscr M  &k_{\frac{p+r}{q+s}}\end{bmatrix}.
\]
\end{proposition}

\begin{proof}
\textbf{Case 1: $\frs \in \mathbb{Q} \cap [0,\infty)$}

First, we note that from Corollary \ref{cor:g_vecs_in_cluster},  the leading terms in each entry of $C_{\frac{p}{q}}C_\frs - S_{ \frac{p+r}{q+s}}$ agree with those in $C_{ \frac{p+r}{q+s}} $; by ``leading term'', we mean the terms associated with empty order ideals in each poset. 
The matrices $C_\fpq$ are closely related to the matrices used in \cite{ouguz2025oriented,ezgieminecluster2024}. In particular, if we ignore the leading monomial in each term, we recover the \emph{dual rank matrix} in \cite{ouguz2025oriented}. As a consequence, from \cite[Proposition 4.2]{ouguz2025oriented} as well as an analysis of the leading monomials $\xx^\gg$, we have \[
C_{\frac{p}{q}}C_\frs = \begin{bmatrix} \xx^{\gg^\circ_\frac{p+r}{q+s}} \mathcal{W}(\Ptilde_{\frac{p}{q}} \nearrow \Ptilde_\frs;R_{\Ptilde_{\frac{r}{s}}}) 
&  \xx^{\gg_\frac{p+r}{q+s}} \mathcal{W}(\Ptilde_{\frac{p}{q}} \nearrow \Ptilde_\frs;\neg R_{\Ptilde_{\frac{r}{s}}})\\
 \xx^{2\gg^\circ_\frac{p+r}{q+s} - \gg_\frac{p+r}{q+s} } \mathcal{W}(\Ptilde_{\frac{p}{q}} \nearrow \Ptilde_\frs;R_{\Ptilde_{\frac{r}{s}}}, \neg L_{\Ptilde_{\frac{p}{q}}}) 
 &  \xx^{\gg^\circ_\frac{p+r}{q+s}} \mathcal{W}(\Ptilde_{\frac{p}{q}} \nearrow \Ptilde_\frs;\neg R_{\Ptilde_{\frac{r}{s}}}, \neg L_{\Ptilde_{\frac{p}{q}}})\end{bmatrix},\]
and now we will compare entries of $N:=C_{\frac{p}{q}}C_\frs - S_{ \frac{p+r}{q+s}}$ with those of $C_{ \frac{p+r}{q+s}} $. 

 In order to compare these two matrices, which involve different posets, we define $Q_{11}$ to be the poset $\overline{H} \searrow \overline{P}_{\frac{p+r}{q+s}} \nearrow H$.  Using Lemma \ref{lem:ShapeOfPosetInFareyTriple}, we draw a sketch of this poset below, where each diagonal $\cdots$ denotes a copy of $H$. Throughout, we assume $\fpq > \frac01$, so that $\calP_\fpq$ is nonempty. However, one can use item (2) in Lemma \ref{lem:ShapeOfPosetInFareyTriple} when $\fpq = \frac01$ to get the desired result in this case.

\begin{center}
\begin{tikzpicture}
\node(21) at (0,0){$x_2$};
\node(dots1) at (1,1){$\iddots$};
\node(31) at (2,2){$x_3$};
\node(rs) at (3,1){$\calP_{\frac{p}{q}}$};
\node(32) at (4,2){$x_3$};
\node(dots2) at (5,1){$\ddots$};
\node(22) at (6,0){$x_2$};
\node(pq2) at (7,1){$\calP_{\frac{r}{s}}$};
\node(33) at (8,2){$x_3$};
