Intuitively, an agent may withhold her information to prevent her neighbors from excessively responding to her signal due to their strong coordination motives. Of course, keeping information private is not necessarily socially desirable, especially when other agents would benefit from the commonality of information. Thus, the resulting inefficiency can be substantial in the core-periphery interaction networks when the core is relatively large. This finding presents an interesting contrast to the case of public information provision, where the adverse welfare effects can be pronounced when the periphery is relatively large.



\section{Conclusion}
This paper studies how payoff heterogeneity affects the social value of information in beauty contest games where a network of coordination motives represents agents' interactions. The analysis provides a geometric characterization of interaction networks under which public information provision can harm aggregate welfare. A key mechanism identified is that agents with relatively low Katz-Bonacich centrality may be harmed by public information because their highly central neighbors, by excessively responding to the public signal, distort their own actions relative to the payoff state. Building on this insight, the paper also highlights a novel channel through which information sharing becomes inefficient in beauty contest games: an agent may choose to withhold her signal to avoid the adverse consequences of her neighbors' altered actions that would result from the increased commonality of information.

This paper is an initial step in understanding the social value of information with ex-ante heterogeneous agents. Promising avenues for future research include identifying optimal information dissemination policies, introducing endogenous information acquisition, and extending the analysis to more general linear-quadratic games.


\section{Proofs}\label{sectionproof}
\subsection{Proposition 1}\label{sectionproof1}
The remaining part of the proof is to show that the sum of the equilibrium slopes must be one in any linear equilibrium.
Suppose $a_i=b_i^yy+b_i^xx_i$ for all $i \in N$.
Substituting these linear strategies into (\ref{FOC}) yields
\begin{align*}
b^y_i y + b^x_i x_i&=(1-d_i^{out})\left((1-\ga)y+  \ga x_i\right)+ \sum_{j \neq i}g_{ij}\left(b_j^y y + b_j^x((1-\ga)y+\ga x_i)\right)\\
&= \left((1-d_i^{out})(1-\ga) + \sum_{j \neq i}g_{ij}b^y_j+(1-\ga)\sum_{j \neq i}g_{ij}b^x_j\right)y+\ga \left(1-d_i^{out} + \sum_{j \neq i}g_{ij}b^x_j\right)x_i,
\end{align*}
where the first equality follows from $\mE_i[\theta]=(1-\ga)y+  \ga x_i$ and $\mE_i[a_j]=b_j^y y+  b_j^x \left((1-\ga)y+  \ga x_i\right)$.
By matching the coefficients, the equilibrium slopes must satisfy
\begin{align*}
b^y_i - \sum_{j \neq i}g_{ij}b^y_j-(1-\ga)\sum_{j \neq i}g_{ij}b^x_j&= (1-\ga)(1-d_i^{out});  \\
b^x_i -\ga \sum_{j \neq i}g_{ij}b^x_j&= \ga (1-d_i^{out}) .
\end{align*}
Summing these two equations yields
\begin{equation*}
b^y_i+b^x_i -\sum_{j \neq i}g_{ij}\left(b^y_j+b^x_j\right)= 1-d_i^{out}.
\end{equation*}
In matrix notation, \begin{equation*}
(I - G)(\mb^y+\mb^x) =(I - G)\mone,\end{equation*}
where $\mb^y=(b^y_1, \ldots, b^y_n)'$ and $\mb^x=(b^x_1, \ldots, b^x_n)'$ are $n$-dimensional column vectors.
Because the inverse matrix $(I-G)^{-1}$ exists by assumption, $\mb^y+\mb^x=(I-G)^{-1}(I-G)\mone=\mone$.
Thus, any linear equilibrium must satisfy $b_i^y+b_i^x=1$ for all $i\in N$, as desired.
\qed

\subsection{Proposition \ref{propindividual}}
By Proposition \ref{propequilibrium}, $X_i=(1-(1-\ga)c_i(\ga, G))\varepsilon_i+(1-\ga)c_i(\ga, G)\varepsilon_y$ does not depend on $\theta$, and the ex-ante expected payoff is well defined. I simplify $\mE[X^2_i]$, $\mE[X_iX_j]$, and $\sum_{j\neq i}g_{ij}\mE[X_iX_j]$ as follows:
\begin{align*}
	\mE[X^2_i] &= \mE[((1-b_i)\varepsilon_{i}+b_i \varepsilon_{y})^2]\\
	&= (1-b_i)^2\tx^{-1}+b_i^2\ty^{-1}\\
	&= \tx^{-1}(1-(1-\ga)c_i(\ga, G))^2+\ty^{-1}\left((1-\ga)c_i(\ga, G)\right)^2\\
    &= (\tx^{-1}+\ty^{-1})(1-\ga)^2 c^2_i(\ga, G)-2\tx^{-1}(1-\ga)c_i(\ga, G)+\tx^{-1}\\
	&= \tx^{-1}(1-\ga)c^2_i(\ga, G)-2\tx^{-1}(1-\ga)c_i(\ga, G)+\tx^{-1}\\
	&= \tx^{-1}(1-\ga)c_i(\ga, G) (c_i(\ga, G)-2)+\tx^{-1};\\
	\mE[X_iX_j] &= \mE[((1-b_i)\varepsilon_{i}+b_i \varepsilon_{y})((1-b_j)\varepsilon_{j}+b_j \varepsilon_{y})]\\
	&= b_ib_j\ty^{-1}\\
	&= \ty^{-1}(1-\ga)^2c_i(\ga, G)c_j(\ga, G);\\
	\sum_{j\neq i}g_{ij}\mE[X_iX_j] &= \ty^{-1}(1-\ga)^2c_i(\ga, G)\sum_{j\neq i}g_{ij}c_j(\ga, G)\\
	&= \ty^{-1}(1-\ga)^2c_i(\ga, G) \ga^{-1}(c_i(\ga, G)-1)\\
	&= \tx^{-1}(1-\ga)c_i(\ga, G)(c_i(\ga, G)-1).
\end{align*}
The second last equality follows from the identity $\mc(\ga, G)=\mone+\ga G \mc(\ga, G)$.

Using these expressions, agent $i$'s equilibrium payoff simplifies to
\begin{align*}
	U_i(\tx, \ty, G) &= -\left(1-d_i^{out}\right)\mE[X^2_i] - \sum_{j \neq i}g_{ij}\mE[(X_i-X_j)^2]\\
    &=-\mE[X^2_i]- \sum_{j \neq i}g_{ij}\mE[X_j^2]+2 \sum_{j \neq i}g_{ij}\mE[X_i X_j]\\
    &= \tx^{-1}(1-\ga)\left(-c_i(\ga, G) (c_i(\ga, G)-2)+2c_i(\ga, G)(c_i(\ga, G)-1)\right)-\sum_{j \neq i}g_{ij}\mE[X_j^2]-\tx^{-1}\\
    &=  \tx^{-1}(1-\ga)\left(c_i^2(\ga, G)-\sum_{j \neq i}g_{ij}c_j(\ga, G)\left(c_j(\ga, G)-2\right)\right)-\tx^{-1}(1+d_i^{out}).
\end{align*}
Because $U_i(\tx, 0, G)=-\tx^{-1}(1+d_i^{out})$, it follows that $\Delta U_i(\tx, \ty, G)<0$ if and only if $c_i^2(\ga, G)-\sum_{j \neq i}g_{ij}c_j(\ga, G)\left(c_j(\ga, G)-2\right)<0$, as desired.\qed

\subsection{Claims in Example \ref{exampleABC}}\label{sectionproofexample1}
\begin{claim}
$\Delta U_{A}(\tx,\ty, G)<0$ if and only if  $f(\alpha,\beta,\gamma)<0$.
\end{claim}
\noindent The centralities of Ann and Bob are derived using the self-referentiality:
$c_A(\ga, G)=1+\ga \alpha c_B(\ga, G)$, $c_B(\ga, G)=1+\ga \beta c_C(\ga, G)$, and $c_C(\ga, G)=1+\ga \beta c_B(\ga, G)$.
Solving these simultaneous equations yields $c_A(\ga, G)=(1+\ga (\alpha-\beta))/(1-\ga \beta)$ and $c_B(\ga, G)=c_C(\ga, G)=1/(1-\ga \beta)$.
For Ann, plugging these into the terms inside the large parentheses of (\ref{equationpayoff})  yields
\begin{align*}
  c_A^2(\ga, G)-\alpha c_B(\ga, G)\left(c_B(\ga, G)-2\right) &=  (1-\ga\beta)^{-2}\left((1+\ga (\alpha-\beta))^2-\alpha (1-2(1-\ga\beta))\right)\\
  &=(1-\ga\beta)^{-2}\left((1+\ga (\alpha-\beta))^2-\alpha(2\ga\beta-1)\right)\\
  &=(1-\ga\beta)^{-2}f(\alpha,\beta,\gamma).
\end{align*}
Hence, (\ref{inequalityindividual}) holds for Ann if and only if $f(\alpha,\beta,\gamma)<0$. \qed

\begin{claim}
$\mathcal{G}(\ga)$ is non-empty if and only if $\ga> (1+\sqrt{5})/4$. 
\end{claim}
\noindent
It suffices to show that there exists a triplet $(\alpha,\beta,\gamma)$ such that $f(\alpha,\beta,\gamma)<0$ if and only if $\ga> (1+\sqrt{5})/4$.
Define a quadratic  function $h(\alpha,\ga)\equiv\inf_{\beta\in [0, 1)} f(\alpha, \beta,\gamma)$.
Simple algebra shows
\begin{align*}
	h(\alpha,\ga)	&= f(\alpha, 1,\gamma) \\
	&= (1+\ga (\alpha-1))^2-\alpha(2\ga-1)\\
	&= \ga^2 \alpha^2+2\ga(1-\ga)\alpha +(1-\ga)^2-2\ga\alpha+\alpha\\
	&= \ga^2 \alpha^2+(1-2\ga^2)\alpha +(1-\ga)^2.
\end{align*}
Because $h(0, \ga) > 0$ and $h(1, \ga) > 0$ for any $\ga \in (0,1)$, the quadratic function $h(\alpha,\ga)$ can be strictly negative for some $\alpha \in [0,1)$ if and only if its minimum is negative. This requires two conditions to hold jointly: (i) the vertex must lie in the interval $(0,1)$, i.e., $\ga > 1/\sqrt{2}$, and (ii) the value at the vertex must be negative, i.e., $(2\ga-1)(-4\ga^2+2\ga+1)<0$.
Since $\ga > 1/\sqrt{2}$ implies that $2\ga-1 > 0$, the two conditions are jointly equivalent to the single inequality $4\ga^2-2\ga-1>0$. This final inequality holds if and only if $\ga > (1+\sqrt{5})/4$.
\qed

\begin{claim}
$\mathcal{G}(\ga)\subseteq \mathcal{G}(\ga')$ for $\ga < \ga'$.
\end{claim}
\noindent
%Take any $\ga, \ga' \in (0,1)$ such that $\ga < \ga'$.
This claim trivially holds if $\mathcal{G}(\ga)$ is empty. 
  Suppose $\mathcal{G}(\ga)$ is nonempty. 
  Then, $\alpha<\beta$ must hold; otherwise, $f(\alpha,\beta,\gamma)\geq 1-\alpha (2\ga\beta-1)>0$.
Differentiating $f(\alpha,\beta,\gamma)$ with respect to $\gamma$ gives
$$\frac{\partial f(\alpha,\beta,\gamma)}{\partial \gamma}=2(\alpha-\beta)+2\ga(\alpha-\beta)^2-2\alpha\beta=-2(\beta-\alpha)(1-\ga (\beta-\alpha))-2\alpha \beta<0.$$
Thus, $f(\alpha,\beta,\gamma)$ is strictly decreasing in $\ga$ whenever $\alpha < \beta$. \qed

\subsection{Derivation of the unique linear equilibrium under $\mathcal{I}'$}\label{sectionI'}
Let Bob's and Carol's linear strategies be $a'_B=b_B^xx_B+b_B^yy$ and $a'_C=b_C^xx_C+b_C^zz$, respectively. 
Then, Bob's first-order condition is
\begin{align*}
a'_B&= (1-\beta)(\ga x_B+(1-\ga)y)+\beta (b_C^x+b_C^z)(\ga x_B+(1-\ga)y)\\
&= \ga\left(1-\beta+\beta (b_C^x+b_C^z)\right)x_B+(1-\ga)\left(1-\beta+\beta (b_C^x+b_C^z)\right)y.
\end{align*}
By matching the coefficients, Bob's equilibrium slopes satisfy
\begin{align*}
b^x_B&= \ga(1-\beta+\beta (b_C^x+b_C^z));\\
b^y_B&= (1-\ga)(1-\beta+\beta (b_C^x+b_C^z)).
\end{align*}
A similar logic applies to Carol's equilibrium strategy, and her equilibrium slopes satisfy
\begin{align*}
b^x_C&= \ga\left(1-\beta+\beta (b_B^x+b_B^y)\right);\\
b^z_C&= (1-\ga)\left(1-\beta+\beta (b_B^x+b_B^y)\right).
\end{align*}
Solving these simultaneous equations yields $b_B^y=b_C^z=1-\ga$ and $b_B^x=b_C^x=\ga$.
Substituting the obtained Bob's equilibrium strategy into Ann's first-order condition gives
\begin{align*}
a'_A&=(1-\alpha)(\ga x_A+(1-\ga)y)+\alpha \left((1-\ga)y+\ga (\ga x_A+(1-\ga)y)\right)\\
&=(1-\ga)(1+\ga\alpha)y+ (\ga(1-\alpha)+\ga^2\alpha)x_A.
\end{align*}
This concludes the proof.
\qed

\subsection{Derivation of inequality (\ref{equationABC2})}
Let $U'_A(\tx, \ty, G)$ denote Ann's equilibrium payoff under $\mathcal{I}'$.
By the proof in Section \ref{sectionI'}, Ann's and Bob's equilibrium strategies under $\mathcal{I}'$ are given by
$a'_{A}= (1-\ga)(1+\ga \alpha)y+ \ga(1-\alpha + \ga\alpha) x_A$ and $a'_{B}=(1-\ga)y+\ga x_B$, respectively.
Notice that $a'_A$ and $a'_B$ coincide with the equilibrium strategies under $\mathcal{I}$ for agents with centralities of $1+\ga \alpha$ and $1$, respectively.
Thus, plugging  $1+\ga \alpha$ as Ann's centrality and $1$ as Bob's centrality into (\ref{equationpayoff}) yields
\begin{align*}
U'_A(\tx, \ty, G)&=  \tx^{-1}(1-\ga)((1+\ga \alpha)^2+\alpha)-\tx^{-1}(1+\alpha).
\end{align*}
The difference in Ann's equilibrium payoff between $\mathcal{I}'$ and $\mathcal{I}$ is then computed as
\begin{align*}
U'_A(\tx, \ty, G)-U_A(\tx, \ty, G)&=  \tx^{-1}(1-\ga)\left((1+\ga \alpha)^2+\alpha-(1-\ga\beta)^{-2}f(\alpha,\beta,\gamma)\right).
\end{align*}
Thus, $U_A(\tx, \ty, G)<U'_A(\tx, \ty, G)$ if and only if $f(\alpha,\beta,\gamma)<(1-\ga\beta)^2\left((1+\ga \alpha)^2+\alpha\right)$.
\qed

\subsection{Proposition \ref{propwelfare}}
By the proof of Proposition \ref{propindividual}, for each $i \in N$,
\begin{align*}
		\Delta U_i(\tx, \ty, G) &=  \tx^{-1}(1-\ga)\left(c_i^2(\ga, G)-\sum_{j \neq i}g_{ij}c_j(\ga, G)\left(c_j(\ga, G)-2\right)\right).
\end{align*}
Summing these equations over $i$ yields
\begin{align*}
	\Delta W(\tx, \ty, G) &=  \sum_{i\in N}\Delta U_i(\tx, \ty, G)\\
	&=\tx^{-1}(1-\ga)\left(\sum_{i\in N}c_i^2(\ga, G)-\sum_{i\in N}\sum_{j \neq i}g_{ij}c_j(\ga, G)\left(c_j(\ga, G)-2\right)\right)\\
	&=\tx^{-1}(1-\ga)\left(\sum_{i\in N}c_i^2(\ga, G)-\sum_{i\in N}d_i^{in}c_i(\ga, G)\left(c_i(\ga, G)-2\right)\right)\\
	&=\tx^{-1}(1-\ga)\sum_{i\in N}c_i(\ga, G)\left((1-d_i^{in})c_i(\ga, G)+2d_i^{in}\right).
\end{align*}
Hence, $\Delta W(\tx, \ty, G)<0$ if and only if $\sum_{i\in N}c_i(\ga, G)\left((1-d_i^{in})c_i(\ga, G)+2d_i^{in}\right)<0$. \qed

\subsection{Claims in Example \ref{exampleWelfare}}\label{sectionproofexample2}
\begin{claim}
Suppose $G$ is a core-periphery interaction network. Then, $\Delta W(\tx,\ty, G)<0$ if and only if  $f(\alpha,\beta,\gamma)<-l(1-\beta(2\ga\beta-1))/m$.
\end{claim}
\noindent 
Suppose $G$ is a core-periphery interaction network.
Each agent $i$'s  centrality is given by
$c_i(\ga, G)=1/(1-\ga \beta)$ if $i$ is core and $c_i(\ga, G)=(1+\ga (\alpha-\beta))/(1-\ga \beta)$ if $i$ is peripheral.
The sum of all core agents' in-degrees is $l\beta+m\alpha$, and the sum of all peripheral agents' in-degrees is $0$.
Plugging these into the left-hand side of (\ref{inequalitywelfare})  yields
\begin{align*} 
\mathrm{(LHS)} &=   (1-\ga\beta)^{-2}\left(l-(l\beta+m\alpha) +2(1-\ga\beta)(l\beta+m\alpha)+m(1+\ga (\alpha-\beta))^2\right)\\
 &=(1-\ga\beta)^{-2}\left(l+(l\beta+m\alpha)(1 -2\ga\beta)+mf(\alpha,\beta,\ga)+m\alpha(2\ga\beta-1)\right)\\
 &=(1-\ga\beta)^{-2}\left(mf(\alpha,\beta,\ga)+l(1-\beta(2\ga\beta-1)\right)).
\end{align*}
Hence, (\ref{inequalitywelfare}) holds if and only if $f(\alpha,\beta,\ga)<-l(1-\beta(2\ga\beta-1))/m$. \qed

\begin{claim}
$\mathcal{H}(\ga, q)\subseteq \mathcal{H}(\ga, p)$ for $p \leq q$. 
\end{claim}
\noindent This is immediate from the fact that $1-\beta(2\ga\beta-1)>0$.
\qed

\begin{claim}
For each $\ga\in (0, 1)$, $\mathcal{H}(\ga, l/m)\rightarrow \mathcal{G}(\ga)$ as $l/m\rightarrow 0$. 
\end{claim}
\noindent Fixing $\ga\in (0, 1)$, the right-hand side of (\ref{exampleinequalitywelfare}) converges to 0 as $l/m\rightarrow 0$. 
The obtained inequality in the limit coincides with inequality (\ref{equationABC}).
\qed

\subsection{Proposition \ref{propmonotonicity}}
To show this proposition, it suffices to focus on the three-player interaction network in Example \ref{exampleABC} and show that for any $\ga > 1/\sqrt{2}$, there exist interaction parameters $(\alpha, \beta) \in [0,1)^2$ such that
$$\frac{\partial f}{\partial \alpha}<0.\footnote{If $\partial f / \partial \alpha < 0$, $\Delta U_A$ does not monotonically increase with $\alpha$ for given $\beta$ and $\gamma$. The same applies to $\Delta W$ since Bob's and Carol's payoffs are independent of $\alpha$. For the case of $n>3$, similar reasoning applies by considering the core-periphery networks with $l=2$ and $m=n-2$.}$$
Specifically, the partial derivative is computed as
$$\frac{\partial f}{\partial \alpha}=2\ga+2\ga^2(\alpha-\beta)-2\ga\beta +1=2\ga^2\alpha-2\ga(\ga+1)\beta+2\ga+1.$$
The infimum of $\partial f / \partial \alpha$ with respect to $(\alpha, \beta)$ is then
$$\inf_{(\alpha, \beta)\in [0,1)^2} \frac{\partial f}{\partial \alpha}=-2\ga^2+1.$$
Because $-2\ga^2+1<0$ if and only if $\ga > 1/\sqrt{2}$, the result follows. \qed

\subsection{Derivation of the unique linear equilibrium under $\mathcal{I}^\dagger$}
Following the proof in Section \ref{sectionproof1}, it is easy to show that the sum of equilibrium slopes must be one for each agent in any linear equilibrium under $\mathcal{I}^\dagger$.
This observation immediately implies that agent $i \neq 1$'s unique linear equilibrium strategy must be  $a^\dagger_i=x_i$.
Plugging these into agent $1$'s first-order condition yields
\begin{align*}
a^\dagger_1= (1-d_1^{out}) \mE_1[\theta]+\sum_{j \neq 1}g_{1j} \mE_1[x_j]=\mE_1[\theta]=\ga x_1+(1-\ga)y. 
\end{align*}
This concludes the proof. \qed

\subsection{Derivation of $U^\dagger_i(\tx,\ty, G)$ and $W^\dagger(\tx,\ty, G)$}
First, I derive agent $1$'s equilibrium payoff under $\mathcal{I} ^\dagger$:
\begin{align*}
	U^\dagger_1(\tx,\ty, G) &= -\left(1-d_1^{out}\right)\mE[(a^\dagger_1-\theta)^2] - \sum_{j \neq 1}g_{1j}\mE[(a^\dagger_1-a^\dagger_j)^2]\\
    &=-\mE[(a^\dagger_1-\theta)^2]- \sum_{j \neq 1}g_{1j}\mE[(a^\dagger_j-\theta)^2]+2 \sum_{j \neq 1}g_{1j}\mE[(a^\dagger_1-\theta)(a^\dagger_j-\theta)]\\
    &=-\mE[(a^\dagger_1-\theta)^2]- \sum_{j \neq 1}g_{1j}\mE[(a^\dagger_j-\theta)^2]\\
    &= -(1-\ga)^2\ty^{-1}-\ga^2 \tx^{-1}-d_1^{out}\tx^{-1}\\
    &= -\ga \tx^{-1}-d_1^{out}\tx^{-1}\\
    &= \tx^{-1}(1-\ga)-\tx^{-1}(1+d_1^{out}).
\end{align*}
Similarly, agent $i \neq 1$'s equilibrium payoff under $\mathcal{I} ^\dagger$ is derived as
\begin{align*}
	U^\dagger_i(\tx,\ty, G) &= -\tx^{-1}- \sum_{j \neq i, 1}g_{ij} \tx^{-1}-g_{i1}((1-\ga)^2\ty^{-1}+\ga^2 \tx^{-1})\\
    &= \tx^{-1}(1-\ga)g_{i1}-\tx^{-1}(1+d_i^{out}).
\end{align*}
Thus, $U^\dagger_1(\tx,\ty, G)= \tx^{-1}(1-\ga)+U_1(\tx, 0, G)$ and $U^\dagger_i(\tx,\ty, G)=\tx^{-1}(1-\ga)g_{i1}+U_i(\tx, 0, G)$ for each $ i \neq 1$.
Summing over all agents then yields $W^\dagger(\tx,\ty, G)=\tx^{-1}(1-\ga)(1+d^{in}_{1})+W(\tx, 0, G)$, which concludes the proof. \qed

\subsection{Proposition \ref{propinfoshare}}
By the proof of Proposition \ref{propindividual} and Proposition \ref{propwelfare}, 
\begin{align*}
	U^\dagger_1(\tx,\ty, G)-U_1(\tx,\ty, G)&=\tx^{-1}(1-\ga)+U_1(\tx, 0, G)-U_1(\tx,\ty, G)\\
	&=\tx^{-1}(1-\ga)-\Delta U_1(\tx,\ty, G)\\
	&=  \tx^{-1}(1-\ga)\left(1-c_1^2(\ga, G)+\sum_{j \neq 1}g_{1j}c_j(\ga, G)\left(c_j(\ga, G)-2\right)\right);\\
	W(\tx,\ty, G)-W^\dagger(\tx,\ty, G)&=W(\tx,\ty, G)-\tx^{-1}(1-\ga)(1+d^{in}_{1})-W(\tx, 0, G)\\
	&=\Delta W(\tx,\ty, G)-\tx^{-1}(1-\ga)(1+d^{in}_{1})\\
    &=\tx^{-1}(1-\ga)\left(\sum_{i\in N}c_i(\ga, G)\left((1-d_i^{in})c_i(\ga, G)+2d_i^{in}\right)-(1+d^{in}_{1})\right).
\end{align*}
Thus, $U_1(\tx,\ty, G)<U^\dagger_1(\tx,\ty, G)$ and $W^\dagger(\tx,\ty, G)<W(\tx,\ty, G)$ if and only if $c_1^2(\ga, G)-\sum_{j \neq 1}g_{1j}c_j(\ga, G)\left(c_j(\ga, G)-2\right)<1$ and $1+d^{in}_{1}<\sum_{i\in N}c_i(\ga, G)\left((1-d_i^{in})c_i(\ga, G)+2d_i^{in}\right)$. \qed


\subsection{Derivation of compound inequality (\ref{exampleinequalityinfoshare})}
\noindent
Suppose $G$ is a core-periphery interaction network. By substituting the simplified expressions for the left-hand side of (\ref{inequalityinfoshare1}) (derived in Section \ref{sectionproofexample1}) and the right-hand side of (\ref{inequalityinfoshare2}) (derived in Section \ref{sectionproofexample2}), the two conditions can be combined into the single compound inequality:
$$(1-\ga\beta)^{-2}f(\alpha,\beta,\gamma) < 1 < (1-\ga\beta)^{-2}\left(mf(\alpha,\beta,\gamma)+l(1-\beta(2\ga\beta-1))\right).$$
Multiplying all parts of this inequality by $(1-\ga\beta)^{2}$ yields the compound inequality (\ref{exampleinequalityinfoshare}). \qed



