The following notations are used for the bootstrap asymptotics: for any bootstrap statistic $T^*$, we write $T^* = o_{p^*}(1)$ in probability if for any
$\delta >0$, $\epsilon>0$, $\lim_{n \rightarrow \infty} P[P^*[|T^*|>\delta]>\epsilon]=0$, i.e., $P^*[|T^*|>\delta] = o_p(1)$. 
To be concise, we use the short version $T^* = o_{p^*}(1)$ to say that $T^* = o_{p^*}(1)$ in probability.  
Also, we write $T^* \rightarrow^{d^*} T$ in probability if, conditional on the sample, $T^*$ weakly converges to $T$ under $P^*$, for all samples contained in a set with probability approaching one. 
Specifically, we write $T^* \rightarrow^{d^*} T$ in probability if and only if $E^*[ f(T^*) ] \rightarrow E[ f(T) ]$ in probability for any bounded and uniformly continuous function $f$, 
where $E^*$ denotes the expectation under the probability measure induced by the bootstrap.  


\section{Discussion on Assumptions}\label{sec:diss_assumption}

Assumptions \ref{ass: 1}-\ref{ass: 3} follow closely Assumptions 1-3 in \cite{cattaneo2018inference} and \cite{jochmans2022heteroscedasticity},  under which they show the asymptotic normality of the OLS estimator in the high-dimensional case with $q_n/n \nrightarrow 0$ as $n \rightarrow \infty$. 

Specifically, Assumption \ref{ass: 1} covers not only standard randomly sampled data but also repeated-measurement data 
such as short panel data.  $\{N_1,  ...,  N_{G_n}\}$ represents a partition of $\{1, ...,  n\}$ into $G_n$ strata,  which are independent from each other but dependence between observations within the strata is allowed. 
However,  this assumption does not allow for correlation in the error terms across units,  and therefore excludes clustered,  spatial or time series dependence in the sample.   

Assumption \ref{ass: 2} contains standard rank and moment conditions.  In addition,  it allows $q_n$ to grow at the same rate as the sample size.  

Furthermore, the settings in \cite{cattaneo2018inference} and \cite{jochmans2022heteroscedasticity} allow for the cases where the linear regression model in (\ref{eq: model}) is a linear-in-parameters mean-square approximation to the conditional expectation 
$\mu_i = E[y_i | X_n,  \mathcal{W}_n]$.  
Assumption \ref{ass: 3} provides regularity conditions on how fast such an approximation should improve.  
We refer interested readers to Section 3.2.3 of \cite{cattaneo2018inference} and Section 2.1 of \cite{jochmans2022heteroscedasticity} for more detailed discussions of this assumption.  

Assumption \ref{ass: 4} follows closely Assumption 4 of \cite{jochmans2022heteroscedasticity},  which is required for the consistency of his variance estimator. 
In particular,  the condition that $\max_i \mu_i^2 = o_p(n)$ is used to control the variance of $\sum_{i=1}^n \hat{v}_i^2 (y_i \acute{u}_i)$,  as the variance of $y_i \acute{u}_i$ depends on $\mu_i^2$. 
Interested readers are referred to Section 2.2 and Supplementary Appendix A.2 of \cite{jochmans2022heteroscedasticity} for more discussions and related sufficient conditions.   

Assumption \ref{ass: 5} contains the conditions for the modified wild bootstrap procedure.   
Specifically,  it requires the random weights of the wild bootstrap to be independent from the sample,  
to have their mean equal to zero,  their variance equal to one,  and a finite fourth moment. 
Similar to Assumption \ref{ass: 4},  we need the last condition in Assumption \ref{ass: 5} to control the (conditional) variance of $\sum_{i=1}^n \hat{v}_i^2 (y^*_i \acute{u}^*_i)$.


\section{Proof of Theorem \ref{theom: 1}}
\label{sec:pf_boot-stud-t-power}

We first show that under the null, $n^{-1} \sum_{i=1}^n \hat{v}_i^2 (y_i^*\acute{u}^*_i - \sigma_i^{*2})
= o_{p^*}(1)$. To do so, we follow the steps of the proof for Theorem 1 in \cite{jochmans2022heteroscedasticity}.
Notice that 
\begin{align}\label{eq: proof_1}
n^{-1} \sum_{i=1}^n \hat{v}_i^2 (y_i^*\acute{u}^*_i - \sigma_i^{*2})
= n^{-1} \sum_{i=1}^n \hat{v}_i^2 (u_i^{*2} - \sigma_i^{*2}) + n^{-1} \sum_{i=1}^n \hat{v}_i^2 (y_i^*\acute{u}^*_i - u_i^{2*}),
\end{align}
where $\sigma_i^{*2} = E^*[u_i^{*2}] = a_n^2(\beta_0) \tilde{u}^2_i(\beta_0)$. 
%and $n^{-1} \sum_{i=1}^n \hat{v}_i^2 \sigma_i^{2*} = n^{-1} \sum_{i=1}^n \hat{v}_i^2 y_i \acute{u}_i(\beta_0)= n^{-1} \acute{\Sigma}_n(\beta_0)$.  

For the first term on the right-hand side of (\ref{eq: proof_1}),  we have 
$E^*\left[ n^{-1} \sum_{i=1}^n \hat{v}_i^2 (u_i^{*2} - \sigma_i^{*2}) \right] =0.$
Furthermore,  for the variance (conditional on the data)
\begin{align*}
& E^*\left[ \left(n^{-1} \sum_{i=1}^n \hat{v}_i^2 (u_i^{*2} - \sigma_i^{*2}) \right)^2 \right] \notag \\
&= n^{-2} \sum_{i=1}^n \hat{v}_i^4 \left( E^*[u_i^{*4}] - \sigma_i^{*4} \right)  
= n^{-2} \sum_{i=1}^n \hat{v}_i^4 \left( a_n^4(\beta_0) E^*[\omega_i^{*4}] \tilde{u}^4_i(\beta_0) - 
(a_n^2(\beta_0) \tilde{u}^2_i(\beta_0) ) \right) 
= o_p(1),
\end{align*}
which follows from $a^2_n(\beta_0) = O_p(1)$,  $\tilde{u}^2_i(\beta_0)	 = O_p(1)$, 
$(\max_i |\hat{v}_i|/\sqrt{n})^2 = o_p(1)$,  $n^{-1}\sum_{i=1}^n\hat{v}_i^2 = O_p(1)$, 
and Assumption \ref{ass: 5}.
In particular, $n^{-1}\sum_{i=1}^n \hat{v}_i^2 \leq n^{-1}\sum_{i=1}^n v_i^2 
\leq 2(n^{-1} \sum_{i=1}^n Q_i^2) + 2(n^{-1}\sum_{i=1}^n V_i^2)
=O_p(\chi_n) + O_p(1) = O_p(1)$.

Therefore,  we have 
\begin{align}\label{eq: proof_3}
n^{-1} \sum_{i=1}^n \hat{v}_i^2 (u_i^{*2} - \sigma_i^{*2}) =o_{p^*}(1). 
\end{align}

Then, for the second term on the right-hand side of (\ref{eq: proof_1}),  we use the following decomposition:
\begin{align}\label{eq: proof_2}
& n^{-1} \sum_{i=1}^n \hat{v}_i^2 (y_i^*\acute{u}^*_i - u_i^{2*}) \notag \\
&= n^{-1} \sum_{i=1}^n \sum_{j \neq i} \hat{v}_i^2 u_i^* (A_n)_{ij} u_j^* 
 + n^{-1} \sum_{i=1}^n \hat{v}_i^2 ((A_n)_{ii} - 1) u_i^{*2} + n^{-1} \sum_{i=1}^n \sum_{j=1}^n \hat{v}_i^2 \hat{\mu}_i(\beta_0) (A_n)_{ij} u_j^*,
% \notag \\
\end{align}
which follows from 
$(A_n)_{ij} = (H_n)_{ij} / (M_n)_{ii}$,  $(H_n)_{ij} = (M_n)_{ij} - (n^{-1} \sum_{k=1}^n \hat{v}_k^2)^{-1} (n^{-1} \hat{v}_i \hat{v}_j )$, 
and $\acute{u}_i^* = \sum_{j=1}^n ((H_n)_{ij}/(M_n)_{ii}) u_j^* = \sum_{j=1}^n (A_n)_{ij} u_j^*$. 
We aim to show that all the three terms on the right-hand side of (\ref{eq: proof_2}) are of $o_{p^*}(1)$. 

For the first right-hand side term, we notice that 
$E^*\left[ n^{-1}\sum_{i=1}^n\sum_{j \neq i} \hat{v}_i^2 u_i^* (A_n)_{ij} u_j^* \right] = 0$
and 
\begin{align*}
& E^*\left[ \left( n^{-1}\sum_{i=1}^n\sum_{j \neq i} \hat{v}_i^2 u_i^* (A_n)_{ij} u_j^*\right)^2 \right] \notag \\
& = n^{-2} \sum_{i_1=1}^n \sum_{i_2=1}^n \sum_{j_1 \neq i_1} \sum_{j_2 \neq i_2} 
\hat{v}_{i_1}^2 (A_n)_{i_1, j_1} E^*[ u_{i_1}^* u_{j_1}^* u_{i_2}^* u_{j_2}^*] (A_n)_{i_2, j_2} \hat{v}^2_{i_2} \notag \\
& \leq \left( \max_i \sigma_i^{*2} \right)^2 n^{-2} \sum_{i=1}^n \hat{v}_i^4 \sum_{j \neq i} (A_n)_{ij}^2  
   + \left( \max_i \sigma_i^{*2} \right)^2 n^{-2} \sum_{i=1}^n \sum_{j \neq i} \hat{v}_i^2 \hat{v}_j^2 (A_n)_{ij} 
   (A_n)_{ji} = o_p(1),
%& + \left( \min_i (M_n)_{ii} \right)^{-2}  \left( \max_i E^*[u_i^{*4}] \right) \left( \max_i %|\hat{v}_i|/\sqrt{n} \right)^2  \left( n^{-1} \sum_{i=1}^n \hat{v}_i^2 \right) 
%   = o_p(1),
\end{align*}
which follows from $E^*[ u_{i_1}^* u_{j_1}^* u_{i_2}^* u_{j_2}^*] = 0$ except for the cases where 
(1) $i_1=i_2$ and $j_1=j_2$ , or (2) $i_1=j_2$ and $i_2=j_1$, 
$\sum_{j \neq i} (A_n)_{ij}^2 \leq \sum_{j=1}^n (A_n)^2_{ij} = (H_n)_{ii} (M_n)_{ii}^{-2} 
\leq (M_n)_{ii}^{-2}$,  
$\sum_{j \neq i} (A_n)_{ij} (A_n)_{ji} \leq \sum_{j=1}^n (A_n)_{ij} (A_n)_{ji} 
\leq (\min_i (M_n)_{ii} )^{-2}$, 
$(\min_i(M_n)_{ii})^{-1}=O_p(1)$, 
$\max_i \sigma_i^{*2}=O_p(1)$,  %$\max_i E^*[u_i^{*4}]=O_p(1)$,  
$(\max_i |\hat{v}_i |/\sqrt{n})^2 = o_p(1)$,  
and $n^{-1}\sum_{i=1}^n\hat{v}_i^2=O_p(1)$.
%\begin{align*}
%\left( \max_i \sigma_i^{*2} \right)^2 n^{-2} \sum_{i=1}^n \hat{v}_i^4 \sum_{j \neq i} (A_n)_{ij}^2
%\leq 
%\end{align*}

Using similar arguments,  we find the second right-hand side term in (\ref{eq: proof_2}) has (conditional) mean
\begin{align*}
E^* \left[ n^{-1} \sum_{i=1}^n \hat{v}_i^2 ((A_n)_{ii} -1) u_i^{*2} \right]
= \left( n^{-1} \sum_{i=1}^n \hat{v}_i^2 \right)^{-1} n^{-2} \sum_{i=1}^n \hat{v}_i^4 \sigma_i^{*2} (M_n)_{ii}^{-1} = o_p(1), 
\end{align*}
by using $n^{-1}\sum_{i=1}^n\hat{v}_i^2=O_p(1)$, $(\max_i |\hat{v}_i |/\sqrt{n})^2 = o_p(1)$,  
$\max_i \sigma_i^{*2}=O_p(1)$, and $(\min_i(M_n)_{ii})^{-1}=O_p(1)$. 
Similarly, we obtain that it has (conditional) variance
\begin{align*}
& E^* \left[ \left( n^{-1} \sum_{i=1}^n \hat{v}_i^2 ((A_n)_{ii} -1) u_i^{*2} \right)^2 \right] \notag \\
& = \left(n^{-1} \sum_{i=1}^n \hat{v}_i^2 \right)^{-2}
\left(n^{-4} \sum_{i=1}^n \sum_{j=1}^n \hat{v}_i^4 \hat{v}_j^4 (M_n)_{ii}^{-1} (M_n)_{jj}^{-1} E^*[u_i^{*2}u_j^{*2}] \right) = o_p(1), 
\end{align*}
by using the Cauchy-Schwarz inequality and Assumption \ref{ass: 5}. 

The third right-hand side term in (\ref{eq: proof_2}) has (conditional) mean
%\begin{align*}
$E^*\left[ n^{-1} \sum_{i=1}^n \sum_{j=1}^n \hat{v}_i^2 \hat{\mu}_i(\beta_0) (A_n)_{ij} u_j^* \right] =0,$
%\end{align*}
and (conditional) variance
