Therefore,  we obtain that all the three right-hand side terms in (\ref{eq: proof_2}) are of $o_{p^*}(1)$ and thus
$n^{-1}\sum_{i=1}^n\hat{v}_i^2(y_i^*\acute{u}_i^* - u_i^{*2}) = o_{p^*}(1)$. 

Combining with (\ref{eq: proof_3}),  we obtain that under the null,
$n^{-1} \sum_{i=1}^n \hat{v}_i^2 (y_i^*\acute{u}^*_i - \sigma_i^{*2}) = o_{p^*}(1)$, which, together with the definition of $\sigma_i^{*2}$, 
further implies that 
\begin{align}\label{eq: proof_4}
n^{-1} \sum_{i=1}^n \hat{v}_i^2 y_i^*\acute{u}^*_i - n^{-1} \acute{\Sigma}_n(\beta_0) = o_{p^*}(1).
\end{align}

Now, let $\bar{t}_n^* = (\hat{\beta}_n^* - \beta_0)/\sqrt{\acute{\Omega}_n(\beta_0)}$,  
where $\acute{\Omega}_n(\beta_0) = (\sum_{i=1}^n \hat{v}_i^2)^{-1}  \acute{\Sigma}_n(\beta_0) (\sum_{i=1}^n \hat{v}_i^2)^{-1}$. Then,  under the null hypothesis,  by Lemma 2.9.5 of \cite{van1996weak} and the bootstrap data generating process in Section 3,  we have 
\begin{align*}
\bar{t}^*_n = \left( n^{-1} \acute{\Omega}_n(\beta_0) \right)^{-1/2} \left( \sum_{i=1}^n \hat{v}_i^2 \right)^{-1} \frac{1}{\sqrt{n}}\sum_{i=1}^n \hat{v}_i u_i^*
\rightarrow^{d^*} N(0,1),  
\end{align*}
in probability.  
Furthermore,  by (\ref{eq: proof_4}) and Slutsky's theorem,  we have
\begin{align*}
t_n^* = \left( n^{-1} \acute{\Omega}_n^*\right)^{-1/2}  \left( n^{-1} \acute{\Omega}_n(\beta_0) \right)^{1/2} \bar{t}_n^* \rightarrow^{d^*} N(0,1),  
\end{align*}
in probability.  
Finally,  the conclusion follows by Polya's theorem.  $\blacksquare$

\section{Simulation Results for the Fixed Effect Model}\label{sec:further simu}

The second simulation model considered is a one-way fixed effect model for panel data, similar to the one considered in \cite{jochmans2022heteroscedasticity}. 
For double-indexed data $(y_{(g,m)}, x_{(g,m)})$,  it can be written as 
\begin{align*}
y_{(g,m)} = x_{(g,m)} \beta + \alpha_g + \epsilon_{(g,m)}, \;\; g=1, ..., G, \;\; m=1, ..., M, 
\end{align*}
where $\alpha_g$ is a group-specific intercept.
For this model, the fixed effect estimator equals the OLS estimator of $y_{(g,m)}$ on $x_{(g,m)}$ and $G$ group dummy variables. 
%i.e., the least squares dummy variable estimator. 
Following \cite{jochmans2022heteroscedasticity}, we let $x_{(g,m)} \sim i.i.d. N(0,1)$, $\epsilon_{(g,m)} \sim i.i.d.N(0,1)$, $\beta=2$, 
