\subsection{Symbolic Termination via Ranking Function}

\begin{definition}[Cycle Distance Ranking]
Let \( \mathcal{C} \subset S \) be the 3-cycle defined in Theorem~\ref{thm:cycle}.  
Define the symbolic ranking function \( \varrho : S \to \mathbb{N} \) by
\[
\varrho(s) := \min \{k \in \mathbb{N}_0 \mid \delta^{(k)}(s) \in \mathcal{C}\}
\]
\end{definition}

\begin{lemma}[Monotonic Descent]
Every symbolic transition $\delta(s_i) = s_{i+1}$ satisfies:
\[
\varrho(s_{i+1}) \leq \varrho(s_i),
\]
with strict inequality unless $s_i \in \mathcal{C}$
\end{lemma}

\begin{theorem}[Symbolic Termination]
All symbolic trajectories $(s_0, s_1, \dots)$ generated by iterated application of $\delta$ reach the terminal cycle $\mathcal{C}$ in finitely many steps.
\end{theorem}

\begin{proof}
The function $\varrho$ is finite-valued and strictly decreases outside $\mathcal{C}$. Thus, every sequence must eventually enter the cycle, and no infinite descent is possible.
\end{proof}

\begin{corollary}[Convergence of Collatz Iterates]
\label{cor:symbolic-termination}
For every $n \in \mathbb{N}^+$, the symbolic trajectory of $n$ under $\delta$ terminates in the 3-cycle $\mathcal{C}$, and hence the classical Collatz sequence enters the loop $4 \to 2 \to 1$.
\end{corollary}

