First note that for any $n \in \bN$ and $x \in \Ninfty$, we can prove by
induction over $|\iota(x)|$ that we have
\[\left(\exists m \in \bN. \; h(x) = \underline{\tuple{n,m}}\right)
\quad \Longleftrightarrow \quad \left(\exists m' \in \bN. \; x = \underline{\tuple{n,m'}}\right)
\qquad \qquad (\dagger)\]

Define $\mathrm{sgn} : \bZ \to 2$ as the map with $\mathrm{sgn}(d) = 1$ if and
only if $d \ge 0$. By~\Cref{lem:oscillation}, it suffices to show that
$\mathrm{sgn} \circ \iota$ takes the values $0$ and $1$ infinitely often
over $\underline{\bN}$. To this end, fix some $a \in \bN$, $i \in 2$ and let us
look for some values $b \ge a$ with $\mathrm{sgn}(\iota(b)) = i$.
First note that for any such $a$, there is $n_0 \in \bN$ such that
\[\forall n \ge n_0. \; \forall m \in \bN. \; a \le \tuple{n, m}\]
Pick $n$ such that $2n + i \ge n_0$. We make a case distinction on $i$:
\begin{itemize}
\item If $i = 0$, by~$(\dagger)$, $h^{-1}(\underline{\tuple{2n,0}}) = \underline{\tuple{2n, m}}$
  for some $k \in \bN$.
  Set $d = \iota(\underline{\tuple{2n,m}})$ and assume towards a contradiction
  that $d \ge 0$. By definition
  definition $h(\underline{\tuple{2n,m}}) = (\underline{f} \circ \underline{g})^d(\underline{f}(\underline{\tuple{2n, m}}))$. Using the fact that
  $\underline{f}$ and $\underline{g}$ are liftings, we thus have
  $h(\underline{\tuple{2m,m}}) = \underline{(f \circ g)^d(\tuple{2n,m+1})} = \underline{\tuple{2n,0}}$.
  But we have that $f \circ g$ is increasing, so we cannot have $d \ge 0$.
  So $d < 0$ and $\mathrm{sgn}(\iota(h^{-1}(\underline{\tuple{2n,0}}))) = 0$.
\item If $i = 1$, set $d = \iota(\underline{\tuple{2n+1, 0}})$.
  We have that $h(\underline{2n+1,0})$ should be well-defined as
  \[\left(\underline{f} \circ (\underline{g} \circ \underline{f})^d\right)(\tuple{2n+1,0})\]
  In particular, this would mean that if $d < 0$, we should have that
  $z = \underline{g}^{-1}(\tuple{2n+1,0})$ should be defined. We cannot
  have $z = \infty$, for it would contradict injectivity of $\underline(g)$,
  so by $\MP$, we have some $n', m' \in \bN$ such that $z = \underline{\tuple{n',m'}}$.
  But then we have $\underline{g}(\tuple{n',m'}) = \underline{g(\tuple{n',m'})} = \underline{\tuple{2n+1,0}}$, which is a contradiction as
  $\tuple{2n+1,0}$ is not in the image of $g$. Hence
  $d \ge 0$ and $\mathrm{sgn}(\iota(\underline{\tuple{2n+1,0}})) = 1$.
\end{itemize}
\end{proof}

We can use that to prove that $\Ninfty$ does not have the Myhill property in Kleene-Vesley
realizability thanks to the following lemma (for which, we assume the reader is familiar with Kleene-Vesley realizability). Recall that a partitioned modest set $Z$ consists of a pair $(|Z|, \Vdash_Z)$ consisting of a carrier
and a relation $\Vdash_Z \subseteq \mathcal{K}_2 \times |Z|$ which is actually a bijection.

\begin{lemma}
\label{lem:transfermodestcountable}
Working classically (and meta-theoretically), let $X$ be a partitioned modest set in the Kleene-Vesley topos with 
countable carrier $|X|$.
Then if ``$X$ has the Myhill property'' holds in Kleene-Vesley realizability, so does ``$X$ has the strong Myhill property''.
\end{lemma}
\begin{proof}
For this proof, write $e \Vdash \varphi$ for ``$e$ realizes $\varphi$'' and $\tuple{ -, -, \ldots}$ for the standard tupling in a PCA. We will also use the
$\lambda$ notation when convenient to work in $\mathcal{K}^{\mathrm{rec}}_2$.
Assume we have a realizer $e_{\mathrm{My}} \in \mathcal{K}_2^{\mathrm{rec}}$ for ``$X$ has the Myhill property''.
Shuffling around the arguments of $e_{\mathrm{My}}$ and suppressing those that have trivial computational content due to $X$ being a modest set, we have that whenever $e_f \Vdash_{X \to X} f$ and $e_g \Vdash_{X \to X} g$
for injections $f, g : |X| \to |X|$ and we have, for some $A, B : |X| \to \powerset(\mathcal{K}_2)$,
realizers
\[ e_{f,\preceq} \Vdash \forall x \in X. \; x \in A \Leftrightarrow f(x) \in B \quad \text{and}
\quad e_{g,\preceq} \Vdash \forall x \in X. \; x \in B \Leftrightarrow g(x) \in A
\]
then we have some bijection $h : |X| \to |X|$ and codes
\[e_h \Vdash_{X \to X} h \qquad e_{h^{-1}} \Vdash_{X \to X} h^{-1} \quad \text{and} \quad e_{h, \preceq} \Vdash \forall x \in X. \; x \in A \Rightarrow h(x) \in B\] such that $e_{\mathrm{My}} \; e_f \; e_g \; e_{f, \preceq} \; e_{g, \preceq} \simeq \tuple{e_h, e_{h^{-1}}, e_{h,\preceq}}$.

We will use this to build a realizer $e_{\mathrm{sMy}} \in \mathcal{K}_2^{\mathrm{rec}}$ that $X$ has the strong Myhill property, that is, we should have for every $e_f \Vdash_{X \to X} f$ and $e_g \Vdash_{X \to X} g$ for injections $f, g : |X| \to |X|$ that there is a bijection $h : |X| \to |X|$
and codes $e_h \Vdash_{X \to X} h$, $e_{h^{-1}} \Vdash_{X \to X} h^{-1}$
and $e_{h, \mathrm{sMy}}$ such that, for every $e_x \Vdash_X x$, there is $m \in \bZ$ such that  $e_{h, \mathrm{sMy}} \; e_x \Vdash_{\bZ} m$ and $h(x) = f \circ (g \circ f)^m$.
To then argue that our proposed realizer is sound,
we will exploit correctness of $e_{\mathrm{My}}$ for different predicates $A_{e_f, e_g}, B_{e_f, e_g} : |X| \to \powerset(\mathcal{K}_2)$, where $e_f, e_g \in \mathcal{K}_2$ are codes for injections $f, g : |X| \to |X|$.

Concretely $e_{\mathrm{sMy}}$ is defined by
\[ e_{\mathrm{sMy}} = \lambda e_f. \lambda e_g. p \; \left(e_{\mathrm{My}} \; e_f \; e_g \; e_0 \; e_1\right) \]
where $p$, $e_0$ and $e_1$ are characterized as follows:
\begin{itemize}
\item $e_0$ is a code for the function $X \longto \left( \bZ \times \Baire \to \bZ \times \Baire\right)^2$
which ignores its argument and produces the following two functions:
\[(m, p) \longmapsto (m+1,p) \qquad (m, p) \longmapsto (m-1,p)\]
\item similarly, $e_0$ is a code for a function $X \longto \left( \bZ \times \Baire \to \bZ \times \Baire\right)^2$
that ignores its argument and produces a code for two functions, but this time, the functions in question are both the identity
\item $p$ codes a map $\id_{\mathcal{K}_2} \times \id_{\mathcal{K}_2} \times p' : (\mathcal{K}_2)^3 \to (\mathcal{K}_2)^3$ that acts componentwise. The first two components are the identity, but the last one is non-trivial. $p'$ takes as input a code for map $\iota' : X \to \left(\bZ \times \Baire \partto \bZ \times \Baire\right)^2$ and outpus a code for a map $X \partto \bZ$ as follows: the $X$ argument $x$ of $p'$ is fed to $\iota'$
unchanged and we take a code for the corresponding first component $a_x : \bZ \times \Baire \partto \bZ \times \Baire$. Define the map $a'_x : \Baire \partto \bZ$ by $a'_x(s) = \pi_1(a_x(0,s))$. What $p'$ applied to a
code for $x$ does is looking for any computable\footnote{It would be sufficient to restrict to sequence that
are ultimately $0$.} $s \in \Baire$ such that $a'_x$ is well-defined and outputs
the code of $a'_x(s)$.
\end{itemize}

Now let's see why this realizer is correct. Assume we have $f, g : |X| \to |X|$ injective and $e_f \Vdash_{X \to X} f$ and $e_g \Vdash_{X \to X} g$. Using countability of $|X|$,
fix a map $C : |X| \to \powerset(\mathcal{K}_2)$ such that $(C(x))_{x \in |X|}$
is an antichain in the Turing degrees relative to the infinite tupling of
$e_f$, $e_g$ and the countably many\footnote{This set is countable because
$|X|$ is countable and $X$ is partitioned modest.} $e_x$ such that $e_x \Vdash_X x$ for some $x \in |X|$
 (that is, if we take this tupling as oracle, we can't compute Turing reductions
between $C(x)$ and $C(y)$ whenever $x \neq y$). $C$ corresponds, in the semantics of Kleene-Vesley
realizability, to a subset of $X$. We then define $A : |X| \to \powerset(\mathcal{K}_2)$ such that $A(x)$
consists of code $\tuple{e, e'}$ such that $e \Vdash_\bZ m$ for some $m \in \bZ$ and $e' \in C_{(f \circ g)^m(x)}$.
$B : |X| \to \powerset(\mathcal{K}_2)$ is then simply defined by $B(x) = B(g(x))$.

The basic intuition is that, for providing evidence that $x$ belongs to $A$ (or $B$), one must provide some evidence that we can compute the degree $C(y)$ associated with some $y$ in the same connected component in the bipartite graph generated by $f$ and $g$ and some $m \in \bZ$ that tells us how to travel from $y$ to $x$ in the graph. With this in mind, it is not difficult to check that we have
\[e_0 \Vdash \forall x \in X. \; x \in A \Leftrightarrow f(x) \in B \qquad \text{and}\qquad
e_1 \Vdash \forall x \in X. \; x \in A \Leftrightarrow g(x) \in B
\]
We thus know that $e_{\mathrm{My}} \; e_f \; e_g \; e_0 \; e_1 \simeq \tuple{e_h, e_{h^{-1}}, e_{h, \preceq}}$
with $e_h$ and $e_{h^{-1}}$ describing the bijection $h$ we desire and $e_{h, \preceq} \Vdash \forall x \in X. \; h(x) \in A \Leftrightarrow x \in B$. Now, we simply need to know that, for any $e_x \Vdash_X x$, $p' \; e_{h, \preceq} \; e_x$ computes a code for some $m \in \bZ$ such that $h(x) = f \circ (g \circ f)^m(x)$.
Here the procedure encoded in $p'$ first turns produces some $e' \in \mathcal{K}_2$ which is computable
from $\tuple{e_f, e_g, e_x}$ such that
\[e' \Vdash x \in A \Rightarrow h(x) \in B\]
More concretely, this means that $e'$ represents a map
$\alpha : \bZ \times C(x) \to \bZ \times C(x)$ such that 
$(\pi_1 \circ \alpha)(n,s) = m$ implies that $h(x) = f \circ (g \circ f)^{m-n}(x)$. Ultimately,
$p'$ searches for some approximation of $s$ that makes the code output some $m$ for $n = 0$.
Since convergence must happen after finding a finite prefix of $s$, $p'$ will find such a $k$.
But since $C(x)$ is a Turing degree, it is dense in $\Baire$, so the prefix used must be consistent
with some $s \in C(x)$ and thus the obtained $k$ satisfies $h(x) = f \circ (g \circ f)^{m-n}(x)$.
\end{proof}


\begin{corollary}
\label{cor:KVnotNinftyMP}
Kleene-Vesley realizability does not validate that $\Ninfty$ has the Myhill property.
\end{corollary}
\begin{proof}
$\Ninfty$ is a partitioned modest set in Kleene-Vesley realizability with a countable carrier.
So if it had the Myhill property, it would have the strong Myhill property by~\Cref{lem:transfermodestcountable}.
But this is not the case by~\Cref{thm:oscNinftyNotMP}.
\end{proof}


\subsection{Failure of stability under exponentiation, product and coproducts}
\label{subsec:negEM}


Here we show
that if the class of sets with the Myhill property
is closed under either products, exponentiations or coproducts, $\LPO$ implies
full excluded middle, an implication which is not provable constructively~\cite{HL16}.
This relies on sets parameterized by truth values rather than concrete counter-examples
much like in the proofs that Cantor-Bernstein implies excluded middle
in~\cite{CBEM}. 

\begin{lemma}
  \label{lem:expEM}
For any $p \in \Omega$, if $(\{0,1\} \uplus \{2 \mid p\})^\bN$ has the Myhill property,
then $p \vee \neg p$ holds.
\end{lemma}
\begin{proof}
Call $2_\infty$ the sequence defined by $(2_\infty)_0 = 2$ and $(2_\infty)_{n + 1} = 0$
for all $n \in \bN$.
Take $A = \{2x \mid x \in \Ninfty\}$ and $B = A \cup \{ 2_\infty \mid p\}$.
Reductions between $A$ and $B$ are witnessed by the following injections $f$ and $g$:
\begin{itemize}
  \item $f(s)$ is defined by shifting $s$ by inserting two zeroes at the beginning:
\[f(s)_0 = f(s)_1 = 0
\quad \text{and} \quad f(s)_{n + 2} = s_{n + 2}\]
  \item $g(s)$ is defined by case depending on the value of $s_0$:
    \begin{itemize}
      \item if $s_0 = 2$, then we define $g(s)_0 = 1$ and $g(s)_{n+1} = s_{n+1}$
      \item otherwise, we set $g(s)_0 = g(s)_1 = 0$ and $g(s)_{n+2} = s_n$
    \end{itemize}
\end{itemize}
These two functions are easily checked to be injections and we do have
$f^{-1}(B) = A$ and $g^{-1}(B) = A$. Now assume that, thanks to the Myhill
property, we have a bijection $h : 
(\{0,1\} \uplus \{2 \mid p\})^\bN
\to
(\{0,1\} \uplus \{2 \mid p\})^\bN$
such that $h(A) = B$.
By \Cref{thm:Ninftysel}, we can decide whether there exists
$x \in \Ninfty$ such that $h(x)_0 = 2$ or not.
If there is, then we know that $p$ must hold. Otherwise, assuming $p$,
we know that $2_\infty \in B$. But then since $B = h(A)$ and $A \subseteq \Ninfty$,
we would have a contradiction. Hence $\neg p$ holds in that case.
\end{proof}
\begin{corollary}
  \label{cor:coproductMyhill}
``$A^B$ has the Myhill property whenever $A$ and $B$ both have the strong Myhill property''
entails excluded middle.
\end{corollary}
\begin{proof}
Combine the previous lemma with~\Cref{lem:subfinite} and Myhill's isomorphism
theorem.
\end{proof}

\begin{lemma}
For any $p \in \Omega \subseteq 1$, if $p + \bN$ has the Myhill property
and $\LPO$ holds, then $p \vee \neg p$ holds.
\end{lemma}
\begin{proof}
Take $A = \{\inr(2n) \mid n \in \bN\}$, $B = \{\inl(0) \mid p\} \cup A$ and
$f, g : p + \bN \to p + \bN$ defined by
\[
\begin{array}{lcl!\qquad lclr}
  f(\inr(k)) &=& \inr(k + 2) & g(\inr(k)) &=& \inr(k+2) \\
  f(\inl(0)) &=& \inr(1) & g(\inl(0)) &=& \inl(0) & \text{(if $p$ holds)} \\
\end{array}
\]
Using the Myhill property, we have a bijection $h : p + \bN \to p + \bN$
with $h(A) = h(B)$. Using $\LPO$, we can decide whether the sequence
$n \mapsto h(\inr(2n))$ ever takes the value $\inl(0)$ (which is equivalent
to deciding whether $\inl(0) \in h(A)$). If we do have
$h(\inr(2n)) = \inl(0)$, we do know that $p$ holds. Otherwise, assuming $p$,
we know that $\inl(0) \in p + \bN$, and we thus should have $h^{-1}(\inl(0)) \in A$,
which contradicts $\inl(0) \not\in h(A)$; hence $\neg p$ holds.
\end{proof}

\begin{lemma}
For any $p \in \Omega$, if $(p \uplus \{1\}) \times \bN$ has the Myhill property and $\LPO$ holds,
then $p \vee \neg p$ holds.
\end{lemma}
\begin{proof}
Take $A = \{ (1, \inr(2x)) \mid x \in \bN\}$ and $B = A \cup \{(0, 0) \mid p\}$.
Then we have injections 
$f$ and $g$ that witness $A \preceq_1^{(p \uplus \{1\}) \times \Ninfty} B$ and $B \preceq_1^{(p \uplus \{1\}) \times \Ninfty} A$
respectively:
\[
\begin{array}{llcl !\qquad lcl}
& f(1, z) &=& (1,2 + z) &
g(1,z) &=& (1, 2 + z) \\
 \text{and, if $p$ holds, } &
 f(0, x) &=& (0, x + 1) &
 g(0, {0}) &=& (1, {0}) \\
& & & & g(0, x + {1}) &=& (0, x) \\
\end{array}
\]
Now, if $p + \bN$ has the Myhill property, then we have a bijection $h :
(p \uplus \{1\}) \times \bN \to (p \uplus \{1\}) \times \bN$
with $h(A) = B$. 
By $\LPO$, we can decide whether there exists
$x \in \bN$ such that $h(1,x) = (0, {0})$ or not.
If there is, then we know that $p$ must hold.
Otherwise, assuming $p$, we have $(0, {0}) \in B$.
But since $B = h(A)$ and $A \subseteq \{1\} \times \Ninfty$, we then would
have a contradiction. Hence $\neg p$ holds in that case.
\end{proof}

\begin{corollary}
  \label{cor:coproductMyhill}
``$A+B$ or $B+A$ has the Myhill property whenever $A$ and $B$ both have the strong Myhill property''
together with $\LPO$ entails excluded middle.
\end{corollary}

\section{Weakening the Myhill property and one positive result}
\label{sec:positive}

\subsection{The modal Myhill property}

For the rest of this paper, we will discuss
a weakening of the Myhill property, as well as a corresponding weakening of
the strong Myhill property. The basic idea is that, while we are still going to
ask explicitly for a bijection, we will relax our requirement on its correctness
so that we may no longer extract evidence telling us explicitly
which paths to follow in graphs such as those pictured
in Figures~\ref{fig:myhilliso55} and~\ref{fig:NinftyMPLPO}.

To do this, we are going to use some modalities, taking some inspiration
from~\cite{RSSmod,Kihara24rethinking,Swan24}.

\begin{definition}
A modality is a map $\modal : \Omega \to \Omega$ such that, for
every proposition $p \in \Omega$, $p \Rightarrow \modal p$.
We call a proposition $p$ $\modal$-stable if the converse
$\modal p \Rightarrow p$ holds and, for any set $X$, we say that $A \subseteq X$
is a $\modal$-subset of $X$ if, for every $x \in X$, $x \in A$ is $\modal$-modal.

Given two modalities $\modal, \modal' \in \Omega$, we say that $\modal \le \modal'$
if for every $p \in \Omega$, $\modal p$ implies $\modal' p$.
\end{definition}

The double-negation map $\dneg : \Omega \to \Omega$ is the main modality we are
going to use. In realizability models, double-negation erases the computational
content of propositions (that is, double-negated statement can always be trivially
witnessed). The other one, which we will use 
to make a couple positive results a bit sharper, is defined as follows.

\begin{definition}[The mindchange modality]
For any proposition $p \in \Omega$, define $\modal_{\LPO} p$ as
\[ \exists x \in \Ninfty. \; \left(x \in \underline{\bN} \vee x = \infty\right) \Rightarrow p\]
\end{definition}
The basic intuition is that proving $\modal_{\LPO} p$ is the same as proving
$p$ after asking an $\LPO$ question. The witness $x \in \Ninfty$ indicates
that we want to ask whether $x = \underline{t}$ for some $t$ or whether $x =\infty$
before we can prove $t$.

\begin{lemma}
  \label{lem:LPOltdneg}
  We have $\modal_{\LPO} \le \neg\neg$.
\end{lemma}
\begin{proof}
Assume that $\neg p$ holds and $\modal_{\LPO} p$, that is, we have some $x \in \Ninfty$
and $x \in \underline{\bN} \cup \{\infty\}$ implies $p$.
Then we clearly have $x \not\in \underline{\bN}$, so by induction we can
show that $x \ge \underline{n}$ for all $n \in \bN$, and thus that $x = \infty$.
But this is also a contradiction.
\end{proof}

\begin{remark}
\label{rem:modWei}
The nomenclature $\modal_{\LPO}$ is chosen because $\modal_{\LPO}$ is an instance of the following
construction: to a map $r : S \to Q$, one may assign the following endomap
on truth values:
\[
\begin{array}{llcl}
  \modal_r :& \Omega &\longto&\Omega\\
            &  p &\mapsto& \exists q \in Q. \; \forall s \in S. \; r(s) = q ~ \Longrightarrow ~p
\end{array}
\]
Regarding $r$ as a problem with inputs $q \in Q$ and solutions $r^{-1}(q)$, proving
$\modal_r p$ means ``we can prove $p$ provided we can solve one instance of $F$''.
In particular ``$r$ has a section'' proves that $\modal_r$ is the identity over $\Omega$.

The obvious map $\bN + \{ \infty\} \to \Ninfty$ yields $\modal_\LPO$, and this
map having a section is equivalent to $\LPO$.
\end{remark}


Note that, unlike $\dneg$, $\modal_{\LPO}$ is \emph{not} idempotent: to prove
$\modal_{\LPO}\modal_{\LPO} p$, one is allowed to ask two $\LPO$ questions
in succession.
To get a closure operators, one would need to allow an arbitrary finite number
of mindchanges, resulting in a modality better named $\modal_{\LPO^\diamond}$ or
$\modal_{\mathsf{C}_\bN}$ (see~\cite[Proposition 10]{NeumannP18}). Let us
define it now.

\begin{definition}[The finite mindchange modality]
Define the modality $\modal_{\LPO^\diamond}$ as the map which takes $p \in \Omega$ to
\[ \exists s : \bN \to \bN. \;
  \text{$s$ is monotone, $\neg\left( \lim_{n \to +\infty} s(n) = +\infty\right)$ and }
\left(\forall \ell \in \bN. \; \lim_{n \to +\infty} s(n) = \ell ~ \Longrightarrow ~ p\right)\]
\end{definition}

We now define the weakening of the (strong) Myhill property. In what follows,
$\modal$ is an arbitrary modality.

\begin{definition}
We say that a set $X$ has the $\modal$ strong Myhill property when, for
every pair of injections $f, g : X \to X$, there is a bijection
  $h : X \to X$ such that, for every $x \in X$,
$\modal\left(h(x) \in \bigcup_{m \in \bZ} f \circ (g \circ f)^{m}\right)$ holds.

We say that $X$ has the $\modal$ Myhill property if, for any $\modal$-subsets
$A, B \subseteq X$, we have that $A \preceq_1^X B$ and $B \preceq_1^X A$ imply
that $A \simeq^X B$.
\end{definition}

By unpacking the definitions and~\Cref{lem:LPOltdneg} one can
establish the following.

\begin{proposition}
Let $\modal \le \modal'$ be two modalities and $X$ be a set. The following holds:
\begin{itemize}
\item If $X$ has the $\modal$ (strong) Myhill property, then it also has the
    $\modal'$ (strong) Myhill property.
\item If $X$ has the $\modal$ strong Myhill property, then it has the $\modal$ Myhill property
\end{itemize}
\end{proposition}

To which extent those implications are strict is unclear, but we can note the
following when it comes to the $\neg\neg$ modality for certain sets and models.

\begin{remark}
  \label{rem:modest}
If $X$ is a modest set in a realizability model,
then if it holds that $X$ has the $\neg\neg$ Myhill property, then it necessarily has the
$\neg\neg$ strong Myhill property.
\end{remark}
\begin{proof}
Assume we have a realizer $e$ for $X$ having the $\neg\neg$ Myhill property.
Up to trivial modifications, it takes input evidence for $A$ and $B$ being $\dneg$-stable,
codes for injections $f$ and $g$ together
with evidence that $f$ and $g$ reduce $A$ to $B$ and vice-versa and outputs a
code for a bijection $h$ such that $h(A) = B$.
Consider the families of sets
$(A_{f,g,x})_{f,g,x}$ and $(B_{f,g,x})_{f,g,x}$ indexed by injections $f, g : X \to X$
and $x \in X$ defined by
\[
  \begin{array}{l !\quad c !\quad l}
  z \in A_{f,g,x} &\Longleftrightarrow& \neg\neg z \in \bigcup_{m \in \bZ} (g \circ f)^{m}(x) \\
  y \in B_{f,g,x} &\Longleftrightarrow& \neg\neg y \in \bigcup_{m \in \bZ} \left(f \circ (g \circ f)^{m}\right)(x)
\end{array}
\]
Those sets are clearly $\neg\neg$-stable, and this is realized by a trivial
realizer $\bullet$ that does not depend on $f,g$ and $x$. Similarly, evidence that
$f$ and $g$ are reductions can also be realized by the same realizer $\bullet$.
So overall,
$e' := \lambda f. \lambda g. \; e \; \bullet \; \bullet \; f \; g \; \bullet \; \bullet$
realizes ``if $f, g : X \to X$ are injections reducing $A_{f,g,x}$ to $B_{f,g,x}$
and vice-versa, there is a bijection $h : X \to X$ such that $\dneg h(A_{f,g,x}) = B_{f,g,x}$'',
and it does so without inspecting the code of $x$. Furthermore, because we assume
that $X$ is modest, we know that for any codes $e_f$ and $e_g$ for injections,
$e' \; e_f \; e_g$ determines at most one possible bijection $X \cong X$
that must work for all pairs $A_{f,g,x}$ and $B_{f,g,x}$.
Therefore, it follows that $e'$ realizes that $X$ has the $\dneg$ strong Myhill property.
\end{proof}

This remark essentially applies to most concrete examples we examine in the
sequel, as modest sets are closed under exponentiation, (co)products, and
contain $1$, $\bN$ and $\Ninfty$.

\subsection{The conatural numbers have the $\modal_{\LPO}$ strong Myhill property}

\begin{theorem}
  \label{thm:ninftymyhill}
  Assuming $\MP$, $\mathbb{N}_\infty$ has the $\modal_{\LPO}$ strong Myhill property.
\end{theorem}

For this whole subsection, let us thus fix some injections
$f, g : \mathbb{N}_\infty \to \mathbb{N}_\infty$, from which we want to produce
some bijection $h \subseteq \bigcup_{m \in \bZ} f \circ (g \circ f)^{m}$.

The gist of the proof is that one can attempt to build $h$
over $\mathbb{N}_\infty \setminus \{\infty\}$ using the same back-and-forth
construction as in the classical Myhill isomorphism theorem if we
optimistically assume that $f(\infty) = g(\infty) = \infty$.
Of course this is not something we can simply assume nor check, but we can
check that $\inf(f(\infty), g(\infty))$ is ``large enough'' for a
given stage of the construction to not be wrong. If that quantity is always
large enough, this will mean that $f(\infty) = g(\infty) = \infty$ and the
construction will naturally enforce that $h(\infty) = \infty$.
Otherwise, at some stage we will realize (via~\Cref{lem:MPmin}) that either
$f(\infty) \neq \infty$ or $g(\infty) \neq \infty$. In either case, we
can apply~\Cref{lem:badinjectionLPO} to deduce that
$\Ninfty \cong \bN$, which allows us to continue the back-and-forth as if
$\Ninfty$ was actually $\bN$ much like in the original proof of the Myhill
isomorphism theorem.

Now let us make all of that more precise. First, let us define what are
the approximations we are going to build. There are going to be two kinds,
those that are continuous, corresponding to the first optimistic phase.


\begin{definition}
A \emph{continuous partial solution} is a finite subset $I$ of $\bN \times \bN$
such that:
\begin{itemize}
\item $I$ is a partial isomorphism: for all $n, n', m, m' \in \bN$, we have
\[
(n, m) \in I ~\text{and}~ (n', m') \in I \qquad \text{if and only if} \qquad n = n' \Longleftrightarrow m = m'\]
\item the image of $I$ by $(n,m) \mapsto (\underline{n},\underline{m})$ is included in $\bigcup\limits_{m \in \bZ} f \circ (g \circ f)^{m}$
\end{itemize}
We say $I$ has rank (at least) $n$ if
\begin{itemize}
\item for every $k < n$, $k$ belongs to both the domain and codomain of $I$
\item $\inf(f(\infty), g(\infty)) \ge \underline{n}$.
\end{itemize}
\end{definition}

The second kind corresponds to the phase where we noticed
$\inf(f(\infty), g(\infty)) \neq \infty$ and have $\LPO$ available.

\begin{definition}
A \emph{discontinuous partial solution} is a finite subset $I$ of $\Ninfty \times \Ninfty$
such that:
\begin{itemize}
\item $I$ is a partial isomorphism: for all $n, n', m, m' \in \bN$, we have
\[
(n, m) \in I ~\text{and}~ (n', m') \in I \qquad \text{if and only if} \qquad n = n' \Longleftrightarrow m = m'\]
\item $I \subseteq \bigcup\limits_{m \in \bZ} f \circ (g \circ f)^{m}$
\item $\infty$ belongs to both the domain and codomain of $I$
\item $\LPO$ holds
\end{itemize}
We say $I$ has rank (at least) $n > 0$ if 
\begin{itemize}
\item for every $k < n$, $k$ belongs to both the domain and codomain of $I$
\item $\infty$ belongs to both the domain and codomain of $I$.
\end{itemize}
\end{definition}

We say that a partial solution $I$ extends a partial solution $J$ if we have
either $J \subseteq I$ or that $J$ is continuous, $I$ discontinuous and the
image of $J$ by $(n,m) \mapsto (\underline{n}, \underline{m})$ is included in
$I$. Now the first step towards proving~\Cref{thm:ninftymyhill} is to
establish the following.

\begin{lemma}
  \label{lem:ninftymyhillapprox}
Assuming Markov's principle, there exists a sequences of partial solutions
\[(I_n)_{n \in \bN} \in \left(\powerset(\bN \times \bN) + \powerset(\Ninfty \times \Ninfty)\right)^\bN\]
such that $I_n$ has rank at least $n$ and $I_n$ extends $I_m$ whenever $n \ge m$.
\end{lemma}

To prove this, it suffices to show that any partial solution of rank $n$
can be extended to a solution of rank $n+1$. For discontinuous partial solutions,
this is easy.

\begin{lemma}
  \label{lem:discontinuouspartialsolutionext}
There is a function that turns partial discontinuous solution of rank $n$ into
partial discontinuous solution of rank $n + 1$.
\end{lemma}
\begin{proof}
Since we are given a partial discontinuous solution, we know that $\LPO$ holds.
Thus we can simply use the isomorphism $\Ninfty \cong \bN$ to extend the solution
as in the proof of~\Cref{thm:myhilliso55}.
\end{proof}

The more difficult part is thus to extend partial continuous solutions. In the
presence of $\LPO$, we can straightforwardly use~\Cref{lem:discontinuouspartialsolutionext}
since we can then turn a partial continuous solution into a discontinuous one.

\begin{lemma}
There is a function that turns partial continuous solutions $I$ of rank $n$ into
a compatible partial discontinuous solutions $I'$ of rank $n$ if $\LPO$ holds.
\end{lemma}
\begin{proof}
First take the image of $I$ under $(n,m) \mapsto (\underline{n}, \underline{m})$;
that is almost a partial discontinuous solution, except for the fact that $\infty$
is not in the domain or codomain. Since we have $\LPO$, we can again use
the isomorphism $\Ninfty \cong \bN$ to make equality on $\Ninfty$ decidable and
add $\infty$ to the domain and codomain as in the proof of~\Cref{thm:myhilliso55}.
\end{proof}

With that in hand, it thus suffices to show the existence of a procedure that
takes a partial continuous solution $I_n$ of rank $n$ and returns either
\begin{itemize}
  \item a partial continuous solution of rank $n+1$
  \item or a distinct dummy value with the guarantee that $\LPO$ holds
\end{itemize}
This is done in two steps.
First, we check whether
$\inf(f(\infty),g(\infty)) \ge \underline{n + 1}$, a precondition to an extension
existing in the first place; if it's not, we return the dummy value.
This can be done because, by~\Cref{lem:MPmin} we can decide whether $f(\infty) \le \underline{n+1}$
or $\underline{n+1} \ge f(\infty)$, and similarly for $g$. If we are forced
to return the dummy value, we know that $f(\infty) \in \underline{\bN}$ or
$g(\infty) \in \underline{\bN}$, and we can deduce $\LPO$ from~\Cref{lem:inftyToIsolated}.
We can then proceed with the second step, which corresponds to a back-and-forth
similar to what is going on in the proof of~\Cref{thm:myhilliso55}: first we attempt
to add $n$ to the domain of $I$ if necessary, and then the codomain in a similar
manner. Since both steps are symmetrical, we focus on proving only the following
statement.

\begin{lemma}
\label{lem:forthCont}
There is a function $\Phi$ taking as input a partial continuous
solution $I$ and $n \in \bN$ such that:
\begin{itemize}
\item either $\Phi(I)$ is defined and returns some $m \in \bN$ such that
$I \cup (n, m)$ is a partial continuous solution
\item or a dummy value with the guarantee that $\LPO$ holds.
\end{itemize}
\end{lemma}
\begin{proof}
To compute $\Phi(I, n)$, first we compute
$\inf(f(\underline{n}), f(\infty))$. By~\Cref{lem:MPmin} and the injectivity
of $f$, we know this value is in $\underline{\bN} \cong \bN$ and thus that there
is $m \in \bN$ such that
\[ \text{either } \quad f(\underline{n}) = \underline{m} \quad \text{ or } \quad f(\infty) = \underline{m}\]
In the latter case, we let $\Phi$ return the dummy value as we know $\LPO$ holds by~\Cref{lem:inftyToIsolated}.
Otherwise, we check if $m$ is in the codomain of $I$.
If it isn't, $\Phi(I, n) = m$. If it is, we then compute $\inf(g(\underline{m}), g(\infty))$
and similarly have some $n'$ such that
\[ \text{either } \quad g(\underline{m}) = \underline{n'} \quad \text{ or } \quad g(\infty) = \underline{n'}\]
Similarly as before, we can assume without loss of generality we are in the first case, as otherwise $\LPO$
holds. Then we recursively compute $\Phi(I \setminus \{(n',m)\},n')$. This process will always halt
as the size of $I$ decreases at each step. Since we follow $f$ and $g$, $I \cup (n, \Phi(I,n))$
is still a partial continuous solution.
\end{proof}

This statement, together with the previous remarks, thus concludes the proof
of~\Cref{lem:discontinuouspartialsolutionext}. All that is left is thus
to argue that this allows us to build a suitable bijection.

\begin{proof}[Proof of~\Cref{thm:ninftymyhill} from~\Cref{lem:discontinuouspartialsolutionext}]
Assume a suitable sequence of partial solutions $(I_n)_{n \in \mathbb{N}}$
and recall we defined $\Ninfty \subseteq \Cantor$ as the set of sequence with
a single $1$. For $x \in \Ninfty$ and $n \in \bN$, define $h(x)_n \in 2$ by cases:
\begin{itemize}
\item If $I_{n+1}$ is continuous and $x \le \underline{n}$, then $x = \underline{m}$ for some $m \le n$.
Since $I_{n+1}$ has rank $n+1$, there is some $k \in \bN$ such that $(m, k) \in I_{n+1}$; set $h(x)_n = \underline{k}_n$.
\item If $I_{n+1}$ is continuous and $\underline{n} < x$, then set $h(x)_n = 0$.
\item If $I_{n+1}$ is discontinuous, then $\LPO$ holds and we can check if $x$ is in the domain of $I_{n+1}$. If it
is and $(x, y) \in I_{n+1}$, we set $h(x)_n = y_n$, otherwise we set $h(x)_n = 0$.
\end{itemize}
It is relatively straightforward to check that this definition of $h$ is total and
that its inverse can be defined in a similar way.
Now we need to check that we have, for every $x \in \Ninfty$ that 
\[\modal_{\LPO}\left(\exists m \in \bZ. \; h(x) = \left(f \circ (g \circ f)^{m}\right)(x)\right)\]
To this end, fix such an $x \in \Ninfty$ and recall that the proposition above
unfolds to
\[\exists w \in \Ninfty. \; \left(w \in \underline{\bN} \vee w = \infty\right) \Rightarrow 
\exists m \in \bZ. \; h(x) = \left(f \circ (g \circ f)^{m}\right)(x)\]
Note we can compute an element $s \in \Ninfty$
such that $s \ge \underline{n}$ if and only if $I_n$ is continuous.
To witness the existential statement, we take $w = \inf(x, s)$.

Intuitively, we
first start with the belief that $x = s = \infty$, which entails $f(\infty) = g(\infty) = \infty$.
In such a case ($w = \infty$), we can take $m = 0$ and we know we are in the right.
Otherwise, we may possibly notice that there is $n \in \bN$ such that $w = \underline{n}$.
By~\Cref{lem:minwoMP}, this means that either $s = \underline{n}$ or $x = \underline{n}$,
two cases we may treat separately:
\begin{itemize}
  \item if $s = \underline{n}$, it means $\LPO$ holds. In such a case, we may
    decide whether $x \in \underline{\bN}$ or not.
    \begin{itemize}
      \item if $x = \infty$, then we may examine $I_n$ and replay the
        construction of $I_n$ to compute $m$.
      \item if $x = \underline{k}$ for some $k \in \bN$, then one may similarly
        examine the construction of $I_{k + 1}$ to compute $m$.
    \end{itemize}
  \item if $x = \underline{n}$, then it suffices to replay the construction of
    $I_{n+1}$ to compute $m$.
\end{itemize}
\end{proof}



\section{Negative results for the $\neg\neg$ Myhill property}
\label{sec:negnegative}


\subsection{Concrete examples for which the $\neg\neg$ Myhill property is $\LPO$-hard}

We now turn to arguing that the classes of sets with the Myhill property cannot
be closed under products, coproducts or exponentiations. We first give some
concrete sets for which having the $\dneg$ strong Myhill property implies $\LPO$. This
implies that it cannot be the case that sets with the Myhill property can be
closed under (co)products or exponentiation in constructive logic.

When using the assumption that some set has the $\dneg$ Myhill property, we will 
need to exhibit particular $\dneg$-stable subsets. To establish that the
subsets we want to use are $\dneg$-stable, we will always be able to check
that they are effectively closed, by which we mean they are inverse images of $\infty$
by some map\footnote{This matches the definition of synthetic topology provided we take Sierpi{\'n}ski space to be the coequalizer of the 
maps $\id, \Succinfty : \Ninfty \to \Ninfty$, as is typically done in computable analysis.}.

\begin{lemma}
For any set $X$ and $\chi : X \to \Ninfty$,
for any $x \in X$, $\chi^{-1}(\infty)$ is $\dneg$-stable.
\end{lemma}
\begin{proof}
Abstracting away, this follows from $\neg x \neq \infty \Rightarrow x = \infty$; from the
premise one can prove $x \ge \underline{n}$ by induction over $n$ and thus
conclude.
\end{proof}

We will not explicitly appeal to this lemma and will leave to the reader
checking that the sets we are using do fit in this pattern. Let us give
a few examples of such constructions that cover the main ideas behind our
use-cases.

\begin{example}
For any $s \in \Baire$, $\{s\} = \chi_s^{-1}(\infty)$ for some $\chi_s$
defined by corecursion in the obvious way:
\[ \chi_{ns}(mp) = \left\{ \begin{array}{ll}
  \underline{0} & \text{if $n \neq m$} \\
  \Succinfty(\chi_s(p)) & \text{otherwise}
\\ \end{array} \right. \]
\end{example}

\begin{example}
For the set $2\Ninfty = \{ 2x \mid x \in \Ninfty\} \subseteq \Baire$,
we may define $\chi_{2\Ninfty} : \Baire \to \Ninfty$ such that $\chi_{2\Ninfty}^{-1}(2\Ninfty) = 2\Ninfty$
by corecursion as follows:
\[
\chi_{2\Ninfty}(1p) = \chi_\infty(p) \qquad
\chi_{2\Ninfty}(0(k+1)p) = \underline{0} \quad \text{and} \quad
\chi_2(00p) = \Succinfty(\Succinfty(\chi_2(p)))
\]
\end{example}

\begin{example}
If we are given $\chi_1, \chi_2 : X \to \Ninfty$, then the preimage of
$\infty$ by the pointwise sum $\chi_1 + \chi_2$ is the union
$\chi_1^{-1}(\infty) \cup \chi_2^{-1}(\infty)$.
\end{example}


\begin{theorem}
  \label{thm:notCoproddneg}
Assuming Markov's principle, the following are equivalent:
\begin{itemize}
\item the limited principle of omniscience
\item $\bN + \Ninfty$ has the $\neg\neg$ strong Myhill property
\end{itemize}
\end{theorem}
\begin{proof}
We focus proving that $\bN + \Ninfty$ having the $\dneg$ Myhill property implies
$\LPO$; that $\LPO$ implies the other direction is straightforward.

Recall the functions $f, g : \bN \to \bN$ and their lifts
$\underline{f}, \underline{g} : \Ninfty \to \Ninfty$ defined in the proof
of~\Cref{thm:oscNinftyNotMP}. This allows us to argue that
the following functions $f', g' : 2 \times \Ninfty \to 2 \times \Ninfty$ are
well-defined
\[
  \begin{array}{llcl !\qquad llcl}
f' : & \bN + \Ninfty &\longto& \bN + \Ninfty
    &
g' : & \bN + \Ninfty &\longto& \bN + \Ninfty
\\
    & \inr(x) &\longmapsto& \inr(f_0(x))
    &
    & \inr(x) &\longmapsto& \inr(g_0(x))
\\
    & \inl(n) &\longmapsto& \inr(\underline{\tuple{2n,0}})
    &
    & \inl(n) &\longmapsto& \inr(\underline{\tuple{2n+1,0}})
\end{array}
\]
The corresponding graph is pictured in~\Cref{fig:notCoproddneg}; those
functions are easily checked to be injective.
Now,
assume we have a bijection $h : \bN + \Ninfty \to \bN + \Ninfty$
such that for every $x \in \bN + \Ninfty$,
$\dneg \exists m \in \bZ. \; h(x) = \left(f' \circ (g' \circ f')^m\right)(x)$.
Write $\alpha : \Ninfty \to 2$ the map defined by $\alpha(x) = 1 \Leftrightarrow
\exists y \in \Ninfty. \; h(x) = \inl(y)$.

