\begin{lemma}
  \label{lem:continjNNinfty}
Assuming classical logic, an injection
$f : 2 \times \Ninfty \to 2 \times \Ninfty$ is continuous if and only if
there is some $(j, n) \in 2 \times \bN$ and continuous injection
$f' : 2 \times \Ninfty \to \Ninfty$ such that $f(i, \underline{n} + x) = (i + j \mod 2 ,f'(i,x))$.
\end{lemma}
\begin{proof}
The right-to-left direction is immediate.
For the left-to-right direction, first note that $(0, \infty)$
and $(1, \infty)$ are the only non-isolated points.
For $f$ to be injective, it needs to preserve non-isolated points, so
we necessarily have $f(0, \infty) = (j, \infty)$ and $f(1, \infty) = (1 - j, \infty)$
for some $j \in 2$.

By compactness of $\Ninfty$, there is some $n$ large enough such that
the image of $\{ x \in \Ninfty \mid x \ge \underline{n}\}$ by the map
\[
  \begin{array}{lcl}
    \Ninfty &\longto& 2 \times 2\\
    x &\longmapsto& (\pi_1(f(0,x)), \pi_2(f(1,x)))
  \end{array}
\]
is constantly $(j, 1 - j)$; we can then simply set $f'(i,x) = \pi_2(f(i,x)) - n$.
\end{proof}

\begin{lemma}
  \label{lem:NinftyNinftC0classical}
Assuming classical logic, an injection $f : \Ninfty \to \Ninfty$ is continuous
if and only if $f(\infty) = \infty$.
\end{lemma}
\begin{proof}
The topology on $\Ninfty$ is generated by sets $\{\underline{n}\}$
and $U_n = \{ x \in \Ninfty \mid x > \underline{n}\}$ when $n \in \bN$. It is obvious
that $f^{-1}(\{\underline{n}\})$ is open since $f$ is assumed to be injective,
so it simply remains to show that $f^{-1}(U_n)$ is open. Since $f$ is injective,
there can only be finitely values mapped outside of $U_n$, say all strictly inferior to
$\underline{k}$. So $f^{-1}(U_n)$ is $U_k$ joined with the finitely many values
strictly below $\underline{k}$, hence it is open.
\end{proof}


\begin{theorem}
  \label{thm:contbij2Ninfty}
Assuming classical logic, for any two continuous functions
injections $f, g : \bN + \Ninfty \to \bN + \Ninfty$,
there exists a continuous bijection $h : \bN + \Ninfty \to \bN + \Ninfty$
such that $h \subseteq \bigcup_{m \in \bZ} f \circ (g \circ f)^m$.
\end{theorem}
\begin{proof}
First let us treat the case where $f(0,\infty) = g(0, \infty) = (j, \infty)$
for some $j \in 2$.
Using a suitable variant of the Cantor-Bernstein theorem~\cite{Banaschewski-1986},
there exists a bijection $h \subseteq f \cup g^{-1}$.
By~\Cref{lem:continjNNinfty}, we also have $n \in \bN$ large enough so that there exists
$j_f, j_g \in 2$ and $f', g' : 2 \times \Ninfty \to \Ninfty$ such that
$f(i, \underline{n} + x) = (i + j \mod 2, f'(i, x))$ and
$g(i, \underline{n} + x) = (i + j \mod 2, g'(i,x))$ for every $x \in \Ninfty$.
Since $g$ is injective, there exists some $m \in \bN$ such that,
for any $i \in 2$, if $g(i, x) = (i', y)$ with $y \ge \underline{n + m}$,
then $x \ge \underline{n}$ (and therefore, $i = i'$).
Now we define $h' : 2 \times \Ninfty \to \Ninfty$ by
\[h'(i, x) = \left\{ \begin{array}{lc}
f'(i,x) & \text{if $h(i, \underline{n + m} + x) = f(i, \underline{n + m} + x) = (i + j \mod 2, f'(\underline{m} + i, x))$} \\
y - n& \text{if otherwise $h(i, \underline{n + m} + x)) = g^{-1}(i, \underline{n + m} + x) = (i, y)$}
\end{array} \right.
\]
Due to the way we picked $n, m \in \bN$, we can check that we do have that
$h(i, \underline{n + m} + x) = (i + j \mod 2, h'(i, x))$.
We also have that $h'(i,x) = \infty \Leftrightarrow x = \infty$, so $h'$ is
continuous by~\Cref{lem:NinftyNinftC0classical}, and by~\Cref{lem:continjNNinfty}
$h$ is continuous.

Now if $f(0, \infty) = (j, \infty)$ and $g(0, \infty) = (1 - j, \infty)$,
we have that $(g \circ f \circ g)(j, \infty) = (j, \infty)$ and $g \circ f \circ g$
remains injective. So if we use $g \circ f \circ g$ instead of $g$ in our
previous argument, we obtain a continuous
$h \subseteq \bigcup_{m \in \bZ} f \circ (g \circ f \circ g \circ f)^m$, which
is enough as $f \circ (g \circ f \circ g \circ f)^m = f \circ (g \circ f)^{2m}$.
\end{proof}

This has for direct consequence that a doubly-negated version of the strong Myhill
property holds in Kleene-Vesley realizability.

\begin{corollary}
\label{cor:dneg2NinftyMP}
The following is valid in Kleene-Vesley realizability:
given two injections $f, g : 2 \times \Ninfty \to 2 \times \Ninfty$, there $\dneg$-exists
a bijection $h : 2 \times \Ninfty \cong 2 \times \Ninfty$ such that
\[\forall x \in 2 \times \Ninfty. \;
  \neg\neg \left(h(x) \in \bigcup_{m \in \bZ} \left(f \circ (g \circ f)^m\right)(x)\right)\]
\end{corollary}

We now turn to showing that $2 \times \Ninfty$ does \emph{not} have the $\dneg$
Myhill property in Kleene-Vesley realizability. The key idea is that, while any continuous
$f$ and $g$ admit a continuous solution, that solution cannot be computed
continuously from codes for $f$ and $g$ in the setting of type 2
computability\footnote{Specifically, a code for a partial function
$f : \Baire \to \bN$ is given by a tree whose leaves are labeled by outputs
in $\bN$. $f(p)$ is then defined if $p$ is a path leading to a leaf labeled
by $n$, see~\cite[\S 1.4.2]{VanOosten}.}.

\begin{theorem}
  \label{thm:noNNinftyMP}
Assuming classical logic, there is no continuous functional that takes codes for two continuous injections $f, g : 2 \times \Ninfty \to 2 \times \Ninfty$
to a code for a bijection $h : 2 \times \Ninfty \to 2 \times \Ninfty$ and its inverse so that $h \subseteq \bigcup_{m \in \bZ} f \circ (g \circ f)^m$.
\end{theorem}

