\begin{remark}
Let $F_1,\ldots,F_r$ be DG $\Gamma$-algebras. Then $F_1\otimes_R\cdots\otimes_R F_r$ is a DG $\Gamma$-algebra, where the divided power structure is given by
\[
(f_1\otimes\cdots\otimes f_r)^{(i)}=\begin{cases}
0,\quad\text{if there is an $k$ such that $|f_k|$ is odd}\\
f_1^i\otimes\cdots f_{j-1}^i\otimes f_j^{(i)}\otimes f_{j+1}^i\otimes\cdots\otimes f_r^i,\quad\text{$|f_k|$ even $\forall k$ and $j$ smallest such that $|f_j|>0$.}
\end{cases}
\]
This is the unique DG $\Gamma$-algebra structure for which the canonical maps $F_i\rightarrow F_1\otimes_R\cdots\otimes_R F_r$ are DG $\Gamma$-algebra maps for all $i$'s. See \cite[Proposition 1.7.10]{GulliksenLevin}
\end{remark}

\begin{remark}
We point out that it follows from the DG $\Gamma$-algebra axioms that if $f_1,\ldots,f_r$ are even and $f_l,f_j$ have positive degree, then
\[
f_1^i\otimes\cdots f_{j-1}^i\otimes f_j^{(i)}\otimes f_{j+1}^i\otimes\cdots\otimes f_r^i=(f_1\otimes\cdots\otimes f_r)^{(i)}=f_1^i\otimes\cdots f_{l-1}^i\otimes f_l^{(i)}\otimes f_{l+1}^i\otimes\cdots\otimes f_r^i.
\]
The same will be true for the DG $\Gamma$-algebra structure on the generalized Taylor resolution given below. Defining it first by taking the smallest $j$ such $|f_j|>0$ allows us to have a well-posed definition, but it will follow from the DG $\Gamma$-algebra axioms that taking $j$ to be the smallest is not needed.
\end{remark}

\begin{theorem}
Let $I_1,\ldots, I_r$ be monomial ideals. Let $F_i$ be a free DG $\Gamma$-algebra resolution of $R/I_i$ for all $i=1,\ldots,r$. Then, the resolution $F_1*\cdots *F_r$ is a DG $\Gamma$-algebra where the divided power structure is given, on elements of positive and even homological degree, by
\[
(f_1*\cdots*f_r)^{(i)}=\begin{cases}
0\quad\text{if there is an $k$ such that $|f_k|$ is odd}\\
f_1^i*\cdots f_{j-1}^i*f_j^{(i)}*f_{j+1}^i*\cdots*f_r^i\quad\text{$|f_k|$ even $\forall k$ and $j$ smallest such that $|f_j|>0$.}
\end{cases}
\]
For the divided power of a linear combination of the elements above one uses the axioms defining divided power algebras.

Moreover this is the unique DG $\Gamma$-structure for which the inclusion maps $F_i\rightarrow F_1*\cdots*F_r$ are maps of DG $\Gamma$-algebras for all $i=1,\ldots,r$.
\end{theorem}

\begin{proof}
The map
\begin{align*}
\varphi:&F_1\otimes_R\cdots\otimes_R F_r\rightarrow F_1*\cdots*F_r\\
&f_1\otimes\cdots\otimes f_r\longmapsto(m_{f_1},\ldots,m_{f_r})f_1*\cdots*f_r
\end{align*}
is a map of DG algebras by \cite[Theorem 4.5]{Keller}.
It is clearly invertible when localized at the multiplicative subset consisting of all monomials, therefore by \Cref{lem:transfer} it suffices to prove
\[
\varphi((f_1\otimes\cdots\otimes f_r)^{(i)})=\varphi(f_1\otimes\cdots\otimes f_r)^{(i)}.
\]


Assuming that $j$ is the smallest index such that $|f_j|>0$, the following chain of equalities gives the desired result
\begin{align*}
\varphi((f_1\otimes\cdots\otimes f_r)^{(i)})&=\varphi(f_1^i\otimes\cdots\otimes f_j^{(i)}\otimes\cdots\otimes f_r^i)\\
&=(m_{f_1^i},\ldots,m_{f_j^{(i)}},\ldots,m_{f_r^i})f_1^i*\cdots*f_j^{(i)}*\cdots*f_r^i\\
&=(m_{f_1}^i,\ldots,m_{f_j}^i,\ldots,m_{f_r}^i)f_1^i*\cdots*f_j^{(i)}*\cdots*f_r^i\\
&=(m_{f_1},\ldots,m_{f_j},\ldots,m_{f_r})^if_1^i*\cdots*f_j^{(i)}*\cdots*f_r^i\\
&=((m_{f_1},\ldots,m_{f_r})f_1*\cdots*f_r)^{(i)}\\
&=\varphi(f_1\otimes\cdots\otimes f_r)^{(i)}.
\end{align*}

We show that the DG $\Gamma$-algebra structure is unique. Assume that the generalize Taylor resolution admits a DG $\Gamma$-structure and assume that the canonical maps
\begin{align*}
\iota_i:&F_i\rightarrow F_1*\cdots*F_r\\
&f_i\mapsto1*\cdots1*f_i*1\cdots1
\end{align*}
are DG $\Gamma$-algebra maps for all $i$. Let $f_1*\cdots*f_r\in F_1*\cdots*F_r$ of even and positive homological degree and assume that $j$ is the smallest index such that $|f_j|>0$. Then
\begin{align*}
(f_1*\cdots *f_r)^{(i)}&=\left(\frac{[m_{f_1},\ldots, m_{f_r}]}{m_{f_1}\cdots m_{f_r}}\iota_1(f_1)\cdots\iota_r(f_r)\right)^{(i)}\\
&=\left(\frac{1}{(m_{f_1},\ldots,m_{f_r})}\iota_1(f_1)\cdots\iota_r(f_r)\right)^{(i)}\\
&=\frac{1}{(m_{f_1},\ldots,m_{f_r})^i}(\iota_1(f_1)\cdots\iota_r(f_r))^{(i)}\\
&=\frac{1}{(m_{f_1},\ldots,m_{f_r})^i}\iota_1(f_1)^i\cdots\iota_j(f_j)^{(i)}\cdots\iota_r(f_r)^i\\
&=\frac{1}{(m_{f_1},\ldots,m_{f_r})^i}\iota_1(f_1^i)\cdots\iota_j(f_j^{(i)})\cdots\iota_r(f_r^i)\\
&=\frac{1}{(m_{f_1},\ldots,m_{f_r})^i}\frac{m_{f_1^i}\cdots m_{f_j^{(i)}}\cdots m_{f_r^i}}{[m_{f_1^i},\ldots,m_{f_j^{(i)}},\ldots,m_{f_r^i}]}f_1^i*\cdots*f_j^{(i)}*\cdots*f_r^i\\
&=\frac{1}{(m_{f_1},\ldots,m_{f_r})^i}\frac{m_{f_1}^i\cdots m_{f_j}^i\cdots m_{f_r}^i}{[m_{f_1}^i,\ldots,m_{f_j}^i,\ldots,m_{f_r}^i]}f_1^i*\cdots*f_j^{(i)}*\cdots*f_r^i\\
&=\frac{1}{(m_{f_1},\ldots,m_{f_r})^i}(m_{f_1}^i,\ldots,m_{f_r}^i)f_1^i*\cdots*f_j^{(i)}*\cdots*f_r^i\\
&=f_1^i*\cdots*f_j^{(i)}*\cdots*f_r^i,
\end{align*}
where the first equality follows from \Cref{thm:DGA}.
\end{proof}

\section{Comparison to the Taylor Resolution}

In this section we show that if $I_1,\ldots,I_r$ are principal monomial ideals and $F_i$ is the Koszul resolution of $R/I_i$, then the Taylor resolution of $I_1+\cdots+I_r$ and the generalized Taylor resolution $F_1*\cdots*F_r$ are isomorphic as DG $\Gamma$-algebras. We point out that it was already observed by Herzog in \cite{herzog2007} that these complexes were isomorphic, even though he did not include a proof. VandeBogert also observed in \cite{Keller} that these complexes were isomorphic as DG algebras, but he also did not include a proof. Since VandeBogert's product formula was missing a sign, we have decided to show the proof of this claim in full detail. 


\begin{theorem}
Let \( I = (u_1, \dots, u_r) \) be a monomial ideal in \( R = \kk[x_1, \dots, x_n] \). Let $I_i=(u_i)$ and $F_i$ be the Koszul resolution of $R/I_i$. Then, the Taylor resolution \( T_{\bullet} \) of $I$ and the generalized Taylor resolution 
\[
F_\bullet= F_1 * \cdots * F_r
\]
are isomorphic as DG \(\Gamma\)-algebras.
\end{theorem}

\begin{proof}
Let $F_i=(0\rightarrow Rf_i\rightarrow R\rightarrow0)$ be the Koszul resolution of $R/(u_i)$.
We construct a homomorphism
\[
\Phi: T_{\bullet} \to F_1 * \cdots * F_r
\]
and prove that it is an isomorphism of DG \( \Gamma \)-algebras. For a subset $\sigma \subseteq \{1, \dots, r\}$, we introduce the notation:
\[
f^*_{\sigma} := g_1*\cdots *g_r,
\]
where 
\[
g_i:=\begin{cases}f_i,\quad\mathrm{if\;}i\in\sigma\\
1,\quad\mathrm{if\;}i\not\in\sigma.
\end{cases}
\]
We define \( \Phi \) on basis elements of \( T_{\bullet} \) by $\Phi(e_\sigma) = f^*_{\sigma}$.
To verify that \( \Phi \) commutes with differentials, we need to show 
\begin{equation}\label{eq:cxMap}
\Phi(\partial^{T_{\bullet}}(e_\sigma)) = \partial^{F_\bullet}(\Phi(e_\sigma)).
\end{equation}
Computing the left side of \Cref{eq:cxMap} yields
\begin{align*}
\Phi(\partial^{T_{\bullet}}(e_\sigma)) &= \sum_{i \in \sigma} (-1)^{\alpha(i,\sigma)} \frac{m_\sigma}{m_{\sigma\setminus\{i\}}} \Phi(e_{\sigma \setminus \{i\}})\\
&=\sum_{i \in \sigma} (-1)^{\alpha(i,\sigma)} \frac{m_\sigma}{m_{\sigma\setminus\{i\}}} f^*_{\sigma\setminus\{i\}}.
\end{align*}
Next we compute the right side of \Cref{eq:cxMap}. First we notice the following
\[
\partial^{F_i}(g_i)=\begin{cases}
u_i,\quad i\in\sigma\\
0,\quad i\not\in\sigma.
\end{cases}
\]
Since $\partial^{F_\bullet}(\Phi(e_\sigma))=\partial^{F_\bullet}(f_\sigma^*)$, using the formula for the differential of the generalized Taylor resolution and the observation above one gets
\[
\partial^{F_\b}(f_\sigma^*)=\sum_{i\in\sigma}(-1)^{|g_1|+\cdots+|g_{i-1}|}\frac{[m_{g_1},\ldots,m_{g_r}]}{[m_{g_1},\ldots,m_{g_{i-1}},m_{g_{i+1}},\ldots,m_{g_r}]}g_1*\cdots g_{i-1}*1*g_{i+1}*\cdots g_r.
\]
Now we make the following elementary observations:
\[
g_1*\cdots g_{i-1}*1*g_{i+1}*\cdots g_r=f_{\sigma\setminus\{i\}}^*,
\]
and
\[
[m_{g_1},\ldots,m_{g_r}]=m_{\sigma},\quad [m_{g_1},\ldots,m_{g_{i-1}},m_{g_{i+1}},\ldots,m_{g_r}]=m_{\sigma\setminus\{i\}}.
\]
To conclude the proof of \Cref{eq:cxMap} it just remains to check the signs
\begin{align*}
|g_1|+\cdots+|g_{i-1}|&=\sum_{\substack{j\in\sigma\\j\leq i-1}}|f_j|\\
&=|\{j\in\sigma\mid j\leq i-1\}|\\
&=\alpha(i,\sigma),
\end{align*}
where the second equality follows since $|f_j|=1$ for all $j$'s. This concludes the proof that $\Phi$ commutes with the differential.

Now we check that $\Phi$ is a DG algebra map, i.e. we need to check that $\Phi(e_Pe_Q)=\Phi(e_P)\Phi(e_Q)$, that is we need to check that $\Phi(e_Pe_Q)=f_P^*f_Q^*$. We divide the proof into two cases.

\textbf{Case 1: $P\cap Q=\emptyset$}. In this case
\[
\Phi(e_Pe_Q)=(-1)^{\alpha(P,Q)}(m_P,m_Q)\Phi(e_{P\cup Q})=(-1)^{\alpha(P,Q)}(m_P,m_Q) f_{P\cup Q}^*.
\]
Next we compute the product $f_P^*f_Q^*$. We introduce the notation $(f_P^*)_i$ for the $i$th component of $f_P^*$, which is 1 if $i\not\in P$ and $f_i$ otherwise. Similarly for $Q$. We begin by noticing that
\[
(f_P^*)_i(f_Q^*)_i=\begin{cases}
1\quad i\not\in P\cap Q\\
(f_P^*)_i\quad i\in P\\
(f_Q^*)_i\quad i\in Q.
\end{cases}
\]
Therefore, using the formula for the product of the generalized Taylor resolution one gets
\[
f_P^*f_Q^*=(-1)^{\displaystyle\sum_{i=1}^r|(f_Q^*)_i|\sum_{j=i+1}^r|(f_P^*)_j|}\frac{m_{f_P^*}m_{f_Q^*}}{m_{f_{P\cup Q}^*}}f_{P\cup Q}^*.
\]
We first observe that $m_{f_P^*}=m_P$, and therefore
\[
\frac{m_{f_P^*}m_{f_Q^*}}{m_{f_{P\cup Q}^*}}=\frac{m_{P}m_{Q}}{m_{P\cup Q}}=\frac{m_{P}m_{Q}}{[m_P,m_Q]}=(m_P,m_Q).
\]
Next we check the the signs coincide
\begin{align*}
\sum_{i=1}^r|(f_Q^*)_i|\sum_{j=i+1}^r|(f_P^*)_j|&=\sum_{i=1}^r|(f_Q^*)_i|\cdot|\{j\in P\mid i+1\leq j\leq r\}|\\
&=\sum_{i\in Q}|\{j\in P\mid i+1\leq j\leq r\}|\\
&=|\{(j,i)\in  P\times Q\mid i<j\}|\\
&=\alpha(P,Q).
\end{align*}

\textbf{Case 2: $P\cap Q\neq\emptyset$.} In this case $\Phi(e_Pe_Q)=\Phi(0)=0$. Moreover, if $i\in P\cap Q$, then $(f_P^*)_i(f_Q^*)_i=0$, and therefore $f_P^*f_Q^*=0$ as well. This concludes the proof that $\Phi$ is a map of DG algebras.

Now, to show that \( \Phi \) is a map of DG \(\Gamma\)-algebras, it suffices to show that $\Phi(e_\sigma^{(i)})=\Phi(e_\sigma)^{(i)}$ for all $i$'s.  If \( i = 0,1 \), then the desired equality follows immediately from the first axiom defining $\Gamma$-algebras.
So we will assume that \( i \geq 2 \). Avramov’s proof of \cite[Lemma 6]{Avramov} shows that divided powers vanish
\[
e_\sigma^{(i)} = 0\quad\text{for all }i\geq2.
\]
Therefore $\Phi(e_\sigma^{(i)}) = \Phi(0) = 0$. Thus, it remains to show
\[
\Phi(e_\sigma)^{(i)}=(f_\sigma^*)^{(i)}=0
\]
Recall that $f_\sigma^*=g_1*\cdots*g_r$, and assume that $j$ is the smallest index such that $|g_j|>0$. Then
\[
(f_\sigma^*)^{(i)}=(g_1*\cdots*g_r)^{(i)}=g_1^i*\cdots* g_j^{(i)}*\cdots g_r^i.
\]
Since $|g_j|>0$ it follows that $g_j=f_j$. Since the resolution $F_j$ is zero in degree $\geq2$, it follows that $g_j^{(i)}=0$, and therefore $(f_\sigma^*)^{(i)}=0$. This concludes the proof that $\Phi$ respects divided powers.
\end{proof}

\section{Some Applications}
In this section we include some applications of our main result. 
\subsection{Homotopy Lie Algebras} The first application concerns homotopy Lie algebras, see \cite[Chapter 10]{IFR} for the definition and basic properties. If $I$ is a monomial ideal of $R$, we denote the homotopy Lie algebra of $R/I$ by $\pi(R/I)$. If $D$ is a DG $\Gamma$-algebra such that $D_0$ is noetherian and the $D_0$-module $\mathrm{H}_n(D)$ is finite for every $n\in\mathbb{Z}$, we denote the homotopy Lie algebra of $D$ by $\pi(D)$, see \cite[Remark 7]{Avramov} for more details. In the proof of \cite[Theorem 1]{Avramov}, Avramov proves that if $I$ is a monomial ideal of $R$ minimally generated by monomials of degree at least 2, then $\pi^{\geq2}(R/I)\cong\pi(T_\bullet\otimes_R\kk)$, where $T_\bullet$ is the Taylor resolution of $I$. The next proposition generalizes Avramov's result.

\begin{proposition}
Let $I_1,\ldots,I_r$ be monomial ideals of $R$ minimally generated by monomials of degree at least 2. Let $F_i$ be a DG $\Gamma$-algebra resolution of $R/I_i$ for all $i$'s. Then, there is an isomorphism of graded Lie algebras
\[
\pi^{\geq2}(R/I)\cong\pi((F_1*\cdots*F_r)\otimes_R\kk).
\]
\end{proposition}
\begin{proof}
Let $K^R$ be the Koszul complex over the variables of $R$. Let $\varepsilon:K^R\rightarrow\kk$ and $\tau:F_1*\cdots*F_r\rightarrow R/I$ be the augmentation maps of $K^R$ and $F_1*\cdots*F_r$. These maps induce the quasi-isomorphisms below
\[
K^{R/I}= R/I\otimes_RK^R\xleftarrow{\;\;\tau\otimes K^R\;\;} (F_1*\cdots*F_r)\otimes_R K^R\xrightarrow{\;\; (F_1*\cdots*F_r)\otimes\varepsilon\;\;}(F_1*\cdots*F_r)\otimes_R\kk,
\]
where $K^{R/I}$ is the Koszul complex over the images of the variables of $R$ in $R/I$ and the equality follows since $I$ is generated by monomials of degree at least 2. The Koszul complex $K^{R/I}$ is a DG $\Gamma$-algebra and it was proved in \cite[Lemma 8]{Avramov} that $\pi^{\geq2}(R/I)\cong\pi(K^{R/I})$. Since quasi-isomorphic DG $\Gamma$-algebras have isomorphic homotopy Lie algebras the desired result now follows.
\end{proof}


\subsection{Squarefree monomial ideals}
In this subsection we complement a result of VandeBogert \cite[Proposition 4.8]{Keller}, which was a generalization of a result of Katth\"{a}n \cite[Theorem 3.6]{katthan}.

\begin{remark}We start by recalling the definition of the algebraic Scarf complex. The algebraic Scarf complex is the subcomplex of the Taylor resolution generated by all the basis elements having unique multidegree. It is known that the Scarf complex is always a subcomplex of the minimal free resolution of a monomial ideal. For more details about the Scarf complex see \cite[Section 6.2]{combCommAlg}.
\end{remark}

\begin{remark}\label{rmk:sqf}
If $F$ is a multigraded free $R$-module whose generators have squarefree multidegree, then for every multihomogeneous $f\in F$ there exists a monomial $u_f\in R$ and a multihomogeneous element of $F$ denoted by $|f|_{\sqf}$ such that $f=u_f|f|_\sqf$ and the multidegree of $|f|_\sqf$ is $(m_f,x_1\cdots x_n)$. The monomial $u_f$ and the element $|f|_\sqf$ are unique. See \cite[Lemma 1.4]{katthan}.

If $I$ is a squarefree monomial ideal of $R$ and $F_\b$ is a minimal DG algebra resolution of $R/I$, then every multihomogeneous element $f\in F$ of positive homological degree and squarefree multidegree can be written as
\[
f=\sum_{j=1}^l|g_{1,j}\cdots g_{|f|,j}|_\sqf
\]
where $g_{1,j},\ldots,g_{|f|,j}$ have homological degree 1 for all $j=1,\ldots,l$. See \cite[Proposition 3.4]{katthan} for a proof. This shows that a minimal DG algebra resolution of a squarefree monomial ideal is essentially generated in homological degree 1.
\end{remark}

\begin{theorem}
Let $I_1,\ldots,I_r$ be squarefree monomial ideals. Let $F_i$ be a multigraded DG $\Gamma$-algebra minimal free resolution of $R/I_i$ for $i=1,\ldots,r$. If the minimal free resolution $G_\b$ of $R/(I_1+\cdots +I_r)$ is a multigraded DG $\Gamma$-algebra, then there exists a DG $\Gamma$-ideal $J$ of $F_1*\cdots*F_r$ such that $G_\b\cong (F_1*\cdots *F_r)/J$ as multigraded DG $\Gamma$-algebras.
\end{theorem}

\begin{proof}
Set $F_\b=F_1*\cdots*F_r$. We assume the resolutions $F_1,\ldots,F_r,G_\b$ have a fixed basis. In the proof of \cite[Proposition 4.8]{Keller}, VandeBogert constructs a surjective DG algebra map $\psi:F_\b\rightarrow G_\b$. We recall this construction and show that $\psi$ preserves divided powers.

If $f_i\in F_i$, we denote by $f_i^*$ the element of $F_\b$ with $f_i$ in position $i$ and 1 everywhere else. We first notice that if $f_i\in F_i$ is of squarefree multidegree for all $i$, it follows from \Cref{thm:DGA} that
\[
f_1*\cdots*f_r=\frac{f_1^*\cdots f_r^*}{(m_{f_1},\ldots,m_{f_r})}=|f_1^*\cdots f_r^*|_\sqf.
\]
We now define $\psi$ in homological degree 1. If $g_i\in F_i$ is a basis element of homological degree 1, then we set $\psi(g_i^*)=\tilde{g}_i$ where $\tilde{g}_i$ is the element of the algebraic Scarf complex (as a subcomplex of $G_\b$) corresponding to $g_i$. We then extend by $R$-linearity.

If $f_i\in F_i$ is a basis element (and therefore of squarefree multidegree) of positive homological degree, then by \Cref{rmk:sqf}
\[
f_i=\sum_{j=1}^l|g_{1,j}\cdots g_{|f_i|,j}|_\sqf,
\]
where $g_{1,j},\ldots,g_{|f_i|,j}$ are elements of $F_i$ of homological degree 1 for all $j=1,\ldots,l$. We define 
\[
\psi(f_i^*)=\sum_{j=1}^l|\psi(g_{1,j}^*)\cdots \psi(g_{|f_i|,j}^*)|_\sqf,
\]
and extend by $R$-linearity.

If $f_1\in F_1,\ldots, f_r\in F_r$ are basis elements, then we define
\[
\psi(f_1*\cdots*f_r)=\frac{\psi(f_1^*)\cdots\psi(f_r^*)}{(m_{f_1},\ldots,m_{f_r})}=|\psi(f_1^*)\cdots\psi(f_r^*)|_\sqf,
\]
and extend by $R$-linearity.

%We now show that $\psi$ preserves divided powers. We first note that if $g_i\in F_i$ is an element of homological degree 1, then $g_i^{(m)}=0$ for $m\geq2$ since $0=g_i^m=m!g_i^{(m)}$. Similarly for elements of homological degree 1 of $G_\b$. Therefore it is obvious that $\psi((g_i^*)^{(m)})=\tilde{g_i}^{(m)}$ for all $m$. 

Now we show that $\psi$ preserves divided powers. Let $f_i\in F_i$ be a basis element of even and positive homological degree. Then by \Cref{rmk:sqf}
\[
f_i=\sum_{j=1}^l|g_{i,1,j}\cdots g_{i,|f_i|,j}|_\sqf
\]
for some elements of homological degree 1 $g_{i,1,j},\ldots,g_{i,|f_i|,j}$ for $j=1,\ldots,l$. By the axioms of DG $\Gamma$-algebras one has the following equality
\begin{equation}\label{eq:gamma}
f_i^{(m)}=\sum_{j_1+\cdots+j_l=m}|g_{i,1,j_1}\cdots g_{i,|f_i|,j_1}|_\sqf^{(j_1)}\cdots|g_{i,1,j_l}\cdots g_{i,|f_i|,j_l}|_\sqf^{(j_l)}.
\end{equation}
If $h\in F_i$ is of even positive homological degree then, since $h=u_h|h|_\sqf$, it follows that $h^{(m)}=0$ if and only if $|h|_\sqf^{(m)}=0$. We now note that by the axioms of divided powers algebra
\begin{equation}\label{eq:zeroPw}
(g_{i,1,j_k}\cdots g_{i,|f_i|,j_k})^{(j_k)}=0\quad\mathrm{for\;}j_k\geq2,\quad\mathrm{and\;}k=1,\ldots,l.
\end{equation}
Therefore \Cref{eq:gamma} can be rewritten as
\[
f_i^{(m)}=\sum_{\substack{\sigma\subseteq[m]\\|\sigma|=l}}\prod_{j\in\sigma}|g_{i,1,j}\cdots g_{i,|f_i|,j}|_\sqf.
\]
Therefore
\begin{align*}
\psi((f_i^*)^{(m)})&=\sum_{\substack{\sigma\subseteq[m]\\|\sigma|=l}}\prod_{j\in\sigma}\psi(|g_{i,1,j}^*\cdots g_{i,|f_i|,j}^*|_\sqf)\\
&=\sum_{\substack{\sigma\subseteq[m]\\|\sigma|=l}}\prod_{j\in\sigma}|\psi(g_{i,1,j}^*)\cdots \psi(g_{i,|f_i|,j}^*)|_\sqf.
\end{align*}
While
\begin{align*}
\psi(f_i^*)^{(m)}&=\left(\sum_{j=1}^l\psi(|g_{i,1,j}^*\cdots g_{i,|f_i|,j}^*|_\sqf)\right)^{(m)}\\
&=\left(\sum_{j=1}^l|\psi(g_{i,1,j}^*)\cdots \psi(g_{i,|f_i|,j}^*)|_\sqf\right)^{(m)}\\
&=\sum_{j_1+\cdots+j_l=m}|\psi(g_{i,1,j_1}^*)\cdots \psi(g_{i,|f_i|,j_1}^*)|_\sqf^{(j_1)}\cdots|\psi(g_{i,1,j_l}^*)\cdots \psi(g_{i,|f_i|,j_l}^*)|_\sqf^{(j_l)}\\
&=\sum_{\substack{\sigma\subseteq[m]\\|\sigma|=l}}\prod_{j\in\sigma}|\psi(g_{i,1,j}^*)\cdots \psi(g_{i,|f_i|,j}^*)|_\sqf,
\end{align*}
where the last equality follows from \Cref{eq:zeroPw}. This shows $\psi((f_i^*)^{(m)})=\psi(f_i^*)^{(m)}$ for all $m$.

Finally if $f_1\in F_1,\ldots, f_r\in F_r$ are basis elements of even degree, and $j$ is the smallest index such that $|f_j|>0$ and $k$ any positive integer, then
\begin{align*}
\psi((f_1*\cdots*f_r)^{(k)})&=\psi(f_1^k*\cdots*f_j^{(k)}*\cdots*f_r^k)\\
&=\frac{\psi((f_1^*)^k)\cdots\psi((f_j^*)^{(k)})\cdots\psi((f_r^*)^k)}{(m_{f_1^k},\ldots,m_{f_j^{(k)}},\ldots,m_{f_r^k})}\\
&=\frac{\psi(f_1^*)^k\cdots\psi(f_j^*)^{(k)}\cdots\psi(f_r^*)^k}{(m_{f_1},\ldots,m_{f_r})^k}\\
&=\left(\frac{\psi(f_1^*)\cdots\psi(f_j^*)\cdots\psi(f_r^*)}{(m_{f_1},\ldots,m_{f_r})}\right)^{(k)}\\
&=\psi(f_1*\cdots*f_r)^{(k)}.\qedhere
\end{align*}
\end{proof}

\begin{remark}
We point out that if the minimal free resolution of $R/I$ with $I$ squarefree has a DG algebra structure, then it has a divided powers algebra structure. Indeed, if $f$ is a basis element of the resolution of even positive homological degree, then
\[
f=\sum_{j=1}^l|g_{1,j}\cdots g_{|f|,j}|_\sqf,
\]
with $g_{1,j},\ldots,g_{|f|,j}$ of homological degree 1 for all $j$. The divided power $(g_{1,j}\cdots g_{|f|,j})^{(m)}$ needs to be defined as 0 for $m\geq2$ to satisfy the axioms of divided powers algebra. It follows that $|g_{1,j}\cdots g_{|f|,j}|_\sqf^{(m)}=0$ for $m\geq2$, and following the axioms one needs to set
\[
f^{(m)}=\sum_{\substack{\sigma\subseteq[m]\\|\sigma|=l}}\prod_{j\in\sigma}|g_{1,j}\cdots g_{|f_i|,j}|_\sqf.
\]
Then one can extend these divided powers to linear combinations of basis elements by using the axioms of DG $\Gamma$-algebra.
\end{remark}

In \cite[Proposition 3.1]{katthan}, Katth\"{a}n proved that if the minimal free resolution of $R/I$, where $I$ is a squarefree ideal, is a DG algebra, then the product induced on the Scarf subcomplex is unique and it matches the product on the Taylor resolution. We complement this result by showing that if this resolution admits the structure of a DG $\Gamma$-algebra, then the divided powers structure on the Scarf subcomplex matches the DG $\Gamma$-structure of the Taylor resolution. If $I$ is a monomial ideal generated by $r$ elements, then we fix basis elements of the Scarf complex $e_\sigma$ with $\sigma\subseteq[r]$ corresponding to the standard basis elements of the Taylor resolution.

\begin{proposition}
Let $I$ be a squarefree monomial ideal of $R$. Let $F_\b$ be a minimal DG $\Gamma$-algebra free resolution of $R/I$. If $e_\sigma$ is a basis element of the Scarf complex (as a subcomplex of $F_\b$) corresponding to a standard basis element of the Taylor resolution, then $e_\sigma^{(m)}=0$ for all $m\geq2$.
\end{proposition}

\begin{proof}
We first notice that the claim is true when $|\sigma|=1$. It follows from \cite[Proposition 3.1]{katthan} that the basis elements of the Scarf complex multiply exactly as they would in the Taylor resolution. Therefore
\[
\prod_{i\in\sigma}e_i=\pm d_\sigma e_\sigma
\]
for some monomial $d_\sigma$. Therefore
\[
0=\left(\prod_{i\in\sigma}e_i\right)^{(m)}=\pm d_{\sigma}^me_{\sigma}^{(m)},
\]
yielding the desired result.
\end{proof}




