        &[(x_1^2x_2, x_2x_3), (x_1^2x_3, x_2^2)],
        [(x_1^2x_2, x_2x_4), (x_1^2x_4, x_2^2)],
        [(x_1^2x_2, x_3^2), (x_1^2x_3, x_2x_3)],\\
        & [(x_1^2x_2, x_3x_4), (x_1^2x_3, x_2x_4)]
        [(x_1^2x_2, x_3x_4), (x_1^2x_4, x_2x_3)],
        [(x_1^2x_2, x_4^2), (x_1^2x_4, x_2x_4)],\\
