    \end{bmatrix},\quad 
    \bb{{\mathbf{A}^1}'}_{Y_4}= \begin{bmatrix}
        -m_{x_1x_2}^{x_2^2} & m_{x_1x_3}^{x_2^2} & -m_{x_1x_4}^{x_2^2} \\
