        \[Y=\{x_1^5, x_1^4x_2\}\]
        and 
        \[E_1=\{(x_1^3, x_1x_2)\}, E_2=\{[(x_1^3, x_2^2), (x_1^2x_2, x_1x_2)]\}.\]
        Therefore,
        \[\mathbf{A}=\begin{bmatrix}
            -m_{x_1^2}^{x_1x_2} & m \\ 
            -m_{x_1^2}^{x_2^2} & m_{x_1^2}^{x_1x_2}
        \end{bmatrix}.\]
