\[
\left[
\begin{array}{cccccccccc}
 - m_{ x_1^2}^{ x_2^2} & m_{x_1 x_2}^{ x_2^2} &  - m_{x_1 x_3}^{ x_2^2} & m & 0 & 0 & 0 & 0 & 0 & 0 \\
 - m_{ x_1^2}^{ x_3^2} & m_{x_1 x_2}^{ x_3^2} &  - m_{x_1 x_3}^{ x_3^2} & 0 & 0 & m & 0 & 0 & 0 & 0 \\
0 &  - m_{ x_1^2}^{ x_2^2} & 0 & m_{x_1 x_2}^{ x_2^2} &  - m_{x_1 x_3}^{ x_2^2} & 0 & m & 0 & 0 & 0 \\
0 &  - m_{ x_1^2}^{ x_3^2} & 0 & m_{x_1 x_2}^{ x_3^2} &  - m_{x_1 x_3}^{ x_3^2} & 0 & 0 & 0 & m & 0 \\
0 & 0 &  - m_{ x_1^2}^{ x_2^2} & 0 & m_{x_1 x_2}^{ x_2^2} &  - m_{x_1 x_3}^{ x_2^2} & 0 & m & 0 & 0 \\
0 & 0 &  - m_{ x_1^2}^{ x_3^2}  & 0 & m_{x_1 x_2}^{ x_3^2} &  - m_{x_1 x_3}^{ x_3^2} & 0 & 0 & 0 & m \\
0 & 0 & 0 & 0 &  - m_{ x_1^2}^{x_2 x_3} & m_{ x_1^2}^{ x_2^2} & 0 & m_{x_1 x_2}^{x_2 x_3} &  - m_{x_1 x_2}^{ x_2^2} - m_{x_1 x_3}^{x_2 x_3} & m_{x_1 x_3}^{ x_2^2} \\
0 & 0 & 0 &  -m_{ x_1^2}^{ x_3^2} & m_{ x_1^2}^{x_2 x_3} & 0 & m_{x_1 x_2}^{ x_3^2} &  - m_{x_1 x_2}^{x_2 x_3} - m_{x_1 x_3}^{ x_3^2} & m_{x_1 x_3}^{x_2 x_3} & 0
