\subsection{Section \ref{sec:collinear}}

\begin{example}\label{ex:collinear}
    Let $n=2, r=4$, with $\phi$ satisfying Condition \ref{cond:collinear}.  Recall from the proof of Lemma \ref{lem:n23_linear} that the single polynomial $m\cdot m_{x_1^2}^{x_2^2}-\bb{m_{x_1^2}^{x_1x_2}}^2$ determines whether $\mathbf{A}$ drops rank.  But indeed this polynomial is equal to zero by Proposition \ref{prop:collinear_eqs}, and as we can show that $m\neq 0$, $\mathbf{A}$ is rank $1$.  As the two moment variables are $y_{x_1^5}, y_{x_1^4x_2}$, we can treat $y_{x_1^5}$ as a parameter, thus determining a value for $y_{x_1^4x_2}$ via the single linearly independent relation.

For simplicity we assume $\lambda_i=1, i=1, \dots, 4$.  We have 
\[
\mathcal{H}_{B, B_1}=\begin{bmatrix}
    \phi_{x_1} & \phi_{x_1^2} & \phi_{x_1x_2} & \phi_{x_1^3}\\
    \phi_{x_1^2} & \phi_{x_1^3} & \phi_{x_1^2x_2} & \phi_{x_1^4}\\
    \phi_{x_1x_2} & \phi_{x_1^2x_2} & \phi_{x_1x_2^2} & \phi_{x_1^3 x_2}\\
    \phi_{x_1^3} & \phi_{x_1^4} & \phi_{x_1^3x_2} & y_{x_1^5}
\end{bmatrix},\quad \mathcal{H}_{B, B_2}=\begin{bmatrix}
    \phi_{x_2} & \phi_{x_1x_2} & \phi_{x_2^2} & \phi_{x_1^2x_2}\\
    \phi_{x_1x_2} & \phi_{x_1^2x_2} & \phi_{x_1x_2^2} & \phi_{x_1^3x_2}\\
    \phi_{x_2^2} & \phi_{x_1x_2^2} & \phi_{x_2^3} & \phi_{x_1^2 x_2^2}\\
    \phi_{x_1^2x_2} & \phi_{x_1^3x_2} & \phi_{x_1^2x_2^2} & y_{x_1^4x_2}
\end{bmatrix}.
\]
Now letting $\Z_B^{\hat{i}, \hat{x^\alpha}}$ denote the $3\times 3$ submatrix of $\Z_B$ obtained by removing row $i$ and column $x^\alpha$, 
\[
\Z_B^{-1}=\frac{1}{\operatorname{det}\bb{\Z_B}}\begin{bmatrix}
    \operatorname{det}\bb{\Z_{B}^{\hat{1}, \hat{1}}} & -\operatorname{det}\bb{\Z_{B}^{\hat{2}, \hat{1}}} & \operatorname{det}\bb{\Z_{B}^{\hat{3}, \hat{1}}} & -\operatorname{det}\bb{\Z_{B}^{\hat{4}, \hat{1}}}\\
    -\operatorname{det}\bb{\Z_{B}^{\hat{1}, \hat{x_1}}} & \operatorname{det}\bb{\Z_{B}^{\hat{2}, \hat{x_1}}} & -\operatorname{det}\bb{\Z_{B}^{\hat{3}, \hat{x_1}}} & \operatorname{det}\bb{\Z_{B}^{\hat{4}, \hat{x_1}}}\\
    \operatorname{det}\bb{\Z_{B}^{\hat{1}, \hat{x_2}}} & -\operatorname{det}\bb{\Z_{B}^{\hat{2}, \hat{x_2}}} & \operatorname{det}\bb{\Z_{B}^{\hat{3}, \hat{x_2}}} & -\operatorname{det}\bb{\Z_{B}^{\hat{4}, \hat{x_2}}}\\
    -\operatorname{det}\bb{\Z_{B}^{\hat{1}, \hat{x_1^2}}} & \operatorname{det}\bb{\Z_{B}^{\hat{2}, \hat{x_1^2}}} & -\operatorname{det}\bb{\Z_{B}^{\hat{3}, \hat{x_1^2}}} &\operatorname{det}\bb{\Z_{B}^{\hat{4}, \hat{x_1^2}}}
\end{bmatrix},
\]
and in particular, $\operatorname{det}\bb{\Z_{B}^{\hat{3}, \hat{x_1^2}}}=0$.  Therefore, $\mathbf{M}_1^B=\mathcal{H}_{B, B_1}\mathcal{H}_{B, B}^{-1}=\mathcal{H}_{B, B_1}\Z_B^{-1}\Z_B^{-\top}$ is such that
\[\mathcal{H}_{B, B_1}\Z_B^{-1}=\begin{bmatrix}
    \z_{1, 1} & \z_{2, 1} & \z_{3, 1} & t\z_{1, 1}+(1-t)\z_{2, 1} \\ 
    \z_{1, 1}^2 & \z_{2, 1}^2 & \z_{3, 1}^2 & \bb{t\z_{1, 1}+(1-t)\z_{2, 1}}^2 \\ 
    \z_{1, 1}\z_{1, 2} & \z_{2, 1}\z_{2, 2} & \z_{3, 1}\z_{3, 2} & \bb{t\z_{1, 1}+(1-t)\z_{2, 1}}\bb{t\z_{1, 2}+(1-t)\z_{2, 2}} \\ 
    f_{x_1^3, 1}(y_{x_1^5}) & f_{x_1^3, 2}(y_{x_1^5}) & f_{x_1^3, 3}(y_{x_1^5}) & f_{x_1^3, 4}(y_{x_1^5})
\end{bmatrix},\]
where $f_{x_1^3, j}$ are linear functions in $y_{x_1^5}$.  In particular, we can calculate explicitly
\begin{align*}
    f_{x_1^3, 3}(y_{x_1^5})
    &=\phi_{x_1^3}\operatorname{det}\bb{\Z_B^{\hat{3}, \hat{1}}}-\phi_{x_1^4}\operatorname{det}\bb{\Z_B^{\hat{3}, \hat{x_1^2}}}+\phi_{x_1^3x_3}\operatorname{det}\bb{\Z_B^{\hat{3}, \hat{x_2}}}-y_{x_1^5}\operatorname{det}\bb{\Z_B^{\hat{3}, \hat{x_1^2}}}\\
    &=\phi_{x_1^3}\operatorname{det}\bb{\Z_B^{\hat{3}, \hat{1}}}-\phi_{x_1^4}\operatorname{det}\bb{\Z_B^{\hat{3}, \hat{x_1^2}}}+\phi_{x_1^3x_3}\operatorname{det}\bb{\Z_B^{\hat{3}, \hat{x_2}}}\\
    &=\z_{3, 1}^3.
\end{align*}
Then we immediately have $\mathbf{M}_1^B(y_{x_1^5})\z_3^B=\z_{3, 1}\z_3^B$, so that $\z_3^B$ is always an eigenvector of the multiplication matrices regardless of the value of $y_{x_1^5}$.

On the other hand, consider a vector $\z'=s\z_1+(1-s)\z_2$ for any $s\in (0,1 )$.  We have ${\z'}^B=s\z_1^B+(1-s)\z_2^B-s(1-s)\begin{bmatrix}
    0\\0\\0\\(\z_{1, 1}-\z_{2, 1})^2
\end{bmatrix}$; then a calculation shows $\mathbf{M}_1^B(y_{x_1^5}){\z'}^B$ is equal to
\[
 \begin{bmatrix}
    s\z_{1, 1}+(1-s)\z_{2, 1}\\
    (s\z_{1, 1}+(1-s)\z_{2, 1})^2\\
    (s\z_{1, 1}+(1-s)\z_{2, 1})(s\z_{1, 2}+(1-s)\z_{2, 2})\\
    g_{3, 0}(y_{x_1^5})+g_{3, 1}(y_{x_1^5})(s\z_{1, 1}+(1-s)\z_{2, 1})+g_{3, 2}(y_{x_1^5})(s\z_{1, 2}+(1-s)\z_{2, 2})+g_{3, 3}(y_{x_1^5})(s\z_{1, 1}+(1-s)\z_{2, 1})^2
\end{bmatrix},
\]
for linear functions $g$ in $y_{x_1^5}$, so we consider
\begin{multline*}
     g_{3, 0}(y_{x_1^5})+g_{3, 1}(y_{x_1^5})(s\z_{1, 1}+(1-s)\z_{2, 1})+g_{3, 2}(y_{x_1^5})(s\z_{1, 2}\\+(1-s)\z_{2, 2})+g_{3, 3}(y_{x_1^5})(s\z_{1, 1}+(1-s)\z_{2, 1})^2\\
    =  (s\z_{1, 1}+(1-s)\z_{2, 1})^3.
\end{multline*}
This is a cubic polynomial in $s$, with coefficients the entries of $\phi$, $\z_1, \z_2$, and the parameter $y_{x_1^5}$.  There are three distinct eigenvectors when there are three distinct solutions to this cubic, which is a condition on the discriminant.  For generic choices of value for $y_{x_1^5}$ the discriminant is nonzero, as checked by specialization.

Because there are no quadratic relations, all decompositions are specified by the linear relations: the point $\z_3$ and $s_1\z_1+(1-s_1)\z_2, s_2\z_1+(1-s_2)\z_2, s_3\z_1+(1-s_3)\z_2$, where $s_1, s_2, s_3$ are the three distinct solutions corresponding to the above cubic for a fixed value for the variable $y_{x_1^5}$.  That is, as there is one free parameter, the dimension of the space of decompositions is one-dimensional -- geometrically, $\z_3$ along with the line passing through $\z_{1}$ and $\z_2$.  This recovers case (4b)(ii) of Theorem 3.7 of \cite{MOURRAIN2020347}.
\end{example}











\section{Additional Proofs for Section \ref{sec:monomials}}\label{app:b}
\subsection{Section \ref{sec:monomialeqs}}


\begin{proof}[Proof of Lemma \ref{lem:monomial_G}]
    As $\mathcal{H}_{B, B}$ is symmetric lower antitriangular, $\mathcal{G}$ is symmetric upper antitriangular.  By definition, for $x^\gamma, x^{\gamma'}\in B$, $\mathcal{G}_{x^\gamma}^\top \mathcal{H}_{B, x^{\gamma'}}=1$ if $\gamma=\gamma'$ and $0$ otherwise.

    Explicitly, we have
    \[\mathcal{G}_{x^\gamma}^\top \mathcal{H}_{B, x^{\gamma'}}=\sum_{\delta}\mathcal{G}_{x^\gamma, x^{\overline{d}-\delta}}\mathcal{H}_{x^{\overline{d}-\delta}, x^{\gamma'}}.\]
    $\mathcal{H}_{\overline{d}-\delta, \gamma'}$ is nonzero when either $\delta=\gamma'$, so that the corresponding entry is $1$, or $(x^\delta, x^{\gamma'})\in S_k$ for $k\geq 1$, in which case the corresponding entry is $y_{x^{\overline{d}-\delta+\gamma'}}$ (note that it suffices to consider only those $\delta$ such that $|\delta|\leq |\gamma'|$; for $|\delta|>|\gamma|$ the size of $\overline{d}-\delta+\gamma'$ is too small so the entry of $\mathcal{H}_{B, B}$ is zero).  Then
    \begin{multline*}
        \mathcal{G}_{x^\gamma}^\top \mathcal{H}_{B, x^{\gamma'}}=\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}+\sum_{(x^\delta, x^{\gamma'})\in S_k, k\geq 1}\mathcal{G}_{x^\gamma, x^{\overline{d}-\delta}}\mathcal{H}_{x^{\overline{d}-\delta}, x^{\gamma'}}\\=\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}+\sum_{(x^\delta, x^{\gamma'})\in S_k, k\geq 1}\mathcal{G}_{x^\gamma, x^{\overline{d}-\delta}}y_{x^{\overline{d}-\delta+\gamma'}}.
    \end{multline*}

    In particular, for $\gamma=\gamma'$ 
    \[\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma}}=1-\sum_{(x^\delta, x^\gamma)\in S_k, k\geq 1}\mathcal{G}_{x^\gamma, x^{\overline{d}-\delta}}y_{x^{\overline{d}-\delta+\gamma}}\]
    and when $\gamma\neq \gamma'$
    \[\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}=-\sum_{(x^\delta, x^{\gamma'})\in S_k, k\geq 1}\mathcal{G}_{x^\gamma, x^{\overline{d}-\delta}}y_{x^{\overline{d}-\delta+\gamma'}}.\]

    First, note that for $|\gamma|>|\gamma'|$ $\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}=0$; this can be seen easily from upper antitriangularity of $\mathcal{G}$.  Assuming now $|\gamma|\leq |\gamma'|$ we compute $\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}$ for $(x^\gamma, x^{\gamma'})\in S_k$ for increasing $S_k$.  Let $k=0$; then $0\leq |\gamma'|-|\gamma|\leq d_0$.  But the summation is vacuous: suppose there exists $\delta$ such that $(x^\delta, x^{\gamma'})\in S_k, k\geq 1$.  For $|\gamma|>|\delta|$ we know $\mathcal{G}_{x^\gamma, x^{\overline{d}-\delta}}=0$, so we can also assume $|\gamma|\leq |\delta|$.  But then we have $|\gamma'|-|\delta|\geq d_0+1$ and $-\gamma\geq -\delta$, so $|\gamma'|-|\gamma|\geq d_0+1$, a contradiction.  Therefore, for $(x^\gamma, x^{\gamma'})\in S_0$, $\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}=1$ is $\gamma=\gamma'$ and is $0$ otherwise.

    Now suppose $(x^\gamma, x^{\gamma'})\in S_k$ for some $k\geq 1$.  In this case the entry is always
    \[\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}=-\sum_{(x^\delta, x^{\gamma'})\in S_k, k\geq 1}\mathcal{G}_{x^\gamma, x^{\overline{d}-\delta}}y_{x^{\overline{d}-\delta+\gamma'}}.\]
    In fact, we can always upper bound $k$ in the summation.  Suppose $(x^\delta, x^{\gamma'})\in S_\ell$ for some $\ell> k$.  Then by the same argument as before, as $|\gamma|\leq |\delta|$ we have
    \[|\gamma'|-|\gamma|\geq |\gamma'|-|\delta|\geq \ell(d_0+1),\]
    a contradiction.  On the other hand, for $\ell\leq k$ there will always exist some $(x^\delta, x^{\gamma'})\in S_\ell$ (e.g., for $\ell=k$ just take $\delta=\gamma$).  Thus, we can write
    \[\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}=-\sum_{\ell=1}^k \sum_{(x^\delta, x^{\gamma'})\in S_\ell} \mathcal{G}_{x^\gamma, x^{\overline{d}-\delta}}y_{x^{\overline{d}-\delta+\gamma'}}.\]
    Let us be more precise.  We can see that if $(x^\delta, x^{\gamma'})\in S_\ell$, that we immediately have the upper bound $|\delta|-|\gamma|\leq (k-\ell+1)(d_0+1)-1$, i.e., if $(x^\delta, x^{\gamma'})\in S_\ell$ and $(x^\gamma, x^\delta)\in S_{\ell'}$, then $\ell'\leq d-\ell$.  In particular, if $(x^\delta, x^{\gamma'})\in S_k$ then $(x^\gamma, \delta)\in S_0$; as we know that for $(\gamma, x^\delta)\in S_0$, $\mathcal{G}_{x^\gamma, x^{\overline{d}-\delta}}\neq 0$ if and only if $\gamma=\delta$, we finally write
    \[\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}=-y_{x^{\overline{d}-\gamma+\gamma'}}-\sum_{\ell=1}^{k-1}\sum_{(x^\delta, x^{\gamma'})\in S_\ell}\mathcal{G}_{x^\gamma, x^{\overline{d}-\delta}}y_{x^{\overline{d}-\delta+\gamma'}}.\]
    It is easy to induct via this expression and see that the degree of $\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}$ is $k$ and the only moment variable in $Y_k$ is $y_{x^{\overline{d}-\gamma+\gamma'}}$.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:monomial_eq}]
    We can see that
    \[\operatorname{det}\mathcal{H}_{B\cup\{x^{\alpha}x_i\}, B\cup\{x^\beta x_j\}}=-y_{x^{\alpha+\beta}x_i x_j}+\sum_{\gamma, \gamma'}\mathcal{H}_{x^\alpha x_i, x^\gamma}\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}\mathcal{H}_{x^{\overline{d}-\gamma'}, x^\beta x_j}.\]
    Then the expression simply comes from the fact that $\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma}}=1$.  

    By induction we see that for fixed $\ell$,
    \[\operatorname{deg}\bb{\sum_{\substack{|\gamma|\geq d-|\alpha|,\\ |\gamma'|\leq |\beta|-d_0,\\(x^\gamma, x^{\gamma'})\in S_\ell}}y_{x^{\alpha+\gamma}x_i}\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}y_{x^{\overline{d}-\gamma'+\beta} x_j}}=\ell+2,\]
    so that if $x^{\alpha+\beta}x_i x_j\in Y_k$ then $\operatorname{deg}\bb{\mathcal{H}_{B\cup \{x^\alpha x_i\}, B\cup \{x^\beta x_j\} }}=k$ with degree $\ell$ part graded in the above manner.  For some fixed $\ell$ we calculate the sizes of the variables present.  First, from $(x^\gamma, x^{\gamma'})\in S_\ell$ we can see $|\gamma|\leq |\gamma'|-\ell(d_0+1)$.  Then
    \begin{align*}
        |\alpha|+|\gamma|+1
        &\leq |\alpha|+|\gamma'|-\ell(d_0+1)+1\\
        &\leq |\alpha|+|\beta|+2-(\ell+1)(d_0+1)\\
        &\leq d+(k-(\ell+1))(d_0+1).
    \end{align*}
    Thus, if $x^{\alpha+\gamma }x_i\in Y_{\ell'}$ then we must have $\ell'\leq k-(\ell+1)$.  The same idea works for $x^{\overline{d}-\gamma'+\beta} x_j$.  We also now that the maximum size of any variable that appears in $\mathcal{G}_{x^\gamma, x^{\overline{d}-\gamma'}}$ is in $Y_\ell$.  Therefore, we have again that the only variable in $Y_k$ in the equation is $x^{\alpha+\beta}x_ix_j$.
\end{proof}

