\centering
\includegraphics[angle=0,width=1.0\hsize]{figs/nz_mag22-24p5_6bins_ser++_number-1.pdf}
\includegraphics[angle=0,width=1.0\hsize]{figs/nz_mag24p5-26p5_6bins_ser++_number-1.pdf}
