\section{Problem Formulation}
\label{sec:formulation}

Let $\mathcal{X}$ denote the collection of all bounded measurable real-valued functions on a given measurable space $(S, \Sigma)$. We consider a reinsurance market populated by $n$ insurers, each subject to a random initial loss represented by a nonnegative random variable $X_i\in\mathcal{X}$, for $i\in\{1,\ldots,n\}$.
These insurers seek reinsurance from $m$ reinsurers present in the market.
For notational convenience, let $\mathcal{N} := \{1,\ldots,n\}$ denote the set of insurers indexed by $i$, and let $\cM := \{1,\ldots,m\}$ denote the set of reinsurers, indexed by $j$. Since each initial loss is bounded, we may define $M<\infty$ to be a uniform upper bound for all $X_i$.


\medskip
%===================
\subsection{Reinsurance Contracts}

In this market, each insurer $i \in \cN$ may cede a portion of their initial risk to reinsurer $j\in\cM$ by paying a premium.
Specifically, let $I_{ij}$ denote the indemnity function purchased by insurer $i$ from reinsurer $j$,
    and let $\pi_{ij}$ be the premium paid for this contract.
Then the risk exposure of each insurer $i \in \mathcal{N}$ after reinsurance is
    \begin{equation*}
         X_i - \sum_{j=1}^mI_{ij}(X_i) +\sum_{j=1}^m\pi_{ij}\,.
    \end{equation*}
The risk exposure of each reinsurer $j \in \cM$ is
\begin{equation*}
    \sum_{i=1}^n \bigg((1+\theta_j) I_{ij}(X_i) - \pi_{ij}\bigg)\,,
\end{equation*}
where $\theta_j>0$ is a loading factor that represents the cost of reinsurance to reinsurer $j$.

Denote the set of 1-Lipschitz and non-decreasing functions on $[0,M$] by
    \[
        \mathcal{I}_0=\left\{f:[0,M]\rightarrow[0,M]\quad\middle|\quad f(0)=0, \,\,\, 0 \leq f(x) - f(y) \leq x-y \,\,\, \forall\, 0\le y\le x\le M\right\}\,.
    \]


\noindent We assume throughout that only those indemnity functions that satisfy the no-sabotage condition of \cite{carlierdana2003} are admissible. Moreover, we assume that for each insurer $i\in\cN$, the sum of contracts also satisfies the no-sabotage condition, as given by the following:

\medskip

\begin{assumption}
    \label{as:sum_1-lipschitz}
    \[
        \sum_{j=1}^mI_{ij}\in\cI_0\,.
    \]
\end{assumption}

\noindent This assumption guarantees that each insurer does not purchase multiple reinsurance contracts for the same risk.
We refer to Appendix \ref{apdx:sum_1-lipschitz} for a more detailed justification of Assumption \ref{as:sum_1-lipschitz}. 
Hence, the set of admissible indemnity structures in this market is given by
    \[
        \mathcal{I}:=\left\{\{I_{ij}\}_{i\in \cN, j \in \cM}\,\,\middle|\,\,I_{ij} \in \mathcal{I}_0\quad\forall\,(i,j) \in \cN\times\cM\,, \,\,\, \text{and} \,\,\,   \sum_{j=1}^m I_{ij} \in \mathcal{I}_0\quad\forall i \in \cN \right\}\,. 
    \]

\noindent For notational convenience, we will define the set of admissible indemnity structures for each insurer $i$ by
    \[
        \mathcal{I}_i:=\left\{\{I_j\}_{j \in \cM}\,\,\middle|\,\,I_j\in \mathcal{I}_0\quad\forall\,j\in\cM\,, \,\,\, \text{and} \,\,\,   \sum_{j=1}^m I_j \in \cI_0\right\}\,. 
    \]

\noindent Note that $\prod_{i=1}^n\cI_i=\cI$.
The reinsurance contracts in aggregate completely determine how risk is reallocated among the agents through reinsurance.

\medskip

\begin{definition}[Allocation]
An \emph{allocation} is a pair
        \[
            \allocation\in\cI\times\mathbb{R}^{n\times m}\,,
        \]
    where $\{I_{ij}\}_{i \in \cN, j \in \cM}$ is an admissible vector of indemnity functions and $\{\pi_{ij}\}_{i\in \cN, j \in \cM}$ is a vector of premia.
\end{definition}


\medskip
%===================
\subsection{Risk Measures}

The preferences of each agent are represented by risk measures. We recall some standard properties of risk measures below.

\medskip

\begin{definition}
    A risk measure $\rho:\mathcal{X} \rightarrow \mathbb{R}$ is said to be:
    \begin{itemize}
        \item Monotone: if $\rho(X) \leq \rho(Y)$ whenever $X \leq Y$, for all $X, Y \in \mathcal{X}$.
        \item Positive Homogeneous: if $\rho(\lambda X) = \lambda \rho(X)$, for all $X \in \mathcal{X}$ and $\lambda \in \mathbb{R}^+$.
        \item Translation  invariant: if $\rho(X+c) = \rho(X) + c$, for all $X \in \mathcal{X}$ and $c \in \mathbb{R}$.
        \item Comonotone additive: if $\rho(X + Y) = \rho(X) + \rho(Y)$, for all $X,Y \in \cX$ that are comonotone.\footnote{Two random variables $X, Y \in \mathcal{X}$ are said to be comonotone if $(X(s_1) - X(s_2))(Y(s_1) -Y(s_2)) \geq 0$, for all $s_1,s_2\in S$.}
        \item Subadditive: if $\rho(X+Y) \leq \rho(X) + \rho(Y)$, for all $X, Y \in \mathcal{X}$.
    \end{itemize}
\end{definition}

We assume throughout that all risk measures are Choquet risk measures, as given by the following definitions.

\medskip

\begin{definition}
    A set function $\nu:\Sigma\rightarrow\R_+$ is a \emph{capacity} if
    \begin{itemize}
        \item $\nu(\varnothing) = 0$ and $\nu(S)<\infty$, and,
        \item If $A,B\in \Sigma$ are such that $A \subseteq B $, then $\nu(A) \leq \nu(B)$.
    \end{itemize}
    \end{definition}

\noindent Note that we require all capacities to be finite. Let $\mathcal{C}$ denote the set of all capacities.

\medskip

\begin{definition}
    Given a capacity $\nu \in \mathcal{C}$ and a random variable $X \in \mathcal{X}$, the \emph{Choquet expectation} of $X$ with respect to $\nu$ is defined as
        \begin{equation*}
            \int X\,d\nu := \int_0^{\infty}\nu(X>t)\,dt + \int_{-\infty}^0(\nu(X>t) -\nu(S))\,dt.
        \end{equation*}
\end{definition}

We denote the risk measure of insurer $i \in \mathcal{N}$ by $\rho_i^{In}$, and the risk measure of reinsurer $j\in\cM$ by $\rho_j^{Re}$.
For all risks $X\in\cX$, we assume that
$$\rho_i^{In}(X):=\int X\,d\alpha_i 
\ \ \hbox{and} \ \ 
\rho_j^{Re}(X):=\int X\,d\tau_j,$$
where $\alpha_i,\tau_j\in\cC$ for all $i\in\cN$ and $j\in\cM$.

\medskip

Note that Choquet risk measures are translation invariant, positively homogeneous, and comonotone additive.
Hence, the risk level of insurer $i\in\cN$ given the allocation $(\{I_{ij}\}_{i \in \cN, j \in \cM}, \{\pi_{ij}\}_{i\in \cN, j \in \cM})$ is
    \[
       \rho^{In}_i \left(X_i- \sum_{j=1}^mI_{ij}(X_i) +\sum_{j=1}^m\pi_{ij}\right)= \rho^{In}_i(X_i) -  \rho^{In}_i\left(\sum_{j=1}^mI_{ij}(X_i)\right) +\sum_{j=1}^m\pi_{ij}\,.
    \]


\noindent Similarly, the risk level of reinsurer $j\in\cM$ is
    \[
       \rho^{Re}_j\left(\sum_{i=1}^n \bigg((1+\theta_j) I_{ij}(X_i) - \pi_{ij}\bigg)\right)= (1+\theta_j) \rho_j^{Re}\left( \sum_{i=1}^n I_{ij}(X_i)\right) -\sum_{i=1}^n \pi_{ij}\,.
    \]

\medskip
%===================
\subsection{Market Structure and Equilibria}
\label{sec:equilibria}


We model the reinsurance market with a sequential structure, in which the reinsurers as a collective have the first-mover advantage.
That is, each reinsurer may determine the premium principle they wish to charge to each insurer before the reinsurance contracts are purchased.
For each $(i,j)\in\cN\times\cM$, let $\Pi_{ij}:\mathcal{X}\to\R$ denote the premium principle charged by reinsurer $j$ to insurer $i$.
We assume that each reinsurer uses a Choquet premium principle, of the form
    \[
        \Pi_{ij}(X)=\int X\,d\nu_{ij}, \ \forall \, X \in \cX,
    \]
where $\nu_{ij}\in\cC$.
The strategy of a reinsurer is then completely determined by a choice of pricing capacities, as made precise by the following.

\medskip

\begin{definition}
    For each $j\in\cM$, the strategy of reinsurer $j$ is a vector $\bm{\nu_j}$ of capacities $\nu_{ij}$ of length $n$:
        \[
            \bm{\nu}_j:=\begin{bmatrix}
                    \nu_{1j}\\
                    \vdots\\
                    \nu_{nj}
                \end{bmatrix}\in\mathcal{C}^n\,,
        \]


\noindent where $\nu_{ij}$ is the pricing capacity associated with the premium charged to insurer $i$ by reinsurer $j$.
\end{definition}

The strategy of each insurer $i \in \cN$ is to select an admissible indemnity structure from the set $\cI_i$, given the prices charged by each reinsurer $j \in \cM$.

\medskip

\begin{definition}
    The strategy of insurer $i \in \cN$ is a map $\mathfrak{I}_i:\cC^m\to\cI_i$. Specifically, for an $m$-dimensional vector of capacities $(\nu_{i1},\ldots,\nu_{im})$, the selection $\mathfrak{I}_i(\nu_{i1},\ldots,\nu_{im})$ represents the indemnities selected by insurer $i$ after observing the prices $(\nu_{i1},\ldots,\nu_{im})$. For this reason, we will also refer to maps of the form $\mathfrak{I}_i:\cC^m\to\cI_i$ as indemnity selections.
\end{definition}

We denote by $\mathfrak{I}_{ij}(\nu_{i1},\ldots,\nu_{im})$ the $j$-th entry of $\mathfrak{I}_i(\nu_{i1},\ldots,\nu_{im})$. This is the indemnity purchased by the $i$-th insurer from the $j$-th reinsurer under the strategy $\mathfrak{I}_i$, given that the pricing capacities of the reinsurers are $(\nu_{i1},\ldots,\nu_{im})$.

\medskip

\begin{definition}
    A \emph{strategy} is a tuple $(\bm{\nu}_1,\ldots,\bm{\nu}_m,\mathfrak{I}_1,\ldots,\mathfrak{I}_n)$ where:
        \begin{itemize}
            \item Each $\bm{\nu}_j$ is an $n$-dimensional vector of capacities representing reinsurer $j$'s strategy vector, for each $j \in \cM$.
            \item For each $i\in\mathcal{N}$, each $\mathfrak{I}_i$ is an indemnity selection. That is, $\mathfrak{I}_i$ is a map from $\mathcal{C}^m$ to $\mathcal{I}_i$.
        \end{itemize}
\end{definition}

The risk level to insurer $i \in \cN$ resulting from a strategy $(\bm{\nu}_1,\ldots,\bm{\nu}_m,\mathfrak{I}_1,\ldots,\mathfrak{I}_n)$  is therefore
    \[
        \rho_i^{In}(X_i)
            -\sum_{j=1}^m\rho_i^{In}\Big(\mathfrak{I}_{ij}(\nu_{i1},\ldots,\nu_{im})(X_i)\Big)
            +\sum_{i=1}^n\Pi_{ij}\Big(\mathfrak{I}_{ij}(\nu_{i1},\ldots,\nu_{im})(X_i)\Big)\,.
    \]


\noindent Similarly, the risk level to reinsurer $j \in \cM$ is
    \[
        \rho_j^{Re}\left(\sum_{i=1}^n\Big((1+\theta_j) \mathfrak{I}_{ij}(\nu_{i1},\ldots,\nu_{im})(X_i)\Big)\right)
            -\sum_{i=1}^n\Pi_{ij}\Big(\mathfrak{I}_{ij}(\nu_{i1},\ldots,\nu_{im})(X_i)\Big)\,.
    \]

\medskip
%============
\subsubsection{Subgame Perfect Nash Equilibria}

Our focus is to identify and characterize the Subgame Perfect Nash Equilibria (SPNE) within this economic game.

\medskip

\begin{definition}
\label{defn:ne}
    A \emph{Nash Equilibrium} (NE) is a strategy from which no player has an incentive to deviate. Precisely, a strategy $\stratstar$ is a Nash Equilibrium if the following hold:
    \begin{enumerate}[label=(\roman*)]
        \item \label{defn:ne_1}
            There does not exist a capacity vector $\bm{\tilde{\nu}}\in\mathcal{C}^n$ and a reinsurer $j\in\cM$ such that 
                \begin{align*}
                    &\rho^{Re}_j \bigg(\sum_{i=1}^n (1+\theta_j)\mathfrak{I}^*_{ij}(\tilde{\nu}_i, \nu^*_{i,-j})(X_i)\bigg)
                        -\sum_{i=1}^n \Pi^{\tilde{\nu}_i}\bigg(\mathfrak{I}^*_{ij}(\tilde{\nu}_i, \nu^*_{i,-j})(X_i)\bigg)\\
                    &<\rho^{Re}_j \bigg(\sum_{i=1}^n (1+\theta_j) \mathfrak{I}^*_{ij}(\nu_{i1}^*, \ldots, \nu^*_{im})(X_i)\bigg)
                        -\sum_{i=1}^n\Pi^{\nu^*_{ij}}\bigg(\mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots, \nu^*_{im})(X_i)\bigg)\,,
                \end{align*}
            where $\tilde{\bm{\nu}}$ is an $n$-dimensional column vector of capacities, and $(\tilde{\nu}_i,\nu_{i,-j})$ is the $m$-dimensional row vector $(\nu_{i1},\ldots,\nu_{im})$ with its $j$-th element replaced by $\tilde{\nu}_i$.
            In other words, reinsurer $j$ cannot improve by changing their strategy from $\bm{\nu}_j^*$ to $\tilde{\bm{\nu}}$, all else held constant.
        \item \label{defn:ne_2}
            There does not exist an insurer $i\in\cN$ and an indemnity selection $\tilde{\mathfrak{I}}_i$ such that
                \begin{align*}
                    &\rho^{In}_i(X_i)
                        -\rho^{In}_i\bigg(\sum_{j=1}^m \tilde{\mathfrak{I}}_{ij}(\nu^*_{i1},\ldots, \nu^*_{im})(X_i)\bigg)
                        +\sum_{j=1}^m \Pi^{\nu^*_{ij}} \bigg( \tilde{\mathfrak{I}}_{ij}(\nu^*_{i1},\ldots, \nu^*_{im})(X_i)\bigg)\\
                    &<\rho^{In}_i(X_i)
                        -\rho^{In}_i\left(\sum_{j=1}^m \mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots, \nu^*_{im})(X_i)\right)
                        +\sum_{j=1}^m\Pi^{\nu^*_{ij}}\bigg(\mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots, \nu^*_{im})(X_i)\bigg).
                \end{align*}
            That is, insurer $i$ does not improve by changing their indemnity selection from $\mathfrak{I}_i^*$ to $\tilde{\mathfrak{I}}_i$.
    \end{enumerate}
\end{definition}

\medskip

\begin{definition}
\label{defn:spne}
    A strategy $\stratstar$ is a Subgame Perfect Nash Equilibria (SPNE) if the following hold:
    \begin{enumerate}[label=(\roman*)]
        \item \label{defn:spne_1}
            $\stratstar$ is an NE.
        \item \label{defn:spne_2}
            For any choice of capacity vectors $(\bm{\nu}_1,\ldots,\bm{\nu}_m) \in \mathcal{C}^{n \times m}$, there does not exist an insurer $i\in\cN$ and an indemnity selection $\tilde{\mathfrak{I}}_i$ such that
            \begin{align*}
                &\rho^{In}_i(X_i) - \rho^{In}_i\bigg(\sum_{j=1}^m \tilde{\mathfrak{I}}_{ij}(\nu_{i1},\ldots, \nu_{im})(X_i)\bigg) +\sum_{j=1}^m \Pi^{\nu_{ij}} \bigg( \tilde{\mathfrak{I}}_{ij}(\nu_{i1},\ldots, \nu_{im})(X_i)\bigg) \\
            &< \rho^{In}_i(X_i) - \rho^{In}_i\bigg(\sum_{j=1}^m \mathfrak{I}^*_{ij}(\nu_{i1},\ldots, \nu_{im})(X_i)\bigg) +\sum_{j=1}^m \Pi^{\nu_{ij}}\bigg( \mathfrak{I}^*_{ij}(\nu_{i1},\ldots, \nu_{im})(X_i)\bigg)\,.
        \end{align*}
    \end{enumerate}
\end{definition}

Note that by definition, every SPNE is an NE, but the converse does not necessarily hold.
The main difference is that Definition \ref{defn:spne}\ref{defn:spne_2} must hold for \emph{any} choice of capacity vectors $(\bm{\nu}_1,\ldots,\bm{\nu}_m) \in \mathcal{C}^{n \times m}$, instead of only holding for the specific choice $(\bm{\nu}^*_1,\ldots,\bm{\nu}^*_m)$.
For an in-depth discussion of the motivation for this distinction, we refer to \cite[Chapter 7]{maschler2020game}, for instance.


