\section{Characterization of SPNEs}
\label{sec:SPNE_characterization}


\subsection{Backward Induction}
Our main result in this section is a characterization of SPNEs in a market with multiple insurers and reinsurers.
It is well-known (e.g., \citealt[Remark 4.50]{maschler2020game}) that all SPNEs may be found through the process of backward induction.
That is, to determine an SPNE, we first determine the optimal strategy for each insurer in the market, since the insurers are the last agents to act.
Then, given one such optimal strategy for each insurer, we then determine the pricing capacities for the reinsurers that form an NE.
This process is illustrated in the context of the present paper by the following lemma.

\medskip

\begin{lemma} 
\label{SPNEminprop}
A strategy $\stratstar$ is an SPNE if and only if the following hold:
    \begin{enumerate}[label=(\roman*)]
        \item \label{SPNEminprop_1}
        For any choice of pricing capacities $(\bm{\nu}_1,\ldots,\bm{\nu}_m)$ $\in \mathcal{C}^{n \times m}$ and for all $i\in\cN$, the indemnity structure $\mathfrak{I}^*_i(\nu_{i1},\ldots, \nu_{im})$ solves 
            \begin{equation} \label{eq:minproblemSPNE}
                \min_{\{I_{ij}\}_{j\in \cM} \in \mathcal{I}_i} \left\{ \rho^{In}_i(X_i) - \sum_{j=1}^m \rho^{In}_i(I_{ij}(X_i)) + \sum_{j=1}^m \Pi^{\nu_{ij}}(I_{ij}(X_i)) \right\}.
            \end{equation}

        \item \label{SPNEminprop_2}
        $(\bm{\nu^*}_1,\ldots,\bm{\nu^*}_m)$ is a Nash Equilibrium for the reduced game formed from fixing the strategy $\mathfrak{I}^*_i$ of each insurer $i\in\cN$. That is, there does not exist $j \in \cM$ and $\tilde{\bm{\nu}}\in \mathcal{C}^n$ such that:
            \begin{align*}
                &\rho_j^{Re}\left(\sum_{i=1}^n (1+\theta_j) \mathfrak{I}^*_{ij}(\tilde{\nu}_i, \nu^*_{i,-j})(X_i)\right)
                - \sum_{i=1}^n \Pi^{\tilde{\nu}_i}\left(\mathfrak{I}^*_{ij}(\tilde{\nu}_i, \nu^*_{i,-j})(X_i) \right) \\ &\quad< \rho_j^{Re}\left(\sum_{i=1}^n (1+\theta_j)\mathfrak{I}^*_{ij}(\nu^*_{i1}, \cdots, \nu^*_{im})(X_i) \right) -  \sum_{i=1}^n \Pi^{\nu^*_{ij}}\left( \mathfrak{I}^*_{ij}(\nu^*_{i1}, \cdots, \nu^*_{im})(X_i)\right)\,.
                    \stepcounter{equation}\tag{\theequation}\label{eq:no_deviation}
            \end{align*}
    \end{enumerate}
\end{lemma}

\begin{proof}
    Note that point \ref{SPNEminprop_1} is a restatement of Definition \ref{defn:spne}\ref{defn:spne_2}.
    Hence, by Definition \ref{defn:spne}, it suffices to show that if \ref{SPNEminprop_1} holds, a strategy $\stratstar$ is an NE if and only if \ref{SPNEminprop_2} holds.
    To this end, if \ref{SPNEminprop_1} holds, it follows that for all $i\in\cN$, the indemnity structure $\mathfrak{I}^*_i(\nu_{i1}^*,\ldots,\nu_{im}^*)$ solves
        \[
            \min_{\{I_{ij}\}_{j\in \cM}\in\mathcal{I}_i}
                \left\{\rho^{In}_i(X_i)
                -\sum_{j=1}^m\rho^{In}_i(I_{ij}(X_i))
                +\sum_{j=1}^m\Pi^{\nu_{ij}^*}(I_{ij}(X_i))\right\}\,,
        \]
    which implies that Definition \ref{defn:ne}\ref{defn:ne_2} holds.
    Since \ref{SPNEminprop_2} is a restatement of Definition \ref{defn:ne}\ref{defn:ne_1}, the result follows.
\end{proof}

Lemma \ref{SPNEminprop} implies that the process of characterizing SPNE strategies involves first solving for insurer strategies before solving for reinsurer strategies.
To this end, we first determine all candidate insurer strategies by identifying the indemnity structures solving \eqref{eq:minproblemSPNE}.
This is given by the following result, which characterizes each indemnity function through its derivative using the so-called Marginal Indemnification Function approach.

\medskip

\begin{proposition}
    \label{propcapacity}
    Let $(\bm{\nu}_1,\ldots,\bm{\nu}_m)\in \mathcal{C}^{n \times m}$ be fixed pricing capacities, and define, for each $i\in\cN$ and $z\in[0,M]$,
        \begin{align*}
            \underline{\nu}_i(X_i>z)&:=\min_{j\in \cM} \nu_{ij}(X_i>z)\,,\\
            \mathcal{M}_i(z)&:=\{j\in\cM\,:\,\nu_{ij}(X_i>z)=\underline{\nu}_i(X_i>z)\}\,. 
        \end{align*}

    \noindent Then for a fixed $i\in\cN$, an indemnity structure $\{I^*_{ij}\}_{j \in \cM}\in\cI_i$ is a solution to \eqref{eq:minproblemSPNE} if and only if for each $j\in\cM$ and $x\in[0,M]$, the indemnity $I_{ij}^*$ can be written as
        \begin{equation}
        \label{eq:gamma_defn}
            I^*_{ij}(x) = \int_0^x \gamma^*_{ij}(z)\,dz\,,
        \end{equation}
    where each $\gamma_{ij}^*$ is a $[0,1]$-valued measurable function that satisfies, for almost all $z\in[0,M]$,
        \[
            \gamma^*_{ij}(z)=h_{ij}(z)\One_{\{j \in \mathcal{M}_i(z)\}},
        \]
    and  
        \[
            \sum_{j=1}^m\gamma^*_{ij}(z)=\begin{cases}
                1,&\mbox{ if}\quad\alpha_i(X_i >z)>\underline{\nu}_i(X_i>z)\\
                H_i(z),&\mbox{ if}\quad\alpha_i(X_i >z)=\underline{\nu}_i(X_i>z)\\
                0,&\mbox{ if}\quad\alpha_i(X_i >z)<\underline{\nu}_i(X_i>z)
            \end{cases}\,,
        \]
    for some $[0,1]$-valued measurable functions $H_i$ and $h_{ij}$.
\end{proposition}

\begin{proof}
    Note that if prices are fixed, the choice of each individual insurer $i\in\cN$ is not affected by the decisions of other insurers in the market.
    Hence, when $i\in\cN$ is fixed, this market reduces to the case with the one insurer $i$ and multiple reinsurers $j\in\cM$.
    It then follows that an application of \cite[Theorem 3.1]{BOONEN202123} to each $i\in\cN$ yields the result.
\end{proof}

Note that Proposition \ref{propcapacity} characterizes each indemnity function $I_{ij}^*$ using its derivative $\gamma_{ij}^*$ and the relationship given by \eqref{eq:gamma_defn}.
Hence, we refer to the $[0,1]$-valued function $\gamma_{ij}^*$ as the \emph{marginal indemnification} of $I_{ij}^*$. Furthermore, Proposition \ref{propcapacity} implies that the solutions to \eqref{eq:minproblemSPNE} are not unique, since multiple reinsurers may be charging the lowest price (i.e., the set $\cM_i(z)$ is not a singleton).
Different indemnity structures may also result from the flexibility when $\alpha_i=\underline{\nu}_i$ for an insurer $i$.
To facilitate an explicit characterization of SPNEs, we consider only those solutions to \eqref{eq:minproblemSPNE} that satisfy the property of \emph{generous distribution} introduced in \cite{zhu2023equilibria}.

\medskip

\begin{definition}[Generous Distribution]
\label{Generous Distribution}
    For a fixed $i\in\cN$, let $\{I_{ij}^*\}_{j\in\cM}$ be a solution to \eqref{eq:minproblemSPNE}.
    By \eqref{eq:gamma_defn}, we may write $I^*_{ij}(x)=\int_0^x\gamma^*_{ij}(z)\,dz$, where $\gamma^*_{ij}$ is a $[0,1]$-valued function.
    For each $z\in[0,M]$, let
        \begin{align*}
            \gamma^*_{i0}(z)&:=1-\sum_{j=1}^m\gamma^*_{ij}(z)\,,\\
            \tau_{i,0}(X_i>z)&:=\alpha_i(X_i>z)\,,\quad\mbox{and}\,,\\
            \tau_{i,j}(X_i>z)&:=(1+\theta_j)\tau_j(X_i>z)\quad\forall j\in\cM\,.
     \end{align*}

     \noindent Then $\{I_{ij}^*\}_{j\in\cM}$ \emph{distributes generously} if for almost all $z\in[0,1]$ and all $k \in\cM\cup\{0\}$, we have $\gamma^*_{ik}(z)=0$ if both of the following hold: 
        \begin{itemize}
            \item $\nu_{ik}(X_i>z) = \min_{j \in \cM \cup \{0\}} \{ \nu_{ij}(X_i>z)\}$, and,
            \item There exists $k'\in \big(\cM \cup \{0\}\big) \setminus \{k\}$ such that
                \[
                    \nu_{ik'}(X_i>z) = \nu_{ik}(X_i>z) \,\,\, \text{but}\,\,\, \tau_{i,k'}(X_i>z) < \tau_{i,k}(X_i>z)\,.
                \]
        \end{itemize}
\end{definition}

For the remainder of this section, we impose the following assumption.

\medskip

\begin{assumption}
    We assume that each insurer $i \in \mathcal{N}$ always selects an optimal indemnity that distributes generously.
    That is, for every fixed set of capacities $(\bm{\nu}_1,\ldots,\bm{\nu}_m)\in \mathcal{C}^{n \times m}$, the indemnity structure $\mathfrak{I}^*_i(\nu_{i1},\ldots,\nu_{im})$ distributes generously in the sense of Definition \ref{Generous Distribution}, for all $i\in\cN$.
    Let $\aleph$ denote the set of such strategies $(\mathfrak{I}_1^*,\ldots,\mathfrak{I}_n^*)$.
\end{assumption}

It now remains to determine the reinsurer strategies after fixing some insurer strategies $(\mathfrak{I}_1^*,\ldots,\mathfrak{I}_n^*)\in\aleph$.
These reinsurer strategies are determined constructively by using the following definitions.

\medskip

\begin{definition}
    For each insurer  $i \in \mathcal{N}$, we define the capacity $\Bar{\tau}_i$ to be the pointwise second-lowest function of the set $\{\tau_{i,0},\tau_{i,1}, \ldots, \tau_{i,m}\}$. We refer to $\Bar{\tau}_i$ as the second-lowest true preference for insurer $i$.
\end{definition}

\medskip

\begin{definition}
    \label{defn:beth}
    Define the class of reinsurer strategies $\beth \subseteq \mathcal{C}^{n\times m}$ as the set of all $(\bm{\nu}_1,\ldots,\bm{\nu}_m)$ such that for all $i\in\cN$ and almost all $z \in [0,M]$,
    \begin{enumerate}
        \item $\min_{j\in \cM} \nu_{ij}(X_i>z)=\Bar{\tau}_i(X_i>z)$.
            That is, the lowest price charged by any reinsurer to indemnify the tail risk $X_i>z$ is given by the second-lowest true preference $\bar{\tau}_i$.
        \item  There exists $k,k'\in\cM\cup\{0\}\,,k \neq k'$ such that
            \[
                \min_{j \in \cM}\nu_{ij}(X_i>z) = \nu_{ik}(X_i>z) = \nu_{ik'}(X_i>z)\,.
            \]
            That is, for each $i\in\cN$, there are always at least two reinsurers charging a price equal to the second-lowest true preference.
        \item We have $\mathcal{T}_i(z) \neq \varnothing \implies \mathcal{T}_i(z) \cap \mathcal{M}_i(z) \neq \varnothing$ , where
            \[
                \mathcal{T}_i(z):=\left\{j\in\cM\,\,\middle|\,\,\tau_{i,j}(X_i>z)  = \min_{k \in \cM \cup \{0\}} \tau_{i,k}(X_i>z)\right\}\,.
            \]
            In other words, for each $i\in\cN$, out of the reinsurers $j$ with the lowest true preference $\tau_{i,j}$, at least one is charging the price $\bar{\tau}_i$ to insurer $i$.           
    \end{enumerate}
\end{definition}

The main result of \cite{zhu2023equilibria} shows that in a model with only one policyholder, every strategy in $\beth\times\aleph$ is an SPNE.
However, since there are multiple policyholders in our model, each reinsurer must consider the risk of the sum of all contracts that they have written.
We show in the following that a characterization is possible under either of two additional assumptions: (i) that the reinsurers are risk neutral, or (ii) that the initial risks are comonotone.

\medskip
%=================================
\subsection{Risk-Neutral Reinsurers}
\label{subsec:expectation}

Suppose that each reinsurer $j\in\cM$ wishes to minimize the expected risk according to their own subjective beliefs, represented by probability measures on the space $(S,\Sigma)$.
In other words, we assume that $\tau_j$ is a probability measure, for all $j\in\cM$.
In this case, each reinsurer's evaluation of the sum of contracts $\sum_{i=1}^nI_{ij}$ is the sum of the expectations of each contract, as shown by the following:
    \begin{align*}
        \rho_j^{Re}\left(\sum_{i=1}^n(1+\theta_j)I_{ij}(X_i)\right)
            &=\mathbb{E}^{\tau_j}\left(\sum_{i=1}^n(1+\theta_j)I_{ij}(X_i)\right)
        =(1+\theta_j)\sum_{i=1}^n \mathbb{E}^{\tau_j}\big(I_{ij}(X_i)\big)\,.
    \end{align*}

\noindent Our main result provides a characterization of SPNEs in this case.
Its proof is provided in Appendix \ref{appendix-proofs}.

\medskip

\begin{theorem}\label{ThSPNE}
    Suppose that $\tau_j$ is a probability measure for all $j\in\cM$.
    Let $\mathfrak{I}^*_i \in \aleph$ and $(\bm{\nu}^*_1,\ldots,\bm{\nu}^*_m) \in \beth$. Then the strategy $\stratstar$ is an SPNE.
\end{theorem}

\medskip
%=================================
\subsection{Comonotone Risks}
\label{subsec:comonotone}

Alternatively, recall that since every $\rho_j^{Re}$ is a Choquet risk measure, they are comonotone additive.
We now show that if the initial risk random variables $X_1,\ldots,X_n$ are comonotone, then a similar characterization result to that of Theorem \ref{ThSPNE} is possible.
While it may not be realistic to assume that the initial risks of each insurer in the market are comonotone, recall that comonotonicity of losses represents a worst-case dependence structure for each reinsurer.
Consider a scenario where there is a probability measure $\Pr$ on the measurable space $(S,\Sigma)$, and that each $\rho_j^{Re}$ is law invariant with respect to $\Pr$.
That is, if two random variables $X$ and $Y$ have the same distribution under $\Pr$, we have 
    \[
        \rho_j^{Re}(X)=\rho_j^{Re}(Y)
    \]
for all $j\in\cM$.

Suppose that each reinsurer knows the distribution of each $X_i$ with respect to the measure $\Pr$, but does not necessarily know the dependence structure between these risks.
It would be prudent to evaluate risk based on the worst-case dependence in such a situation.
In other words, the reinsurer could evaluate the sum of contracts $\sum_{i=1}^nI_{ij}(X_i)$ by
    \[
        \rho_j^{Re}\left(\sum_{i=1}^n(1+\theta_j)I_{ij}(\tilde{X}_i)\right)\,,
    \]
where $(\tilde{X}_1,\ldots,\tilde{X}_n)$ is a comonotone vector of random variables such that $\tilde{X}_i$ and $X_i$ have the same distribution.
Such a comonotone vector is guaranteed to exist as long as the probability space $(S,\Sigma,\Pr)$ is atomless \cite[Lemma A.23]{follmer2011stochastic}.
Indeed, in  this case there exists a uniform random variable $U$ on the probability space $(S,\Sigma,\Pr)$, and taking $\tilde{X}_i:=F_{X_i,\Pr}^{-1}(U)$ for all $i\in\cN$ gives a comonotone vector of risks, where $F_{X_i,\Pr}^{-1}$ denotes a quantile function under $\Pr$ for $X_i$.
It then follows that
    \begin{align*}
        \rho_j^{Re}\left(\sum_{i=1}^n(1+\theta_j)I_{ij}(\tilde{X}_i)\right)
            &=(1+\theta_j)\sum_{i=1}^n\rho_j^{Re}(I_{ij}(\tilde{X}_i))
        =(1+\theta_j)\sum_{i=1}^n\rho_j^{Re}(I_{ij}(X_i))\,,
    \end{align*}
where the last equality follows from law invariance of $\rho_j^{Re}$.
Hence, in this scenario, it may be assumed without loss of generality that $X_1,\ldots,X_n$ are comonotone to begin with.
It then follows through similar arguments that a characterization of SPNE can be obtained, as given by the following.


\medskip

\begin{theorem}
\label{ThSPNEcom}
    Suppose that $X_1,\ldots,X_n$ are comonotone.
    Let $\mathfrak{I}^*_i \in \aleph$ and $(\bm{\nu}^*_1,\ldots,\bm{\nu}^*_m) \in \beth$. Then the strategy $\stratstar$ is an SPNE.
\end{theorem}

\begin{proof}
    Since $X_1,\ldots,X_n$ are comonotone and each indemnity function $\mathfrak{I}^*_{ij}(\nu^*_{i1},\cdots,\nu^*_{im})$ is non-decreasing, we have that for each $j\in\cM$, 
        \[
             \mathfrak{I}^*_{1j}(\nu^*_{11},\cdots,\nu^*_{1m})(X_1),\,
                \ldots,\,
                \mathfrak{I}^*_{nj}(\nu^*_{n1},\cdots,\nu^*_{nm})(X_n)
        \]
    are comonotone as well.
    Since $\rho_j^{Re}$ is comonotone additive, we have
        \begin{align*}
            &\quad\rho_j^{Re}\left(\sum_{i=1}^n (1+\theta_j)\mathfrak{I}^*_{ij}(\nu^*_{i1}, \cdots, \nu^*_{im})(X_i) \right) -  \sum_{i=1}^n \Pi^{\nu^*_{ij}}\left( \mathfrak{I}^*_{ij}(\nu^*_{i1}, \cdots, \nu^*_{im})(X_i)\right)\\            
            &=  \sum_{i=1}^n\rho_j^{Re}\bigg((1+\theta_j) \mathfrak{I}_{ij}^*(\nu^*_{i1}, \ldots, \nu^*_{im})(X_i)\bigg) -\sum_{i=1}^n \Pi^{\nu^*_{ij}}(\mathfrak{I}_{ij}^*(\nu^*_{i1}, \ldots, \nu^*_{im})(X_i)\big)\\
            &= \sum_{i=1}^n \bigg( \int (1+\theta_j)\mathfrak{I}_{ij}^*(\nu^*_{i1}, \ldots, \nu^*_{im})(X_i)\,d\tau_j - \int_0^M \nu^*_{ij}(X_i>z)\gamma^*_{ij}(z)\,dz\bigg)\,,
        \end{align*}

\noindent where each $\gamma^*_{ij}$ is the marginal indemnification of $I_{ij}^*$.
    The remainder of the proof follows similarly to that of Theorem \ref{ThSPNE}.
\end{proof}

\medskip
%=================================
\subsection{Pareto Efficiency of SPNEs}
\label{SecPO}

Moreover, when SPNEs can be characterized using either Theorem \ref{ThSPNE} or \ref{ThSPNEcom}, these equilibria result in Pareto-optimal allocations to each agent.
Recall that an \emph{allocation} is a pair $\allocation\in\cI\times\mathbb{R}^{n\times m}$, representing both an admissible indemnity structure and the premium amount for each reinsurance contract.

\medskip

\begin{definition}
    \label{IRdef}
    An allocation $\allocationstar\in\cI\times\mathbb{R}^{n\times m}$ is individually rational (IR) if it incentivizes all agents to participate in the market.
    That is,
         \[
            \rho^{In}_i \left(X_i-\sum_{j=1}^mI_{ij}^*(X_i) +\sum_{j=1}^m\pi_{ij}^*\right) \leq \rho^{In}_i(X_i)
        \] 
    and 
        \[
            \rho^{Re}_j\left(\sum_{i=1}^n \big( (1+\theta_j) I_{ij}^*(X_i) - \pi_{ij}^*\big)\right) \leq 0\,,
        \]
    for all $i\in\cN$ and $j\in\cM$.
\end{definition}

\medskip

\begin{definition}
    \label{POdef}
    An allocation $\allocationstar\in\cI\times\mathbb{R}^{n\times m}$ is Pareto optimal (PO) if it is IR and there does not exist another allocation $\allocationtilde$ such that
    \begin{align*}
        \rho^{In}_i\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i) +\sum_{j=1}^m\tilde{\pi}_{ij}\right)
            &\leq \rho^{In}_i \left(X_i-\sum_{j=1}^mI_{ij}^*(X_i) +\sum_{j=1}^m\pi_{ij}^*\right)\\
        \rho^{Re}_j\left(\sum_{i=1}^n\big((1+\theta_j) \tilde{I}_{ij}(X_i) - \tilde{\pi}_{ij}\big)\right)
            &\leq \rho^{Re}_j\left(\sum_{i=1}^n \big((1+\theta_j)I_{ij}^*(X_i)-\pi_{ij}^*\big)\right)
    \end{align*} 
    for all $i\in\cN$ and $j\in\cM$, with at least one strict inequality.
\end{definition}

The following provides an explicit characterization of PO allocations in this market. Its proof can be found in Appendix \ref{appendix-proofs}.

\medskip

\begin{proposition}
\label{prop:optimal_indemnities}
    Suppose that either $\tau_j$ is a probability measure for all $j\in\cM$, or that $X_1,\ldots,X_n$ are comonotone.
    Then an allocation $\allocationstar\in\cI\times\mathbb{R}^{n\times m}$ is Pareto optimal if and only if the following hold:
        \begin{enumerate}[label=(\roman*)]
            \item \label{prop:optimal_indemnities_1}
                The marginal indemnifications $\gamma_{ij}^*$ satisfy
                    \[
                        \sum_{j \in \cL_i(z)}\gamma_{ij}^*(z) =1\quad\mbox{and}\quad\sum_{j \in\cM\setminus\cL_i(z)}\gamma_{ij}^*(z) =0\,,
                    \]
                    for each $i\in\cN$, where
                    \[
                        \cL_i(z):= \left\{j \in \cM\cup \{0\}\,\,\middle|\,\, \tau_{i,j}(X_i>z) = \min_{k \in \cM \cup \{0\}} \tau_{i,k}(X_i>z)\right\}\,.
                    \]
            \item \label{prop:optimal_indemnities_2}
                The premia $\{\pi^*_{ij}\}_{i\in\cN,j\in\cM}$ are chosen such that $\allocationstar$ is individually rational.
        \end{enumerate}
\end{proposition}

\medskip

\begin{theorem}
\label{thm:induce_IRPO}
    Suppose that either $\tau_j$ is a probability measure for all $j\in\cM$, or that $X_1,\ldots,X_n$ are comonotone.
    Let $\mathfrak{I}^*_i\in\aleph$ and $(\bm{\nu}^*_{1},\ldots,\bm{\nu}^*_{m})\in\beth$.
    Then the strategy $\stratstar$ induces a PO allocation.
    That is, the allocation
        \[
            \left(\left\{\mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots,\nu^*_{im})\right\}_{i\in \cN, j \in \cM},\,\,
                \left\{\Pi^{\nu^*_{ij}}\left(\mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots,\nu^*_{im})(X_i)\right)\right\}_{i\in \cN, j \in \cM}\right)
        \]
    is Pareto optimal.
\end{theorem}

\begin{proof}
    By Proposition \ref{prop:optimal_indemnities}, verifying Pareto optimality in this market involves checking the two conditions \ref{prop:optimal_indemnities}\ref{prop:optimal_indemnities_1} and \ref{prop:optimal_indemnities}\ref{prop:optimal_indemnities_2}.
    Note first that by construction of the strategy $\stratstar$, it is easily verified that for each $i\in\cN$, we have that
        \[    \big(\nu_{i1}^*,\ldots,\nu_{im}^*,\mathfrak{I}^*_i\big)
        \]
    is a strategy for a market with one insurer and $m$ reinsurers that satisfies the conditions of \cite[Theorem 3.11]{zhu2023equilibria}.
    It then follows from \cite[Theorem 4.4]{zhu2023equilibria} that for each $i\in\cN$, we have
        \begin{align*}
            \rho^{In}_i\left(X_i-\sum_{j=1}^m\mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots,\nu^*_{im})(X_i)+\sum_{j=1}^m\Pi^{\nu^*_{ij}}\left(\mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots, \nu^*_{im})(X_i)\right)\right)&\le \rho^{In}_i(X_i)\,,\\
            \rho^{Re}_j\left( (1+\theta_j)\mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots,\nu^*_{im})(X_i)-\Pi^{\nu^*_{ij}}\left(\mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots, \nu^*_{im})(X_i)\right)\right)&\le0\quad\forall j\in\cM\,.
        \end{align*}

\noindent By summing the second inequality over all $i\in\cN$, we have that
        \[
      \rho^{Re}_j\left(\sum_{i=1}^n \left((1+\theta_j)\mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots,\nu^*_{im})(X_i)-\Pi^{\nu^*_{ij}}\left(\mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots, \nu^*_{im})(X_i)\right)\right)\right)\le0\quad\forall j\in\cM\,,
        \]
    implying individual rationality, so condition \ref{prop:optimal_indemnities}\ref{prop:optimal_indemnities_2} holds.

    It remains to verify condition \ref{prop:optimal_indemnities}\ref{prop:optimal_indemnities_1}.
    To this end, notice that this condition is verified by iterating over each $i\in\cN$.
    It then follows that a direct application of \cite[Theorem 4.12]{zhu2023equilibria} to each $i\in\cN$ yields the desired result.
\end{proof}



