\subsection{Proof of Theorem \ref{ThSPNE}}

For $i \in \mathcal{N}$ and $j \in \cM$, let $\mathfrak{I}^*_i \in \aleph$ and $(\bm{\nu}_{1},\ldots,\bm{\nu}_m)\in\beth$.
To verify that this is strategy indeed an SPNE, we apply Lemma \ref{SPNEminprop}.
By the definition of $\aleph$, it follows immediately that $\mathfrak{I}^*_i(\nu^*_{i1},\ldots,\nu^*_{im})$ is a solution to \eqref{eq:minproblemSPNE}.
It remains to show that there does not exist a $\bm{\tilde{\nu}}\in\cC^n$ such that \eqref{eq:no_deviation} holds.
To this end, we will first show that the total post-transfer risk to each reinsurer $j$ is exactly
    \[
        \sum_{i=1}^n\int_0^M\min\{\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z),\,0\}\,dz\,.
    \]
We then argue that it is not possible for each reinsurer to improve their post-transfer risk beyond this value by changing their pricing strategy.

To this end, recall that we may write each indemnity function $\mathfrak{I}^*_{ij}(\nu^*_{i1},\ldots,\nu^*_{im})$ in terms of its marginal indemnification $\gamma_{ij}^*$, as in \eqref{eq:gamma_defn}.
    \begin{align*}
    \rho_j^{Re}&\left(\sum_{i=1}^n (1+\theta_j)\mathfrak{I}^*_{ij}(\nu^*_{i1}, \cdots, \nu^*_{im})(X_i) \right) -  \sum_{i=1}^n \Pi^{\nu^*_{ij}}\left( \mathfrak{I}^*_{ij}(\nu^*_{i1}, \cdots, \nu^*_{im})(X_i)\right)\\
        &=  \sum_{i=1}^n \E^{\tau_j}\bigg((1+\theta_j) \mathfrak{I}_{ij}^*(\nu^*_{i1}, \ldots, \nu^*_{im})(X_i)\bigg) -\sum_{i=1}^n \Pi^{\nu^*_{ij}}(\mathfrak{I}_{ij}^*(\nu^*_{i1}, \ldots, \nu^*_{im})(X_i)\big)\\
        &= \sum_{i=1}^n \bigg(\E^{\tau_j}\big((1+\theta_j) \mathfrak{I}_{ij}^*(\nu^*_{i1}, \ldots, \nu^*_{im})(X_i)\big) - \Pi^{\nu^*_{ij}}(\mathfrak{I}_{ij}^*(\nu^*_{i1}, \ldots, \nu^*_{im})(X_i)\big)\bigg)\\
        &= \sum_{i=1}^n \bigg( \int (1+\theta_j)\mathfrak{I}_{ij}^*(\nu^*_{i1}, \ldots, \nu^*_{im})(X_i)\,d\tau_j - \int_0^M \nu^*_{ij}(X_i>z)\gamma^*_{ij}(z)\,dz\bigg)\\
        &= \sum_{i=1}^n \bigg(\int_0^M(1+\theta_j)\tau_j(X_i>z) \gamma^*_{ij}(z)\,dz - \int_0^M \nu^*_{ij}(X_i>z)\gamma^*_{ij}(z)\,dz\bigg)\\
        &= \sum_{i=1}^n \bigg(
        \int_0^M\tau_{i,j}(X_i>z) \gamma^*_{ij}(z)\,dz - \int_0^M \nu^*_{ij}(X_i>z)\gamma^*_{ij}(z)\,dz\bigg)\\
        &=  \sum_{i=1}^n \int_0^M \big( \tau_{i,j}(X_i>z) - \nu^*_{ij}(X_i>z)\big) \gamma^*_{ij}(z)\,dz\,.
    \end{align*}

By repeatedly applying \cite[Proposition 3.9]{zhu2023equilibria} for each $i\in\cN$, it follows that
    \begin{equation}
        \label{eq:target}
        \sum_{i=1}^n \int_0^M \big( \tau_{i,j}(X_i>z) - \nu^*_{ij}(X_i>z)\big) \gamma^*_{ij}(z)\,dz
        =\sum_{i=1}^n\int_0^M\min\{\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z),\,0\}\,dz\,.
    \end{equation}
In other words, the improvement in the reinsurer's risk measure is precisely the sum over all contracts of the positive difference between their true preference $\tau_{i,j}$ and the second-lowest preference $\bar{\tau}_i$.
That is, the reinsurer profits exactly when their true preference $\tau_{i,j}$ is lower than $\bar{\tau}_i$.


Now for a fixed reinsurer $j$, consider an alternative strategy $\bm{\tilde{\nu}}\in\cC^n$.
If the reinsurer were to switch to this alternative strategy, the indemnity structure selected by each insurer $i$ would be $\mathfrak{I}^*_{ij}(\tilde{\nu}_i,\nu^*_{i, -j})$, which can be expressed in terms of the marginal indemnification as
    \[
        \mathfrak{I}^*_{ij}(\tilde{\nu}_i, \nu^*_{i, -j})(x) = \int_0^x \tilde{\gamma}_{ij}(z)\,dz\,.
    \]

Using a similar simplification as the above, we can show that
    \begin{align*}
    \rho_j^{Re}&\left(\sum_{i=1}^n (1+\theta_j) \mathfrak{I}^*_{ij}(\tilde{\nu}_i, \nu^*_{i,-j})(X_i)\right)
            -\sum_{i=1}^n \Pi^{\tilde{\nu}_i}\left(\mathfrak{I}^*_{ij}(\tilde{\nu}_i, \nu^*_{i,-j})(X_i) \right)\\
        &=\sum_{i=1}^n \int_0^M \big( \tau_{i,j}(X_i>z) -\tilde{\nu}_i(X_i>z)\big)\tilde{\gamma}_{ij}(z)\,dz\,.
    \end{align*}
Hence, by \eqref{eq:target}, it suffices to show that
    \begin{align*}
        \sum_{i=1}^n\int_0^M \big( \tau_{i,j}(X_i>z) - \tilde{\nu}_i(X_i>z)\big)\tilde{\gamma}_{ij}(z)\,dz
            &\ge\sum_{i=1}^n\int_0^M \big( \tau_{i,j}(X_i>z) - \nu^*_{ij}(X_i>z)\big) \gamma^*_{ij}(z)\,dz\\
        &=\sum_{i=1}^n\int_0^M\min\{\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z),\,0\}\,dz.
    \end{align*}

Fix $i\in\cN$, and consider the following cases for different tail risks $X_i>z$.
    \begin{enumerate}
        \item $\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z)<0$:
            In this case, the reinsurer is fully profiting from indemnifying this tail risk when using the original strategy $\nu_{ij}^*$.
            If the reinsurer were to switch their strategy to $\tilde{\nu}_i$, we have the following:
            \begin{itemize}
                \item $\tilde{\nu}_i(X_i>z)>\bar{\tau}_i(X_i>z)$: In this case the reinsurer has increased the price for this tail risk. 
                However, by point (2) of Definition \ref{defn:beth}, there is another reinsurer charging the price $\bar{\tau}_i(X_i>z)$, so the new price $\tilde{\nu}_i(X_i>z)$ is no longer the lowest price in the market.
                This implies that $\tilde{\gamma}_{ij}=0$, and so
                    \[
                        \big( \tau_{i,j}(X_i>z) - \tilde{\nu}_i(X_i>z)\big)\tilde{\gamma}_{ij}(z)=0\ge\min\{\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z),\,0\}\,.
                    \]
                \item $\tilde{\nu}_i(X_i>z)<\bar{\tau}_i(X_i>z)$: In this case the reinsurer has decreased the price for this tail risk.
                By point (1) of Definition \ref{defn:beth}, this price $\tilde{\nu}_i(X_i>z)$ is now the unique lowest price for this tail risk, which implies $\tilde{\gamma}_{ij}(z)=1$. Hence,
                    \begin{align*}
                        \big( \tau_{i,j}(X_i>z)-\tilde{\nu}_i(X_i>z)\big)\tilde{\gamma}_{ij}(z)&=\tau_{i,j}(X_i>z)-\tilde{\nu}_i(X_i>z)\\
                        &\ge\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z)\\
                        &=\min\{\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z),\,0\}\,.
                    \end{align*}
                \item $\tilde{\nu}_i(X_i>z)=\bar{\tau}_i(X_i>z)$: In this case the reinsurer has not changed the price for this tail risk. Here, we have
                    \begin{align*}
                        \big( \tau_{i,j}(X_i>z)-\tilde{\nu}_i(X_i>z)\big)\tilde{\gamma}_{ij}(z)
                            &=\big( \tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z)\big)\tilde{\gamma}_{ij}(z)\\
                        &\ge\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z)\\
                        &=\min\{\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z),\,0\}\,.
                    \end{align*}
            \end{itemize}

        \item $\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z)\ge0$: In this case, the reinsurer is unable to profit from indemnifying this tail risk using the original strategy. In what follows, we show that it is not possible to profit on these tail risks regardless of the choice of pricing capacity.
            \begin{itemize}
                \item $\tilde{\nu}_i(X_i>z)>\bar{\tau}_i(X_i>z)$: Similar to case (1), increasing the price for this tail risk causes $\tilde{\gamma}_{ij}=0$, so
                    $
                    \big(\tau_{i,j}(X_i>z) - \tilde{\nu}_i(X_i>z)\big)\tilde{\gamma}_{ij}(z)=0=\min\{\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z),\,0\}\,.
                    $
                \item $\tilde{\nu}_i(X_i>z)\le\bar{\tau}_i(X_i>z)$: In this case the reinsurer has decreased the price for this tail risk, but since $\tilde{\nu}_i(X_i>z)\le\bar{\tau}_i(X_i>z)\le\tau_{i,j}(X_i>z)$, this price is now so low that a loss is incurred to reinsurer $j$. That is,
                    \[
                    \big(\tau_{i,j}(X_i>z) - \tilde{\nu}_i(X_i>z)\big)\tilde{\gamma}_{ij}(z)\ge 0=\min\{\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z),\,0\}\,.
                    \]
            \end{itemize}
    \end{enumerate}

    \noindent Hence, we have shown that for all $i\in\cN$, we have
        \[
            \big(\tau_{i,j}(X_i>z) - \tilde{\nu}_i(X_i>z)\big)\tilde{\gamma}_{ij}(z)\ge\min\{\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z),\,0\}\,.
        \]
    It then follows that
        \[
        \sum_{i=1}^n\int_0^M \big( \tau_{i,j}(X_i>z) - \tilde{\nu}_i(X_i>z)\big)\tilde{\gamma}_{ij}(z)\,dz
            \ge\sum_{i=1}^n\int_0^M\min\{\tau_{i,j}(X_i>z)-\bar{\tau}_i(X_i>z),\,0\}\,dz\\
        \]
    as desired, which completes the proof.\qed



