\subsection{Proof of Proposition \ref{prop:optimal_indemnities}}

We prove this characterization result for Pareto-optimal allocations using two steps.
Firstly, since preferences are translation invariant, Pareto optimality of an allocation is equivalent to minimizing the aggregate post-transfer risk, as shown by Lemma \ref{lem:po_minimize_risk} below.
It then follows that those allocations that minimize aggregate post-transfer risk are precisely those of the form given in the statement of Proposition \ref{prop:optimal_indemnities}.
To this end, we first show the following:

\medskip

\begin{lemma}
    \label{lem:po_minimize_risk}
    An allocation $\allocationstar\in\cI\times\mathbb{R}^{n\times m}$ is PO if and only if the following hold:
        \begin{enumerate}[label=(\roman*)]
            \item \label{lem:po_minimize_risk_1}
                The indemnity structure $\{I^*_{ij}\}_{i\in\cN,j\in\cM}$ is a solution to
        \begin{equation}\label{infPO}
                        \inf_{\{I_{ij}\}_{i\in\cN,j\in\cM}\in\cI}
                            \left\{\sum_{j=1}^m \rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)I_{ij}(X_i)\right)
                    +\sum_{i=1}^n \rho^{In}_i \left(X_i - \sum_{j=1}^m I_{ij}(X_i)\right)\right\}\,.
                    \end{equation}
            \item \label{lem:po_minimize_risk_2}
                The premia $\{\pi^*_{ij}\}_{i\in\cN,j\in\cM}$ are chosen such that $\allocationstar$ is IR.
        \end{enumerate}
\end{lemma}

\begin{proof}
    Let $\allocationstar$ be an allocation such that \ref{lem:po_minimize_risk_1} and \ref{lem:po_minimize_risk_2} hold, and assume for the sake of contradiction that this allocation is not PO.
    Then there exists another allocation $\allocationtilde$ such that
        \begin{align*}
            \rho^{In}_i\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i)+\sum_{j=1}^m\tilde{\pi}_{ij}\right)
                &\le\rho^{In}_i \left(X_i - \sum_{j=1}^m I^*_{ij}(X_i) +\sum_{j=1}^m\pi^*_{ij}\right)\quad\forall i\in\cN\,,\\
            \rho^{Re}_j\left(\sum_{i=1}^n\big((1+\theta_j)\tilde{I}_{ij}(X_i)-\tilde{\pi}_{ij}\big)\right)
                &\le\rho^{Re}_j\left(\sum_{i=1}^n\big((1+\theta_j) I^*_{ij}(X_i)-\pi^*_{ij}\big)\right)\quad\forall j\in\cM\,,
        \end{align*}
    with at least one strict inequality for some $i\in\cN$ or $j\in\cM$.
    Summing these inequalities gives
        \begin{align*}
            \sum_{j=1}^m\rho^{Re}_j&\left(\sum_{i=1}^n\big((1+\theta_j)\tilde{I}_{ij}(X_i)-\tilde{\pi}_{ij}\big)\right)
                +\sum_{i=1}^n\rho^{In}_i\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i)+\sum_{j=1}^m\tilde{\pi}_{ij}\right)\\
            &<\sum_{j=1}^m \rho^{Re}_j\left(\sum_{i=1}^n \big((1+\theta_j)I^*_{ij}(X_i) - \pi^*_{ij}\big)\right) + \sum_{i=1}^n \rho^{In}_i \left(X_i - \sum_{j=1}^mI^*_{ij}(X_i) +\sum_{j=1}^m\pi^*_{ij}\right)\,.
        \end{align*}

    \noindent Since each $\rho_i^{In}$ and $\rho_j^{Re}$ is translation invariant, the premia $\tilde{\pi}_{ij}$ and $\pi_{ij}^*$ all cancel out, which yields
        \begin{align*}
            \sum_{j=1}^m\rho^{Re}_j&\left(\sum_{i=1}^n(1+\theta_j)\tilde{I}_{ij}(X_i)\right)
                +\sum_{i=1}^n\rho^{In}_i\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i)\right)\\
            &<\sum_{j=1}^m\rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)I^*_{ij}(X_i)\right)+\sum_{i=1}^n\rho^{In}_i\left(X_i-\sum_{j=1}^mI^*_{ij}(X_i)\right)\,,
        \end{align*}
    contradicting \ref{lem:po_minimize_risk_1}. Hence, $\allocationstar$ must be PO.

    Conversely, suppose that $\allocationstar$ is PO.
    Since PO allocations are IR by definition, \ref{lem:po_minimize_risk_2} holds.
    Assume for the sake of contradiction that \ref{lem:po_minimize_risk_1} does not hold, so there exists an indemnity structure $\{\tilde{I}_{ij}\}_{i\in\cN,j\in\cM}\in\cI$ such that
        \begin{align*}
            \sum_{j=1}^m\rho^{Re}_j&\left(\sum_{i=1}^n(1+\theta_j)\tilde{I}_{ij}(X_i)\right)
                +\sum_{i=1}^n\rho^{In}_i\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i)\right)\\
            &<\sum_{j=1}^m\rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)I^*_{ij}(X_i)\right)+\sum_{i=1}^n\rho^{In}_i\left(X_i-\sum_{j=1}^mI^*_{ij}(X_i)\right)\,.
        \end{align*}

\noindent Let $\varepsilon>0$ denote the positive difference in the above inequality.
    That is,
        \begin{align*}
            \varepsilon&:=\sum_{j=1}^m\rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)I^*_{ij}(X_i)\right)
                +\sum_{i=1}^n\rho^{In}_i\left(X_i-\sum_{j=1}^mI^*_{ij}(X_i)\right)\\
            &\quad\quad-\sum_{j=1}^m\rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)\tilde{I}_{ij}(X_i)\right)
                -\sum_{i=1}^n\rho^{In}_i\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i)\right)\,.
        \end{align*}
    Define
        \begin{align*}
            a_i&:=\sum_{j=1}^m\pi_{ij}^*
                +\rho^{In}_i\left(X_i-\sum_{j=1}^mI_{ij}^*(X_i)\right)
                -\rho^{In}_i\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i)\right)
                \quad\forall i\in\cN\,,\\
            b_j&:=\sum_{i=1}^n\pi_{ij}^*
                +\rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)\tilde{I}_{ij}(X_i)\right)
                -\rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)I_{ij}^*(X_i)\right)
                +\frac{\varepsilon}{m}
                \quad\forall j\in\cM\,.
        \end{align*}

    \noindent It is straightforward to verify that
        \begin{align*}
            \sum_{i=1}^na_i&=
                \sum_{i=1}^n\sum_{j=1}^m\pi_{ij}^*
                +\sum_{i=1}^n\rho^{In}_i\left(X_i-\sum_{j=1}^mI_{ij}^*(X_i)\right)
                -\sum_{i=1}^n\rho^{In}_i\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i)\right)\\
            &=\sum_{j=1}^m\sum_{i=1}^n\pi_{ij}^*
                +\sum_{j=1}^m\rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)\tilde{I}_{ij}(X_i)\right)
                -\sum_{j=1}^m\rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)I^*_{ij}(X_i)\right)
                +\varepsilon\\
            &=\sum_{j=1}^mb_j\,.
        \end{align*}
    Now consider the following system of linear equations with variables $\{\pi_{ij}\}_{i\in\cN,j\in\cM}$:
        \begin{align*}
            \sum_{j=1}^m\pi_{ij}&=a_i\quad\forall i\in\cN\,,\\
            \sum_{i=1}^n\pi_{ij}&=b_j\quad\forall j\in\cM\,.
        \end{align*}
    This is a system of $n+m-1$ linearly independent equations and $n\times m$ variables.
    Since $\sum_{i=1}^na_i=\sum_{j=1}^mb_j$ and there at least as many variables as equations, there exists a solution $\{\tilde{\pi}_{ij}\}_{i\in\cN,j\in\cM}$ to this linear system.
    We now show that the allocation $\allocationtilde$ is a Pareto improvement over $\allocationstar$, providing the desired contradiction.
    Firstly, for each $i\in\cN$, we have
        \begin{align*}
            \rho^{In}_i&\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i)+\sum_{j=1}^m\tilde{\pi}_{ij}\right)\\
                &=\rho^{In}_i\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i)\right)
                    +a_i\\
                &=\rho^{In}_i\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i)\right)
                    +\sum_{j=1}^m\pi_{ij}^*
                    +\rho^{In}_i\left(X_i-\sum_{j=1}^mI_{ij}^*(X_i)\right)
                    -\rho^{In}_i\left(X_i-\sum_{j=1}^m\tilde{I}_{ij}(X_i)\right)\\
                &=\rho^{In}_i\left(X_i-\sum_{j=1}^mI_{ij}^*(X_i)+\sum_{j=1}^m\pi_{ij}^*\right)\,.
        \end{align*}
    Moreover, for each $j\in\cM$, we have
        \begin{align*}
            \rho^{Re}_j\left(\sum_{i=1}^n\big((1+\theta_j)\tilde{I}_{ij}(X_i)-\tilde{\pi}_{ij}\big)\right)
            &=\rho^{Re}_j\left(\sum_{i=1}^n\big((1+\theta_j)\tilde{I}_{ij}(X_i)\big)\right)
                    -b_j\\
                &=\rho^{Re}_j\left(\sum_{i=1}^n\big((1+\theta_j)\tilde{I}_{ij}(X_i)\big)\right)
                    -\sum_{i=1}^n\pi_{ij}^*
                    -\rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)\tilde{I}_{ij}(X_i)\right)\\
                &\quad\qquad+\rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)I_{ij}^*(X_i)\right)
                    -\frac{\varepsilon}{m}\\
                &<\rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)I_{ij}^*(X_i)\right)
                    -\sum_{i=1}^n\pi_{ij}^*\\
                &=\rho^{Re}_j\left(\sum_{i=1}^n\big((1+\theta_j) I^*_{ij}(X_i)-\pi^*_{ij}\big)\right)\,,
        \end{align*}

    \noindent where the inequality is strict since $\varepsilon>0$.
    It then follows that $\allocationstar$ is not Pareto optimal, a contradiction.
    Hence, if $\allocationstar$ is PO, then both \ref{lem:po_minimize_risk_1} and \ref{lem:po_minimize_risk_2} must hold.
\end{proof}

To complete the proof of Proposition \ref{prop:optimal_indemnities}, it suffices to show that an indemnity structure is a solution to \eqref{infPO} if and only if it satisfies condition \ref{prop:optimal_indemnities_1} of Proposition \ref{prop:optimal_indemnities}.
To this end, note that since either $\rho_j^{Re}$ is an expectation or the risks $X_1,\ldots,X_n$ are comonotone, we have that for each $j\in\cM$,
    \[
       \rho^{Re}_j\left(\sum_{i=1}^n(1+\theta_j)I_{ij}(X_i)\right)=\sum_{i=1}^n\rho^{Re}_j\left((1+\theta_j)I_{ij}(X_i)\right)\,.
    \]
Hence, the problem \eqref{infPO} is equivalent to
    \begin{equation}\label{infPO_simplified}
        \inf_{\{I_{ij}\}_{i\in\cN,j\in\cM}\in\cI}\left\{
           \sum_{i=1}^n\sum_{j=1}^m\rho^{Re}_j\left((1+\theta_j)I_{ij}(X_i)\right)
            -\sum_{i=1}^n\sum_{j=1}^m\rho^{In}_i \left( I_{ij}(X_i)\right)\right\}\,,
    \end{equation}
where the constant terms $\rho_i^{In}(X_i)$ have been omitted.
For each $i\in\cN$, define the set
    \[
        A_i:=\left\{\sum_{j=1}^m\rho^{Re}_j\left((1+\theta_j)I_{ij}(X_i)\right)
            -\sum_{j=1}^m\rho^{In}_i\left(I_{ij}(X_i)\right)
            \,\,\middle|\,\,
            \{I_{ij}\}_{j\in\cM}\in\cI_i\right\}\,.
    \]
Since $\cI=\prod_{i=1}^n\cI_i$, the optimization problem \eqref{infPO_simplified} simplifies to
    \begin{align*}
        \inf\left(\sum_{i=1}^nA_i\right)=\sum_{i=1}^n\inf A_i\,,
    \end{align*}
since the infimum commutes with the Minkowski sum.
The above decomposes the problem \eqref{infPO_simplified} into $n$ different minimization problems.
That is, $\{I_{ij}^*\}_{i\in\cN,j\in\cM}$ solves \eqref{infPO_simplified} if and only if for each $i\in\cN$, the indemnity structure $\{I_{ij}^*\}_{j\in\cM}\in\cI_i$ solves
    \begin{equation}\label{infPO_simplified_2}
        \inf_{\{I_{ij}\}_{j\in\cM}\in\cI_i}\left\{
           \sum_{j=1}^m\rho^{Re}_j\left((1+\theta_j)I_{ij}(X_i)\right)
            -\sum_{j=1}^m\rho^{In}_i \left( I_{ij}(X_i)\right)\right\}\,.
    \end{equation}
Note that for each insurer $i\in\cN$, problem \eqref{infPO_simplified_2} is precisely the problem of minimizing the aggregate risk of only those contracts involving insurer $i$.
Hence, problem \eqref{infPO_simplified_2} is related to the characterization of Pareto optima in a market with only one insurer.
The result of Proposition \ref{prop:optimal_indemnities} now follows through an application of \cite[Proposition 4.10]{zhu2023equilibria} to each insurer $i\in\cN$.\qed


