        G22 = g33_d[i,j,k,e]
        H0  = h1_d[i,j,k,e]
        r_ = rtmp_[e]
        s_ = stmp_[e]
        t_ = ttmp_[e]

        ur[i,j,k,e] += H0*(G00*r_ + G01*s_ + G02*t_)
        us[i,j,k,e] += H0*(G01*r_ + G11*s_ + G12*t_)
        ut[i,j,k,e] += H0*(G02*r_ + G12*s_ + G22*t_)


    for e,k2,j2,i2,l2 in dc.map[0:ne,0:lx,0:lx,0:lx,0:lx]:
        w[i2,j2,k2,e] += dxt[i2,l2] * ur[l2,j2,k2,e]
        w[i2,j2,k2,e] += dyt[j2,l2] * us[i2,l2,k2,e]
        w[i2,j2,k2,e] += dzt[k2,l2] * ut[i2,j2,l2,e]

    w_d[:] = w[:]
    \end{lstlisting}
\end{minipage}

