% The following result will be applied in the special setting of countable virtually abelian groups, but it seems worthwhile to state and prove it in greater generality.
% to show that no assumptions such as Type I or second countability are necessary. 

\begin{prop}\label{p:pi of mu_K}
Let $G$ be a locally compact group, let $K$ be a compact normal subgroup of~$G$, and let $\mu_K$ be the pushforward of Haar measure on $K$ along the inclusion map $K \hookrightarrow G$, normalized such that $\mu_K(K)=1$.

Let $\pi: G\to\cU(H_\pi)$ be an irreducible unitary representation, and let $I_\pi$ denote the identity operator on $H_\pi$. If $\pi$ factors through the quotient homomorphism $G\to G/K$, then $\pi(\mu_K)=I_\pi$; if not, then $\pi(\mu_K)=0$.
\end{prop}

\begin{proof}
Suppose that $\pi$ factors through the quotient homomorphism $q: G\to G/K$, i.e., $\pi(k)=I_{\pi}$ for every $k\in K$. Then, for arbitrary $\xi,\eta\in H_\pi$, we have
\[
\langle \pi(\mu_K)\xi,\eta\rangle=\int_G \langle \pi(x)\xi,\eta\rangle\, d\mu_K(x)=\int_K \langle \pi(x)\xi,\eta\rangle\, d\mu_K(x)=\langle \xi,\eta\rangle \int_K \, d\mu_K(x)=\langle \xi,\eta\rangle,
\]
and so $\pi(\mu_K)=I_\pi$. 

% Next, suppose $\pi:G\to {\cal U}(H_\pi)$ does not factor through $q$, i.e., there exists $k\in K$ with $\pi(k)\neq I_\pi$. It is easy to observe that $\mu_K$ is a self-adjoint idempotent. So, $\pi(\mu_K)$ is an orthogonal projection.

Now suppose that $\pi$ does not factor through~$q$.
For each $g\in G$, conjugation by $g$ is a continuous automorphism of $K$, so by uniqueness of normalized Haar measure on $K$ we see that $\delta_g * \mu_K * \delta_{g^{-1}}=\mu_K$. Hence, $\pi(g)\pi(\mu_K)\pi(g)^{-1}=\pi(\mu_K)$ for all $g\in G$, which implies by Schur's lemma that $\pi(\mu_K)=\lambda_\pi I_\pi$ for some $\lambda_\pi\in\Cplx$.
Since $\pi$ does not factor through $q$, there exists some $k\in K$ with $\pi(k)\neq I_\pi$. But since $\delta_k*\mu_K=\mu_K$, we have $\lambda_\pi \pi(k)=\lambda_\pi I_\pi$. This forces $\lambda_\pi=0$.
\end{proof}

We now specialize to cases where $G$ is second-countable, unimodular and Type I. 
Given such a group $G$ and a fixed choice of Haar measure on $G$, 
there exists a unique Radon measure $\nu$ on $\widehat{G}$ (the \dt{Plancherel measure} for $G$) that satisfies
\begin{equation}\label{eq:plancherel formula}
\norm{f}_2^2 = \int_{\widehat{G}} \Tr \left( \pi(f)^*\pi(f) \right) \;d\nu(\pi) \quad(f\in C_c(G)).
\end{equation}
%(For example: if $G$ is finite then so is $\widehat{G}$, and the Plancherel measure assigns mass $d_\pi |G|^{-1}$ to the atom $\{\pi\}$.)
Equation \eqref{eq:plancherel formula} is often referred to as the \dt{Plancherel formula} for $G$; 
for further context and referenes, see \cite[Section 8.5]{Deitmar-Echterhoff-book}, \cite[Theorem 7.36]{Folland-book} or \cite[Theorem 3.31]{Fuhr-book}.




\begin{rem}\label{r:LCVA implies Type I}
We will apply this machinery in the setting of countable virtually abelian groups. To justify this, we note that every virtually abelian group $G$ has a \emph{normal} abelian subgroup $M$ of finite index (this is a standard observation in group theory), and hence if we regard $G$ as a discrete group, it is Type I and satisfies $\maxdeg(G)\leq \lvert G\mathbin{:} M\rvert$ (see for example \cite[Satz 5]{Thoma-1968}). 

More generally: if $G$ is locally compact and virtually abelian, then taking an abelian subgroup $H_0\leq G$ that has finite index, the closure of $H_0$ in $G$ is an \emph{open} abelian subgroup of finite index; it then follows, using a version of Frobenius reciprocity, that $\maxdeg(G)<\infty$ (see \cite[Proposition 2.1]{Moore-fd-irrep} for a proof), which in particular implies that $G$ is Type~I. 
\end{rem}


%We continue to assume that $G$ is second-countable, unimodular and Type~I, and let $\nu$ be the Plancherel measure for $G$.
%In this section, 

The proof of Theorem \ref{t:sharper upper bound} (which is the key ingredient needed to prove our main new results) relies on the fact that when $G$ and $N$ are countable virtually abelian groups, one can express the norms on $\FA(G)$, $\FA(G)\ptp\FA(N)$ and $\FA(G\times N)$ in terms of the Fourier transforms for $G$ and~$N$. Since it is not immediate how to extract these known results from the literature, we shall give a precise statement below, and then provide further details/explanation in Appendix~\ref{app:norms via FT}.

In fact, since our approach goes via the Plancherel theorem for second-countable unimodular Type I groups, we shall state our results for this more general class of groups, in case this is useful for future work.
We need to introduce some more notation: let $(L^1\cap L^2)(G)$ denote the intersection of $L^1(G)$ and $L^2(G)$, and let
\begin{equation}\label{eq:the nice subspace}
\cV_2^G \defeq \operatorname{span} \{ \alpha_G(\xi\otimes\eta) \colon \xi,\eta\in (L^1\cap L^2)(G)
\end{equation}
(note that this the uncompleted linear span). Note that $\cV_2^G$ is a dense subspace of $\FA(G)$.

%Using these facts, we obtain explicit formulas for the $\FA(G)\ptp\FA(G)$-norm and the $\FA(G\times G)$-norm of a given element of $\FA(G)\otimes\FA(G)$. 


\begin{prop}\label{p:norms via FT}
Let $G$ and $N$ be second-countable unimodular Type I groups. Fix Haar measures on $G$ and $G$, and let $\nu_G$ and $\nu_N$ be the corresponding Plancherel measures on $\widehat{G}$ and $\widehat{N}$ respectively.
\begin{alphnum}
\item\label{li:AG-norm}
For every $f\in \cV_2^G$, we have
\begin{equation}\label{eq:A(G)-norm via plancherel}
\norm{f}_{\FA(G)} = \int_{\pi\in \widehat{G}} \norm{\pi(f)}_{S^1(\pi)} \; d\nu_G(\pi)
\end{equation}

\item\label{li:AG-tp-norm}
For every $w\in \cV_2^G \otimes \cV_2^N$, we have
\begin{equation}
\norm{w}_{\FA(G)\ptp\FA(N)}
 = \int_{\widehat{G}\times\widehat{N}} \norm{ (\pi\otimes \sigma)(w)}_{S^1(\pi)\ptp S^1(\sigma)} \;d(\nu_G\times\nu_N)(\pi,\sigma)
 \end{equation}

\item\label{li:AGN-norm}
For any $w\in \cV_2^{G\times N}$, we have
\begin{equation}
\norm{w}_{\FA(G\times N)}
 = \int_{\widehat{G}\times\widehat{N}} \norm{ (\pi\otimes \sigma)(w)}_{S^1(\pi\otimes\sigma)} \;d(\nu_G\times\nu_N)(\pi,\sigma) 
\end{equation}
\end{alphnum}
\end{prop}

\begin{rem}\label{r:scope}
We briefly comment on the scope of the results stated in Proposition \ref{p:norms via FT}.
\begin{alphnum}
\item
With more work, one can show that part \ref{li:AG-norm} remains valid for all $f\in \FA(G)\cap L^1(G)$, which would seem to be the natural space for this result. However, it seems that to do this rigorously, one has to address some delicate issues concerning the Fourier inversion formula; we have chosen to avoid dealing with these issues in this paper, since the space $\cV_2^G$ suffices for our needs. Similar comments apply to parts \ref{li:AG-tp-norm} and \ref{li:AGN-norm}.
\item
In fact, we will only apply Proposition \ref{p:norms via FT} when $G$ and  $N$ are countable (in particular, discrete). For such groups, note that each point mass $\delta_s$ arises as $\alpha_G(\delta_e\otimes\delta_s)$, and so by taking linear combinations we have $c_{00}(G)\subseteq \cV_2^G$. Then, upon tensoring, we have
\[
c_{00}(G\times N)= c_{00}(G)\tp C_{00}(N) \subseteq \cV_2^G\tp \cV_2^N \subseteq \cV_2^{G\times N}\;.
\]
Hence, in the intended applications, we can apply Proposition \ref{p:norms via FT} to any $f\in c_{00}(G)$ and any $w\in c_{00}(G\times N)$.
\end{alphnum}
\end{rem}




\section{General results for the amenability constant}
\label{s:soft results}
We start by honouring a promised made in the introduction: namely, we show how one proves a sharper upper bound on $\AM(\FA(G))$ when $G$ is finite.

Let $G$ be a finite group, and write $\cL$ for the set of $1$-dimensional representations of $G$. Using Johnson's formula \eqref{eq:johnson formula}, we have
\[
\begin{aligned}
\AM(\FA(G)) - 1  & = \frac{1}{|G|} \sum_{\pi\in \widehat{G}} (d_\pi)^3 -\frac{1}{|G|} \sum_{\pi\in \widehat{G}} (d_\pi)^2 \\
& = \frac{1}{|G|} \sum_{\pi\in \widehat{G} \setminus\cL} (d_\pi)^3-(d_\pi)^2 \\
& \leq \frac{\maxdeg(G)-1}{|G|} \sum_{\pi\in \widehat{G} \setminus\cL} (d_\pi)^2
& = \frac{\maxdeg(G)-1}{|G|} \left( |G|- |\cL| \right) \,.
\end{aligned}
\]
Let $[G,G]$ denote the commutator subgroup of $G$. Then $G/[G,G]$ is abelian and its Pontrjagin dual can be naturally identified with $\cL$.
In particular, $|\cL| = |G|\,|[G,G]|^{-1}$, and we thus obtain 
\[
\AM(\FA(G))
 \leq  1+ (\maxdeg(G)-1) \left( 1- \frac{1}{|[G,G]|}\right)  \,,
\]
which is precisely the inequality stated in \eqref{eq:finite group improved bound}. As we will see in Section \ref{s:prove upper bound}, the same inequality remains true for infinite discrete groups $G$, but our proof has to replace Johnson's formula with  abstract norm estimates in tensor products of Fourier algebras.



Next, we give proofs for some properties of $\AM(\FA(\cdot))$ that were stated in the introduction. It is convenient to isolate a common part of these proofs as a separate lemma.

\begin{lem}\label{l:AMAG is submult}
Let $G$ and $H$ be locally compact groups. Then
\[
\AM(G\times H)\leq \AM(G)\,\AM)(H).
\]
\end{lem}

\begin{proof}
There is a natural contractive homomorphism $\FA(G)\ptp\FA(H)\to \FA(G\times H)$, defined by sending an elementary tensor $f\otimes g$ to the function $(s,t)\mapsto f(s)g(t)$.
% This is stated without proof at the start of \cite[Section 3.6]{Kaniuth-Lau-book}
Therefore, by standard hereditary properties of $\AM$
(see e.g. \cite[Propositions 2.3.1 and 2.3.14]{Runde-newbook}), it follows that
\[ \AM(\FA(G\times H)) \leq \AM(\FA(G))\, \AM(\FA(GH)),
\]
as claimed.
\end{proof}

\begin{prop}\label{p:multiply by LCA}
Let $G$ and $H$ be locally compact groups with $H$ abelian.
Then $\AM(\FA(G))=\AM(\FA(G\times H))$.
\end{prop}

\begin{proof}
There is a contractive algebra homomorphism $\rho_G: \FA(G\times H) \to \FA(G)$, obtained by identifying $G$ with the subgroup $G\times\{e\}\subseteq G\times H$ and appealing to Herz's restriction theorem. Hence (by e.g.~\cite[Propositions 2.3.1]{Runde-newbook}) we have $\AM(G)\leq \AM(\FA(G\times H))$.

To prove the converse inequality, we note that since $H$ is abelian we have $\AM(\FA(H))=1$. (One can deduce this from results concerning operator space tensor products and operator amenability; alternatively, note that if $\Gamma$ denotes the Pontrjagin dual of $H$, then $\FA(H)$ is isometrically isomorphic to the convolution algebra $L^1(\Gamma)$, and $\AM(L^1(\Gamma))=1$ by \cite[Corollary 1.10]{Stokke-2004}.)
%\footnotetext{This fact was probably known to earlier authors; the results of \cite{Stokke-2004} apply much more generally, to all locally compact amenable groups.}
Therefore, Lemma \ref{l:AMAG is submult} gives $\AM(\FA(G\times H))\leq\AM(\FA(G))$.
The result now follows.
\end{proof}


\begin{prop}\label{p:taking products preserves conjecture}
Let $G_1,\dots, G_n$ be locally compact virtually abelian groups and let $G=\prod_{i=1}G_i$ (with the product topology). If $\AM(\FA(G_i))=\AD(G_i)$ for all $i$, then $\AM(\FA(G))=\AD(G)$.
\end{prop}

\begin{proof}
We give the proof for $n=2$; the general case follows by induction. 

Runde's lower bound already gives $\AM(\FA(G_1\times G_2))\geq \AD(G_1\times G_2)$, so it suffices to prove the converse inequality.
Since $G_1$ and $G_2$ satisfy Con\-jecture \ref{conj:main}, and since $\AD$ respects direct products,
\[
\AM(\FA(G_1))\,\AM(\FA(G_2)) = \AD(G_1)\, \AD(G_2) = \AD(G_1\times G_2).
\]
Therefore, since $\AM(\FA(\cdot))$ is submultiplicative (Lemma~\ref{l:AMAG is submult}, we have $\AM(\FA(G_1\times G_2))\leq \AD(G_1\times G_2)$, as required.
\end{proof}


We now show how one proves that when $G$ is discrete, there is always some countable subgroup $\Gamma\leq G$ such that $\AM(\FA(\Gamma))=\AM(\FA(G))$ (Theorem \ref{t:AMA-discrete-countable}).
The key idea is that since $G$ is discrete, we can write $\FA(G)$ as an inductive limit of Fourier algebras of countable subgroups of~$G$. Before spelling this out precisely, we review some general facts concerning amenability constants of inductive limits of Banach algebras.

%The following result is well known to specialists in the amenability of Banach algebras.
%; indeed, it was almost certainly known to Johnson when he wrote his original papers introducing amenability for Banach algebras.

\begin{lem}[{\cite[Proposition 2.3.15]{Runde-newbook}}]
\label{l:AM of inductive limit}
\previously{L2.5}
Let $A$ be a Banach algebra, let $(I,\preceq)$ be a directed set, and let $(A_i)_{i\in I}$ be a directed system of closed subalgebras of $A$.
If 
$A=\overline{\bigcup_{i\in I} A_i}$, then $\AM(A)\leq\sup_{i\in I}\AM(A_i)$. 
\end{lem}

Note that in this result we do not presuppose that $A$ is amenable. Indeed, in many applications, amenability of $A$ is shown to follow from the existence of a suitable ``exhaustion'' of $A$ by a family $(A_i)$ of amenable subalgebra with control on the amenability constant.

\begin{rem}\label{r:limsup}
\previously{R2.6}
Given a directed set $(I,\preceq)$ and a function $h: I\to \Real$, we write $\limsup_{i\in I} h(i)$ for $\inf_{i\in I} \sup_{i\preceq j} h(j)$. Since the union $\bigcup_{i\in I} A_i$ is unchanged if we replace $I$ by some cofinal subset $I'$, it follows that
%$\AM(A)\leq\limsup_{i\in I'} \AM(A_i)$.
$\AM(A)\leq\limsup_{i\in I} \AM(A_i)$.
\end{rem}

% To control the amenability constant of the Fourier algebra of a profinite group, we appeal to Lemma \ref{l:AM of inductive limit}. However, since the lemma only gives an upper bound on $\AM(A)$, it is natural to wonder if one can pass to smaller families of subalgebras and still retain the same upper bound. The next result gives a positive answer.

The previous lemma and remark are well known to specialists in the amenability of Banach algebras. However, the following refinement seems to be new.

\begin{prop}[Sequential control of the amenability constant of a direct limit]
\label{p:AM upper bound sequential}
\previously{P5.1}
Let $A$ be a Banach algebra. Let $(I,\preceq)$ be a directed set, and let $(A_i)_{i\in I}$ be a directed system of closed subalgebras of $A$, such that $A=\overline{\bigcup_{i\in I} A_i}$. Then there exists an increasing sequence $i(1)\preceq i(2) \preceq \dots$ such that $\AM(A) \leq\limsup_{n\geq 1} \AM(A_{i(n)})$.
\end{prop}

\begin{proof}
We first deal with the case where $\AM(A)<\infty$. By Lemma \ref{l:AM of inductive limit} we can choose $i(1)\in I$ such that $\AM(A_{i(1)}) \geq \AM(A) -2^{-1}$. Now suppose that $n\geq 1$ and we have chosen $i(n)$ such that $\AM(A_{i(n)}) \geq \AM(A)-2^{-n}$. Let $I_n = \{ j\in I \colon j\succeq i(n)\}$. Since $I_n$ is cofinal in $I$, we have $\bigcup_{j\in I_n}A_j = \bigcup_{i\in I} A_i$, so by using Lemma \ref{l:AM of inductive limit} again
% by Remark \ref{r:limsup} we have $\AM(A)\leq\sup_{i\in I_n} \AM(A_i)$,
we can choose $i(n+1)\succeq i(n)$ such that $\AM(A_{i(n+1)}) \geq \AM(A) - 2^{-(n+1)}$. Continuing by induction, we obtain an increasing sequence $i(1)\preceq i(2)\preceq\dots$ with the desired property.

If $\AM(A)=\infty$ (i.e. if $A$ is not amenable) then the argument is similar, except that our inductive hypothesis has the form $\AM(A_{i(n)}) \geq n$. (The key point is that Lemma \ref{l:AM of inductive limit} remains true if $\AM(A)=\infty$.)
\end{proof}

\begin{rem}\
\previously{R5.2}
In the previous result, two points seem worth highlighting.
\begin{alphnum}
\item  The conclusion does not imply that the bounded approximate diagonals for each $A_{i(n)}$ can be assembled to provide a bounded approximate diagonal for $A$ itself. For although $\bigcup_{n\geq 1} A_{i(n)}$ is a subalgebra of $A$, it need not be norm dense in~$A$. Indeed, if $A$ is not unital, then there could exist a non-zero $b\in A$ such that $a_nb=0=ba_n$ for all $a_n\in A_{i(n)}$.
\item Without further information or restrictions on the directed system $(A_i)_{i\in I}$, it does not seem possible to directly relate the amenability constant of $A_{i(n+1)}$ with that of $A_{i(n)}$. For certain nested inclusions of Fourier algebras, we can say more; this will be seen in the proof of Theorem \ref{t:AMA-discrete-countable} below.
\end{alphnum}
\end{rem}




% In certain settings, where one has more control over the approximating family of subalgebras, one can say more.


\begin{proof}[The proof of Theorem \ref{t:AMA-discrete-countable}]
Let $\cS$ be the set of countable subgroups of $G$. Each $f\in \FA(G)$ has countable support (since $f\in c_0(G)$ and $G$ is discrete), and hence belongs to $\iota_H(\FA(H))$ for some $H\in\cS$ (by Lemma \ref{l:embed and restrict}).
Thus $\FA(G)=\bigcup_{H\in\cS} \iota_H(\FA(H))$ (we do not need to take closures).

Moreover, $\cS$ is a directed set when ordered by inclusion, and $(\iota_H(\FA(H)))_{H\in \cS}$ is a directed system of closed subalgebras of~$\FA(G)$.



By Proposition \ref{p:AM upper bound sequential}, there is an increasing sequence $H_1 \leq H_2 \leq \dots$ in $\cS$ such that $\AM(\FA(G)) \leq \sup_n \AM(\FA(H_n))$.
Put $\Gamma=\bigcup_{n\geq 1} H_n \in \cS$. Since the restriction maps $\FA(G)\to\FA(\Gamma)$ and $\FA(\Gamma)\to\FA(H_n)$ are contractive  algebra homomorphisms, we have $\AM(\FA(G))\geq \AM(\FA(\Gamma))\geq \AM(\FA(H_n))$ for all $n$.
The result now follows.
\end{proof}

\begin{proof}[The proof of Corollary \ref{c:conjecture-discrete-countable}]
Suppose that there is a discrete counterexample to Conjecture~\ref{conj:main}, i.e.\ a discrete group $G$ such that $\AM(\FA(G))> \AD(G)$. By Theorem \ref{t:AMA-discrete-countable} there is a countable subgroup $\Gamma \leq G$ satisfying
$\AM(\FA(\Gamma)) = \AM(\FA(G)) > \AD(G)$.
Since $\Gamma\leq G$, we have $\AD(G)\geq\AD(\Gamma)$ by \cite[Proposition 2.9]{Choi-minorant}. Therefore $\Gamma$ is also a counterexample to Conjecture \ref{conj:main}.
\end{proof}




\section{A sharper upper bound for the amenability constant}\label{s:prove upper bound}

\subsection{The statement of our main upper bound}
%\subsection{First steps}


Our goal is to prove the following result.
\begin{thm}[A sharper upper bound for $\AM(\FA(G))$ in the discrete case]
\label{t:sharper upper bound}
Let $G$ be a discrete group that is virtually abelian.
Then
\[ \AM(\FA(G)) \leq 1+ (\maxdeg(G)-1) \left( 1- \frac{1}{|[G,G]|} \right).
\]
\end{thm}

To see where this upper bound comes from, we need to  consider the (standard) method for constructing bounded approximate diagonals for Fourier algebras of discrete groups.
Given a discrete group $G$, let $\Delta\defeq\{(s,s) \colon s\in G\}$ be the diagonal subgroup of $G\times G$.
If $u\in\FA(\Delta)$, then by Lemma \ref{l:embed and restrict} we may view $u$ as an element of $\FA(G\times G)$ that is supported inside $\Delta$, with the same norm. Moreover, since $\Delta\cong G$ we have an isometric algebra isomorphism $\FA(G)\cong\FA(\Delta)$.
%
We thus obtain an isometric algebra homomorphism $\FA(G)\to\FA(G\times G)$, which (by slight abuse of notation) we denote by $\iota_\Delta$. Explicitly, if $f\in\FA(G)$ then
\[
\iota_\Delta f(s,t)= \begin{cases} f(s) & \text{if $s=t$} \\ 0 & \text{otherwise.}
\end{cases}
\]

For any locally compact group $G$, there is a canonical contractive linear map
\[
J:\FA(G)\ptp\FA(G) \to \FA(G\times G),
\]
defined on elementary tensors by $J(a\tp b)(s,t) = a(s)b(t)$. If $G$ is also virtually abelian, then by \cite[Theorem 1]{Losert-tp-AG} $J$ is bijective, so that $J^{-1}:\FA(G\times G)\to \FA(G)\ptp\FA(G)$ is well-defined and continuous.
% Moreover, since $J$ is an $\FA(G)$-bimodule map, so is $J^{-1}$.

\begin{rem}
When $G$ is virtually abelian, \cite[Remark (a)]{Losert-tp-AG} provides the explicit upper bound.
An alternative proof of this estimate is given in \cite[Corollary ~2.6]{Runde-2006}, but it relies on the fact that $\FA(G\times G)$ coincides with the \emph{operator-space} projective tensor square of $\FA(G)$.
(Warning: in \cite{Runde-2006}, $\ptp$ denotes the operator-space projective tensor product, not the Banach-space projective tensor product.)
\end{rem}




\begin{lem}\label{l:AM via diagonal embedding}
Let $G$ be discrete and virtually abelian. Then $\AM(\FA(G))\leq \norm{J^{-1}\iota_\Delta}$.
\end{lem}

This result may be folklore (it was certainly known to the authors of \cite{Forrest-Runde-2005}). For the reader's convenience, we provide the details.

\begin{proof}[Proof of Lemma \ref{l:AM via diagonal embedding}]
We start by noting that $\iota_\Delta:\FA(G)\to\FA(G\times G)$ is an $\FA(G)$-bimodule map. In particular, since $\FA(G)$ is commutative, $a\cdot\iota_\Delta(f)=\iota_\Delta(f)\cdot a$ for all $a,f\in \FA(G)$.

Since $G$ is virtually abelian it is amenable, so by Leptin's theorem $\FA(G)$ has a bounded approximate identity of norm~$1$, $(f_\alpha)$~say. Put $m_\alpha = J^{-1}\iota_\Delta(f_\alpha) \in \FA(G)\ptp\FA(G)$.

Since $J$ is a bijective $A$-bimodule map, so is $J^{-1}$. Hence,
$a\cdot m_\alpha=m_\alpha\cdot a$ for all $a\in\FA(G)$.
Moreover, since $\Delta J^{-1}\iota_\Delta$ is just the identity map on $\FA(G)$, we have $\Delta(m_\alpha)=f_\alpha$.
Thus $(m_\alpha)$ is a bounded approximate diagonal for $\FA(G)$, with norm bounded by $\norm{J^{-1}\iota_\Delta}$.
%, and applying Proposition \ref{p:main bound} completes the proof of the Theorem.
\end{proof}

% Theorem \ref{t:sharper upper bound} will now follow by combining Lemma \ref{l:AM via diagonal embedding} with the following new estimate, which has some interest that is independent of the application to amenability constants.


\begin{prop}\label{p:bound on diagonal embedding}
Let $G$ be a discrete virtually abelian group. Then
\[
\norm{ J^{-1}\iota_\Delta: \FA(G) \to \FA(G)\ptp\FA(G)} \leq 1 + (\maxdeg(G)-1) \left( 1- \frac{1}{|[G,G]|}\right) ,
\]
with the convention that if $[G,G]$ is infinite then $| [G,G]|^{-1}=0$.
\end{prop}

Clearly, Theorem \ref{t:sharper upper bound} follows instantly from combining Lemma \ref{l:AM via diagonal embedding} with Proposition \ref{p:bound on diagonal embedding}, and so it only remains to prove the proposition.
%
This will be done in two stages. In the first stage, we perform a reduction step that allows us to restrict attention to \emph{countable} virtually abelian groups.
In the second stage, we use the Plancherel theorem for countable virtually abelian groups, and the accompanying formulas for the $\FA(G\times G)$-norm and $\FA(G)\ptp\FA(G)$-norm of a given function in terms of its matrix-valued Fourier coefficients.


\subsection{Reducing to the countable case}
To simplify calculations in this subsection, we introduce some notation. For a discrete group~$G$, define
\[ C_G \defeq 1+ (\maxdeg(G)-1) \left(1 - \frac{1}{|[G,G]|}\right) \in [1,\infty]. \]
This is the claimed upper bound on the norm of $J^{-1}\iota_\Delta : \FA(G)\to\FA(G)\ptp\FA(G)$.

% To prove Proposition \ref{p:bound on diagonal embedding}, it suffices to show that $\norm{J^{-1}\iota_\Delta(f)}_{\FA(G)\ptp\FA(G)} \leq C_G \norm{f}_{\FA(G)}$ for all $f\in c_{00}(G)$.



\begin{lem}\label{l:monotone}
Let $G$ be discrete and satisfy $\maxdeg(G)<\infty$. Then for every subgroup $L\leq G$, we have
\begin{alphnum}
\item\label{li:monotone maxdeg}
 $\maxdeg(L)\leq\maxdeg(G)$;
\item\label{li:monotone upper bound}
 $C_L\leq C_G$.
\end{alphnum}
\end{lem}

\begin{proof}
Part \ref{li:monotone maxdeg} appears to be folklore; a proof can be given by following the arguments used in the proof of \cite[Proposition 3.1]{Moore-fd-irrep}.
For the reader's convenience, we have included details in the appendix.

Combining part \ref{li:monotone maxdeg} with the trivial inequality $|[L,L]| \leq | [G,G]|$ yields
\[
\begin{aligned}
C_L-1
& = (\maxdeg(L)-1) \left( 1- \frac{1}{|[L,L]|}\right) \\
& \leq (\maxdeg(G)-1) \left( 1- \frac{1}{|[G,G]|}\right) 
= C_G -1\,,
\end{aligned}
\]
which proves part \ref{li:monotone upper bound}.
\end{proof}

\begin{lem}\label{l:commuting diagram}
Let $G$ be any discrete group and $H\leq G$ any subgroup; let $\iota_H:\FA(H)\to\FA(G)$ be the canonical embedding. Then the following diagram
commutes.
\[
\begin{tikzcd}
	{\FA(G)} && {\FA(G\times G)} && {\FA(G)\ptp \FA(G)} \\
	{} \\
	{\FA(H)} && {\FA(H\times H)} && {\FA(H)\ptp \FA(H)}
	\arrow["{\iota_\Delta}", from=1-1, to=1-3]
	\arrow["J"', from=1-5, to=1-3]
	\arrow["{\iota_H}", from=3-1, to=1-1]
	\arrow["{\iota_\Delta}"', from=3-1, to=3-3]
	\arrow["{\iota_{H\times H}}"', from=3-3, to=1-3]
	\arrow["{\iota_H \ptp\iota_H}"', from=3-5, to=1-5]
	\arrow["J", from=3-5, to=3-3]
        \end{tikzcd}\]
\end{lem}

\begin{proof}
Since
\[
J(\iota_H\ptp\iota_H)(\delta_s\tp \delta_t) = \delta_{(s,t)}=\iota_{H\times H}J(\delta_s\tp\delta_t)
\quad\text{for all $s,t\in H$,}
\]
it follows by linearity and continuity that $J(\iota_H\ptp\iota_H)=\iota_{H\times H}J$. Thus the right-hand square commutes.
A similar argument shows that the left-hand square commutes (alternatively, use the characterization of the ranges of $\iota_{H}$ and $\iota_{H\times H}$ given in Lemma \ref{l:embed and restrict}).
\end{proof}

\begin{proof}[Reduction of Proposition \ref{p:bound on diagonal embedding} to the countable case]
Suppose that for every countable virtually abelian group $H$, we have $\norm{J^{-1}\iota_\Delta: \FA(H)\to \FA(H)\ptp\FA(H)} \leq C_H$.

Now let $G$ be a discrete virtually abelian group; recall that this implies $\maxdeg(G)<\infty$ (Remark \ref{r:LCVA implies Type I}). Moreover, since $\FA(G)\subseteq c_0(G)$ and $G$ is discrete, every element of $\FA(G)$ has countable support.
Choose a sequence $(f_n)$ in $\FA(G)$ such that
\[
\norm{f_n} = 1 \text{ and } \norm{J^{-1}\iota_\Delta(f_n)}\geq \norm{J^{-1}\iota_\Delta :\FA(G)\to\FA(G)\ptp\FA(G)} - 2^{-n} \text{ for all $n$.}
\]
Let $L$ be the subgroup of $G$ generated by $\bigcup_n \supp(f_n)$. Then  $L$ is countable,  and it is virtually abelian (since $G$ is). By Lemma \ref{l:embed and restrict}, $f_n$ can be viewed as a norm-$1$ element of $\FA(L)$. Then, by Lemma \ref{l:commuting diagram}, we have
\[ \norm{ J^{-1}\iota_\Delta(f_n)}_{\FA(G)\ptp\FA(G)} \leq
\norm{ J^{-1}\iota_\Delta(f_n)}_{\FA(L)\ptp\FA(L)} \leq C_L \,, \]
with the final inequality holding because of our starting assumption. Taking the supremum over all $n$ and using Lemma \ref{l:monotone}\ref{li:monotone upper bound} gives
\[
\norm{ J^{-1}\iota_\Delta :\FA(G) \to  \FA(G)\ptp\FA(G)} \leq C_L\leq C_G\,,
\]
as required.
\end{proof}

