This ``reduction to the countable case'' is done mostly for technical convenience: it allows us to invoke results from non-abelian Fourier analysis that are usually stated for 2nd-countable unimodular Type I groups, without needing to discuss versions of the Plancherel theorem for uncountable discrete virtually abelian groups. However, we believe that the techniques used in this reduction step have some independent interest.
In any case, the main examples to which we will apply Theorem \ref{t:sharper upper bound} are countable.
% Moreover, it turns out that to prove Conjecture \ref{conj:main} for discrete groups, it would suffice to do so for countable groups (see Theorem \ref{t:countable subgroups suffice}).

\subsection{The proof of Proposition \ref{p:bound on diagonal embedding} for countable groups}
Recall that discrete virtually abelian groups are Type~I (see Remark \ref{r:LCVA implies Type I}).

Throughout this subsection, we adopt the following conventions \textbf{unless explicitly stated otherwise}: $G$~denotes a countable virtually abelian group; $\nu$ denotes Plancherel measure on~$\widehat{G}$, normalized so that $1= \int_{\widehat{G}} d_\pi \,d\nu(\pi)$; $\Omega$ denotes the set of $1$-dimensional representations of~$G$; and we write $d$ for $\maxdeg(G)$.
% Note that a discrete group is type I precisely when it is virtually abelian \cite[Theorem 7.8]{Folland-book}, so discrete virtually abelian groups are guaranteed to have a Plancherel measure as described in \cite[Theorem 7.44]{Folland-book}.

As in \cite{Runde-2006}, a key role is played by the following estimate, which is purely finite-dimensional in nature.
For a proof, see {\cite[Lemma]{Losert-tp-AG}} or \cite[Lemma~3.6.1]{Kaniuth-Lau-book}.

\begin{lem}\label{l:tp trace-class}
Given $d\in\Nat$, let $S^1(\Cplx^d)$ denote the space of trace-class matrices on $\Cplx^d$, equipped with the Schatten-$1$ norm. Then for any $m,n\in\Nat$, the natural map $J_{m,n}:S^1(\Cplx^m)\ptp S^1(\Cplx^n)\to S^1(\Cplx^{mn})$ satisfies $\norm{(J_{m,n})^{-1}} = \min(m,n)$.
\end{lem}

(Strictly speaking, the statement of \cite[Lemma]{Losert-tp-AG} concerns the adjoint map $\Phi_{m,n}=(J_{m,n})^\ast$, but it is a standard fact that the norm of a linear map between Banach spaces is equal to the norm of the adjoint map between the duals of these spaces.)


%The starting point for our approach is to make a more careful estimate of the norm of $J^{-1}: \FA(G\times G)\to \FA(G)\ptp\FA(G)$, using Proposition \ref{p:norms via FT}.
To simplify the formulas in the following calculations, define a function $\Psi: c_{00}(G\times G)\to [0,\infty)$  by
\begin{equation}\label{eq:auxiliary}
\Psi(u) \defeq \int_{\chi\in\Omega} \int_{\sigma\in\widehat{G}} \norm{ (\chi\otimes\sigma)(u)}_{S^1(\sigma)} \,d\nu(\sigma)\,d\nu(\chi)\,.
\end{equation}

\begin{rem}\label{r:absorb}
The notation in Equation \eqref{eq:auxiliary} may require some explanation. If $H_\chi$ and $H_\sigma$ are the Hilbert spaces on which we represent $\chi$ and $\sigma$, then  $(\chi\otimes\sigma)(u)$ is an operator on the Hilbert space $H_\chi\otimes^2 H_\sigma$. But since $H_\chi$ is one-dimensional, $H_\chi\otimes^2 H_\sigma$ may be identified isometrically with~$H_\sigma$. Moreover, using the same convention for Schatten-classes as in Equation \eqref{eq:A(G)-norm via plancherel}, we have \emph{isometric} identifications
$S^1(\chi\otimes\sigma) = S^1(\sigma) = S^1(\chi)\ptp S^1(\sigma)$.
\end{rem}

\begin{lem}\label{l:small saving}
Let $u\in c_{00}(G\times G)\subseteq \FA(G\times G)$. Then
\[
\norm{J^{-1}u}_{\FA(G)\ptp\FA(G)} \leq d\norm{u}_{\FA(G\times G)} - (d-1) \Psi(u).
\]
\end{lem}

\begin{proof}
We use the formulas in Proposition \ref{p:norms via FT} (see Remark \ref{r:scope} for why these formulas are valid for elements of $c_{00}(G\times G)$).

Using Fubini's theorem to write $\int_{\widehat{G}\times\widehat{G}}$ as an iterated integral, and then splitting $\int_{\widehat{G}} \int_{\widehat{G}} = \int_{\Omega}\int_{\widehat{G}} + \int_{\widehat{G}\setminus\Omega}\int_{\widehat{G}}$, we obtain
\[
\norm{u}_{\FA(G\times G)}  = \Psi(u) + \int_{\pi\in\widehat{G}\setminus\Omega} \int_{\sigma\in\widehat{G}} \norm{ (\pi\otimes\sigma)(u)}_{S^1(\pi \otimes\sigma)} \,d\nu(\sigma)\,d\nu(\pi)\;,
\]
and
\[
\norm{J^{-1}u}_{\FA(G)\ptp\FA(G)}  = \Psi(u) + \int_{\pi\in\widehat{G}\setminus\Omega} \int_{\sigma\in\widehat{G}} \norm{ (\pi\otimes\sigma)(u)}_{S^1(\pi)\ptp S^1(\sigma)} \,d\nu(\sigma)\,d\nu(\pi)\;.
\]
Applying Lemma \ref{l:tp trace-class} to the second term in each equation, we deduce that
\[
\norm{J^{-1}u}_{\FA(G)\ptp\FA(G)}  - \Psi(u)
\leq d\left( \norm{u}_{\FA(G\times G)}  - \Psi(u)\right),
\]
and rearranging gives the desired result.
\end{proof}

% Lemma \ref{l:small saving} is only useful if one can obtain a good lower bound on $\Psi(u)$ when $u$ is supported inside $\Delta$. The next lemma provide something stronger, namely the exact value of $\Psi(u)$ in such cases.


\begin{lem}\label{l:key trick}
Let $f\in c_{00}(G)$. Then $\Psi(\iota_\Delta(f)) = \nu(\Omega)\ \norm{f}_{\FA(G)}$.
\end{lem}



\begin{proof}
By definition,
\[
\Psi(\iota_\Delta(f)) = \int_{\chi\in\Omega} \int_{\sigma\in\widehat{G}} \norm{ (\chi\otimes\sigma)(\iota_\Delta(f))}_{S^1(\sigma)} \,d\nu(\sigma)\,d\nu(\chi)\;.
\]
But for each $\sigma\in \widehat{G}$ and each $\chi\in\Omega$, we have
\[
(\chi\otimes\sigma)(\iota_\Delta(f)) = \sum_{s,t\in G} \iota_\Delta(f)(s,t) \chi(s)\sigma(t) = \sum_{t\in G} f(t)\chi(t) \sigma(t) = \sigma(f\chi)\;,
\]
and so
\[ 
\Psi(\iota_\Delta(f))
 =\int_{\chi\in\Omega} \int_{\sigma\in\widehat{G}} \norm{ \sigma(f\chi))}_{S^1(\sigma)} \,d\nu(\sigma)\,d\nu(\chi) 
\\
 =\int_{\chi\in\Omega} \norm{  f\chi }_{\FA(G)}\;d\nu(\chi)\;,
\]
where we used Proposition \ref{p:norms via FT}\ref{li:AG-norm} on the inner integral.

We now recall a general result about Fourier algebras (valid for all locally compact groups). Let $\FS(G)$ denote the Fourier--Stieltjes algebra of $G$: then for each $f\in\FA(G)$ and $h\in \FS(G)$ we have $\norm{fh}_{\FA(G)}\leq \norm{f}_{\FA(G)}\norm{h}_{\FS(G)}$. Applying this with $h=\chi$ and $h=\overline{\chi}$, for some given $\chi\in\Omega$, yields
\[
\norm{f\chi}_{\FA(G)}\leq \norm{f}_{\FA(G)} = \norm{f\chi\overline{\chi}}_{\FA(G)} \leq \norm{f\chi}_{\FA(G)}\;.
\]
Thus, for each $\chi\in\Omega$, multiplication by $\chi$ acts as an \emph{isometry} on $\FA(G)$. Hence
\[
\Psi(\iota_\Delta(f))
=\int_{\chi\in\Omega} \norm{  f }_{\FA(G)}\;d\nu(\chi) = \nu(\Omega)\ \norm{f}_{\FA(G)}\,,
\]
as required.
\end{proof}



Our final ingredient, which explains the presence of $|[G,G]|$ in Proposition \ref{p:bound on diagonal embedding}, has nothing to do with amenability constants or Fourier algebras. We suspect that it is not a new result.

\begin{prop}[The Plancherel measure of the set of 1-dimensional representations]\label{p:nu(Omega) and [G,G]}
\
\begin{alphnum}
\item\label{li:[G,G] infinite}
If $[G,G]$ is infinite, then $\nu(\Omega)=0$.
\item\label{li:[G,G] finite}
If $[G,G]$ is finite, then $\nu(\Omega) = |[G,G]|^{-1}$.
\end{alphnum}
\end{prop}

% Since we do not know any convenient explicit reference, we provide a full proof, using Proposition \ref{p:pi of mu_K}.

\begin{proof}
%[Proof of Proposition \ref{p:nu(Omega) and [G,G]}]
Part \ref{li:[G,G] infinite} was proved in \cite[Lemma 5.1]{Choi-minorant}, so we only need to prove part \ref{li:[G,G] finite}.
Suppose that $[G,G]$ is finite, and define $h\in c_{00}(G)$ by
\[
h(t) = \begin{cases}
|[G,G]|^{-1} & \text{if $t\in [G,G]$,} \\
0 & \text{otherwise.}
\end{cases}
\]
Taking $K=[G,G]$ in Proposition \ref{p:pi of mu_K}, the measure $\mu_K$ corresponds to the function $h$ defined above, while the set of $\pi\in\widehat{G}$ that factor through $G \to G / [G,G]$ is exactly the set $\Omega$. We thus obtain $\chi(h) = 1$ for all $\chi\in\Omega$ and $\pi(h)=0$ for all $\pi\in\widehat{G}\setminus\Omega$.
Applying Equation \eqref{eq:plancherel formula} (the Plancherel formula) now gives
\[
\frac{1}{|[G,G]|} = \norm{h}_2^2
= \int_{\widehat{G}} \Tr(\pi(h)\pi(h)^\ast) \,d\nu(\pi) = \int_{\Omega} |\chi(h)|^2\,d\nu(\chi) = \nu(\Omega),
\]
as required.
\end{proof}

\begin{rem}
It was already shown in \cite[Section~4]{Choi-minorant} that $|[G,G]|=2 \iff \nu(\Omega)=1/2$, and this played a crucial role in characterizing those non-abelian groups $G$ on which $\AD$ is minimized.
%(See Lemma 4.2(i) and Proposition 4.3 of that paper.)
However, the methods used in that paper do not seem to generalize to larger values of $|[G,G]|$.
\end{rem}

\begin{proof}[The proof of Proposition \ref{p:bound on diagonal embedding} for countable virtually abelian groups]
Let $f\in c_{00}(G)$.
Combining Lemmas \ref{l:small saving} and \ref{l:key trick}, and recalling that $\norm{\iota_\Delta(f)}_{\FA(G\times G)} = \norm{f}_{\FA(G)}$,
 we obtain
\begin{equation}\label{eq:stepping stone}
\norm{J^{-1}\iota_\Delta(f)} \leq d\norm{f}_{\FA(G)} - (d-1)\nu(\Omega)\norm{f}_{\FA(G)}\;.
\tag{$\ast$}
\end{equation}
Since $c_{00}(G)$ is dense in $\FA(G)$, we deduce that
\[ \norm{J^{-1}\iota_\Delta} \leq d -(d-1)\nu(\Omega) = 1+ (d-1)(1-\nu(\Omega)) . \]
Applying Proposition~\ref{p:nu(Omega) and [G,G]} completes the proof.
\end{proof}





\subsection{Applications to discrete groups with two degrees of irreps}\label{s:applications}

\begin{proof}[Proof of Theorem \ref{t:two degrees}]
\previously{SS4.1}
Let $G$ be a countable non-abelian group, let $d\in\Nat$, and suppose that $\{ d_\pi \colon \pi\in\widehat{G}\} = \{1,d\}$. (This implies, in particular, that $G$ is virtually abelian.) From Theorem~\ref{t:sharper upper bound} we have
\begin{equation}\label{eq:two degrees upper bound}
\AM(\FA(G)) \leq 1 + (d-1)\left( 1- \frac{1}{|[G,G]|}\right).
\tag{$*$}
\end{equation}
We now seek a matching lower bound on $\AD(G)$.
%, we use the formula from \cite{Choi-minorant}.
Let $\Omega=\{ \pi\in\widehat{G}\colon d_\pi=1\}$, so that $d_\sigma=d$ for all $\sigma\in\widehat{G}\setminus\Omega$. Let $\nu$ be the Plancherel measure for $G$, normalized so that
\[
1 = \int_{\widehat{G}} d_\pi\,d\nu(\pi) = \nu(\Omega) + d\ \nu(\widehat{G}\setminus\Omega).
\]
Then, by \cite[Theorem 1.5]{Choi-minorant},
\[ \begin{aligned}
\AD(G) = \int_{\widehat{G}} (d_\pi)^2\,d\nu(\pi) 
& = \nu(\Omega) + d^2\nu(\widehat{G}\setminus\Omega) \\
& = \nu(\Omega) + d ( 1- \nu(\Omega)) = 1 + (d-1)(1-\nu(\Omega)).
\end{aligned} \]
Combining this with Proposition \ref{p:nu(Omega) and [G,G]} yields
\begin{equation}\label{eq:two degrees lower bound}
\AD(G) = 1 + (d-1)\left( 1- \frac{1}{|[G,G]|}\right).
\tag{$**$}
\end{equation}
Since $\AM(\FA(G))\geq \AD(G)$, we deduce from \eqref{eq:two degrees upper bound} and \eqref{eq:two degrees lower bound} that
\[
\AM(\FA(G)) = \AD(G) = 1 + (d-1)\left( 1- \frac{1}{|[G,G]|}\right),
\]
as required.
\end{proof}


Our second application is to discrete groups $G$ for which $|G\mathbin{:}Z(G)|=4$. For context, we recall that the statememt of Theorem\ref{t:minimal AM(A(non-abelian))} included some results that were already proved in \cite{Choi-minorant}. Namely, given a locally compact non-abelian group $G$, we always have $\AM(\FA(G))\geq \AD(G)\geq 3/2$, and the second inequality is an equality precisely when $|G\mathbin{:}Z(G)|=4$.

\begin{proof}[The proof of Theorem \ref{t:minimal AM(A(non-abelian))}\ref{li:partial converse}]
Let $G$ be discrete and satisfy $|G\mathbin{:}Z(G)|=4$. In particular, $G$ is non-abelian, so as remarked above, \cite[Theorem 1.6]{Choi-minorant} implies that $\AM(\FA(G))\geq 3/2$. We need to prove the converse inequality.

It is folklore that if $|G\mathbin{:}Z(G)|=4$ then $|[G,G]|=2$ and that each $\pi\in\widehat{G}$ satisfies
%$d_\pi=2$.
$d_\pi\in\{1,2\}$.(For details, see the proof of \cite[Theorem 4.6]{Choi-minorant} and combine it with \cite[Lemma 4.2(i)]{Choi-minorant}.)
%
Substituting these values into Theorem \ref{t:sharper upper bound} gives $\AM(\FA(G)) \leq 3/2$, as required.
\end{proof}


\section{New examples of groups satisfying the main conjecture}\label{s:p-reduced Heis}
Given a ring $S$ (assumed to be unital and commutative), we define
\begin{equation}
\sH(S) \defeq \left\{ \utmat{x}{z}{y} \colon x,y,z\in S\right\}
\end{equation}
which forms a group with respect to matrix multiplication. We refer to $\sH(S)$ as the \dt{Heisenberg group over $S$}, or the $S$-Heisenberg group. It is convenient to view elements of $\sH(S)$ as ordered triples $(x,y,z)$, with the group multiplication given by the formula
\begin{equation}\label{eq:heisenberg law}
(x,y,z)(x',y',z') \defeq (x+x', y+y', z+xy'+z')
\end{equation}
and we will adopt this notation going forwards.

\begin{rem}\label{r:Heisenberg as semidirect}
For studying the representation theory of $\sH(S)$, it is useful to observe that it decomposes as an internal semidirect product, with the subgroup $\{(x,0,0)\colon x\in S\}$ acting on the normal abelian subgroup $\{(0,y,z)\colon y\in S\}$ by conjugation:
\[
(x,0,0)(0,y,z)(x,0,0)^{-1} = (x,0,0)(0,y,z)(-x,0,0) = (x,0,0)(-x,y,z) = (0,y,xy+z).
\]
We denote this decomposition by $\sH(S)\cong S\ltimes (S\oplus S)$.
\end{rem}

The following facts are easily verified:
\begin{itemize}
\item the function $(x,y,z)\mapsto (x,y)$ is a group homomorphism from $\sH(S)$ onto the additive group of $S\oplus S$; 
\item the subgroup $\{(0,0,z)\colon S\}$ is contained in the centre of $\sH(S)$, and is isomorphic to $(S,+)$.
\end{itemize}

\begin{dfn}\label{d:p-reduced Heisenberg}
Let $p$ be prime, and assume that $p$ (when viewed as $\overbrace{1_S+\dots + 1_S}^{p} \in S)$ is not invertible in~$S$. We define $\Hpred(S)$ to be the quotient of $\sH(S)$ by the (central) subgroup $\{ (0,ps,0) \colon s\in S\}$.
\end{dfn}

Note that the condition $p\notin S^\times$ is satisfied in each of the following cases: $S=\bbZ$ (the usual ring of integers); or $S=\Zadic{p}$, the ring of $p$-adic integers.


\begin{rem}\label{r:reduced Heisenberg}
The group $\sH(\Real)$ has centre isomorphic to $(\Real,+)$, and quotienting by a central copy of $\bbZ$ gives a Lie group, the so-called (real) \dt{reduced Heisenberg group}, which turns up naturally in connection with Gabor time-frequency analysis. The groups $\Hpred(S)$ may be thought of as a discretized analogue of the ``true'' reduced Heisenberg group.
\end{rem}

Let us establish some general properties of $\Hpred(S)$, so that certain aspects of the cases $S=\bbZ$ and $S=\Zadic{p}$ can be treated simultaneously.
We may identify $\Hpred(S)$ as a set with $S\times S\times (S/pS)$ and denote its elements by $(x,y,[z])$, with $[z]$ denoting the image of $z$ in $S/pS$. With this convention, we have
\[
(1,0,[0])(0,1,[0]) = (1,1,[1]) \text{ and } (0,1,[0])(1,0,[0])=(1,1,[0]),
\]
showing that $\Hpred(S)$ is non-abelian. Note also that the semi-direct product decomposition $\sH(S)\cong S\ltimes (S\oplus S)$ from Remark \ref{r:Heisenberg as semidirect} induces a semi-direct product decomposition $\Hpred(S)\cong S\ltimes (S\oplus S/pS)$.

% For this section, $S$ will either be $\bbZ$, $\Zadic{p}$, or $\bbZ/p^n\bbZ$ for some $n\in\Nat$.


\begin{prop}\label{p:not finite times anything}
Assume that $S$ has characteristic zero, and suppose $p$ is a prime that is not invertible in~$S$. If there exist groups $B$ and $C$ with $B$ finite, such that $\Hpred(S)\cong B\times C$, then $B$ is trivial.
\end{prop}

\begin{proof}
For this proof, we put $G=\Hpred(S)$ and $K=\{(0,0,[s]) \colon s\in S\}\subset G$, to reduce notational clutter. Observe that if $F$ is any finite subgroup of $G$, then $F\subseteq K$ (because $G/K \cong S\oplus S$ is torsion-free); since $K$ is cyclic of order~$p$, it follows that $F$ is either trivial or all of~$K$.

Now suppose that $G\cong B\times C$ for some groups $B$ and $C$ where $B$ is finite and non-trivial; we will derive a contradiction. The previous paragraph implies that the given isomorphism $B\times C \to G$ maps $B\times\{1_C\}$ bijectively onto~$K$. Hence, $C\cong G/K \cong S\oplus S$, which is abelian. Since $B\cong K$ is also abelian, we conclude that $G$ is abelian, which is not the case.
\end{proof}


\begin{proof}[The proof of Theorem \ref{t:new examples}, part~\ref{li:p-reduced integer Heis}]
The unitary representations of $\Hpred(\bbZ)$ can be worked out using the Mackey machine (see \cite[Section 6.8.2]{Folland-book} for a detailed explanation). In particular, if $\pi\in \widehat{\Hpred(\bbZ)}$ then $d_\pi \in\{1,p\}$.
Moreover, a straightforward calculation shows that the commutator subgroup of $\Hpred(\bbZ)$ has order~$p$. Applying Theorem \ref{t:two degrees}, we deduce that
\[ \AM(\FA(\Hpred(\bbZ)))= \AD(\Hpred(\bbZ)) = p - 1 + \frac{1}{p}\,, \]
as claimed.
\end{proof}

% The rest of this section is devoted to explaining how one obtains the same conclusion if the discrete group $\Hpred(\bbZ)$ is replaced by the compact group $\Hpred(\Zadic{p})$, where $\Zadic{p}$ denotes the ring of $p$-adic integers.

We now turn to the proof of the corresponding statement for $\Hpred(\Zadic{p})$. This group is compact, so we cannot apply Theorem \ref{t:two degrees}. Instead, our leverage comes from the fact that this group is profinite.
%
We summarize some general properties of Fourier algebras of profinite groups that will be needed; they all seem to be folklore. A convenient reference for the basic facts concerning profinite groups and their natural compact topologies is \cite[Section 1.1]{Ribes-Zalesskii-book}.


\begin{prop}\label{p:A(profinite)}
\previously{P4.4}
Let $(I,\preceq)$ be a directed set and let $(G_i)_{i\in I}$ be an inverse system of finite groups. Let $G=\varprojlim_{i\in I} G_i$ equipped with is natural compact topology. Write $Q_i:G\to G_i$ for the canonical projection, and let $Q_i^*:C(G_i) \to C(G)$ be the algebra homomorphism induced by composition with $Q_i$.
Then
\begin{alphnum}
\item\label{li:subalgebra}
 for each $i\in I$, $Q_i^*$ maps $\FA(G_i)$ isometrically onto a norm-closed subalgebra of $\FA(G)$;
\item\label{li:exhaustion}
 $\bigcup_{i\in I} Q_i^*(\FA(G_i))$ is norm-dense in $\FA(G)$;
\item\label{li:upper bound}
$\AM(\FA(G)) \leq \sup_{i\in I} \AM(\FA(G_i))$.
\end{alphnum}
\end{prop}


%We note that a compact group $G$ is topologically isomorphic to an inverse limit of finite groups if and only if it is totally disconnected.




\begin{proof}
Part \ref{li:subalgebra} is a special case of general results concerning homomorphisms between locally compact groups and the maps that these induce between the respective Fourier(--Stieltjes) algebras. See e.g. \cite[Corollary 2.2.4]{Kaniuth-Lau-book} or \cite[Proposition~2.4.2]{Kaniuth-Lau-book}.

Since we could not find an explicit and self-contained reference for part \ref{li:exhaustion}, we provide a proof here for the reader's convenience.
% it seems harder to pin down a precise reference; this result has probably been reinvented by various authors as and when needed.
Consider the following space:
\[
\cF_{00} \defeq \bigcup_i Q_i^\ast (C(G_i)) \subseteq C(G).
\]
It is easily checked that $\cF_{00}$ is a subalgebra of $C(G)$ that is closed under complex conjugation. Moreover, the standard construction of $G$ realizes it as a subset of $\prod_i G_i$
(see \cite[Pro\-pos\-ition 1.8.9]{Deitmar-Echterhoff-book} or \cite[Pro\-pos\-ition 1.1.1]{Ribes-Zalesskii-book});
in particular, given $x,x'\in G$ with $x\neq x'$, there exists some $j\in I$ such that $Q_j(x)\neq Q_j(x')$.
Thus, $\cF_{00}$ separates the points of $G$. By the Stone--Weierstrass theorem, it follows that $\cF_{00}$ is dense in $C(G)$ with respect to the supremum norm, and therefore it is dense in $L^2(G)$ with respect to the $L^2$-norm.
Now let $f\in\FA(G)$. Since $f=\alpha_G(\xi\otimes\eta)$ for some $\xi,\eta\in L^2(G)$, a routine approximation argument produces $\xi_n,\eta_n\in \cF_{00}$ such that $\norm{\alpha_G(\xi_n\otimes\eta_n)-f}_{\FA(G)}\to 0$. By the definition of $\cF_{00}$, each function $\alpha_G(\xi_n\otimes\eta_n)$ belongs to $\bigcup_{i\in I} Q_i^*(\FA(G_i))$, and thus we have proved part~\ref{li:exhaustion}.


Finally, part \ref{li:upper bound} follows immediately from part \ref{li:exhaustion} and Lemma \ref{l:AM of inductive limit}.
\end{proof}




\begin{rem}
\previously{C5.3}
One can use Proposition \ref{p:AM upper bound sequential} to give a slight refinement of Proposition \ref{p:A(profinite)}\ref{li:upper bound}: namely, there is an increasing sequence $i(1)\preceq i(2)\preceq \dots$ in $I$, such that
\[ \AM(\FA(G)) \leq \limsup_{n\geq 1} \AM(\FA(G_{i(n)})) \;. \]
\end{rem}


\begin{proof}[The proof of Theorem \ref{t:new examples}, part \ref{li:p-reduced p-adic Heis}]
To ease notation, let $\bbS_n$ denote the ring $\bbZ/p^n\bbZ$.

By construction, $\Zadic{p}$ can be identified as a topological group with the inverse limit $\varprojlim_n \bbS_n$; this identification also respects the ring structure. It follows, either by direct calculations or the universal property of inverse limits, that $\Hpred(\Zadic{p})$ can be identified as a topological group with the inverse limit $\varprojlim_n \Hpred(\bbS_n)$.

As previously mentioned (see the comments before Remark \ref{r:reduced Heisenberg}), we have a semidirect product decomposition
\[
\Hpred(\bbS_n) \cong \bbS_n\ltimes  \left( \bbS_n \oplus  (\bbS_n/p\bbS_n) \right)
\cong \bbS_n\ltimes  \left( \bbS_n \oplus \bbS_1) \right),
\]
and so the irreducible representations of $\Hpred(\bbS_n)$(up to equivalence) can be determined using Mackey theory. One finds that $\Hpred(\bbS_n)$ has exactly $p^{2n}$ $1$-dimensional representations and exactly $p^{2n-1}-p^{2n-2}$ irreducible representations of degree $p$, and no others.
% MG has checked this (2025-06-26), we omit details from the paper for now

Thus, for each $n$,
applying Johnson's formula \eqref{eq:johnson formula} yields
\[
\AM(\FA(\Hpred(\bbS_n)))= \frac{1}{p^{2n+1}} \left( p^{2n}\cdot 1^3 + (p^{2n-1}-p^{2n-2})\cdot p^3\right ) = p-1+p^{-1} .
\]
We deduce, using Proposition \ref{p:A(profinite)}\ref{li:upper bound}, that $\AM(\FA(\Hpred(\Zadic{p})))\leq p-1+p^{-1}$.

Since $\AM(\FA(\cdot))\geq \AD(\cdot)$, to complete the proof of the theorem it suffices to prove that $\AD(\FA(\Hpred(\Zadic{p})))\geq p-1+p^{-1}$.
We shall do this by exploiting the fact that $\AD(\cdot)$ is monotone increasing with respect to subgroup inclusion (\cite[Proposition 2.9]{Choi-minorant}). The canonical injective ring homomorphism $\bbZ\to\bbZ_p$ induces an injective group homomorphism $\sH(\bbZ)\to\sH(\Zadic{p})$, and a little book-keeping shows that this descends to an injective group homomorphism $\Hpred(\bbZ)\to \Hpred(\Zadic{p})$. We already showed that $\AD(\Hpred(\bbZ))\geq p-1+p^{-1}$, and so monotonicity of $\AD$ implies that
\[
\AD(\Hpred(\Zadic{p})) \geq \AD(\Hpred(\bbZ))=p-1+p^{-1} \;,
\]
as required.
\end{proof}

Finally, we show that neither $\Hpred(\Zahl)$ nor $\Hpred(\Zadic{p})$ can be written as the product of a finite group with an AD-maximal group.

\begin{proof}[The proof of Theorem \ref{t:new examples}, part~\ref{li:not cheap} ]
Let $G$ be either $\Hpred(\Zahl)$ or $\Hpred(\Zadic{p})$, and suppose that $G\cong F\times H$ where $F$ is finite and $H$ is AD-maximal. By Proposition \ref{p:not finite times anything} $F$ has to be trivial, so $G=H$ is AD-maximal. This is a contradiction, since $\maxdeg$ takes positive integer values while $\AD(G)=p-1+p^{-1}$ is not an integer.
\end{proof}








