% \end{align}
where $\mathcal{A}_i$ and $\mathcal{A}_{S_{T_i}}$ represent the set of polynomial coefficients corresponding to only $\theta_i$ and all coefficients that include $\theta_i$, respectively. The variable $\gamma_k$ represents the polynomial normalization factor defined previously. As described in detail by Nagel et al. \cite{Nagel2020}, the coefficients corresponding to the PCE-PCA surrogate can also be used to compute point-wise Sobol' indices describing the original, time-series output. Note that
\begin{eqnarray}
    &\expect\left[Y\mid \theta_i\right]\approx \expect\left[\mathcal{M}^{\text{PCE}}\mid \theta_i\right] \nonumber \\
    &= \boldsymbol{\mu}(\textbf{t}) + \displaystyle\sum_{q=1}^M \expect\left[c_q(\boldsymbol{\param})\mid \theta_i\right] \eta_q(t) \nonumber \\
    &= \boldsymbol{\mu}(\textbf{t}) + \displaystyle\sum_{q=1}^M \sum_{k=0}^{\numpcecoeff-1} \pcecoeff_{qk} \expect\left[\pcepoly_k(\boldsymbol{\param})\mid \theta_i\right] \eta_q
\end{eqnarray}
and similarly
\begin{equation}
    \expect\left[Y\mid \bm{\theta}_{\sim i}\right]\approx \boldsymbol{\mu}(\textbf{t}) + \displaystyle\sum_{q=1}^M \sum_{k=0}^{\numpcecoeff-1} \pcecoeff_{qk} \expect\left[\pcepoly_k(\boldsymbol{\param})\mid \bm{\theta}_{\sim i}\right] \eta_q
\end{equation}
where we remove the time-dependence of $\eta_q$ for ease of notation. We can then write
\begin{eqnarray}
    &\var\left[\expect\left[\data | \theta_i\right]\right] \approx \var\left[\expect\left[\mathcal{M}^{\text{PCE}} | \theta_i\right]\right] \nonumber \\
    = &\displaystyle\sum_{q=1}^M \var\left[\expect\left[c_q(\boldsymbol{\param})\mid \theta_i\right]\right] \eta^2_q + 2\sum_{q<q^*}\textbf{Cov}\left[\expect\left[c_q(\boldsymbol{\param})\mid \theta_i\right],\expect\left[c_{q^*}(\boldsymbol{\param})\mid \theta_i\right]\right]\eta_q\eta_{q^*} \nonumber \\
    = &\displaystyle\sum_{q=1}^M S_i^q \var\left[c_q(\bm{\theta})\right] \eta^2_q + 2\sum_{q<q^*}\textbf{Cov}\left[\expect\left[c_q(\boldsymbol{\param})\mid \theta_i\right],\expect\left[c_{q^*}(\boldsymbol{\param})\mid \theta_i\right]\right]\eta_q\eta_{q^*}
\end{eqnarray}
where on the last line we rearrange the definition of $S_i^q$ provided in eq \eqref{eq:si}. By similar argument, we can rearrange the definition of $S_{T_i}^q$ and write
\begin{eqnarray}
     &\var\left[\expect\left[\data | \bm{\theta}_{\sim i}\right]\right] \approx \var\left[\expect\left[\mathcal{M}^{\text{PCE}} | \bm{\theta}_{\sim i} \right]\right] \nonumber \\
    = &\displaystyle\sum_{q=1}^M \left(1-S_{T_i}^q\right) \var\left[c_q(\bm{\theta})\right] \eta^2_q + 2\sum_{q<q^*}\textbf{Cov}\left[\expect\left[c_q(\boldsymbol{\param})\mid \bm{\theta}_{\sim i}\right],\expect\left[c_{q^*}(\boldsymbol{\param})\mid \bm{\theta}_{\sim i}\right]\right]\eta_q\eta_{q^*}. \ \ \ \ 
\end{eqnarray}
The point-wise first and total-order Sobol' indices are then given by
\begin{eqnarray}\label{eq:sob_time}
    % S_i^Y = \displaystyle \frac{1}{\var\left[\data\right]}\Big(\displaystyle\sum_{q=1}^M S_i^q \var\left[c_q(\bm{\theta})\right] \eta^2_q(t)    + 2\sum_{q<q^*}\textbf{Cov}\left[\expect\left[c_q(\boldsymbol{\param})\mid \theta_i\right],\expect\left[c_{q^*}(\boldsymbol{\param})\mid \theta_i\right]\right]\eta_q(t)\eta_{q^*}(t)\Big) 
    S_i^Y = \displaystyle \frac{\displaystyle\sum_{q=1}^M S_i^q \var\left[c_q(\bm{\theta})\right] \eta^2_q    + 2\sum_{q<q^*}\textbf{Cov}\left[\expect\left[c_q(\boldsymbol{\param})\mid \theta_i\right],\expect\left[c_{q^*}(\boldsymbol{\param})\mid \theta_i\right]\right]\eta_q\eta_{q^*}}{{\var\left[\data\right]}}
\end{eqnarray}
\begin{eqnarray}
    % S_{T_i}^Y =  1 - \displaystyle \frac{1}{\var\left[\data\right]}\left(\displaystyle\sum_{q=1}^M \left(1-S_{T_i}^q\right) \var\left[c_q(\bm{\theta})\right] \eta^2_q(t) + 2\sum_{q<q^*}\textbf{Cov}\left[\expect\left[c_q(\boldsymbol{\param})\mid \bm{\theta}_{\sim i}\right],\expect\left[c_{q^*}(\boldsymbol{\param})\mid \bm{\theta}_{\sim i}\right]\right]\eta_q(t)\eta_{q^*}(t)\right).
    S_{T_i}^Y =  1 - \displaystyle \frac{\displaystyle\sum_{q=1}^M \left(1-S_{T_i}^q\right) \var\left[c_q(\bm{\theta})\right] \eta^2_q + 2\sum_{q<q^*}\textbf{Cov}\left[\expect\left[c_q(\boldsymbol{\param})\mid \bm{\theta}_{\sim i}\right],\expect\left[c_{q^*}(\boldsymbol{\param})\mid \bm{\theta}_{\sim i}\right]\right]\eta_q\eta_{q^*}}{{\var\left[\data\right]}}.
\end{eqnarray}
As noted in the original derivation of this approach by Nagel et al. \cite{Nagel2020}, the orthogonality of the polynomials provides the following covariance definitions:
\begin{eqnarray}
    \textbf{Cov}\left[\expect\left[c_q(\boldsymbol{\param})\mid \theta_i\right],\expect\left[c_{q^*}(\boldsymbol{\param})\mid \theta_i\right]\right] = \displaystyle \sum_{k\in\mathcal{A}_{S_i}}z_{qk}z_{q^{^*} k} \\
    \textbf{Cov}\left[\expect\left[c_q(\boldsymbol{\param})\mid \bm{\theta}_{\sim i}\right],\expect\left[c_{q^*}(\boldsymbol{\param})\mid \bm{\theta}_{\sim i}\right]\right] = \displaystyle \sum_{k\in\mathcal{A}_{S_{T_i}}}z_{qk}z_{q^{^*} k} 
\end{eqnarray}
