\title{Soft Robotics-Inspired Flexible Antenna Arrays}
\author{\author{Elio Faddoul, \IEEEmembership{Member, IEEE}, Andreas Nicolaides, \IEEEmembership{Member, IEEE},\\ Konstantinos Ntougias, \IEEEmembership{Member, IEEE}, and Ioannis Krikidis, \IEEEmembership{Fellow, IEEE}
