\section{Calculation of The Gradient $\nabla_{\bar{\mathbf{z}}} R(\bar{\mathbf{z}})$}
Based on the sum rate expression, $\nabla_{\mathbf{z}} R(\mathbf{z})$ is expressed as
\begin{equation}
\nabla_{\mathbf{z}} R(\mathbf{z}) = \sum_{k\in \mathcal{K}} \frac{1}{\ln(2)(1+\gamma_{k}(\mathbf{z}))} \nabla_{\mathbf{z}} \gamma_{k}(\mathbf{z}),
\end{equation}
which is decomposed by applying the chain rule
\begin{align}
\frac{\partial R}{\partial z_{m,n}}
=\sum_{k\in \mathcal{K}} \frac{1}{\ln(2)(1+\gamma_k(z_{m,n}))} \sum_{i\in\mathcal{K}} \frac{\partial\gamma_k}{\partial S_{ki}}
\frac{\partial S_{ki}}{\partial z_{m,n}},
\end{align}
where $S_{ki}\triangleq\left|\mathbf{h}_k^H \mathbf{w}_i\right|^2$,
\begin{align}
\frac{\partial\gamma_k}{\partial S_{ki}}=
\begin{cases}
1/ (\sum_{i\in\mathcal{K}}S_{ki}+\sigma^2), & i=k,\\
-S_{kk}/(\sum_{i\in\mathcal{K}}S_{ki}+\sigma^2)^2, & i\neq k,
\end{cases}
\end{align}
and $\frac{\partial S_{ki}}{\partial z_{m,n}}
=2\Re\left\{(\mathbf{h}_k^H \mathbf{w}_i)\mathbf{w}_i^H \frac{\partial \mathbf{h}_k}{\partial z_{m,n}}\right\}$.
Moreover, each entry in $\mathbf{h}_k$ only depends on $z_{m,n}$ through $e^{-j\frac{2\pi}{\lambda}z_{m,n}\cos\vartheta}$. Thus, $\partial \mathbf{h}_k/\partial z_{m,n} = -j\frac{2\pi}{\lambda}\cos\vartheta \mathbf{h}_k$. Furthermore, since $z_{m,n}(A_m,v_m)
= A_m\sin(\omega t + v_m\ell_n)$, the corresponding partial derivatives are given by
\begin{align}
\frac{\partial z_{m,n}}{\partial A_m}
=\sin(\omega t + v_m\ell_n), \ \frac{\partial z_{m,n}}{\partial v_m}
= A_m\ell_n\cos(\omega t + v_m\ell_n).
\vspace{-1mm}
\end{align}
By defining the intermediate gradient as $\bar{\mathbf{g}} = \bigl[\frac{\partial R}{\partial z_{1,1}},\dots,\frac{\partial R}{\partial z_{M,N}}\bigr]^T \in \mathbb{R}^{MN\times 1}$,
and the Jacobian matrix $\mathbf{J}_m \in \mathbb{R}^{N\times 2}$ for the $m$-th tentacle as
\begin{align}
\mathbf{J}_m =
\begin{bmatrix}
\sin(\omega t+v_m\ell_1), & A_m\ell_1\cos(\omega t+v_m\ell_1)\\[1mm]
\vdots & \vdots\\[1mm]
\sin(\omega t+v_m\ell_N), & A_m\ell_N\cos(\omega t+v_m\ell_N)
\end{bmatrix},
\end{align}
we obtain
\begin{align}
\nabla_{\bar{\mathbf{z}}} R(\bar{\mathbf{z}})
= \mathbf{J}^T\,\bar{\mathbf{g}} \ \in \mathbb{R}^{2M\times 1},
\end{align}
where $\mathbf{J} = \mathrm{diag}(\mathbf{J}_1,\dots,\mathbf{J}_M)\in\mathbb R^{MN\times2M}$.

