\title{ Impact of Hole-ice Calibration on High Energy Event Reconstruction with the IceCube Upgrade }

\author{The IceCube Collaboration \\{\normalsize \normalfont(a complete list of authors can be found at the end of the proceedings)}\\}

% Your emails:
\emailAdd{kdutta@icecube.wisc.edu}
