\subsection{Effect of density gradients on diffusion}
%\begin{figure}[!t]
%    \centering
%\includegraphics[width=1.0\linewidth]{Figures/Combined_PDF_rho.pdf}
%\put(-220,330){(a)}
%    \put(-220,160){(b)}
