        \lstick[3]{$\ket{GHZ}$\\ or \\$\ket{\widehat{GHZ}}$} & \gate[1]{H} & \ctrl{3} &  &  &  \\
         & \gate[1]{H} &  & \ctrl{2} & &  \\
         & \gate[1]{H} & & & \ctrl{1} &  \\
        \lstick{$\ket{0}$} &             & \targ{} & \targ{} & \targ{} & \meter{}
    \end{quantikz}
