    \centering
    \begin{quantikz}
        \lstick{$\ket{\psi}_L$} & & \gate[1]{S} & &\\
        \lstick{$\ket{0}_A$} & \gate[1]{H} & \ctrl{-1} & \gate[1]{H} & \meter{}\\
    \end{quantikz}
    \caption{
        Syndrome extraction procedure for a stabilizer code.
    }\label{fig:syndromeextraction}
\end{figure}

Now suppose we are concerned with two types of errors and label them $E_1$ and $E_2$. We find
operators $S_1,S_2\in\mathcal{S}$ such that $[S_1,S_2]=0$ and $S_i$ anticommutes with $E_j$ for $i=j$
and commutes with $E_j$ for $i\ne j$, and then we apply the procedure shown in Figure~\ref{fig:syndromeextraction2}. 
Suppose that $\ket{\psi}_L$ has been subject to an error $E\in\{\mathds{1},E_1,E_2\}$.
After the Hadamard gates on the ancillary register, we have the state
\begin{equation}
    \frac{1}{2}E\ket{\psi}_L(\ket{0}_{A_1}+\ket{1}_{A_1})(\ket{0}_{A_2}+\ket{1}_{A_2})
    =\frac{1}{2}(E\ket{\psi}_L\ket{00}_A+E\ket{\psi}_L\ket{01}_A+E\ket{\psi}_L\ket{10}_A+E\ket{\psi}_L\ket{11}_A),
\end{equation}
where we have introduced the notation $\ket{xy}_A=\ket{x}_{A_1}\ket{y}_{A_2}$ for brevity. Now
applying the controlled $S_1$ and $S_2$ operations produces the state
\begin{equation}
    \frac{1}{2}(E\ket{\psi}_L\ket{00}_A+S_2E\ket{\psi}_L\ket{01}_A+S_1E\ket{\psi}_L\ket{10}_A+S_2S_1E\ket{\psi}_L\ket{11}_A).
\end{equation}
Finally, applying Hadamard gates to the ancillary register again produces the state
\begin{align}
    \frac{1}{4}&((\mathds{1}+S_2+S_1+S_2S_1)E\ket{\psi}_L\ket{00}_A+(\mathds{1}-S_2+S_1-S_2S_1)E\ket{\psi}_L\ket{01}_A\\
    &+(\mathds{1}+S_2-S_1-S_2S_1)E\ket{\psi}_L\ket{10}_A+(\mathds{1}-S_2-S_1+S_2S_1)E\ket{\psi}_L\ket{11}_A).
\end{align}
Since $S_1$ and $S_2$ leave $\ket{\psi}_L$ invariant by assumption, we see that if $E=\mathds{1}$, then this 
state reduces to $\ket{\psi}_L\ket{00}_A$, and we are guaranteed that a measurement of the ancillary 
qubits will produce the syndrome 00 while leaving the state of the logical qubit unaffected. 
If $E=E_1$, then using the assumption that $E_1$ anticommutes with $S_1$, the state before measurement reduces to
\begin{align}
    \frac{1}{4}&((\mathds{1}+S_2-\mathds{1}-S_2)E_1\ket{\psi}_L\ket{00}_A+(\mathds{1}-S_2-\mathds{1}+S_2)E_1\ket{\psi}_L\ket{01}_A\\
    &+(\mathds{1}+S_2+\mathds{1}+S_2)E_1\ket{\psi}_L\ket{10}_A+(\mathds{1}-S_2+\mathds{1}-S_2)E_1\ket{\psi}_L\ket{11}_A),
\end{align}
which is equivalent to
\begin{equation}
    \frac{1}{2}((\mathds{1}+S_2)E_1\ket{\psi}_L\ket{10}_A+(\mathds{1}-S_2)E_1\ket{\psi}_L\ket{11}_A).
\end{equation}
Now using the assumption that $E_1$ commutes with $S_2$, we are left with the state $E_1\ket{\psi}_L\ket{10}_A$,
so that a measurement on the ancillary register produces the syndrome 10 with certainty and leaves
the state of the logical qubit invariant. Similarly, if $E=E_2$, then the state before measurement is
$E_2\ket{\psi}_L\ket{10}_A$, which will produce error syndrome 10 upon measurement and leave the
state of the logical qubit invariant. Finally, if $E=E_1E_2$, then the state before measurement is
$E_1E_2\ket{\psi}_L\ket{11}_A$, which will produce error syndrome 11 upon measurement and again
leave the state of the logical qubit invariant. Thus, our code can identify and correct $E_1,E_2,$ and
$E_1E_2$ errors.

