        \lstick{$\ket{0}_{A_1}$} & \gate[1]{H} & \ctrl{-1}     &              & \gate[1]{H} &\meter{}\\
        \lstick{$\ket{0}_{A_2}$} & \gate[1]{H} &               & \ctrl{-2}    & \gate[1]{H} &\meter{}
    \end{quantikz}
